window.__D("text/zohar-hebrew-translation/c026",{"p":[[9522012042,"<p>בֹּא רְאֵה, בְּשָׁעָה שֶׁאָדָם בָּא לְהִתְקַדֵּשׁ לְהִזְדַּוֵּג בִּנְקֵבָתוֹ (בכונה) בְּרָצוֹן קָדוֹשׁ שֶׁלּוֹ, מִתְעוֹרֶרֶת עָלָיו רוּחַ (אחרת) קְדוֹשָׁה, כְּלוּלָה זָכָר וּנְקֵבָה, וְרוֹמֵז הַקָּדוֹשׁ בָּרוּךְ הוּא לְשָׁלִיחַ אֶחָד הַמְמֻנֶּה עַל הֶרְיוֹנוֹת בְּנֵי הָאָדָם, וּמַפְקִיד בְּיָדוֹ אוֹתָהּ הָרוּחַ, וּמוֹדִיעַ לוֹ לְאֵיזֶה מָקוֹם יִפְקֹד אוֹתוֹ. זֶהוּ שֶׁכָּתוּב (איוב ג) וְהַלַּיְלָה אָמַר הֹרָה גָבֶר. הַלַּיְלָה אָמַר לְאוֹתוֹ מְמֻנֶּה: הֹרָה גָבֶר מִפְּלוֹנִי. וְהַקָּדוֹשׁ בָּרוּךְ הוּא מַפְקִיד לוֹ, אֶת אוֹתָהּ הָרוּחַ, כָּל מַה שֶּׁמַּפְקִיד, וְהִנֵּה פֵּרְשׁוּהָ.</p>\n<p>אָז יוֹרֶדֶת רוּחַ, וְצֶלֶם אֶחָד עִמָּהּ, אוֹתוֹ שֶׁעוֹמֵד בִּדְיוֹקְנוֹ לְמַעְלָה, בְּאוֹתוֹ צֶלֶם נִבְרָא (התגדל), בְּאוֹתוֹ צֶלֶם הוֹלֵךְ בָּעוֹלָם הַזֶּה. זֶהוּ שֶׁכָּתוּב (תהלים לט) אַךְ בְּצֶלֶם יִתְהַלֶּךְ אִישׁ. בְּעוֹד שֶׁהַצֶּלֶם הַזֶּה נִמְצָא עִם הָאָדָם, בַּצֶּלֶם שֶׁלּוֹ עוֹמֵד בָּעוֹלָם הַזֶּה, שֶׁמִּתְחַבְּרִים כְּאֶחָד (נמצא עמו אדם עומד בעולם הזה, ושנים הם שמתחברים כאחד) הוּא עוֹמֵד בָּעוֹלָם הַבָּא, וּשְׁנַיִם הֵם שֶׁמְּחֻבָּרִים יַחַד. וּשְׁלֹמֹה הַמֶּלֶךְ מַזְהִיר אֶת בְּנֵי הָאָדָם וְאוֹמֵר, (שיר ב) עַד שֶׁיָּפוּחַ הַיּוֹם וְנָסוּ הַצְּלָלִים, שְׁנַיִם.</p>\n<p>וּבְסֵפֶר הַכְּשָׁפִים שֶׁל אַשְׁמְדַאי מָצָאנוּ, שֶׁאוֹתָם שֶׁיּוֹדְעִים (שרוצים) לְכַשֵּׁף כְּשָׁפִים מִצַּד הַשְּׂמֹאל וּלְהִדָּבֵק בָּהֶם, יָקוּם לְאוֹר הַנֵּר אוֹ בְּמָקוֹם שֶׁיִּרְאוּ אוֹתָם הַצְּלָמִים שֶׁלּוֹ, וְיֹאמַר אוֹתָם דְּבָרִים שֶׁמְּתֻקָּנִים לְאוֹתָם הַכְּשָׁפִים, וְיִקְרָא לָהֶם לְאוֹתָם צְדָדִים טְמֵאִים בַּשֵּׁמוֹת הַטְּמֵאִים שֶׁלָּהֶם, וְיַזְמִין (וישביע) הַצְּלָמִים שֶׁלּוֹ לְאוֹתָם שֶׁקּוֹרֵא, וְיֹאמַר שֶׁהוּא מִתְתַּקֵּן בִּרְצוֹנוֹ לָהֶם לְמִצְוָתָם, וְאוֹתוֹ הָאִישׁ יוֹצֵא מֵרְשׁוּת רִבּוֹנוֹ, וּפִקְדוֹנוֹ נוֹתֵן לַצַּד הָאַחֵר.</p>\n<p>וּבְאוֹתָם דִּבּוּרִים שֶׁל כְּשָׁפִים שֶׁהוּא יֹאמַר וְיַזְמִין (וישביע) אוֹתָם לַצְּלָמִים, נִרְאִים שְׁתֵּי רוּחוֹת, וּמִתְתַּקְּנִים בְּאוֹתָם צְלָמִים שֶׁלּוֹ בְּמַרְאֶה שֶׁל בְּנֵי אָדָם, וּמוֹדִיעִים לוֹ דְּבָרִים לְהָרַע וּדְבָרִים לְהֵיטִיב לִזְמַנִּים יְדוּעִים. וְאֵלּוּ שְׁתֵּי הָרוּחוֹת שֶׁלֹּא נִכְלְלוּ בִּכְלָל שֶׁל גּוּף, עַכְשָׁו נִכְלָלִים בַּצְּלָמִים הַלָּלוּ, וּמִתְתַּקְּנִים בָּהֶם וּמוֹדִיעִים לוֹ לָאָדָם דְּבָרִים לְהָרַע, וְזֶהוּ שֶׁיּוֹצֵא מֵרְשׁוּת רִבּוֹנוֹ, וּפִקְדוֹנוֹ נוֹתֵן לַצַּד הַטָּמֵא.</p>\n<p>בֹּא רְאֵה, אָסוּר לָאָדָם לִזְרֹק כְּלֵי הַבַּיִת וּלְהַפְקִידוֹ לַצַּד הָאַחֵר, שֶׁלֹּא צָרִיךְ, אוֹ דָבָר אַחֵר שֶׁכְּמוֹתוֹ (של ביתו לקבל אותו), שֶׁהֲרֵי כַּמָּה שׁוֹמְרֵי הַכְּלָלִים מְזֻמָּנִים לַדָּבָר הַהוּא לְקַבֵּל אוֹתוֹ, וּמֵאוֹתוֹ זְמַן לֹא שׁוֹרִים עָלָיו בְּרָכוֹת, שֶׁהֲרֵי הוּא מִצַּד אַחֵר. כָּל שֶׁכֵּן מִי שֶׁמַּזְמִין בִּרְצוֹנוֹ עַל אוֹתוֹ הַטּוֹב הָעֶלְיוֹן שֶׁלּוֹ, לְאַחֵר וְלַצַּד הָאַחֵר, שֶׁהֲרֵי הוּא מֵאוֹתוֹ שֶׁהִזְמִין אוֹתוֹ.</p>\n<p>וּכְשֶׁקְּרֵבִים יְמֵי הָאָדָם לָצֵאת מִן הָעוֹלָם הַזֶּה, אוֹתוֹ הַצֶּלֶם הָעֶלְיוֹן שֶׁנּוֹתְנִים לוֹ, בָּאָה אוֹתָהּ רוּחַ רָעָה שֶׁהָיָה נִדְבָּק בָּהּ בְּכָל יוֹם, וְנוֹטֶלֶת אוֹתוֹ הַצֶּלֶם, וּמִתְתַּקֵּן בּוֹ וְהוֹלֵךְ לוֹ, וְלֹא חוֹזֵר לָאָדָם לְעוֹלָמִים. אָז יֵדַע שֶׁהֲרֵי הוּא נִדְחֶה מִן הַכֹּל.</p>\n<p>בֹּא רְאֵה, בְּשָׁעָה שֶׁהַנְּשָׁמָה יוֹרֶדֶת לְהִכָּנֵס לוֹ בָּעוֹלָם הַזֶּה, יוֹרֶדֶת לְגַן הָעֵדֶן שֶׁל הָאָרֶץ, וְרוֹאָה אֶת כְּבוֹדָם שֶׁל רוּחוֹת הַצַּדִּיקִים עוֹמְדִים שׁוּרוֹת שׁוּרוֹת. אַחַר כָּךְ הוֹלֶכֶת לַגֵּיהִנֹּם, וְרוֹאָה אֶת הָרְשָׁעִים שֶׁצּוֹוְחִים וַי וַי, וְלֹא מְרַחֲמִים עֲלֵיהֶם. וּבַכֹּל מְעִידִים בָּהּ עֵדוּת, וְאוֹתוֹ הַצֶּלֶם הַקָּדוֹשׁ עוֹמֵד עָלֶיהָ, עַד שֶׁיּוֹצֵאת לָעוֹלָם.</p>\n<p>כְּשֶׁיּוֹצֵאת לָעוֹלָם, מִזְדַּמֵּן לָהּ אוֹתוֹ הַצֶּלֶם, וּמִשְׁתַּתֵּף עִמָּהּ, וּמִתְגַּדֵּל עִמָּהּ, כְּמוֹ שֶׁנֶּאֱמַר אַךְ בְּצֶלֶם יִתְהַלֶּךְ אִישׁ. וּבְאוֹתוֹ הַצֶּלֶם מִשְׁתַּתְּפִים (נמצאים) יְמֵי הָאָדָם וּתְלוּיִים בּוֹ. זֶהוּ שֶׁכָּתוּב (איוב ח) כִּי תְמוֹל אֲנַחְנוּ וְלֹא נֵדָע כִּי צֵל יָמֵינוּ עֲלֵי אָרֶץ. כִּי צֵל יָמֵינוּ וַדַּאי. וּמִיּוֹם שֶׁמִּתְעַבֶּרֶת הָאִשָּׁה עַד הַיּוֹם שֶׁמּוֹלִידָה, לֹא יוֹדְעִים בְּנֵי אָדָם אֶת מַעֲשֵׂי הַקָּדוֹשׁ בָּרוּךְ הוּא כַּמָּה הֵם גְּדוֹלִים וְכַמָּה הֵם עֶלְיוֹנִים. זֶהוּ שֶׁכָּתוּב (תהלים קד) מָה רַבּוּ מַעֲשֶׂיךְ ה' וְגוֹ'.</p>\n<p>בֹּא רְאֵה, כָּל רוּחוֹת הָעוֹלָם כְּלוּלוֹת זָכָר וּנְקֵבָה, וּכְשֶׁיּוֹצְאוֹת, יוֹצְאוֹת זָכָר וּנְקֵבָה, וְאַחַר כָּךְ נִפְרָדִים בְּדַרְכֵיהֶם, אִם זוֹכֶה הָאָדָם, אַחַר כָּךְ מִזְדַּוְּגִים יַחַד. וְהַיְנוּ בַּת זוּגוֹ, וּמִתְחַבְּרִים בְּזִוּוּג (בגון) אֶחָד בַּכֹּל, רוּחַ וְגוּף, שֶׁכָּתוּב (בראשית א) תּוֹצֵא הָאָרֶץ נֶפֶשׁ חַיָּה לְמִינָהּ. מַה זֶה לְמִינָהּ? אוֹתָהּ רוּחַ הָאָדָם שֶׁיּוֹצֵאת זִוּוּגוֹ שֶׁדּוֹמָה לוֹ.</p>\n<p>וּמַה זֶּה הָאָרֶץ? כְּמוֹ שֶׁנֶּאֱמַר רֻקַּמְתִּי בְּתַחְתִּיּוֹת אָרֶץ, וְהִנֵּה פֵּרְשׁוּהָ. תּוֹצֵא הָאָרֶץ וַדַּאי, שֶׁהֲרֵי מִמֶּנָּה יוֹצְאִים נֶפֶשׁ חַיָּה, כְּמוֹ שֶׁבֵּאַרְנוּ, זוֹ רוּחוֹ שֶׁל אָדָם הָרִאשׁוֹן, זֶהוּ שֶׁכָּתוּב (שם ג) וּמִפְּרִי הָעֵץ אֲשֶׁר בְּתוֹךְ הַגָּן. וּמִפְּרִי הָעֵץ - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא. אֲשֶׁר בְּתוֹךְ הַגָּן - אֲשֶׁר בְּתוֹךְ הָאִשָּׁה שָׁנִינוּ, הַיְנוּ אִשָּׁה כִּי תַזְרִיעַ וְיָלְדָה זָכָר כָּתוּב. וְלֹא כוֹלֵל זָכָר וּנְקֵבָה כְּפִי דֶּרֶךְ הָעוֹלָם, שֶׁהֵם גָּרְמוּ לוֹ, שֶׁלֹּא מִתְחַבְּרִים כְּמוֹ שֶׁיּוֹצְאִים מִלְמַעְלָה זוּגוֹת.</p>\n<p>מִשּׁוּם שֶׁאָדָם הָרִאשׁוֹן וְזִוּוּגוֹ חָטְאוּ לַקָּדוֹשׁ בָּרוּךְ הוּא, וְעַל כֵּן נִפְרָדִים כְּשֶׁיּוֹצְאִים מִלְמַעְלָה, עַד שֶׁיִּהְיֶה רָצוֹן מִלִּפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. אִם זוֹכֶה אָדָם, נוֹתְנִים לוֹ זוּגָתוֹ, וְאִם לֹא - מַפְרִידִים אוֹתָהּ מִמֶּנּוּ, וְנוֹתְנִים אוֹתָהּ לְאַחֵר, מוֹלִידִים בָּנִים שֶׁלֹּא כָּרָאוּי. וְעַל זֶה כָּתוּב (שם ו) לֹא יָדוֹן רוּחִי בָאָדָם. מַה זֶּה רוּחִי? רוּחוֹ הָיָה צָרִיךְ לִהְיוֹת! אוֹתָן שְׁתֵּי רוּחוֹת שֶׁיּוֹצְאוֹת זוּגוֹת, לֹא יִדּוֹנוּ יַחַד. וְעַל זֶה כָּתוּב וְיָלְדָה זָכָר, וְלֹא כוֹלֵל זָכָר וּנְקֵבָה כְּפִי דֶּרֶךְ הָעוֹלָם, שֶׁהֵם גָּרְמוּ.</p>"],[9522012043,"<p>רַבִּי אֶלְעָזָר אָמַר, לֹא כָּךְ, שֶׁהֲרֵי הַכֹּל, זָכָר וּנְקֵבָה כְּלוּלִים יַחַד, וְאַחַר כָּךְ נִפְרָדִים. אֲבָל וְיָלְדָה זָכָר, כְּלוּלִים יַחַד מִצַּד הַיָּמִין. וְאִם תֵּלֵד נְקֵבָה, כְּלוּלִים בְּאֶחָד נְקֵבָה וְזָכָר מִצַּד הַשְּׂמֹאל, שֶׁיּוֹתֵר שׁוֹלֵט צַד הַשְּׂמֹאל עַל צַד הַיָּמִין, וְהַזָּכָר נִכְנָע בַּיָּמִין שֶׁלֹּא שׁוֹלֵט, וְאָז אוֹתוֹ הַזָּכָר שֶׁיּוֹצֵא מִן הַנְּקֵבָה מִצַּד הַשְּׂמֹאל, כָּל דְּרָכָיו כְּמוֹ נְקֵבָה (ולא נקרא זכר). אֲבָל הַזָּכָר שֶׁיּוֹצֵא מִתּוֹךְ הַיָּמִין, הוּא שׁוֹלֵט, וְהַנְּקֵבָה שֶׁיּוֹצֵאת מִמֶּנּוּ נִכְנַעַת, שֶׁהֲרֵי צַד הַשְּׂמֹאל לֹא שׁוֹלֵט, וְעַל כֵּן כָּתוּב וְיָלְדָה זָכָר.</p>"],[9522012044,"<p>וְכַמָּה אֲלָפִים וּרְבָבוֹת יוֹצְאִים בְּפַעַם אַחַת בָּעוֹלָם. וּמֵהַיּוֹם שֶׁמּוֹצִיאָה אוֹתָם, לֹא נִקְרָאִים נְפָשׁוֹת, עַד שֶׁהֵן מִתְיַשְּׁבוֹת בַּגּוּף. וְכַמָּה הוּא? שְׁלֹשִׁים וּשְׁלֹשָׁה יָמִים. הַיְנוּ שֶׁכָּתוּב וּשְׁלֹשִׁים יוֹם וּשְׁלֹשֶׁת יָמִים וְגוֹ'. וְטָמְאָה שִׁבְעַת יָמִים, שֶׁהֲרֵי כָּל שִׁבְעַת יָמִים לֹא נִכְנָסִים אֵלֶיהָ רוּחוֹת לְהִתְקַשֵּׁר בָּהּ, וְכָל שִׁבְעַת הַיָּמִים הַלָּלוּ הָרוּחַ הוֹלֶכֶת בַּגּוּף לִמְצֹא אֶת מְקוֹמָהּ, וְאָז כָּתוּב (ויקרא כב) וְהָיָה שִׁבְעַת יָמִים תַּחַת אִמּוֹ.</p>\n<p>וּבַיּוֹם הַשְּׁמִינִי חוֹזְרִים הָרוּחַ וְהַגּוּף לְהֵרָאוֹת לִפְנֵי הַגְּבִירָה וּלְהִקָּשֵׁר עִמָּהּ, וּבְזָכָר, בְּגוּף וּבְרוּחַ. וּשְׁלֹשִׁים יוֹם וּשְׁלֹשֶׁת יָמִים תֵּשֵׁב עַל (ב) דְּמֵי טָהֳרָה, שֶׁתִּתְיַשֵּׁב הָרוּחַ בַּגּוּף. וּשְׁלֹשָׁה יָמִים מָה עוֹשִׂים? אֵלּוּ שְׁלֹשֶׁת יְמֵי הַמִּילָה, שֶׁלַּתִּינוֹק כּוֹאֵב, וְהָרוּחַ לֹא שָׂמָה אֶת מְדוֹרָהּ בַּגּוּף כְּבִשְׁאָר הַיָּמִים, וְעַל כֵּן - וּשְׁלֹשִׁים יוֹם וּשְׁלֹשֶׁת יָמִים תֵּשֵׁב בִּדְמֵי טָהֳרָה.</p>\n<p>בִּדְמֵי טָהֳרָה בָּרִאשׁוֹנָה, וְאַחַר כָּךְ יְמֵי טָהֳרָה. בִּדְמֵי טָהֳרָה - אֵלּוּ דְּמֵי מִילָה, דָּם אַחַר דָּם שֶׁבָּא מֵהַתִּינוֹק, וְהַקָּדוֹשׁ בָּרוּךְ הוּא שׁוֹמֵר אוֹתָם דָּמִים כָּל הַיָּמִים הַלָּלוּ. זֶהוּ שֶׁכָּתוּב תֵּשֵׁב בִּדְמֵי טָהֳרָה, טָהֳרָה סְתָם, וְלֹא הִזְכִּיר הֵ\"א הָאַחֲרוֹנָה, שֶׁלֹּא תֹאמַר הַטָּהֳרָה שֶׁל הַגְּבִירָה, אֶלָּא טָהֳרָה סְתָם. דְּמֵי טָהֳרָה נִקְרָאִים יְמֵי הַטֹּהַר הַלָּלוּ.</p>\n<p>בְּכָל קֹדֶשׁ לֹא תִגָּע וְאֶל הַמִּקְדָּשׁ וְגוֹ'. בּא רְאֵה, בְּכָל יוֹם וָיוֹם כְּנֶסֶת יִשְׂרָאֵל נוֹטֶלֶת מִבֵּית הַמֶּלֶךְ מָזוֹן לְרוּחוֹת בְּנֵי הָאָדָם וְזָנָה אוֹתָם בִּקְדֻשָּׁה, פְּרָט לְאֵלֶּה, שֶׁעַד שֶׁמִּתְיַשְּׁבוֹת בַּגּוּף אוֹתָן רוּחוֹת. אַחַר שְׁלֹשִׁים וּשְׁלֹשָׁה יָמִים הִיא מַשְׁגִּיחָה עֲלֵיהֶם כָּל יוֹם, שֶׁהֲרֵי הָרוּחוֹת נִקְשָׁרוֹת בַּגּוּף כִּשְׁאָר בְּנֵי הָעוֹלָם. כְּמוֹ שֶׁהִיא לֹא שׁוֹרָה אֶלָּא בְּמָקום שָׁלֵם, כָּךְ כָּל מַעֲשָׂיו כְּגון זֶה, עַד שֶׁנִּשְׁלָמִים. בְּכָל קֹדֶשׁ לֹא תִגָּע, לְהַשְׁגִּיחַ עֲלֵיהֶם.</p>"],[9522012045,"<p>וְאִם נְקֵבָה תֵלֵד. כְּמוֹ שֶׁבֵּאַרְנוּ, שֶׁיּוֹתֵר צַד הַשְּׂמֹאל שׁוֹלֵט, וְהַיָּמִין נִכְנָע. וְעַל כֵּן הַכֹּל, עַל כָּל אֶחָד שְׁנַיִם, רְחוֹקָה הַנְּקֵבָה מִן הַזָּכָר לְהִקָּשֵׁר הָרוּחַ בַּגּוּף, שֶׁהֲרֵי הַשְּׂמֹאל אֵינוֹ מִתְיַשֵּׁב כָּךְ כְּמוֹ הַיָּמִין, וְנִמְצָא יוֹתֵר בְּתֹקֶף.</p>"],[9522012046,"<p>וּבַיּוֹם הַשְּׁמִינִי יִמּוֹל בְּשַׂר עָרְלָתוֹ. מִצְוָה זוֹ לָמוּל לִשְׁמֹנָה יָמִים מִילַת בְּרִית הַקֹּדֶשׁ. סוֹד עֶלְיוֹן, שֶׁכָּתוּב (תהלים כה) סוֹד ה' לִירֵאָיו וּבְרִיתוֹ לְהוֹדִיעָם. לְמִי? לְאוֹתָם יְרֵאָיו, אוֹתָם יִרְאֵי חֵטְא, שֶׁהֲרֵי סוֹד הַבְּרִית הַקָּדוֹשׁ לֹא רָאוּי לְגַלּוֹת, רַק לָהֶם. וְאֶת סוֹד הַבְּרִית הַקָּדוֹשׁ הֲרֵי פֵּרְשׁוּהוּ, וְנִתְבָּאֵר בְּכַמָּה מְקוֹמוֹת.</p>\n<p>וְסוֹד זֶה לִשְׁמֹנָה יָמִים הוּא חִיּוּב עַל הָעוֹלָם, לְכָל הָעָם הַקָּדוֹשׁ, שֶׁכָּתוּב וּבַיּוֹם הַשְּׁמִינִי יִמּוֹל בְּשַׂר עָרְלָתוֹ. יוֹם הַשְּׁמִינִי - זֶהוּ אוֹת בְּרִית הַקֹּדֶשׁ, וְהוּא שְׁמִינִי לְכָל הַדְּרָגוֹת, וּמִילַת אוֹתוֹ הַבְּרִית לְהַעֲבִיר אוֹתָהּ עָרְלָה מִלִּפְנֵי הַבְּרִית.</p>\n<p>שֶׁהֲרֵי בְּאוֹתוֹ הַזְּמַן שֶׁמִּתְכַּנְּסִים הָעָם הַקָּדוֹשׁ לְהַעֲבִיר אוֹתָהּ הָעָרְלָה מִלִּפְנֵי הַבְּרִית, הַקָּדוֹשׁ בָּרוּךְ הוּא מְכַנֵּס אֶת כָּל הַפָּמַלְיָא שֶׁלּוֹ וּמִתְגַּלֶּה וַדַּאי לְהַעֲבִיר אֶת אוֹתָהּ הָעָרְלָה לְמַעְלָה מִלִּפְנֵי בְּרִית הַקָּדוֹשׁ. שֶׁהֲרֵי כָּל הַמַּעֲשִׂים שֶׁיִּשְׂרָאֵל עוֹשִׂים לְמַטָּה, מְעוֹרְרִים מַעֲשֶׂה לְמַעְלָה. וּבְאוֹתוֹ זְמַן נִדְחֵית אוֹתָהּ הָעָרְלָה מִכָּל הָעָם הַקָּדושׁ לְמַעְלָה, וּמַתְקִינִים לְאותָהּ הָעָרְלָה כְּלִי אֶחָד עִם עָפָר לְהַשְׁרוֹת אוֹתָהּ הָעָרְלָה בְּתוֹכוֹ, בְּסוֹד הַכָּתוּב (ישעיה סה) וְנָחָשׁ עָפָר לַחְמוֹ. (בראשית ג) וְעָפָר תֹּאכַל כָּל יְמֵי חַיֶּיךְ.</p>\n<p>מִכָּאן שֶׁלֹּא צָרִיךְ לִנְהֹג בִּזָּיוֹן בַּמָּקוֹם הַהוּא. אַף עַל גַּב שֶׁמַּעֲבִירִים אוֹתוֹ מֵהַבְּרִית הַזּוֹ, וּמְקוֹמוֹ כַּאֲשֶׁר נִפְרָד מֵהַבְּרִית הַזּוֹ הוּא עָפָר, (שהנה) שֶׁהֲרֵי אַחַר שֶׁהַנָּחָשׁ הַהוּא הָעֳבַר מִלִּפְנֵי הָאָדָם, הַקָּדוֹשׁ בָּרוּךְ הוּא שָׂם לוֹ אֶת מְדוֹרוֹ בֶּעָפָר, שֶׁכָּתוּב וְעָפָר תֹּאכַל כָּל יְמֵי חַיֶּיךְ. וְכֵיוָן שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא כְּשֶׁהֶעֱבִיר אוֹתוֹ מִלִּפְנֵי אָדָם, שָׂם מְדוֹרוֹ בֶּעָפָר וְהִתְקִין אוֹתוֹ, כָּךְ בְּאוֹתוֹ גָּוֶן מַמָּשׁ אָנוּ צְרִיכִים כְּשֶׁמַּעֲבִירִים אֶת הָעָרְלָה, לְהַתְקִין לָהּ עָפָר שֶׁיִּהְיֶה בּוֹ הַמָּדוֹר שֶׁלּוֹ.</p>\n<p>כָּל אָדָם צָרִיךְ לְהַקְרִיב אוֹתוֹ בֵּן קָרְבָּן לַקָּדוֹשׁ בָּרוּךְ הוּא, בְּשִׂמְחָה, בִּרְצוֹן הַלֵּב, לְהַכְנִיסוֹ תַּחַת כַּנְפֵי הַשְּׁכִינָה, וְנֶחְשָׁב לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁהוּא קָרְבָּן שָׁלֵם שֶׁיִּתְקַבֵּל בְּרָצוֹן.</p>\n<p>וְהַקָּרְבָּן הַזֶּה, כְּמוֹ קָרְבַּן הַבְּהֵמָה. זֶה לִשְׁמֹנָה יָמִים, וְזֶה לִשְׁמֹנָה יָמִים, שֶׁכָּתוּב וּמִיּוֹם הַשְּׁמִינִי וָהָלְאָה יֵרָצֶה. בַּמֶּה יֵרָצֶה? בָּזֶה שֶׁעוֹבֶרֶת עָלָיו שַׁבָּת אַחַת. כֵּיוָן שֶׁעוֹבֶרֶת עָלָיו שַׁבָּת אַחַת, אָז זֶה יֵרָצֶה לְקָרְבָּן, וְזֶה לְקָרְבָּן. לָמָּה? מִשּׁוּם שֶׁנִּדְבָּק וְנִזְדַּמֵּן אֶל אוֹתָהּ הַשַּׁבָּת, סוֹד בְּרִית הַקֹּדֶשׁ, וְעַל כֵּן הַכֹּל הוּא בְּסוֹד עֶלְיוֹן. (ע\"כ רעיא מהימנא).</p>"],[9522012047,"<p>אִשָּׁה כִּי תַזְרִיעַ וְיָלְדָה זָכָר וְגוֹ'. רַבִּי יְהוּדָה פָּתַח, (שמואל א ב) אֵין קָדוֹשׁ כַּה' כִּי אֵין בִּלְתֶּךְ וְאֵין צוּר כֵּאלֹהֵינוּ. הַפָּסוּק הַזֶּה קָשֶׁה, אֵין קָדוֹשׁ כַּה', מַשְׁמָע שֶׁיֵּשׁ קָדוֹשׁ אַחֵר, מִשּׁוּם שֶׁכָּתוּב כַּה'. וְאֵין צוּר כֵּאלֹהֵינוּ, מַשְׁמָע שֶׁיֵּשׁ צוּר אַחֵר.</p>\n<p>אֶלָּא וַדַּאי, אֵין קָדוֹשׁ כַּה', שֶׁכַּמָּה קְדוֹשִׁים הֵם, קְדוֹשִׁים לְמַעְלָה, שֶׁכָּתוּב (דניאל ד) וּמֵאמַר קַדִּישִׁין שְׁאֵלְתָא. יִשְׂרָאֵל הֵם קְדוֹשִׁים, שֶׁכָּתוּב (ויקרא יט) קְדשִׁים תִּהְיוּ. וְכֻלָּם קְדוֹשִׁים, וְלֹא קְדוֹשִׁים כַּה'. וּמָה הַטַּעַם? מִשּׁוּם שֶׁכָּתוּב כִּי אֵין בִּלְתֶּךְ. מַה זֶּה כִּי אֵין בִּלְתֶּךְ? אֶלָּא קְדֻשַּׁת הַקָּדוֹשׁ בָּרוּךְ הוּא בִּלְתִּי הַקְּדֻשָּׁה שֶׁלָּהֶם, שֶׁהוּא לֹא צָרִיךְ אֶת הַקְּדֻשָּׁה שֶׁלָּהֶם. אֲבָל הֵם אֵינָם קְדוֹשִׁים בִּלְתֶּךְ, וְזֶהוּ כִּי אֵין בִּלְתֶּךְ, אֵין הַקְּדֻשָּׁה שֶׁלָּהֶם בִּלְתֶּךְ.</p>\n<p>וְאֵין צוּר כֵּאלֹהֵינוּ. כְּמוֹ שֶׁבֵּאֲרוּהָ, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא צָר צוּרָה בְּתוֹךְ צוּרָה וּמַתְקִין אוֹתָהּ, וְנוֹפֵחַ רוּחַ חַיִּים, וּמוֹצִיא אוֹתָהּ לַאֲוִיר הָעוֹלָם. דָּבָר אַחֵר וְאֵין צוּר כֵּאלֹהֵינוּ - יֵשׁ צוּר שֶׁנִּקְרָא צוּר, (ישעיה נא) הַבִּיטוּ אֶל צוּר חֻצַּבְתֶּם. (שמות יז) וְהִכִּיתָ בַצּוּר. הִנְנִי עֹמֵד לְפָנֶיךְ שָּׁם עַל הַצּוּר בְּחֹרֵב. וְכֻלָּם נִקְרָאִים צוּר, וְאֵין צוּר בְּכֻלָּם כֵּאלֹהֵינוּ, שֶׁלּוֹ הַשִּׁלְטוֹן וְהַמַּלְכוּת עַל הַכֹּל.</p>"],[9522012048,"<p>רַבִּי חִיָּיא וְרַבִּי אָחָא הָיוּ יוֹשְׁבִים לַיְלָה אֶחָד לִפְנֵי רַבִּי אַבָּא. קָמוּ בַּחֲצוֹת הַלַּיְלָה לַעֲסֹק בַּתּוֹרָה. עַד שֶׁיָּצְאוּ הַחוּצָה, רָאוּ כּוֹכָב אֶחָד שֶׁהָיָה מַכֶּה שָׁלֹשׁ פְּעָמִים בְּכוֹכָב אַחֵר וּמַסְתִּיר אוֹרוֹ. בֵּינְתַיִם שָׁמְעוּ שְׁנֵי קוֹלוֹת בִּשְׁנֵי צְדָדִים, קוֹל אֶחָד לְצַד צָפוֹן לְמַעְלָה, וְקוֹל אֶחָד לְמַטָּה, וְהַקּוֹל הַהוּא מַכְרִיז וְאוֹמֵר: הִכָּנְסוּ וְהִתְכַּנְּסוּ לִמְקוֹמְכֶם, עַכְשָׁו הִשְׁתַּמְּרוּת שֶׁל נְקֵבָה פְּתוּחָה, הַקָּדוֹשׁ בָּרוּךְ הוּא נִכְנָס לְטַיֵּל בַּגָּן לְהִשְׁתַּעֲשֵׁעַ עִם הַצַּדִּיקִים שֶׁבַּגָּן. עָבַר אוֹתוֹ הַקּוֹל וְשָׁכַךְ.</p>\n<p>חָזְרוּ רַבִּי אָחָא וְרַבִּי חִיָּיא. אָמְרוּ, הִנֵּה וַדַּאי עֵת רָצוֹן, שֶׁהִתְעוֹרְרוּת שֶׁל כְּנֶסֶת יִשְׂרָאֵל (זמן) הִיא לְהִתְחַבֵּר עִם הַמֶּלֶךְ הַקָּדוֹשׁ. אָמַר רַבִּי אָחָא, וַדַּאי לֹא (מתחברת) מֻשְׁפַּעַת לָהּ כְּנֶסֶת יִשְׂרָאֵל עִם הַקָּדוֹשׁ בָּרוּךְ הוּא אֶלָּא מִתּוֹךְ שִׁירָה וּמִתּוֹךְ הַשֶּׁבַח שֶׁלָּהּ אֵלָיו. עַד שֶׁבָּא הַבּקֶר, וּמוֹשִׁיט לָהּ הַמֶּלֶךְ חוּט שֶׁל חֶסֶד, וְסוֹד הַדָּבָר כְּמוֹ שֶׁאָמַרְנוּ, (אסתר ה) וַיּוֹשֶׁט הַמֶּלֶךְ לְאֶסְתֵּר אֶת שַׁרְבִיט הַזָּהָב אֲשֶׁר בְּיָדוֹ וְגוֹ'. וְאַל תֹּאמַר שֶׁלָּהּ לְבַדָּהּ מוֹשִׁיט הַמֶּלֶךְ אֶת זֶה, אֶלָּא לָהּ, וּלְכָל אוֹתָם שֶׁמִּתְחַבְּרִים עִמָּהּ. בֹּא וְנִתְחַבֵּר יַחַד. יָשְׁבוּ.</p>"],[9522012049,"<p>פָּתַח רַבִּי אָחָא וְאָמַר, (בראשית ב) וַיֹּאמֶר ה' אֱלֹהִים לֹא טוֹב הֱיוֹת הָאָדָם לְבַדּוֹ וְגוֹ'. לָמָּה פָּתַח הַפָּסוּק כָּךְ? אֶלָּא הִנֵּה נִתְבָּאֵר, שֶׁעַל זֶה לֹא כָתוּב כִּי טוֹב בַּשֵּׁנִי, מִשּׁוּם שֶׁעָתִיד אָדָם לְהִפָּרֵד, וְכָתוּב לֹא טוֹב הֱיוֹת הָאָדָם לְבַדּוֹ.</p>\n<p>וְכִי לְבַדּוֹ הָיָה? וַהֲרֵי כָּתוּב (שם ה) זָכָר וּנְקֵבָה בְּרָאָם. וְשָׁנִינוּ, אָדָם דּוּ פַרְצוּפִים נִבְרָא, וְאַתָּה אוֹמֵר לֹא טוֹב הֱיוֹת הָאָדָם לְבַדּוֹ?! אֶלָּא שֶׁלֹּא הִשְׁתַּדֵּל עִם נְקֵבָתוֹ, וְלֹא הָיְתָה לוֹ עֵזֶר כְּנֶגְדּוֹ, מִשּׁוּם שֶׁהָיְתָה בְּצִדּוֹ, וְהָיוּ יַחַד מֵאָחוֹר, וְאָז הָיָה הָאָדָם לְבַדּוֹ.</p>\n<p>אֶעָשֶׂה לּוֹ עֵזֶר כְּנֶגְדּוֹ. מַה זֶּה כְּנֶגְדּוֹ? כְּנֶגֶד פָּנָיו, לְהִדָּבֵק זֶה עִם זֶה פָּנִים בְּפָנִים. מֶה עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא? נִסֵּר אוֹתוֹ וְנָטַל הַנְּקֵבָה מִמֶּנּוּ, זֶהוּ שֶׁכָּתוּב וַיִּקַּח אַחַת מִצַּלְעֹתָיו. מַה זֶּה אַחַת? זוֹ הַנְּקֵבָה שֶׁלּוֹ, כְּמוֹ שֶׁנֶּאֱמַר אַחַת הִיא יוֹנָתִי תַמָּתִי. וַיְבִיאֶהָ אֶל הָאָדָם, הִתְקִינָהּ כְּכַלָּה, וְהֵבִיא אוֹתָהּ לִהְיוֹת כְּנֶגֶד פָּנָיו הַמְּאִירוֹת פָּנִים בְּפָנִים. וּבְעוֹד שֶׁהָיְתָה דְבוּקָה הַנְּקֵבָה בְּצִדּוֹ, הָיָה הָאָדָם לְבַדּוֹ. אַחַר כָּךְ עָלוּ שְׁנַיִם, וְקָמוּ שֶׁבַע יַחַד.</p>\n<p>בֹּא רְאֵה, בְּשָׁעָה שֶׁנִּכְנְסָה (שהתתקנה) אֵצֶל אָדָם, הַקָּדוֹשׁ בָּרוּךְ הוּא בֵּרַךְ אוֹתָם, זֶהוּ שֶׁכָּתוּב (שם א) וַיְבָרֶךְ אֹתָם אֱלֹהִים, כְּחַזָּן שֶׁמְּבָרֵךְ אֶת הַכַּלָּה בְּשֶׁבַע בְּרָכוֹת. מִכָּאן לָמַדְנוּ, חָתָן וְכַלָּה, כֵּיוָן שֶׁמִּתְבָּרְכִים בְּשֶׁבַע בְּרָכוֹת, נִדְבָּקִים יַחַד, כְּמוֹ דֻגְמָא שֶׁלְּמַעְלָה.</p>\n<p>וְעַל כֵּן, מִי שֶׁבָּא לְהִתְחַבֵּר עִם אִשָּׁה שֶׁל שֶׁל אַחֵר, הִנֵּה פּוֹגֵם אֶת הַזִּוּוּג, (כביכול עושה שתי רשיות למעלה) שֶׁהֲרֵי הַזִּוּוּג שֶׁל כְּנֶסֶת יִשְׂרָאֵל עִם הַקָּדוֹשׁ בָּרוּךְ הוּא לְבַדּוֹ, בִּזְמַן שֶׁהוּא בְּרַחֲמִים וּבִזְמַן שֶׁהוּא בְּדִין. בּא רְאֵה, מִי שֶׁמִּתְחַבֵּר לְאִשָּׁה שֶׁל אַחֵר, כְּאִלּוּ מְשַׁקֵּר בַּקָּדוֹשׁ-בָּרוּךְ-הוּא וּבִכְנֶסֶת יִשְׂרָאֵל, וְעַל זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא לֹא מְכַפֵּר לוֹ בִּתְשׁוּבָה, וְהַתְּשׁוּבָה תְלוּיָה עַד שֶׁיִּסְתַּלֵּק מִן הָעוֹלָם. זֶהוּ שֶׁכָּתוּב (ישעיה כב) אִם יְכֻפַּר הֶעָון הַזֶּה לָכֶם עַד תְּמֻתוּן. וּמָתַי? בְּשָׁעָה שֶׁנִּכְנָס בִּתְשׁוּבָה לָעוֹלָם הַהוּא, וְיֵשׁ לוֹ לְקַבֵּל עֹנֶשׁ.</p>\n<p>רַבִּי אֶלְעָזָר אָמַר, מִי שֶׁמְּשַׁקֵּר בִּכְנֶסֶת יִשְׂרָאֵל לֹא יִתְקַבֵּל בִּתְשׁוּבָה עַד שֶׁיִּדּוֹן בְּדִין שֶׁל גֵּיהִנֹּם. כָּל שֶׁכֵּן מִי שֶׁמְּשַׁקֵּר בִּכְנֶסֶת יִשְׂרָאֵל וּבַקָּדוֹשׁ-בָּרוּךְ- הוּא. וְכָל שֶׁכֵּן אִם מַטְרִיחַ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא לַעֲשׂוֹת דְּמוּת שֶׁל מַמְזֵר בְּאִשְׁתּוֹ שֶׁל הָאַחֵר וּמַכְחִישׁ אֶת פִּרְסוּם הַמֶּלֶךְ.</p>"],[9522012050,"<p>רַבִּי חִיָּיא פָּתַח וְאָמַר, (משליכ) גּוֹזֵל אָבִיו וְאִמּוֹ וְגוֹ'. אָבִיו - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא. אִמּוֹ - זוֹ כְּנֶסֶת יִשְׂרָאֵל. מַה גּוֹזֵל? כְּמוֹ שֶׁנֶּאֱמַר (ישעיה ג) גְּזֵלַת הֶעָנִי בְּבָתֵּיכֶם. וּמִי הִיא? מִי שֶׁחוֹמֵד אִשָּׁה אַחֶרֶת שֶׁאֵינָהּ בַּת זוּגוֹ.</p>\n<p>שָׁם שָׁנִינוּ, כָּל הַנֶּהֱנֶה מִן הָעוֹלָם הַזֶּה בְּלֹא בְרָכָה, כְּאִלּוּ גּוֹזֵל אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא וְאֶת כְּנֶסֶת יִשְׂרָאֵל, שֶׁכָּתוּב גּוֹזֵל אָבִיו וְאִמּוֹ וְגוֹ'. כָּל הַנֶּהֱנֶה מִן הָעוֹלָם הַזֶּה, כְּלָל זֶה הוּא הָאִשָּׁה. מִי שֶׁנִּדְבָּק בְּאִשָּׁה לֵהָנוֹת מִמֶּנָּה, וְאַף עַל גַּב שֶׁהִיא פְּנוּיָה, וְנֶהֱנֶה מִמֶּנָּה בְּלֹא בְרָכָה, כְּאִלּוּ גּוֹזֵל אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא וְאֶת כְּנֶסֶת יִשְׂרָאֵל. מָה הַטַּעַם? מִשּׁוּם שֶׁהַזִּוּוּג שֶׁלָּהֶם הוּא בְּשֶׁבַע בְּרָכוֹת. וּמָה עַל פְּנוּיָה כָּךְ - מִי שֶׁנִּדְבָּק בְּאִשְׁתּוֹ שֶׁל אַחֵר, שֶׁעוֹמֵד כְּמוֹ שֶׁלְּמַעְלָה, בְּזִוּוּג שֶׁל שֶׁבַע בְּרָכוֹת, עַל אַחַת כַּמָּה וְכַמָּה.</p>\n<p>חָבֵר הוּא לְאִישׁ מַשְׁחִית - זֶה יָרָבְעָם, כְּמוֹ שֶׁבֵּאֲרוּהָ, וְאֹמֵר אֵין פָּשַׁע, שֶׁאוֹמֵר הִנֵּה הִיא פְּנוּיָה, לָמָּה אָסוּר? מִשּׁוּם זֶה הוּא גּוֹזֵל אָבִיו וְאִמּוֹ. וְלֹא עוֹד, אֶלָּא שֶׁחָבֵר הוּא לְאִישׁ מַשְׁחִית. מִי הוּא אִישׁ מַשְׁחִית? שֶׁפּוֹגֵם הַדְּמוּת וְהַתִּקּוּן שֶׁל מַעְלָה. כָּל שֶׁכֵּן מִי שֶׁחוֹמֵד אֶת אִשְׁתּוֹ שֶׁל חֲבֵרוֹ לְהִדָּבֵק (ונדבק בה) עִמָּהּ, שֶׁפּוֹגֵם יוֹתֵר, וְעַל זֶה הוּא נִפְגָּם לְעוֹלָמִים. אִישׁ מַשְׁחִית - שֶׁפּוֹגֵם לְמַעְלָה, וּפוֹגֵם לְמַטָּה, וּפוֹגֵם אֶת נַפְשׁוֹ, שֶׁכָּתוּב מַשְׁחִית, וְכָתוּב (משלי ו) מַשְׁחִית נַפְשׁוֹ הוּא יַעֲשֶׂנָּה.</p>"],[9522012051,"<p>רַבִּי אַבָּא פָּתַח וְאָמַר, (בראשית לב) וַיֹּאמֶר שַׁלְּחֵנִי כִּי עָלָה הַשָּׁחַר וְגוֹ'. וַיֹּאמֶר שַׁלְּחֵנִי, וְכִי קָשׁוּר הָיָה בְיָדוֹ שֶׁל יַעֲקֹב? אֶלָּא אַשְׁרֵיהֶם הַצַּדִּיקִים שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא חָס עַל כְּבוֹדָם וְלֹא עוֹזֵב אוֹתָם לְעוֹלָמִים. זֶהוּ שֶׁכָּתוּב (תהלים נה) לֹא יִתֵּן לְעוֹלָם מוֹט לַצַּדִּיק. וְהִנֵּה כָּתוּב, וַתֵּקַע כַּף יֶרֶךְ יַעֲקֹב.</p>\n<p>אֶלָּא אֶת שֶׁלּוֹ גָּבָה. וְהִנֵּה נִתְבָּאֵר, כָּתוּב (בראשית לב) וְהוּא לָן בַּלַּיְלָה הַהוּא בַּמַּחֲנֶה. וְכָתוּב וַיִּקָּחֵם וַיַּעֲבִרֵם אֶת הַנָּחַל. מֶה הָיְתָה דַעְתּוֹ שֶׁל יַעֲקֹב לְהַעֲבִירֵם בַּנַּחַל בַּלַּיְלָה? אֶלָּא רָאָה אֶת הַמְקַטְרֵג הוֹלֵךְ בֵּין הַמַּחֲנֶה שֶׁלּוֹ, אָמַר יַעֲקֹב, אֶעֱבֹר לַצַּד הָאַחֵר שֶׁל הַנָּהָר, אוּלַי לֹא יִמָּצֵא עִרְבּוּבְיָה.</p>\n<p>מָה רָאָה? רָאָה שַׁלְהֶבֶת שֶׁל אֵשׁ לוֹהֶטֶת, הוֹלֶכֶת וְטָסָה בֵּין מַחֲנוֹתָיו. אָמַר יַעֲקֹב, מוּטָב לִנְסֹעַ מִכָּאן, וְהַנָּהָר מַפְסִיק בֵּינֵינוּ, וְלֹא תִמָּצֵא עִרְבּוּבְיָה. מִיָּד - וַיִּקָּחֵם וַיַּעֲבִרֵם אֶת הַנָּחַל. וַיִּוָּתֵר יַעֲקֹב לְבַדּוֹ, מִכָּאן לָמַדְנוּ, מִי שֶׁנִּמְצָא לְבַדּוֹ בַּבַּיִת בַּלַּיְלָה, אוֹ בַּיּוֹם בְּבַיִת מְיֻחָד, כָּל שֶׁכֵּן בַּלַּיְלָה, מַה זֶּה מְיֻחָד? מְיֻחָד מִשְּׁאָר הַבָּתִּים, אוֹ מִי שֶׁהוֹלֵךְ לְבַדּוֹ בַּלַּיְלָה, יָכוֹל לְהִנָּזֵק.</p>\n<p>בֹּא רְאֵה, וַיִּוָּתֵר יַעֲקֹב לְבַדּוֹ, אָז - וַיֵּאָבֵק אִישׁ עִמּוֹ וְגוֹ'. שָׁנִינוּ, הוּא בָּא מִצַּד הַדִּין, וְשִׁלְטוֹנוֹ בַּצַּד שֶׁל הַלַּיְלָה. מַה זֶּה בְּצַד הַלַּיְלָה? לְהִכָּנֵס לַגָּלוּת (בגלותם). כֵּיוָן שֶׁעָלָה הָאוֹר, תָּשַׁשׁ כֹּחוֹ, וּמִתְגַּבֵּר עָלָיו הַכֹּחַ שֶׁל יַעֲקֹב, (הוא) שֶׁהֲרֵי מִצַּד הַלַּיְלָה הוּא בָּא. וּבִזְמַן שֶׁהָיָה לַיְלָה, לֹא הָיָה יָכוֹל לוֹ יַעֲקֹב. כְּשֶׁעָלָה הָאוֹר, הִתְחַזֵּק הַכֹּחַ שֶׁל יַעֲקֹב וְאָחַז בּוֹ, וְהִתְגַּבֵּר עָלָיו. רָאָה אוֹתוֹ יַעֲקֹב שֶׁהִנֵּה הוּא שָׁלִיחַ.</p>\n<p>אָמַר לוֹ, עֲזֹּב אוֹתְךְ, שֶׁאֵינִי יָכוֹל לְךְ. מָה הַטַּעַם לֹא יָכֹל לוֹ? מִשּׁוּם שֶׁהָיָה עוֹלֶה הָאוֹר, וְנִשְׁבַּר הַכֹּחַ שֶׁלּוֹ, שֶׁכָּתוּב (איוב לח) בְּרָן יַחַד כֹּכְבֵי בֹקֶר וַיָּרִיעוּ כָּל בְּנֵי אֱלֹהִים. מַה זֶּה וַיָּרִיעוּ? שֶׁנִּשְׁבְּרוּ כָּל אוֹתָם שֶׁבָּאִים מִצַּד הַדִּין. אָז הִתְחַזֵּק יַעֲקֹב וְאָחַז בּוֹ.</p>\n<p>אָמַר לוֹ, שַׁלְּחֵנִי כִּי עָלָה הַשָּׁחַר, הִגִּיעַ הַזְּמַן לְשַׁבֵּחַ אֶת שִׁבְחוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא וּלְהִתְכַּנֵּס. וַיֹּאמֶר לֹא אֲשַׁלֵּחֲךְ כִּי אִם בֵּרַכְתָּנִי. אִם תְּבָרְכֵנִי הָיָה צָרִיךְ לִהְיוֹת! מַה זֶּה אִם בֵּרַכְתָּנִי? אֶלָּא אָמַר לוֹ יַעֲקֹב, וַדַּאי שֶׁאַבָּא בֵּרַךְ אוֹתִי אוֹתָן הַבְּרָכוֹת שֶׁרָצָה לְבָרֵךְ אֶת עֵשָׂו, וַאֲנִי פּוֹחֵד מִמְּךְ עַל אוֹתָן הַבְּרָכוֹת, אִם תּוֹדֶה לִי עֲלֵיהֶן (או) אִם לָאו, אוֹ שֶׁיִּמָּצֵא עָלַי מְקַטְרֵג בִּגְלָלָם.</p>\n<p>מִיָּד אָמַר לוֹ, וַיֹּאמֶר לֹא יַעֲקֹב יֵאָמֵר עוֹד שִׁמְךְ. מָה אָמַר לוֹ? אֶלָּא כָּךְ אָמַר לוֹ, לֹא בְהִתְחַכְּמוּת וְלֹא בַעֲקֵבוּת (שלך) הִרְוַחְתָּ אֶת אוֹתָן הַבְּרָכוֹת, לֹא יֵאָמֵר עוֹד שִׁמְךְ יַעֲקֹב, שֶׁהֲרֵי לֹא בַעֲקֵבוּת זֶה הָיָה, כִּי אִם יִשְׂרָאֵל, וַדַּאי יִשְׂרָאֵל הוֹדָה עָלֶיךְ וּמִמֶּנּוּ יָצְאוּ הַבְּרָכוֹת, מִשּׁוּם שֶׁאַתָּה אָחוּז בּוֹ, וְעַל זֶה אֲנִי וְכָל שְׁאָר הָאוּכְלוּסִין הוֹדֵינוּ עֲלֵיהֶן.</p>\n<p>כִּי שָׂרִיתָ עִם אֱלֹהִים וְאִם אֲנָשִׁים וַתּוּכָל. עִם אֱלֹהִים - כָּל אוֹתָם שֶׁבָּאִים מִצַּד הַדִּין הַקָּשֶׁה. וְעִם אֲנָשִׁים - זֶה עֵשָׂו וְהָאוּכְלוּסִים שֶׁלּוֹ. וַתּוּכָל - יָכֹלְתָּ לָהֶם, וְהֵם לֹא יָכְלוּ לְךְ. וְלֹא עָזַב אוֹתוֹ יַעֲקֹב עַד שֶׁהוֹדָה לוֹ עַל אוֹתָן הַבְּרָכוֹת. זֶהוּ שֶׁכָּתוּב וַיְבָרֶךְ אֹתוֹ שָׁם.</p>\n<p>בֹּא רְאֵה, בְּשָׁעָה שֶׁעָלָה הָאוֹר, נִכְנָעִים כָּל אוֹתָם בַּעֲלֵי הַדִּינִים וְאֵינָם נִמְצָאִים, וּכְנֶסֶת יִשְׂרָאֵל מְסַפֶּרֶת עִם הַקָּדוֹשׁ בָּרוּךְ הוּא. וְאוֹתָהּ הַשָּׁעָה הִיא עֵת רָצוֹן לַכֹּל, וּמוֹשִׁיט לָהּ הַמֶּלֶךְ וּלְכָל אוֹתָם שֶׁנִּמְצָאִים עִמָּהּ שַׁרְבִיט שֶׁל חוּט שֶׁל חֶסֶד, לְהִמָּצֵא בִשְׁלֵמוּת עִם הַמֶּלֶךְ הַקָּדוֹשׁ, וְהִנֵּה נִתְבָּאֵר.</p>\n<p>בֹּא רְאֵה, בְּשָׁעָה שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא נִמְצָא עִם כְּנֶסֶת יִשְׂרָאֵל, בְּאוֹתָם הַזְּמַנִּים שֶׁנִּמְצָא עִמָּהּ, וְהִיא מְעוֹרֶרֶת רָצוֹן אֵלָיו בָּרִאשׁוֹנָה, וּמוֹשֶׁכֶת אוֹתוֹ אֵלֶיהָ בְּרֹב חִבָּה וּתְשׁוּקָה, אָז מִתְמַלֵּאת מִצַּד הַיָּמִין, וְכַמָּה אוּכְלוּסִים נִמְצָאִים בְּצַד הַיָּמִין בְּכָל הָעוֹלָמוֹת. וּכְשֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מֵעִיר חֲבִיבוּת וְרָצוֹן בָּרִאשׁוֹנָה, וְהִיא מְעִירָה אַחַר כָּךְ, וְלֹא בִּזְמַן שֶׁהוּא מֵעִיר, אָז הַכֹּל נִמְצָא בְּצַד הַנְּקֵבָה, וְהַשְּׂמֹאל מִתְעוֹרֵר, וְכַמָּה אוּכְלוּסִים עוֹמְדִים וּמִתְעוֹרְרִים בְּצַד הַשְּׂמֹאל בְּכָל הָעוֹלָמוֹת. כָּךְ גַּם כָּתוּב, (זהושכתוב) אִשָּׁה כִּי תַזְרִיעַ וְיָלְדָה זָכָר וְגוֹ'. מָה הַטַּעַם? שָׁנִינוּ, הָעוֹלָם הַתַּחְתּוֹן נִמְצָא כְּמוֹ הָעוֹלָם הָעֶלְיוֹן, וְזֶה כְּדֻגְמָא שֶׁל זֶה.</p>\n<p>וְעַל זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא גּוֹזֵר זָכָר אוֹ נְקֵבָה, שֶׁיִּמָּצֵא רָצוֹן בָּעוֹלָם. וּבַכֹּל צָרִיךְ אָדָם לְהַדְבִּיק רָצוֹן לְמַעְלָה אֶל הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁיִּמָּצְאוּ רְצוֹנוֹת בָּעוֹלָם. אַשְׁרֵי חֶלְקָם שֶׁל הַצַּדִּיקִים, שֶׁהֵם יוֹדְעִים לְהַדְבִּיק אֶת רְצוֹנָם אֶל הַמֶּלֶךְ הַקָּדוֹשׁ, עֲלֵיהֶם כָּתוּב, (דברים ד) וְאַתֶּם הַדְּבֵקִים בַּה' אֱלֹהֵיכֶם חַיִּים כֻּלְּכֶם הַיּוֹם.</p>"],[9522012052,"<p>אָדָם כִּי יִהְיֶה בְעוֹר בְּשָׂרוֹ שְׂאֵת אוֹ סַפַּחַת אוֹ בַהֶרֶת וְגוֹ'. רַבִּי יְהוּדָה פָּתַח וְאָמַר, (שיר א) אַל תִּרְאֻנִי שֶׁאֲנִי שְׁחַרְחֹרֶת שֶׁשְּׁזָפַתְנִי הַשָּׁמֶשׁ. הַפָּסוּק הַזֶּה נִתְבָּאֵר, אֲבָל בְּשָׁעָה שֶׁהַלְּבָנָה מִתְכַּסֵּית בַּגָּלוּת, הִיא אוֹמֶרֶת, אַל תִּרְאֻנִי. לֹא שֶׁהִיא מְצַוָּה שֶׁלֹּא לִרְאוֹת אוֹתָהּ, אֶלָּא מִשּׁוּם שֶׁהִיא רוֹאָה אֶת תְּשׁוּקָתָם שֶׁל יִשְׂרָאֵל אֵלֶיהָ, לִרְאוֹת אֶת אוֹרָהּ, הִיא אוֹמֶרֶת אַל תִּרְאֻנִי, לֹא תוּכְלוּ לִרְאוֹת אוֹתִי. אַל תִּרְאֻנִי וַדַּאי. מָה הַטַּעַם? מִשּׁוּם שֶׁאֲנִי שְׁחַרְחֹרֶת, מִשּׁוּם שֶׁאֲנִי בְּקַדְרוּת.</p>\n<p>מַה זֶּה שְׁחַרְחֹרֶת? שְׁחֹרָה הָיָה צָרִיךְ לִהְיוֹת! אֶלָּא שְׁתֵּי קַדְרֻיּוֹת, אַחַת - שֶׁשְּׁזָפַתְנִי הַשָּׁמֶשׁ, שֶׁהִסְתַּלֵּק מִמֶּנִּי הַשֶּׁמֶשׁ לְהָאִיר לִי וּלְהִסְתַּכֵּל בִּי, וְאַחַת - שֶׁבְּנֵי אִמִּי נִחֲרוּ בִי.</p>\n<p>שֶׁשְּׁזָפַתְנִי?! שְׁזָפַתְנִי הָיָה צָרִיךְ לִהְיוֹת! אֶלָּא רֶמֶז הוּא רוֹמֵז, בְּשֵׁשׁ. שֶׁכַּאֲשֶׁר מֵאִיר הַשֶּׁמֶשׁ, בְּשִׁשָּׁה אוֹרוֹת הוּא מֵאִיר, וּכְשֶׁמִּסְתַּלֵּק, כָּל אוֹתָם שֵׁשֶׁת הָאוֹרוֹת מִסְתַּלְּקִים. בְּנֵי אִמִּי - אֵלּוּ הֵם שֶׁבָּאִים מִצַּד הַדִּין הַקָּשֶׁה. נִחֲרוּ בִי, כְּמוֹ שֶׁנֶּאֱמַר נִחַר גְּרוֹנִי. זֶהוּ שֶׁכָּתוּב (איכה ה) עַל צַוָּארֵנוּ נִרְדָּפְנוּ. שֶׁכַּאֲשֶׁר הָיוּ יִשְׂרָאֵל נִכְנָסִים לַגָּלוּת, הָיוּ הוֹלְכִים יְדֵיהֶם מְהֻדָּקוֹת לְאָחוֹר, וְרֵחַיִם עַל צַוָּארָם, וְלֹא יָכְלוּ לִפְתֹּחַ אֶת הַפֶּה.</p>\n<p>שָׂמוּנִי נֹטֵרָה אֶת הַכְּרָמִים, לָלֶכֶת לַגָּלוּת, לִשְׁמֹר אֶת שְׁאָר הָעַמִּים בִּשְׁבִיל יִשְׂרָאֵל. כַּרְמִי שֶׁלִּי לֹא נָטָרְתִּי, שֶׁהֲרֵי לֹא יָכֹלְתִּי לִשְׁמֹר אוֹתָם כְּבָרִאשׁוֹנָה. בָּרִאשׁוֹנָה שָׁמַרְתִּי אֶת כַּרְמִי שֶׁלִּי, וּמִמֶּנּוּ נִשְׁמְרוּ שְׁאָר הַכְּרָמִים. עַכְשָׁו אֲנִי שׁוֹמֶרֶת אֶת שְׁאָר הַכְּרָמִים בִּשְׁבִיל כַּרְמִי שֶׁלִּי שֶׁיִּהְיֶה שָׁמוּר בֵּינֵיהֶם.</p>"],[9522012053,"<p>רַבִּי חִיָּיא וְרַבִּי יוֹסֵי הָיוּ הוֹלְכִים בַּדֶּרֶךְ. כְּשֶׁהִגִּיעוּ לְשָׂדֶה אַחַת, רָאוּ עֵץ אֲפַרְסְמוֹן אֶחָד בְּצַד יְמִין הַדֶּרֶךְ. אָמַר רַבִּי יוֹסֵי, עֲטִיפָה שֶׁל עָשָׁן מְצוּיָה בָעֵינַיִם, אֵין לָנוּ רְשׁוּת לִרְאוֹת בְּשִׂמְחָה מִיּוֹם שֶׁחָרַב בֵּית הַמִּקְדָּשׁ.</p>\n<p>פָּתַח וְאָמַר, (תהלים כד) לַה' הָאָרֶץ וּמְלוֹאָהּ תֵּבֵל וְיֹשְׁבֵי בָהּ. כֵּיוָן שֶׁאָמַר לַה' הָאָרֶץ וּמְלוֹאָהּ, לָמָּה תֵּבֵל וְיֹשְׁבֵי בָהּ? וְכִי תֵבֵל אֵינֶנָּה מִן הָאָרֶץ? אֶלָּא כָּךְ אָמַר, לַה' הָאָרֶץ וּמְלוֹאָהּ - זוֹ הָאָרֶץ הַקְּדוֹשָׁה, שֶׁנִּקְרֵאת עֵץ הַחַיִּים. תֵּבֵל וְיֹשְׁבֵי בָהּ - אֵלּוּ שְׁאָר הָאֲרָצוֹת, כְּמוֹ שֶׁנֶּאֱמַר (שם ט) וְהוּא יִשְׁפֹּט תֵּבֵל בְּצֶדֶק, שֶׁתֵּבֵל תְּלוּיָה בְצֶדֶק, וְהַכֹּל דָּבָר אֶחָד.</p>\n<p>רַבִּי חִיָּיא אָמַר, לַה' הָאָרֶץ וּמְלוֹאָהּ, מֵילָא הָאָרֶץ, מַה זֶּה וּמְלוֹאָהּ? אֶלָּא אֵלּוּ נִשְׁמוֹת הַצַּדִּיקִים. תֵּבֵל וְיֹשְׁבֵי בָהּ. תֵּבֵל - זוֹ הָאָרֶץ שֶׁלְּמַטָּה. וְיֹשְׁבֵי בָהּ - אֵלּוּ הֵם בְּנֵי הָאָדָם. אָמַר רַבִּי יוֹסֵי, אִם כָּךְ, בַּמֶּה בֵּאַרְנוּ כִּי הוּא עַל יַמִּים יְסָדָהּ וְעַל נְהָרוֹת יְכוֹנְנֶהָ? אָמַר לוֹ, וַדַּאי כָּךְ זֶה, שֶׁאוֹתָהּ אֶרֶץ הַחַיִּים עַל יַמִּים יְסָדָהּ וְעַל נְהָרוֹת יְכוֹנְנֶהָ, שֶׁכֻּלָּם יוֹצְאִים מֵאוֹתוֹ הַנָּהָר הָעֶלְיוֹן שֶׁשּׁוֹפֵעַ וְיוֹצֵא מֵעֵדֶן, וּבָהֶם מִתְתַּקֶּנֶת לְהִתְעַטֵּר עִם הַמֶּלֶךְ הַקָּדוֹשׁ וְלָזוּן אֶת הָעוֹלָמוֹת. (ומשום כך)</p>\n<p>מִי יַעֲלֶה בְהַר ה' וְגוֹ', נְקִי כַפַּיִם וּבַר לֵבָב אֲשֶׁר לֹא נָשָׂא נַפְשִׁי וְגוֹ'. נַפְשׁוֹ כָּתוּב, מַה זֶּה נַפְשִׁי וְנַפְשׁוֹ? אֶלָּא הַכֹּל דָּבָר אֶחָד, כְּמוֹ שֶׁנֶּאֱמַר (עמוס ו) נִשְׁבַּע אֲדנָי יֱהִֹוִה בְּנַפְשׁוֹ. (שמואל א ב) כַּאֲשֶׁר בִּלְבָבִי וּבְנַפְשִׁי יַעֲשֶׂה. וְדָוִד הַמֶּלֶךְ נֶאֱחַז בְּאוֹתוֹ לֵב וּבְאוֹתָהּ נֶפֶשׁ, וְעַל כֵּן לֹא נָשָׂא לַשָּׁוְא נַפְשׁוֹ.</p>"],[9522012054,"<p>בְּעוֹדָם הוֹלְכִים, פָּגְשׁוּ בְאִישׁ אֶחָד, וּפָנָיו מְלֵאוֹת בְּמַכּוֹת, וְהָיָה קָם מִתַּחַת אִילָן אֶחָד. הִסְתַּכְּלוּ בוֹ, וְרָאוּ פָנָיו אֲדֻמּוֹת בְּאוֹתָן הַמַּכּוֹת. אָמַר רַבִּי חִיָּיא, מִי אַתָּה? אָמַר לוֹ, אֲנִי יְהוּדִי. אָמַר רַבִּי יוֹסֵי, חוֹטֵא הוּא, שֶׁאִם לֹא כָּךְ, לֹא נִרְשְׁמוּ פָנָיו בְּאֵלּוּ הֶחֳלָאִים הָרָעִים, וְאֵלּוּ לֹא נִקְרָאִים יִסּוּרִים שֶׁל אַהֲבָה. אָמַר רַבִּי חִיָּיא, כָּךְ הוּא וַדַּאי, שֶׁיִּסּוּרִים שֶׁל אַהֲבָה מְכֻסִּים הֵם מִבְּנֵי אָדָם.</p>\n<p>בֹּא רְאֵה, שֶׁכָּתוּב אָדָם כִּי יִהְיֶה בְעוֹר בְּשָׂרוֹ שְׂאֵת אוֹ סַפַּחַת אוֹ בַהֶרֶת. הִנֵּה שְׁלֹשָׁה מִינִים כָּאן, וְכֻלָּם נִקְרָאִים נֶגַע צָרַעַת. זֶהוּ שֶׁכָּתוּב וְהָיָה בְעוֹר בְּשָׂרוֹ לְנֶגַע צָרָעַת. מַה זֶּה נֶגַע צָרָעַת? הַסְגָּרָה, הַסְגָּרָה בַּכֹּל, וְכָתוּב וְהוּבָא אֶל אַהֲרֹן הַכֹּהֵן וְגוֹ'. אֲבָל אוֹתָם שֶׁיֵּרָאוּ לַחוּץ, כָּתוּב וְרָאָהוּ הַכֹּהֵן וְטִמֵּא אֹתוֹ. שֶׁהֲרֵי וַדַּאי אוֹתָם שֶׁיֵּרָאוּ בַחוּץ בִּבְנֵי אָדָם, הֵם בָּאִים מִצַּד הַטֻּמְאָה, וְאֵינָם יִסּוּרִים שֶׁל אַהֲבָה.</p>\n<p>אָמַר רַבִּי יוֹסֵי, מִנַּין לָנוּ? אָמַר רַבִּי חִיָּיא, שֶׁכָּתוּב (משלי כז) טוֹבָה תּוֹכַחַת מְגֻלָּה מֵאַהֲבָה מְסֻתָּרֶת. אֵיזוֹהִי תוֹכַחַת מֵאַהֲבָה? (זוהי תוכחת מאהבה כאשר היא) מְסֻתָּרֶת מִבְּנֵי אָדָם. כְּמוֹ זֶה מִי שֶׁמּוֹכִיחַ אֶת חֲבֵרוֹ בְּאַהֲבָה, צָרִיךְ לְהַסְתִּיר דְּבָרָיו מִבְּנֵי אָדָם, שֶׁלֹּא יִתְבַּיֵּשׁ מֵהֶם חֲבֵרוֹ. וְאִם דְּבָרָיו הֵם בְּגָלוּי לִפְנֵי בְּנֵי אָדָם, אֵינָם בְּאַהֲבָה.</p>\n<p>כָּךָ הַקָּדוֹשׁ בָּרוּךְ הוּא, כְּשֶׁמּוֹכִיחַ אֶת הָאָדָם, בַּכֹּל הוּא מוֹכִיחַ בְּאַהֲבָה. בָּרִאשׁוֹנָה מַכֶּה אוֹתוֹ בְּגוּפוֹ בִּפְנִים. אִם חוֹזֵר בּוֹ - מוּטָב, וְאִם לֹא - מַכֶּה אוֹתוֹ תַּחַת לְבוּשׁוֹ, וְאֵלּוּ (בעורו) נִקְרָאִים יִסּוּרִים שֶׁל אַהֲבָה. אִם חָזַר בּוֹ - מוּטָב, וְאִם לֹא - מַכֶּה אוֹתוֹ בְּגָלוּי בְּפָנָיו, לִפְנֵי כֻלָּם, כְּדֵי שֶׁיִּסְתַּכְּלוּ בוֹ וְיֵדְעוּ שֶׁהִנֵּה הוּא חוֹטֵא, וְלֹא אָהוּב שֶׁל רִבּוֹנוֹ הוּא.</p>\n<p>אָמַר לָהֶם אוֹתוֹ הָאִישׁ, בְּקֶשֶׁר שֶׁל עֵצָה אַחַת בָּאתֶם אֵלַי, וַדַּאי אֵינְכֶם אֶלָּא מֵאוֹתָם שֶׁדִּיּוּרָם בְּבֵית רַשְׁבִּ\"י, שֶׁלֹּא פוֹחֲדִים מֵהַכֹּל. אִם בָּנַי שֶׁבָּאִים אַחֲרַי יִתְגָּרוּ בָכֶם, אֵיךְ דִּבְרֵיכֶם בְּגָלוּי? אָמַר לוֹ, הַתּוֹרָה כָּךְ הִיא, שֶׁכָּתוּב (משלי א) בְּרֹאשׁ הֹמִיּוֹת תִּקְרָא בְּפִתְחֵי שְׁעָרִים בָּעִיר אֲמָרֶיהָ תֹאמֵר. וּמָה אִם בְּדִבְרֵי תוֹרָה אָנוּ פוֹחֲדִים מִפָּנֶיךְ, הֲרֵי נִמָּצֵא בְּבוּשָׁה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וְלֹא עוֹד, אֶלָּא שֶׁהַתּוֹרָה צְרִיכָה צַחוּת. פָּתַח אוֹתוֹ הָאִישׁ וְאָמַר, (מיכה ז) מִי אֵל כָּמוֹךְ נֹשֵׂא עָון וְגוֹ'. הֵרִים יָדָיו וּבָכָה. בֵּינְתַיִם הִגִּיעוּ בָנָיו. אָמַר בְּנוֹ הַקָּטָן, יֵשׁ כָּאן סִיּוּעַ שְׁמֵימִי.</p>"],[9522012055,"<p>פָּתַח וְאָמַר, (קהלת ז) אֶת הַכֹּל רָאִיתִי בִּימֵי הֶבְלִי יֵשׁ צַדִּיק אֹבֵד בְּצִדְקוֹ וְיֵשׁ רָשָׁע מַאֲרִיךְ בְּרָעָתוֹ. הַפָּסוּק הַזֶּה לָמַדְנוּ בְּבֵית רַבִּי דּוֹסְתַאי סָבָא, שֶׁהָיָה אוֹמֵר מִשְּׁמוֹ שֶׁל רַבִּי יֵיסָא סָבָא. אֶת הַכֹּל רָאִיתִי בִּימֵי הֶבְלִי, וְכִי שְׁלֹמֹה הַמֶּלֶךְ שֶׁהָיָה חָכָם עַל הַכֹּל, אֵיךְ אָמַר כָּךְ שֶׁהוּא רָאָה הַכֹּל בִּזְמַן שֶׁהוּא הָלַךְ בֶּחֳשָׁכִים שֶׁל הָעוֹלָם? שֶׁהֲרֵי כָּל מִי שֶׁמִּשְׁתַּדֵּל בֶּחֳשָׁכִים שֶׁל הָעוֹלָם, לֹא רוֹאֶה דָבָר וְלֹא יוֹדֵעַ דָּבָר?</p>\n<p>אֶלָּא כָּךְ נִתְבָּאֵר, בִּימֵי שְׁלֹמֹה הַמֶּלֶךְ עָמְדָה הַלְּבָנָה בִּשְׁלֵמוּתָהּ, וּשְׁלֹמֹה הִתְחַכֵּם עַל כָּל בְּנֵי הָעוֹלָם, וְאָז רָאָה הַכֹּל וְיָדַע הַכֹּל. וּמָה רָאָה? רָאָה כֹּ\"ל, שֶׁלָּא זָז מִן הַלְּבָנָה, וְהָיָה מֵאִיר לָהּ הַשֶּׁמֶשׁ (לה כשמש). זֶהוּ שֶׁכָּתוּב אֶת הַכֹּל רָאִיתִי בִּימֵי הֶבְלִי. מַה זֶּה הֶבְלִי? זוֹ הַלְּבָנָה שֶׁנִּכְלֶלֶת מִן הַכֹּל, מִמַּיִם וְאֵשׁ וְרוּחַ יַחַד. כְּהֶבֶל שֶׁיּוֹצֵא מִן הַפֶּה שֶׁכָּלוּל מִן הַכֹּל.</p>\n<p>וְהוּא רָאָה כֹּ\"ל, בְּאוֹתוֹ הַהֶבֶל שֶׁלּוֹ שֶׁאָחַז בּוֹ. יֵשׁ צַדִּיק אֹבֵד בְּצִדְקוֹ, בֹּא וּרְאֵה, בִּזְמַן שֶׁמִּתְרַבִּים הַצַּדִּיקִים בָּעוֹלָם, הַכֹּ\"ל הַזֶּה לֹא זָז מֵהַלְּבָנָה לְעוֹלָמִים, וְהַכֹּ\"ל הַזֶּה נוֹטֵל כָּל שֶׁמֶן וּמִשְׁחָה וְשִׂמְחָה שֶׁלְּמַעְלָה, וּמִתְמַלֵּא (ידיוורוה) וְשָׂמֵחַ וְגָדֵל, כְּדֵי לְהִזְדַּוֵּג עִם הַלְּבָנָה, וְהוּא מַרְוִיחַ בִּשְׁבִילָהּ.</p>\n<p>וּבִזְמַן שֶׁמִּתְרַבִּים הָרְשָׁעִים בָּעוֹלָם וְהַלְּבָנָה נֶחְשֶׁכֶת, אָז הַצַּדִּיק אֹבֵד בְּצִדְקוֹ. לֹא כָתוּב צַדִּיק נֶאֱבָד, אֶלָּא צַדִּיק אֹבֵד, שֶׁהֲרֵי לֹא נִרְאֶה (מתחבר) בַּלְּבָנָה, וְלֹא נוֹטֵל שֶׁמֶן וּמִשְׁחָה וְשִׂמְחָה לְמַלֵּא אוֹתָהּ וּלְהִזְדַּוֵּג עִמָּהּ. וְעַל זֶה צַדִּיק אֹבֵד בְּצִדְקוֹ, זוֹ הַלְּבָנָה, שֶׁבִּגְלַל הַלְּבָנָה שֶׁלֹּא נִמְצֵאת לְהִזְדַּוֵּג עִמּוֹ, הוּא אוֹבֵד, שֶׁלֹּא שׁוֹאֵב מֵהַשִּׂמְחָה כְּמוֹ שֶׁהָיָה עוֹשֶׂה. וְאָז מִתְעוֹרֵר כָּל צַד הַשְּׂמֹאל, וְהָרְשָׁעִים מַאֲרִיכִים בְּשַׁלְוָה בָּעוֹלָם. זֶהוּ שֶׁכָּתוּב וְיֵשׁ רָשָׁע מַאֲרִיךְ בְּרָעָתוֹ. מַה זֶּה בְּרָעָתוֹ? בְּאוֹתוֹ הַצַּד (באותה רעה) שֶׁנִּדְבָּק בּוֹ.</p>\n<p>עוֹד יֵשׁ צַדִּיק אֹבֵד בְּצִדְקוֹ, שֶׁכַּאֲשֶׁר הָרְשָׁעִים רַבִּים בָּעוֹלָם וְהַדִּין תָּלוּי (בחטאיהם), הַצַּדִּיק אֹבֵד בְּצִדְקוֹ, הוּא נִתְפָּס בְּחֶטְאָם, כְּמוֹ אַבָּא שֶׁנִּתְפָּס בַּחֲטָאֵי בְּנֵי עִירוֹ, שֶׁכֻּלָּם הָיוּ חֲצוּפִים (אליו), וְהוּא לֹא הִתְרָה בָהֶם וְלֹא בִיֵּשׁ אוֹתָם לְעוֹלָמִים, וּמָחָה בְיָדֵינוּ שֶׁלֹּא נִתְגָּרֶה בָּרְשָׁעִים (ולא מחה בידם שלא להתגרות בהם), וְהָיָה אוֹמֵר לָנוּ, (תהלים לז) לְדָוִד אַל תִּתְחַר בַּמְּרֵעִים אַל תְּקַנֵּא בְּעֹשֵׂי עַוְלָה. אָמַר אָבִי, וַדַּאי הַקָּדוֹשׁ בָּרוּךְ הוּא הֶעֱנִישׁ אוֹתִי בָּזֶה, שֶׁהֲרֵי הָיְתָה רְשׁוּת בְּיָדִי לִמְחוֹת בִּידֵיהֶם וְלֹא עָשִׂיתִי, וְלֹא בִיַּשְׁתִּי (הוכחתי) אוֹתָם לֹא בַסֵּתֶר וְלֹא בַגָּלוּי.</p>\n<p>עוֹד פָּתַח בְּנוֹ אַחֵר וְאָמַר, (בראשית ב) וַיִּיצֶר ה' אֱלֹהִים אֶת הָאָדָם עָפָר מִן הָאֲדָמָה וְגוֹ'. וַיִּיצֶר ה' אֱלֹהִים, בִּשְׁנֵי יוֹדִי\"ם, בִּשְׁנֵי יְצָרִים, יֵצֶר טוֹב וְיֵצֶר רָע, אֶחָד כְּנֶגֶד מַיִם וְאֶחָד כְּנֶגֶד אֵשׁ. ה' אֱלֹהִים - שֵׁם מָלֵא. אֶת הָאָדָם - כּוֹלֵל זָכָר וּנְקֵבָה. עָפָר מִן הָאֲדָמָה - זֶה עֲפַר הָאָרֶץ הַקְּדוֹשָׁה, שֶׁמִּשָּׁם נִבְרָא, וְהוּא מְקוֹם בֵּית הַמִּקְדָּשׁ.</p>"],[9522012056,"<p>וַיִּפַּח בְּאַפָּיו נִשְׁמַת חַיִּים - זוֹ הַנְּשָׁמָה הַקְּדוֹשָׁה שֶׁנִּמְשֶׁכֶת מֵאוֹתָם הַחַיִּים שֶׁלְּמַעְלָה. וַיְהִי הָאָדָם לְנֶפֶשׁ חַיָּה, אָדָם נִכְלָל בַּנֶּפֶשׁ הַקְּדוֹשָׁה, מֵהַחַיָּה הָעֶלְיוֹנָה שֶׁהוֹצִיאָה הָאָרֶץ, שֶׁכָּתוּב (שם א) תּוֹצֵא הָאָרֶץ נֶפֶשׁ חַיָּה, הַנֶּפֶשׁ שֶׁל הַחַיָּה הָעֶלְיוֹנָה הַהִיא.</p>\n<p>בֹּא רְאֵה, בְּכָל זְמַן שֶׁהַנְּשָׁמָה הַקְּדוֹשָׁה הַזּוֹ נִדְבֶּקֶת בָּאָדָם, אֲהוּב רִבּוֹנוֹ הוּא. כַּמָּה שׁוֹמְרִים שׁוֹמְרִים אוֹתוֹ מִכָּל הַצְּדָדִים, רָשׁוּם הוּא לְטוֹב, לְמַעְלָה וּלְמַטָּה, וְהַשְּׁכִינָה הַקְּדוֹשָׁה שׁוֹרָה עָלָיו.</p>\n<p>וּבִזְמַן שֶׁהוּא מַסְטֶה אֶת דַּרְכּוֹ, הַשְּׁכִינָה מִסְתַּלֶּקֶת מִמֶּנּוּ, וְהַנְּשָׁמָה הַקְּדוֹשָׁה לֹא נִדְבֶּקֶת בּוֹ. וּמִצַּד הַנָּחָשׁ הָרָע הַתַּקִּיף מִתְעוֹרֶרֶת רוּחַ אַחַת שֶׁמְּשׁוֹטֶטֶת וְהוֹלֶכֶת בָּעוֹלָם, שֶׁלֹּא שׁוֹרָה אֶלָּא בְּמָקוֹם שֶׁהַקְּדֻשָּׁה הָעֶלְיוֹנָה הִסְתַּלְּקָה מִשָּׁם, וְאָז הָאִישׁ נִטְמָא, וְנִפְגָּם בִּבְשָׂרוֹ בְּמַרְאֵה פָנָיו בַּכֹּל.</p>\n<p>וּבֹא רְאֵה, מִשּׁוּם שֶׁנֶּפֶשׁ חַיָּה הַזּוֹ הִיא קְדוֹשָׁה עֶלְיוֹנָה, כְּשֶׁמּוֹשֶׁכֶת אוֹתָהּ הָאָרֶץ הַקְּדוֹשָׁה וְנִכְלֶלֶת בְּתוֹכָהּ, אָז קוֹרְאִים לָהּ נְשָׁמָה, וְזוֹ הִיא שֶׁעוֹלָה לְמַעְלָה וּמְדַבֶּרֶת לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ, וְנִכְנֶסֶת בְּכָל הַשְּׁעָרִים, וְאֵין מוֹחֶה בְיָדָהּ, וְעַל כֵּן נִקְרֵאת רוּחַ מְמַלְּלָא, שֶׁהֲרֵי לְכָל שְׁאָר הַנְּפָשׁוֹת אֵין רְשׁוּת לְדַבֵּר לִפְנֵי הַמֶּלֶךְ, פְּרָט לָזוֹ.</p>\n<p>וְעַל כֵּן הַתּוֹרָה מַכְרִיזָה וְאוֹמֶרֶת: (תהלים לד) נְצֹר לְשׁוֹנְךְ מֵרָע וְגוֹ', וְכָתוּב (משלי כא) שֹׁמֵר פִּיו וּלְשׁוֹנוֹ וְגוֹ'. מִשּׁוּם שֶׁאִם שִׂפְתוֹתָיו וּלְשׁוֹנוֹ מְדַבְּרִים דְּבָרִים רָעִים, אוֹתָם הַדִּבּוּרִים עוֹלִים לְמַעְלָה, וּבְשָׁעָה שֶׁעוֹלִים, הַכֹּל מַכְרִיזִים וְאוֹמְרִים: הִסְתַּלְּקוּ מִסְּבִיב הַדִּבּוּר הָרָע שֶׁל פְּלוֹנִי! פַּנּוּ מָקוֹם לְדַרְכּוֹ שֶׁל הַנָּחָשׁ הַתַּקִּיף! אָז הַנְּשָׁמָה הַקְּדוֹשָׁה עוֹבֶרֶת מִמֶּנּוּ וּמִסְתַּלֶּקֶת וְלֹא יְכוֹלָה לְדַבֵּר, כְּמוֹ שֶׁנֶּאֱמַר (תהלים לט) נֶאֱלַמְתִּי דוּמִיָּה הֶחֱשֵׁיתִי מִטּוֹב.</p>\n<p>וְאוֹתָהּ הַנְּשָׁמָה עוֹלָה בְּבוּשָׁה, בַּצָּרָה שֶׁל הַכֹּל, וְלֹא נוֹתְנִים לָהּ מָקוֹם כְּמִקֹּדֶם. וְעַל זֶה כָּתוּב, שֹׁמֵר פִּיו וּלְשׁוֹנוֹ שֹׁמֵר מִצָּרוֹת נַפְשׁוֹ. נַפְשׁוֹ וַדַּאי. אוֹתָהּ שֶׁהָיְתָה מְדַבֶּרֶת, נֶעֶשְׂתָה מְשֻׁתֶּקֶת מִשּׁוּם הַדִּבּוּר הָרָע. וְאָז מִזְדַּמֵּן הַנָּחָשׁ, שֶׁהַכֹּל חוֹזֵר לִמְקוֹמוֹ, וּכְשֶׁאוֹתוֹ הַדִּבּוּר הָרָע עוֹלֶה בִדְרָכִים יְדוּעוֹת וְשׁוֹרֶה לִפְנֵי הַנָּחָשׁ הַתַּקִּיף, כַּמָּה רוּחוֹת מִתְעוֹרְרוֹת בָּעוֹלָם, וְרוּחַ יוֹרֶדֶת מֵהַצַּד הַהוּא, וּמוֹצֵאת אוֹתוֹ הָאִישׁ מְעוֹרֵר אוֹתוֹ בְּדִבּוּר רָע, וְהָרוּחַ הַמְמַלֶּלֶת הַקְּדוֹשָׁה הַזּוֹ עוֹבֶרֶת מִמֶּנּוּ. אָז שׁוֹרָה עָלָיו וּמְטַמֵּאת אוֹתוֹ, וְאָז הוּא סָגוּר.</p>"],[9522012057,"<p>כְּמוֹ שֶׁעָנְשׁוֹ שֶׁל הָאִישׁ הַזֶּה מִשּׁוּם דִּבּוּר רָע, כָּךְ עָנְשׁוֹ מִשּׁוּם דִּבּוּר טוֹב, שֶׁבָּא לְיָדוֹ וְיָכֹל לְדַבֵּר וְלֹא דִבֵּר. מִשּׁוּם שֶׁפָּגַם אוֹתָהּ הָרוּחַ הַמְמַלֶּלֶת, שֶׁהִיא מְתֻקֶּנֶת לְדַבֵּר לְמַעְלָה וּלְדַבֵּר לְמַטָּה, וְהַכֹּל בִּקְדֻשָּׁה. כָּל שֶׁכֵּן אִם הָעָם הוֹלְכִים בְּדֶרֶךְ עֲקֻמָּה, וְהוּא יָכוֹל לְדַבֵּר לָהֶם וּלְהוֹכִיחַ אוֹתָם, וְשׁוֹתֵק וְלֹא מְדַבֵּר, כְּמוֹ שֶׁאָמַרְנוּ שֶׁכָּתוּב נֶאֱלַמְתִּי דוּמִיָּה הֶחֱשֵׁיתִי מִטּוֹב וּכְאֵבִי נֶעְכָּר. נֶעִכָּר בְּמַכּוֹת שֶׁל טֻמְאָה. וְזֶהוּ שֶׁאָמַר דָּוִד הַמֶּלֶךְ, מַלְקֶה בָּזֶה וּמִתְפַּנֶּה מִמֶּנּוּ, שֶׁכָּתוּב (תהלים פז) פְּנֵה אֵלַי וְחָנֵּנִי. מַה זֶּה פְּנֵה אֵלַי? כְּמוֹ שֶׁנֶּאֱמַר (במדבר יב) וַיִּפֶן אַהֲרֹן. יָרְדוּ רַבִּי חִיָּיא וְרַבִּי יוֹסֵי וּנְשָׁקוּהוּ. הִתְחַבְּרוּ יַחַד כָּל אוֹתָהּ הַדֶּרֶךְ. קָרָא עֲלֵיהֶם רַבִּי חִיָּיא, (משלי ד) וְאֹרַח צַדִּיקִים כְּאוֹר נֹגַהּ הוֹלֵךְ וָאוֹר עַד נְכוֹן הַיּוֹם.</p>\n<p>נֶגַע צָרַעַת כִּי תִהְיֶה בְּאָדָם וְהוּבָא אֶל הַכֹּהֵן. אָמַר רַבִּי יוֹסֵי, הַנֶּגַע הַזֶּה בְּכָל הַגְּוָנִים שֶׁלּוֹ הִתְעוֹרְרוּ הַחֲבֵרִים, וְהַכֹּהֵן הָיָה יוֹדֵעַ בָּהֶם לְטַהֵר וּלְטַמֵּא, הָיָה יוֹדֵעַ אוֹתָם שֶׁהָיוּ יִסּוּרִים שֶׁל אַהֲבָה, אוֹ אוֹתָם שֶׁנִּמְצְאוּ בְּמִי שֶׁמָּאַס בּוֹ רִבּוֹנוֹ וְהִרְחִיק אוֹתוֹ, שֶׁהֲרֵי לְפִי דַּרְכֵי הָאִישׁ גּוֹרֵם נֶגַע בָּעוֹלָם.</p>\n<p>כָּתוּב (תהלים קמא) אַל תַּט לִבִּי לְדָבָר רָע לְהִתְעוֹלֵל עֲלִלוֹת בְּרֶשַׁע. מִכָּאן שָׁנִינוּ, בְּדֶרֶךְ שֶׁבָּהּ רוֹצֶה אָדָם לָלֶכֶת, בָּהּ מַנְהִיגִים אוֹתוֹ. אָמַר רַבִּי יִצְחָק, הַפָּסוּק הַזֶּה קָשֶׁה, וְכִי הַקָּדוֹשׁ בָּרוּךְ הוּא מַסְטֶה אֶת הָאָדָם לָלֶכֶת בְּדֶרֶךְ שֶׁל חֵטְא וְלַעֲשׂוֹת מַעֲשִׂים רָעִים? אִם כָּךְ, אֵין דִּין בְּזֶה הָעוֹלָם וְלֹא בָּעוֹלָם הַבָּא, וְהַתּוֹרָה לֹא מְתֻקֶּנֶת, שֶׁכָּתוּב בָּהּ אִם תִּשְׁמַע וְאִם לֹא תִשְׁמַע!</p>\n<p>אֶלָּא דָּוִד הִזְהִיר אֶת לִבּוֹ לְהַנְהִיגוֹ בְּדֶרֶךְ אֱמֶת, כְּמוֹ שֶׁנֶּאֱמַר (דברים ד) וַהֲשֵׁבתָ אֶל לְבָבֶךְ. מַה זֶּה וַהֲשֵׁבֹתָ? אֶלָּא פַּעַם אַחַת וּפַעֲמַיִם וְשָׁלֹשׁ לַחֲזֹר כְּנֶגְדּוֹ, וּלְהוֹלִיךְ וּלְהַזְהִיר אוֹתוֹ. וְכָךְ אָמַר לוֹ: אַל תַּט לִבִּי לְדָבָר רָע. לְלִבּוֹ אָמַר דָּוִד, (כלומר) אַל תַּטֶּה לְפִי דַרְכֵי הָאָדָם (וכך אמר לו', לבי, אל תט לדבר רע. שהרי דבר) רָע גּוֹרֵם נֶגַע בָּעוֹלָם, וְהַדִּין שׁוֹרֶה בָעוֹלָם, וְהַיְנוּ נֶגַע צָרַעַת.</p>\n<p>נֶגַע צָרַעַת, הִנֵּה הִתְעוֹרְרוּ הַחֲבֵרִים, אֲבָל צָרַעַת כְּתַרְגּוּמוֹ. אָמַר רַבִּי יְהוּדָה, מַה זֶּה כְּתַרְגּוּמוֹ? הַסְגָּרָה, שֶׁסּוֹגֵר וְלֹא פוֹתֵחַ. וּכְשֶׁהוּא סוֹגֵר וְלֹא פוֹתֵחַ, הוּא נִקְרָא נֶגַע. רַבִּי יוֹסֵי אָמַר, שֶׁאֵין הָאָבוֹת נֶהֱנִים, כָּל שֶׁכֵּן הַבָּנִים, וְהַיְנוּ שֶׁכָּתוּב נֶגַע צָרַעַת כִּי תִהְיֶה בְּאָדָם, בָּאָדָם מַמָּשׁ, וּמִכָּאן יוֹרֵד לְמִי שֶׁיּוֹרֵד. נִמְצָא נֶגַע לַכֹּל מֵאוֹתָהּ הַהַסְגָּרָה.</p>\n<p>אָמַר רַבִּי יִצְחָק, וַדַּאי זֶהוּ סוֹד הַדָּבָר, שֶׁכָּתוּב (איכה ב) נִאֵר מִקְדָּשׁוֹ. מָה הַטַּעַם? מִשּׁוּם שֶׁבְּנֵי הָעוֹלָם גָּרְמוּ אֶת זֶה, שֶׁכָּתוּב (במדבריט) אֶת מִקְדַּשׁ ה' טִמֵּא, טִמֵּא מַמָּשׁ. אָמַר רַבִּי אֶלְעָזָר, טִמֵּא, מִשּׁוּם שֶׁהִסְתַּלְּקָה (השכינה ממנו) מִי שֶׁהִסְתַּלְּקָה, וְהַנָּחָשׁ הַתַּקִּיף שָׁרוּי וּמַטִּיל זֻהֲמָא, וּמְטַמֵּא אֶת מִי שֶׁמְּטַמֵּא, וְכֻלָּם מִשּׁוּם חֲטָאֵי הָעוֹלָם.</p>"],[9522012058,"<p>לָמַדְנוּ, כְּשֶׁמַּתְחִיל הַנָּחָשׁ (החזק) לְהִתְגַּלּוֹת, מִסְתַּלְּקִים הַבִּנְיָנִים וְהָעַמּוּדִים וְעוֹבְרִים, וּבָא הַנָּחָשׁ הַתַּקִּיף וּמַטִּיל זֻהֲמָא, וְאָז נִמְצָא הַמִּקְדָּשׁ טָמֵא. מִי הַמִּקְדָּשׁ? כְּמוֹ שֶׁנֶּאֱמַר וְנָתַתִּי נֶגַע צָרַעַת בְּבֵית אֶרֶץ אֲחֻזַּתְכֶם. וְכָתוּב (בראשית ג) וְהַנָּחָשׁ הָיָה עָרוּם מִכֹּל חַיַּת הַשָּׂדֶה אֲשֶׁר עָשָׂה ה' אֱלֹהִים וַיֹּאמֶר אֶל הָאִשָּׁה. אֶל הָאִשָּׁה מַמָּשׁ, שֶׁמְּקוֹם הַמִּקְדָּשׁ נֶאֱחָז בְּתוֹכָהּ, וְהַיְנוּ אֶת מִקְדַּשׁ ה' טִמֵּא, מִשּׁוּם חֶטְאוֹ, מִשּׁוּם שֶׁהִתְגַּלָּה הַנָּחָשׁ הַתַּקִּיף.</p>\n<p>מַה חֶטְאוֹ? זֶה לָשׁוֹן הָרָע, שֶׁבִּגְלַל לָשׁוֹן הָרָע הַנָּחָשׁ מִזְדַּמֵּן, בֵּין לְמַעְלָה בֵּין לְמַטָּה, שֶׁכָּתוּב (במדבר כא) וַיְשַׁלַּח ה' בָּעָם אֵת הַנְּחָשִׁים הַשְּׂרָפִים. הַשּׂוֹרְפִים אוֹ הַשְּׂרוּפִים לֹא כָתוּב, אֶלָּא הַשְּׂרָפִים. מִי הַשְּׂרָפִים? שֶׁכָּתוּב (תהלים עד) רָאשֵׁי תַנִּינִים, (שנים. אחד נאחז למעלה ואחד למטה) (שנים, אחד חוזרים לפעמים) וְכָתוּב (ישעיה ו) שְׂרָפִים עֹמְדִים מִמַּעַל לוֹ, מִמַּעַל לוֹ וַדַּאי, כְּמוֹ שֶׁנֶּאֱמַר (איוב א) לְהִתְיַצֵּב עַל ה', וְאָז הַסְגָּרָה בַּכֹּל, וְאֵין מִי שֶׁפּוֹתֵחַ. וְעַל זֶה כָּתוּב, (משלי ל) כֵּן דֶּרֶךְ אִשָּׁה מְנָאָפֶת אָכְלָה וּמָחֲתָה פִיהָ וְגוֹ'. מַה זֶּה מְנָאָפֶת? מְנָאֶפֶת מַמָּשׁ וַדַּאי, אָכְלָה וּמָחֲתָה פִיהָ וְאָמְרָה לֹא פָעַלְתִּי אָוֶן.</p>\n<p>אָמַר רַבִּי חִיָּיא אָמַר רַבִּי יִצְחָק, בָּרָצוֹן שֶׁל הַכֹּל לֹא נִמְצָא לְמַטָּה, אֶלָּא מִשּׁוּם שֶׁנִּמְצָא לְמַעְלָה. וּלְמַעְלָה לֹא נִמְצָא, אֶלָּא כְּשֶׁנִּמְצָא לְמַטָּה בַּחֲטָאֵי הָעוֹלָם, שֶׁלָּמַדְנוּ שֶׁהַכֹּל תָּלוּי זֶה בָּזֶה, וְזֶה בָּזֶה.</p>"],[9522012059,"<p>וְאִישׁ כִּי יִמָּרֵט רֹאשׁוֹ וְגוֹ'. רַבִּי חִיָּיא פָּתַח וְאָמַר, (קהלת ב) וְרָאִיתִי אָנִי שֶׁיֵּשׁ יִתְרוֹן לַחָכְמָה מִן הַסִּכְלוּת וְגוֹ'. בְּכַמָּה מְקוֹמוֹת הִסְתַּכַּלְתִּי בְּדִבְרֵי שְׁלֹמֹה הַמֶּלֶךְ וְהִשְׁגַּחְתִּי בַחָכְמָה הָרַבָּה שֶׁלּוֹ, וְהִסְתִּיר דְּבָרָיו בְּתוֹכוֹ, לְתוֹךְ הַהֵיכָל הַקָּדוֹשׁ. בְּפָסוּק זֶה יֵשׁ לְהִסְתַּכֵּל, לָמָּה אָמַר וְרָאִיתִי אָנִי? וְכִי שְׁאָר בְּנֵי הָעוֹלָם לֹא יוֹדְעִים וְלֹא רוֹאִים אֶת זֶה? אֲפִלּוּ מִי שֶׁלֹּא יוֹדֵעַ חָכְמָה מִיָּמָיו וְלֹא הִשְׁגִּיחַ בָּהּ, יוֹדֵעַ אֶת זֶה שֶׁיֵּשׁ יִתְרוֹן לַחָכְמָה מִן הַסִּכְלוּת כִּיתְרוֹן הָאוֹר מִן הַחֹשֶׁךְ, וְהוּא מְשַׁבֵּחַ אֶת עַצְמוֹ וְאוֹמֵר רָאִיתִי אָנִי?</p>\n<p>אֶלָּא כָּךְ לָמַדְנוּ, מִי חָכָם כְּמוֹ שְׁלֹמֹה, שֶׁבְּשֶׁבַע דְּרָגוֹת שֶׁל חָכְמָה נִקְרָא כְּמוֹ שֶׁלְּמַעְלָה. שִׁשָּׁה יָמִים לְמַעְלָה, שְׁבִיעִי עֶלְיוֹן עֲלֵיהֶם. שִׁשָּׁה יָמִים לְמַטָּה, שְׁבִיעִי עֲלֵיהֶם. שֵׁשׁ דְּרָגוֹת לַכִּסֵּא, הוּא עַל הַכִּסֵּא, שֶׁכָּתוּב וַיֵּשֶׁב שְׁלֹמֹה עַל כִּסֵּא ה' לְמֶלֶךְ. שִׁבְעָה כְתָרִים שֶׁל יָמִים לְמַעְלָה, וְאָז כְּנֶגְדָּם שִׁבְעָה שֵׁמוֹת לִשְׁלֹמֹה, לְהַרְאוֹת בּוֹ הַחָכְמָה הַקְּדוֹשָׁה. וּמִשּׁוּם כָּךְ נִקְרָא שִׁבְעָה שֵׁמוֹת: שְׁלֹמֹה. יְדִידְיָה. אָגוּר. בֶּן יָקֶה. לְמוּאֵל. אִיתִיאֵל. קֹהֶלֶת.</p>\n<p>וְאָמַר שִׁבְעָה הֲבָלִים. וּמַה שֶּׁהוּא רָאָה לֹא רָאָה אָדָם אַחֵר, וּכְשֶׁכִּנֵּס חָכְמָה וְהִתְעַלָּה לְדַרְגוֹת הַחָכְמָה, נִקְרָא קֹהֶלֶת. וְשִׁבְעָה הֲבָלִים אָמַר, כְּנֶגֶד שִׁבְעָה כְתָרִים שֶׁלְּמַעְלָה, וְכָל הֶבֶל נַעֲשָׂה מִמֶּנּוּ קוֹל, וְהָעוֹלָם אֵינוֹ מִתְקַיֵּם אֶלָּא בְּהֶבֶל.</p>\n<p>וְלָמַדְנוּ מִשְּׁמוֹ שֶׁל רַבִּי שִׁמְעוֹן, הַהֶבֶל מוֹצִיא קוֹל בְּרוּחַ וּמַיִם שֶׁבּוֹ, וְאֵין קוֹל אֶלָּא עִם הֶבֶל. וְלָמַדְנוּ, בְּשִׁבְעָה הֲבָלִים מִתְקַיְּמִים הָעֶלְיוֹנִים וְהַתַּחְתּוֹנִים. וְלָמַד רַבִּי יִצְחָק, בֹּא תִרְאֶה שֶׁעַל הַהֶבֶל מִתְקַיֵּם הָעוֹלָם, שֶׁאִלְמָלֵא לֹא הָיָה הֶבֶל שֶׁיּוֹצֵא מִן הַפֶּה, לֹא הִתְקַיֵּם אָדָם אֲפִלּוּ שָׁעָה אַחַת.</p>\n<p>כְּמוֹ כֵן אָמַר שְׁלֹמֹה דְּבָרָיו, שֶׁהָעוֹלָם מִתְקַיֵּם בָּהֶם, שֶׁבַּהֶבֶל הַזֶּה מִתְקַיֵּם הָעוֹלָם. וְהַהֶבֶל הַזֶּה שֶׁמִּתְקַיֵּם בּוֹ הָעוֹלָם, בָּא מִן הַהֲבָלִים שֶׁלְּמַעְלָה. זֶהוּ שֶׁכָּתוּב הֲבֵל הֲבָלִים, הֶבֶל מֵהַהֲבָלִים שֶׁלְּמַעְלָה, וְכָל דְּבָרָיו הָיוּ כָּךְ. וּבַהֲבָלִים שֶׁלְּמַעְלָה כָּתוּב, (דברים ח) כִּי עַל כָּל מוֹצָא פִּי ה' יִחְיֶה הָאָדָם. מַה זֶּה מוֹצָא פִּי ה'? זֶה הַהֲבָלִים שֶׁלְּמַעְלָה.</p>\n<p>וְלָמַדְנוּ, וְרָאִיתִי אָנִי שֶׁיֵּשׁ יִתְרוֹן לַחָכְמָה מִן הַסִּכְלוּת. מִן הַסִּכְלוּת מַמָּשׁ בָּאָה תוֹעֶלֶת לַחָכְמָה. שֶׁאִלְמָלֵא לֹא נִמְצְאָה שְׁטוּת בָּעוֹלָם, לֹא נוֹדְעָה הַחָכְמָה וּדְבָרֶיהָ. וְלָמַדְנוּ, חִיּוּב הוּא עַל אָדָם שֶׁלָּמַד חָכְמָה לִלְמֹד מְעַט מִן הַשְּׁטוּת וְלָדַעַת אוֹתוֹ, מִשּׁוּם שֶׁבָּאָה תוֹעֶלֶת לַחָכְמָה בִּשְׁבִילוֹ, כְּמוֹ שֶׁבָּאָה תוֹעֶלֶת לָאוֹר מִן הַחֲשֵׁכָה. שֶׁאִלְמָלֵא הַחֲשֵׁכָה לֹא נוֹדָע הָאוֹר, וְלֹא בָאָה (נראית) לָעוֹלָם תּוֹעֶלֶת מִמֶּנּוּ.</p>\n<p>שָׁנָה, שֶׁיֵּשׁ יִתְרוֹן לַחָכְמָה, לַחָכְמָה סְתָם. שֶׁאָמַר רַבִּי שִׁמְעוֹן לְרַבִּי אַבָּא, בֹּא וּרְאֵה סוֹד הַדָּבָר, לֹא מְאִירָה הַחָכְמָה שֶׁלְּמַעְלָה וְלֹא נְאוֹרָה אֶלָּא בִּשְׁבִיל הַשְּׁטוּת שֶׁמִּתְעוֹרֶרֶת מִמָּקוֹם אַחֵר, וְאִלְמָלֵא זֶה, אוֹר וּמִשְׁחָה רַבָּה וְיוֹתֵר לֹא הָיְתָה (להיות), וְלֹא נִרְאֲתָה תוֹעַלְתָּהּ שֶׁל הַחָכְמָה, וּמִשּׁוּם הַשְּׁטוּת מֵאִיר יוֹתֵר, וּמְאִירִים לוֹ יוֹתֵר. זֶהוּ שֶׁכָּתוּב שֶׁיֵּשׁ יִתְרוֹן לַחָכְמָה, לַחָכְמָה סְתָם, מִן הַסִּכְלוּת סְתָם. וְכָךְ לְמַטָּה, אִלְמָלֵא לֹא הָיְתָה שְׁטוּת מְצוּיָה בָעוֹלָם, לֹא הָיְתָה הַחָכְמָה מְצוּיָה בָעוֹלָם.</p>\n<p>וְהַיְנוּ שֶׁרַב הַמְנוּנָא סָבָא, כְּשֶׁהָיוּ לוֹמְדִים מִמֶּנּוּ הַחֲבֵרִים סוֹדוֹת הַחָכְמָה, הָיָה מְסַדֵּר לִפְנֵיהֶם פֶּרֶק שֶׁל דִּבְרֵי שְׁטוּת, כְּדֵי שֶׁתָּבֹא תוֹעֶלֶת לַחָכְמָה בִּשְׁבִילוֹ. זֶהוּ שֶׁכָּתוּב (קהלת י) יָקָר מֵחָכְמָה וּמִכָּבוֹד סִכְלוּת מְעָט, מִשּׁוּם שֶׁהִיא הַתִּקּוּן שֶׁל הַחָכְמָה וּכְבוֹד הַחָכְמָה. וְעַל זֶה כָּתוּב, וְלִבִּי נֹהֵג בַּחָכְמָה וְלֶאֱחֹז בְּסִכְלוּת.</p>\n<p>רַבִּי יוֹסֵי אָמַר, יָקָר מֵחָכְמָה וּמִכָּבוֹד, כְּלוֹמַר, כְּבוֹד הַחָכְמָה וְהַנּוֹי שֶׁלָּהּ וְהַיְקָר שֶׁל הַכָּבוֹד שֶׁלְּמַעְלָה מַה הוּא? סִכְלוּת מְעָט, מְעַט שֶׁל שְׁטוּת, מַרְאֶה וּמְגַלֶּה אֶת כְּבוֹד הַחָכְמָה וְהַכָּבוֹד שֶׁל מַעְלָה יוֹתֵר מִכָּל דַּרְכֵי הָעוֹלָם.</p>\n<p>כִּיתְרוֹן הָאוֹר מִן הַחֹשֶׁךְ, תּוֹעֶלֶת הָאוֹר לֹא בָאָה (נראית) אֶלָּא מִתּוֹךְ הַחֲשֵׁכָה. (ולעולם) תִּקּוּן הַלָּבָן מַהוּ? הַשָּׁחֹר. אִלְמָלֵא הַשָּׁחֹר לֹא נוֹדָע הַלָּבָן, וּמִשּׁוּם הַשָּׁחֹר מִתְעַלֶּה הַלָּבָן וּמִתְיַקֵּר. אָמַר רַבִּי יִצְחָק, מָשָׁל לְמָתוֹק בְּמַר, שֶׁאֵין יוֹדֵעַ אִישׁ טַעַם הַמָּתוֹק עַד שֶׁטּוֹעֵם אֶת הַמַּר. מִי עוֹשֶׂה אֶת זֶה מָתוֹק? הֱוֵה אוֹמֵר זֶה הַמַּר. וְהַיְנוּ שֶׁכָּתוּב (שם ז) גַּם אֶת זֶה לְעֻמַּת זֶה עָשָׂה הָאֱלֹהִים. וְכָתוּב טוֹב אֲשֶׁר תֶּאֱחֹז בָּזֶה וְגַם מִזֶּה אַל תַּנַּח אֶת יָדֶךְ.</p>"],[9522012060,"<p>שָׁנִינוּ, בְּכַמָּה דְרָגוֹת נִקְרָא בֶּן אָדָם: אָדָם, גֶּבֶר, אֱנוֹשׁ, אִישׁ. גָּדוֹל שֶׁבְּכֻלָּם אָדָם, (משום) שֶׁכָּתוּב (בראשית א) וַיִּבְרָא אֱלֹהִים אֶת הָאָדָם בְּצַלְמוֹ. וְכָתוּב (שם ט) כִּי בְּצֶלֶם אֱלֹהִים עָשָׂה אֶת הָאָדָם. וְלֹא כָתוּב גֶּבֶר, אֱנוֹשׁ, אִישׁ. אָמַר רַבִּי יְהוּדָה, אִם כָּךְ, וַהֲרֵי כָּתוּב (ויקרא א) אָדָם כִּי יַקְרִיב מִכֶּם קָרְבָּן לַה'. מִי צָרִיךְ לְהַקְרִיב קָרְבָּן? מִי שֶׁהוּא חוֹטֵא, וְכָתוּב אָדָם.</p>\n<p>אָמַר רַבִּי יִצְחָק, בֹּא רְאֵה, קִיּוּם הָעוֹלָם שֶׁל עֶלְיוֹנִים וְתַחְתּוֹנִים הוּא קָרְבָּן, הַנַּחַת שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא. וּמִי רָאוּי לְהַקְרִיב לְפָנָיו אֶת הַנַּחַת הַזּוֹ? הֱוֵה אוֹמֵר זֶה אָדָם, שֶׁיָּקָר מִן הַכֹּל. אָמַר לוֹ, אִם כָּךְ, הִנֵּה כָּתוּב, אָדָם כִּי יִהְיֶה בְעוֹר בְּשָׂרוֹ וְגוֹ', וְהָיָה בְעוֹר בְּשָׂרוֹ לְנֶגַע צָרָעַת. אָמַר לוֹ, אֶת זֶה צָרִיךְ לְטַהֵר הַקָּדוֹשׁ בָּרוּךְ הוּא יוֹתֵר מֵהַכֹּל, שֶׁמִּי שֶׁהוּא בְּדַרְגָּה עֶלְיוֹנָה שֶׁל כֻּלָּם, לֹא יֵשֵׁב כָּךְ.</p>\n<p>וּמִשּׁוּם כָּךְ כָּתוּב בָּאָדָם, וְהוּבָא אֶל הַכֹּהֵן. וּבָא לֹא כָתוּב, אֶלָּא וְהוּבָא. שֶׁכָּל מִי שֶׁרוֹאֶה אוֹתוֹ, מִתְחַיֵּב בּוֹ לְהַקְרִיבוֹ לִפְנֵי הַכֹּהֵן, שֶׁהַדְּמוּת הַקְּדוֹשָׁה לֹא תֵשֵׁב כָּךְ. וְכָתוּב אִישׁ אוֹ אִשָּׁה כִּי יִהְיֶה בוֹ נָגַע וְגוֹ', וְאִישׁ אוֹ אִשָּׁה כִּי יִהְיֶה בְעוֹר בְּשָׂרָם בֶּהָרֹת וְגוֹ'. וְלֹא כָתוּב בָּהֶם וְהוּבָא.</p>\n<p>אָמַר לוֹ, וַהֲרֵי כָּתוּב (במדבר יב) וְהָאִישׁ מֹשֶׁה, כִּי זֶה מֹשֶׁה הָאִישׁ, לָמָּה לֹא נִקְרָא אָדָם? אָמַר לוֹ, מִשּׁוּם שֶׁנִּקְרָא עֶבֶד לַמֶּלֶךְ, שֶׁכָּתוּב (שם) לֹא כֵן עַבְדִּי מֹשֶׁה. (יהושע א) מֹשֶׁה עַבְדִּי. וְאַף כָּךְ נִקְרָא אִישׁ כְּלַפֵּי אָדָם שֶׁלְּמַעְלָה. אָמַר לוֹ, אִם כָּךְ, הֲרֵי כָּתוּב (שמות טו) ה' אִישׁ מִלְחָמָה, וְלֹא כָתוּב אָדָם. אָמַר לוֹ, סוֹד ה' לִירֵאָיו. אָמַר לוֹ, אִם כָּךְ אֲנִי בֵּינֵיהֶם (יושב) הוֹשִׁיבוּ בַּכֹּל, וּבַמָּקוֹם הַזֶּה לֹא זָכִיתִי.</p>\n<p>אָמַר לוֹ, לֵךְ לְרַבִּי אַבָּא, שֶׁאֲנִי לָמַדְתִּי מִמֶּנּוּ שֶׁלֹּא עַל מְנָת לְגַלּוֹת. הָלַךְ אֵצֶל רַבִּי אַבָּא, מָצָא אוֹתוֹ שֶׁהָיָה דוֹרֵשׁ וְאוֹמֵר: מָתַי נִקְרֵאת שְׁלֵמוּת שֶׁל מַעְלָה (של הכל) ? כְּשֶׁיּוֹשֵׁב הַקָּדוֹשׁ בָּרוּךְ הוּא בְּכִסֵּא, וְעַד שֶׁלֹּא יוֹשֵׁב בְּכִסֵּא, לֹא נִמְצֵאת שְׁלֵמוּת, שֶׁכָּתוּב (יחזקאלא) וְעַל דְּמוּת הַכִּסֵּא דְּמוּת כְּמַרְאֵה אָדָם עָלָיו מִלְמָעְלָה. מַשְׁמָע שֶׁכָּתוּב אָדָם, שֶׁהוּא הַכְּלָל וּשְׁלֵמוּת הַכֹּל. אָמַר רַבִּי יְהוּדָה, בָּרוּךְ הָרַחֲמָן שֶׁמָּצָאתִי אוֹתְךְ בָּזֶה. אָמַר לוֹ, אִם כָּךְ, הֲרֵי כָּתוּב ה' אִישׁ מִלְחָמָה, וְלֹא כָתוּב אָדָם. אָמַר לוֹ, יָפֶה שָׁאַלְתָּ.</p>\n<p>בֹּא רְאֵה, שָׁם לֹא נִמְצֵאת שְׁלֵמוּת שֶׁל הַכֹּל, וּמִשּׁוּם כָּךְ נִקְרָא אִישׁ. אֲבָל כָּאן שְׁלֵמוּת הַכֹּל וְהַכְּלָל שֶׁל הַכֹּל, מִשּׁוּם כָּךְ נִקְרָא אָדָם. קָרָא עָלָיו, (תהלים קיט) טוֹב לִי תּוֹרַת פִּיךְ מֵאַלְפֵי זָהָב וָכָסֶף.</p>\n<p>עוֹד אָמַר לוֹ, כָּתוּב (שם לו) אָדָם וּבְהֵמָה, וְלֹא כָתוּב אִישׁ וּבְהֵמָה. אָמַר לוֹ, וָלֹא?! וַהֲרֵי כָּתוּב (שמות יא) לְמֵאִישׁ וְעַד בְּהֵמָה. אֲבָל מַה שֶּׁכָּתוּב אָדָם וּבְהֵמָה, כְּמוֹ שֶׁכָּתוּב (מלכים א ה) מִן הָאֶרֶז אֲשֶׁר בַּלְּבָנוֹן עַד הָאֵזוֹב אֲשֶׁר יֹצֵא בַּקִּיר. דֶּרֶךְ הַכָּתוּב הוּא, שֶׁלּוֹקֵחַ הָעֶלְיוֹן מִכֻּלָּם וְהַנָּמוּךְ מִכֻּלָּם. אַף כָּאן הָעֶלְיוֹן שֶׁל הַכֹּל - אָדָם, וְהַנָּמוּךְ מֵהַכֹּל - בְּהֵמָה.</p>\n<p>אָמַר לוֹ, וַהֲרֵי כָּתוּב (בראשיתב) וְאָדָם אַיִן לַעֲבֹד אֶת הָאֲדָמָה. אָמַר לוֹ, בֹּא וּרְאֵה שֶׁכָּל מַה שֶּׁבָּעוֹלָם אֵינוֹ אֶלָּא בִּשְׁבִיל הָאָדָם, וְכֻלָּם בִּגְלָלוֹ מִתְקַיְּמִים וְלֹא נִרְאִים בָּעוֹלָם, וְכֻלָּם הִתְעַכְּבוּ עַד שֶׁיָּבֹא אוֹתוֹ שֶׁנִּקְרָא אָדָם. זֶהוּ שֶׁכָּתוּב (שם) וְכֹל שִׂיחַ הַשָּׂדֶה טֶרֶם יִהְיֶה בָאָרֶץ וְגוֹ'. טֶרֶם: עַד שֶׁלֹּא, כְּתַרְגּוּמוֹ. מִשּׁוּם שֶׁלֹּא נִרְאֲתָה הַדְּמוּת הָעֶלְיוֹנָה. זֶהוּ שֶׁכָּתוּב וְאָדָם אַיִן. כְּלוֹמַר, כֻּלָּם הִתְעַכְּבוּ בִשְׁבִילָהּ שֶׁל הַדְּמוּת הַזֹּאת עַד שֶׁנִּרְאֲתָה. וּמִשּׁוּם כָּךְ לֹא נִרְאֲתָה (נבראה) הַדְּמוּת הַזּוֹ אֶלָּא בַּדְּמוּת שֶׁרְאוּיָה לָהּ. זֶהוּ שֶׁכָּתוּב (שם) וַיִּיצֶר ה' אֱלֹהִים אֶת הָאָדָם, בְּשֵׁם מָלֵא, כְּמוֹ שֶׁבֵּאַרְנוּ, שֶׁהוּא שְׁלֵמוּת הַכֹּל וְהַכְּלָל שֶׁל הַכֹּל.</p>\n<p>לָמַדְנוּ, בְּשִׁשִּׁי נִבְרָא אָדָם, בְּשָׁעָה שֶׁנִּשְׁלַם הַכִּסֵּא. וְנִקְרָא כִסֵּא, שֶׁכָּתוּב (מלכים א י) שֵׁשׁ מַעֲלוֹת לַכִּסֵּא. וּלְפִיכָךְ נִבְרָא הָאָדָם בַּשִּׁשִּׁי, שֶׁהוּא רָאוּי לֵישֵׁב עַל הַכִּסֵּא. וְלָמַדְנוּ, כֵּיוָן שֶׁנִּבְרָא אָדָם, הַכֹּל הִתְתַּקֵּן, וְכָל מַה שֶּׁלְּמַעְלָה וּלְמַטָּה, וְהַכֹּל נִכְלָל בָּאָדָם.</p>\n<p>שָׁנִינוּ, אָמַר רַבִּי יוֹסֵי, כָּתוּב (יחזקאל א) וּדְמוּת פְּנֵיהֶם פְּנֵי אָדָם, הַכְּלָל שֶׁל הַכֹּל, וְהַכֹּל כְּלוּלִים בַּדְּמוּת הַזֹּאת. אָמַר רַבִּי יְהוּדָה, וַהֲרֵי כָּתוּב וּפְנֵי אַרְיֵה אֶל הַיָּמִין לְאַרְבַּעְתָּם וּפְנֵי שׁוֹר מֵהַשְּׂמֹאול לְאַרְבַּעְתָּן? אָמַר לוֹ, הַכֹּל הָיוּ פְּנֵי אָדָם, וּבְאוֹתָהּ דְּמוּת שֶׁל אָדָם נִרְאִים כָּל הַגְּוָנִים וְכָל הַדְּמֻיּוֹת. כְּמוֹ שֶׁשָּׁנִינוּ, פָּנָיו פְּנֵי נֶשֶׁר, לֹא שֶׁהוּא נֶשֶׁר, אֶלָּא שֶׁנִּרְאֶה בִּדְמוּת שֶׁל אָדָם, מִשּׁוּם שֶׁכּוֹלֵל אֶת כָּל הַגְּוָנִים וְכָל הַדְּמֻיּוֹת.</p>\n<p>אָמַר רַבִּי יִצְחָק, בּא רְאֵה, כָּל מִי שֶׁהוּא תַּחַת שִׁלְטוֹנוֹ שֶׁל אָדָם, נִקְרָא אִישׁ, מִשּׁוּם שֶׁהִתְתַּקֵּן בְּגָוֶן שֶׁל אָדָם מִדַּרְגָּה אַחֶרֶת שֶׁהָיְתָה לוֹ בָּרִאשׁוֹנָה. שֶׁלָּמַדְנוּ בְּסוֹד עֶלְיוֹן בְּסִפְרָא דִצְנִיעוּתָא, כְּשֶׁנִּבְרָא אָדָם, יָרַד בִּדְמוּת קְדוֹשָׁה עֶלְיוֹנָה, וְיָרְדוּ עִמּוֹ שְׁתֵּי רוּחוֹת מִשְּׁנֵי צְדָדִים, מִיָּמִין וּמִשְּׂמֹאל, הַכְּלָל שֶׁל אָדָם. וְהָרוּחַ שֶׁל הַיָּמִין נִקְרֵאת נְשָׁמָה קְדוֹשָׁה, שֶׁכָּתוּב (בראשית ב) וַיִּפַּח בְּאַפָּיו נִשְׁמַת חַיִּים. וְהָרוּחַ שֶׁל הַשְּׂמֹאל נִקְרֵאת נֶפֶשׁ חַיָּה, וְהָיְתָה הוֹלֶכֶת וְיוֹרֶדֶת מִמַּעְלָה לְמַטָּה, וְלֹא מִתְיַשֶּׁבֶת עִם הָאַחֶרֶת.</p>\n<p>כַּאֲשֶׁר נִכְנְסָה הַשַּׁבָּת וְאָדָם הָיָה חוֹטֵא, נַעֲשׂוּ (נשפעו) מֵאוֹתָהּ רוּחַ הַשְּׂמֹאל בְּרִיּוֹת שֶׁמִּתְפַּשְּׁטוֹת בָּעוֹלָם, וְגוּפָם לֹא הִסְתַּיֵּם, וְהִתְחַבְּרוּ עִם גּוּף הָאָדָם הַזֶּה, עִם זָכָר וּנְקֵבָה, וְנוֹלְדוּ בָעוֹלָם. וְאֵלּוּ נִקְרָאִים נִגְעֵי בְּנֵי אָדָם. לָמַדְנוּ, הָעֶלְיוֹנִים מֵהֶם שֶׁלֹּא נִדְבְּקוּ לְמַטָּה וּתְלוּיִים בָּאֲוִיר, וְשׁוֹמְעִים מַה שֶּׁשּׁוֹמְעִים מִלְמַעְלָה, וּמֵהֶם יוֹדְעִים אוֹתָם הָאֲחֵרִים לְמַטָּה.</p>\n<p>לָמַדְנוּ, מֵהַנִּיצוֹץ הַקָּשֶׁה יוֹצְאִים שְׁלֹשׁ מֵאוֹת וְעֶשְׂרִים וַחֲמִשָּׁה נִיצוֹצוֹת, חֲקוּקִים וַאֲחוּזִים יַחַד מִצַּד הַגְּבוּרָה, שֶׁנִּקְרָאִים גְּבוּרוֹת, (ומתלכדים) יַחַד וְנַעֲשׂוּ אֶחָד (גוף). וּכְשֶׁאֵלֶּה נִכְנָסִים לְגוּף, הוּא נִקְרָא אִישׁ. (ולא איש זה) זֶה שֶׁשָּׁנִינוּ, אִישׁ תָּם וְיָשָׁר אִישׁ צַדִּיק. וְהָאִישׁ שֶׁל כָּאן, כָּתוּב אִישׁ מִלְחָמָה, שֶׁהַכֹּל עוֹלֶה דִין, וְהַכֹּל אֶחָד. אָמַר רַבִּי יְהוּדָה, לָמָּה? לֹא הָיָה בְיָדוֹ (של רבי יצחק) ? בָּאוּ שָׁאֲלוּ לִפְנֵי רַבִּי שִׁמְעוֹן. אָמַר לָהֶם, עוֹד קָשֶׁה, שֶׁהֲרֵי שָׁנִינוּ שֶׁכָּתוּב, (בראשית ב) לְזֹּאת יִקָּרֵא אִשָּׁה כִּי מֵאִישׁ לֻקֳחָה זֹּאת. וְשָׁנִינוּ, מִי זֶה אִישׁ חֶסֶד, וְכָאן אֲמַרְתֶּם שֶׁהוּא דִּין?</p>"],[9522012061,"<p>אֶלָּא כָּךְ לָמַדְנוּ, הַכֹּל הוּא בְּמִשְׁקָל אֶחָד עוֹלֶה, וְהַכֹּל אֶחָד. וּמִשּׁוּם שֶׁהַדִּינִים הַתַּחְתּוֹנִים אֲחוּזִים (ומתלכדים) וּמְחֻבָּרִים בְּשַׂעֲרוֹתָיו שֶׁל זֶה, הוּא נִקְרָא הַדִּין הַקָּשֶׁה, וּכְשֶׁעוֹבֵר מִמֶּנּוּ הַשֵּׂעָר שֶׁל הָרֹאשׁ - נִמְתָּק, וְהַדִּינִים שֶׁל מַטָּה לֹא מִזְדַּמְּנִים, וּמִשּׁוּם כָּךְ נִקְרָא טָהוֹר. שֶׁלֹּא נִקְרָא טָהוֹר, אֶלָּא כְּשֶׁיּוֹצֵא מִצַּד הַטֻּמְאָה, וּכְשֶׁיּוֹצֵא מִצַּד הַטֻּמְאָה נִקְרָא טָהוֹר, שֶׁכָּתוּב (איוביד) מִי יִתֵּן טָהוֹר מִטָּמֵא. מִטָּמֵא וַדַּאי, וְכָאן כָּתוּב וְאִישׁ כִּי יִמָּרֵט רֹאשׁוֹ קֵרֵחַ הוּא טָהוֹר הוּא.</p>\n<p>וּבֹא רְאֵה, בְּרֹאשׁ הָאִישׁ הַזֶּה נִיצוֹץ הַקָּשֶׁה, וּמִשּׁוּם כָּךְ גֻּלְגֹּלֶת הָרֹאשׁ שֶׁל זֶה אֲדֻמָּה כֻּלָּהּ כַּשּׁוֹשַׁנָּה, וְהַשְּׂעָרוֹת אֲדֻמּוֹת בְּתוֹךְ אֲדֻמּוֹת, וּתְלוּיִים מִמֶּנּוּ כְּתָרִים תַּחְתּוֹנִים שֶׁלְּמַטָּה שֶׁמְּעוֹרְרִים דִּינִים בָּעוֹלָם, וּכְשֶׁעוֹבֵר מִמֶּנּוּ הַשֵּׂעָר וְנִגְלָשׁ, מֵהַחֶסֶד הָעֶלְיוֹן הַכֹּל נִמְתָּק, וְנִקְרָא טָהוֹר עַל שְׁמוֹ.</p>\n<p>אָמַר רַבִּי יְהוּדָה, אִם נִקְרָא עַל שְׁמוֹ - קָדוֹשׁ נִקְרָא וְלֹא טָהוֹר? אָמַר לוֹ, לֹא כָּךְ, שֶׁקָּדוֹשׁ לֹא נִקְרָא אֶלָּא כְּשֶׁהַשֵּׂעָר תָּלוּי, שֶׁהַקְּדֻשָּׁה תְּלוּיָה בַּשֵּׂעָר, שֶׁכָּתוּב (במדבר ו) קָדוֹשׁ יִהְיֶה גַּדֵּל פֶּרַע שְׂעַר רֹאשׁוֹ. וְזֶה נִקְרָא טָהוֹר, מֵהַצַּד שֶׁתְּלוּיִים לְמַטָּה מִמֶּנּוּ. וּמִשּׁוּם כָּךְ עוֹבֵר מִמֶּנּוּ הַשֵּׂעָר וְנִטְהָר.</p>\n<p>וּבֹא רְאֵה, כָּל מִי שֶׁהוּא מִצַּד הַדִּין וְהַדִּינִים נֶאֱחָזִים בּוֹ, לֹא נִטְהָר, עַד שֶׁעוֹבֵר מִמֶּנּוּ הַשֵּׂעָר. וּמִשֶּׁעוֹבֵר מִמֶּנּוּ הַשֵּׂעָר, נִטְהָר. וְאִם תֹּאמַר אָדָם - לֹא כָּךְ, שֶׁהֲרֵי הוּא שְׁלֵמוּת הַכֹּל, וְנִמְצָאִים בּוֹ רַחֲמִים. מִשּׁוּם כָּךְ לֹא כָּךְ, שֶׁכָּל הַקְּדֻשּׁוֹת וְהַקְּדוֹשִׁים הִתְיַחֲדוּ בוֹ. אֲבָל זֶה - הוּא דִּין, וְהַדִּינִים אֲחוּזִים בּוֹ, לֹא נִמְתָּק עַד שֶׁעוֹבֵר מִמֶּנּוּ הַשֵּׂעָר.</p>\n<p>בֹּא רְאֵה, שֶׁהֲרֵי הַלְוִיִּם שֶׁבָּאוּ מִצַּד הַדִּין הַזֶּה לֹא נִטְהָרִים עַד שֶׁעוֹבֵר מֵהֶם הַשֵּׂעָר, שֶׁכָּתוּב (שם ח) וְכֹה תַעֲשֶׂה לָהֶם לְטַהֲרָם הַזֵּה עֲלֵיהֶם מֵי חַטָּאת וְהֶעֱבִירוּ תַעַר עַל כָּל בְּשָׂרָם וְגוֹ'. וּכְדֵי שֶׁיֻּמְתְּקוּ יוֹתֵר, צָרִיךְ הַכֹּהֵן, שֶׁהוּא מִצַּד הַחֶסֶד הָעֶלְיוֹן, לְהָרִים אוֹתָם, שֶׁכָּתוּב וְהֵנִיף אַהֲרֹן אֶת הַלְוִיִּם תְּנוּפָה לִפְנֵי ה'. כְּמוֹ שֶׁהוּא לָאִישׁ הַזֶּה שֶׁלְּמַעְלָה, שֶׁכַּאֲשֶׁר רוֹצֶה לְהִתְמַתֵּק יוֹתֵר, מִתְגַּלֶּה בּוֹ חֶסֶד עֶלְיוֹן, וְנִמְתָּק. וּמַמְתִּיק הוּא לְמַטָּה.</p>\n<p>וְהָאִישׁ הַזֶּה הוּא בִּכְלָל שֶׁל אָדָם, וּכְשֶׁרוֹצֶה הַקָּדוֹשׁ בָּרוּךְ הוּא לְהִלָּחֵם בִּקְרָב, בָּאִישׁ הַזֶּה הוּא נִלְחָם בָּהֶם בִּקְרָב, שֶׁכָּתוּב (שמות טז) ה' אִישׁ מִלְחָמָה, בָּאִישׁ הַזֶּה מַמָּשׁ. וְלֹא נִלְחָם בָּהֶם בִּקְרָב, עַד שֶׁעוֹבֵר לוֹ שְׂעַר הָרֹאשׁ, כְּדֵי שֶׁיִּשְׁתַּלְשְׁלוּ מֵהִשְׁתַּלְשְׁלוּתָם, וְיִשָּׁבְרוּ כָּל אוֹתָם הַכְּתָרִים הָאֲחוּזִים בַּשְּׂעָרוֹת. זֶהוּ שֶׁכָּתוּב (ישעיה ז) בַּיּוֹם הַהוּא יְגַלַּח ה' וְגוֹ', בְּעֶבְרֵי נָהָר בְּמֶלֶךְ אַשּׁוּר אֶת הָרֹאשׁ וְשַׂעַר הָרַגְלָיִם וְגַם אֶת הַזָּקָן תִּסְפֶּה.</p>\n<p>לָמַדְנוּ, וְכֹה תַעֲשֶׂה לָהֶם לְטַהֲרָם. מַה זֶּה וְכֹה? כְּמוֹ שֶׁלְּמַעְלָה, הַזֵּה עֲלֵיהֶם מֵי חַטָּאת, שִׁיּוּרֵי הַטַּל שֶׁל הַבְּדוֹלַח כָּאן מֵי חַטָּאת, שֶׁהֵם שִׁיּוּרֵי הַטַּל. לֶעָתִיד לָבֹא כָּתוּב, (יחזקאל לז) וְזָרַקְתִּי עֲלֵיכֶם מַיִם טְהוֹרִים. וְכִבְּסוּ בִגְדֵיהֶם, כְּמוֹ שֶׁלְּמַעְלָה, שֶׁתִּקּוּנֵי הָאִישׁ הַזֶּה רוֹחֲצִים בְּחֶסֶד עֶלְיוֹן, וְנִטְהָר מִן הַכֹּל.</p>\n<p>וְשָׁנִינוּ, לָמָּה כָּתוּב בְּתַעַר, וְלֹא בְמִסְפָּרַיִם? אֶלָּא, מִשּׁוּם שֶׁיַּעֲבֹר הַשֵּׂעָר בְּשָׁרְשׁוֹ וְיַעַבְרוּ מִמֶּנּוּ הַדִּינִים הַתַּחְתּוֹנִים מֵהִשְׁתַּלְשְׁלוּתָם. וּבִזְמַן שֶׁיֵּכְשְׁרוּ הַמַּעֲשִׂים לְמַטָּה, עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַעֲבִיר לוֹ אֶת הַשֵּׂעָר הַזֶּה וּלְגַלֵּחַ אוֹתוֹ, כְּדֵי שֶׁלֹּא יִצְמַח וְיִרְבֶּה, שֶׁכָּתוּב כִּי יִמָּרֵט רֹאשׁוֹ.</p>\n<p>אָמַר רַבִּי יִצְחָק, גָּדוֹל מִכָּל הַלְוִיִּם הָיָה קֹרַח, שֶׁעָשָׂה אוֹתוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא לְמַטָּה כְּמוֹ שֶׁלְּמַעְלָה, וְקָרָא לוֹ קֹרַח. מָתַי? בְּשָׁעָה שֶׁגִּלַּח בִּשְׁבִילוֹ אֶת הָאִישׁ הַזֶּה, שֶׁכָּתוּב קֵרֵחַ הוּא.</p>\n<p>וּכְשֶׁרָאָה קֹרַח אֶת רֹאשׁוֹ בְּלִי שֵׂעָר וְרָאָה אֶת אַהֲרֹן מִתְקַשֵּׁט בְּקִשּׁוּטֵי מְלָכִים, הִזְדַּלְזֵל בְּעֵינָיו וְקִנֵּא לְאַהֲרֹן. אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא: אֲנִי עָשִׂיתִי אוֹתְךְ כְּמוֹ שֶׁלְּמַעְלָה, לֹא רָצִיתָ לַעֲלוֹת לָעֶלְיוֹנִים, רֵד לְמַטָּה וְתִהְיֶה בַתַּחְתּוֹנִים. שֶׁכָּתוּב (במדבר טז) וְיָרְדוּ חַיִּים שְׁאוֹלָה. מַהוּ הַשְּׁאוֹל? גֵּיהִנֹּם, שֶׁשָּׁם צוֹוְחִים הָרְשָׁעִים, וְאֵין מִי שֶׁמְּרַחֲמִים עֲלֵיהֶם. וַעֲתִידִים הֵם לִחְיוֹת וְלַעֲלוֹת כְּשֶׁיְּעוֹרֵר הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת עַמּוֹ וּלְהַחֲיוֹתָם, שֶׁכָתוּב (שמואל א ב) ה' מֵמִית וּמְחַיֶּה מוֹרִיד שְׁאוֹל וַיָּעַל.</p>\n<p>וְאִם מִפְּאַת פָּנָיו יִמָּרֵט רֹאשׁוֹ. לָמַדְנוּ, יֵשׁ פָּנִים וְיֵשׁ פָּנִים. וּמִי הַפָּנִים הַלָּלוּ? אֵלּוּ הֵם שֶׁנִּקְרָאִים פָּנִים שֶׁל זַעַם. וְכָל אֵלּוּ שֶׁתְּלוּיִים מֵאוֹתָם פָּנִים חֲצוּפִים, כֻּלָּם תַּקִּיפִים, כֻּלָּם לֹא מְרַחֲמִים. וּכְשֶׁעוֹבֵר הַשֵּׂעָר מִצַּד אוֹתָם הַפָּנִים, כֻּלָּם עוֹבְרִים וְנִשְׁבָּרִים.</p>\n<p>שֶׁלָּמַדְנוּ, כָּל אוֹתָם שֶׁתְּלוּיִים מֵהַשֵּׂעָר שֶׁל הָרֹאשׁ, הֵם עֶלְיוֹנִים עַל הָאֲחֵרִים וְלֹא חֲצוּפִים כְּמוֹתָם, וְכָל אוֹתָם שֶׁתְּלוּיִים מִצַּד הַשֵּׂעָר שֶׁל אוֹתָם הַפָּנִים, כֻּלָּם חֲצוּפִים וְתַקִּיפִים, וּמִשּׁוּם כָּךְ פָּנָיו מְלֹהָטִים כָּאֵשׁ, מִשּׁוּם הַנִּיצוֹץ שֶׁל הַנִּיצוֹץ הַקָּשֶׁה. וּבָזֶה כָּתוּב (איכה ד) פְּנֵי ה' חִלְּקָם. (תהלים לד) פְּנֵי ה' בְּעֹשֵׂי רָע.</p>"],[9522012062,"<p>אָמַר רַבִּי יִצְחָק, מַהוּ נֶגַע לָבָן אֲדַמְדָּם? נֶגַע מַמָּשׁ הוּא, אִם נִרְאֶה לָבָן, וְהָאָדם לֹא עָבַר. מַשְׁמָע שֶׁכָּתוּב לָבָן אֲדַמְדָּם. אָמַר רַבִּי יוֹסֵי, שֶׁהַלָּבָן לֹא נִרְאֶה אֶלָּא עִם אָדם, כְּמוֹ הַלָּבָן וְהָאָדם. רַבִּי יִצְחָק אָמַר, אַף עַל גַּב שֶׁהַלָּבָן נִרְאֶה, אִם הָאָדם לֹא הוֹלֵךְ - נֶגַע הוּא, שֶׁכָּתוּב (ישעיה א) אִם יִהְיוּ חֲטָאֵיכֶם כַּשָּׁנִים כַּשֶּׁלֶג יַלְבִּינוּ. וּכְשֶׁמַּלְבִּין, כָּל הָרַחֲמִים נִמְצָאִים, וְדִינִים לֹא נִמְצָאִים. (שהרי נעקרו).</p>\n<p>לָמַד רַבִּי אַבָּא, כָּתוּב נֶגַע הוּא, וְכָתוּב נֶגַע הִיא. אֶחָד זָכָר וְאֶחָד נְקֵבָה. אֶלָּא כְּשֶׁהַנְּקֵבָה נִטְמֵאת מִשּׁוּם חֲטָאֵי הַתַּחְתּוֹנִים, כָּתוּב נֶגַע הִיא. וּכְשֶׁהַזָּכָר לֹא נִטְהָר מִשּׁוּם חֲטָאֵי הַתַּחְתּוֹנִים, כָּתוּב נֶגַע הוּא.</p>\n<p>וְהַדְּבָרִים הַלָּלוּ נוֹדָעִים לַכֹּהֵן, הַדִּינִים שֶׁבָּאִים מִזֶּה וְהַדִּינִים שֶׁבָּאִים מִזֶּה. וְנוֹדָעִים הַקָּרְבָּנוֹת שֶׁצָּרִיךְ לְהַקְרִיב, שֶׁכָּתוּב זָכָר תָּמִים, וְכָתוּב נְקֵבָה תְּמִימָה יְבִיאֶנָּה. שֶׁהֲרֵי הַדְּבָרִים נוֹדָעִים מֵאֵיפֹה בָּאוּ הַדִּינִים וּמֵאֵיפֹה אוֹתָם הַחֲטָאִים, שֶׁאֲחוּזִים בָּזֶה אוֹ בָּזֶה. וְעַל כֵּן כָּתוּב, (תהלים נא) זִבְחֵי אֱלֹהִים רוּחַ נִשְׁבָּרָה. לְהוֹצִיא שְׁאָר הַקָּרְבָּנוֹת שֶׁלֹּא כָתוּב רוּחַ נִשְׁבָּרָה, שֶׁהֵם שָׁלוֹם לָעוֹלָם וְשִׂמְחַת הָעֶלְיוֹנִים וְהַתַּחְתּוֹנִים.</p>\n<p>וְאִם יִרְאֶנָּה הַכֹּהֵן. שָׁנָה רַבִּי יוֹסֵי, כָּתוּב (תהלים סה) שֹׁמֵעַ תְּפִלָּה עָדֶיךְ וְגוֹ'. שֹׁמֵעַ תְּפִלָּה - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא. רַבִּי חִזְקִיָּה אָמַר, שּמֵעַ תְּפִלָּה?! שׁוֹמֵעַ תְּפִלּוֹת הָיָה צָרִיךְ לִהְיוֹת! מַה זֶּה שּמֵעַ תְּפִלָּה? אֶלָּא תְּפִלָּה זוֹ כְּנֶסֶת יִשְׂרָאֵל, שֶׁהִיא תְּפִלָּה, שֶׁכָּתוּב (שם קט) וַאֲנִי תְפִלָּה. ((תהלים סט) ואני תפלתי) וְדָוִד אָמַר אוֹתָהּ בִּשְׁבִיל כְּנֶסֶת יִשְׂרָאֵל. וּמַה שֶּׁאָמַר וַאֲנִי תְפִלָּה, הַכֹּל אֶחָד, וְעַל זֶה שֹׁמֵעַ תְּפִלָּה, וְזוֹ תְּפִלָּה שֶׁל יָד, שֶׁכָּתוּב (שמות יג) עַל יָדְכָה, בְּהֵ\"א.</p>\n<p>עָדֶיךָ כָּל בָּשָׂר יָבאוּ - בְּשָׁעָה שֶׁהַגּוּף שָׁרוּי בְּצַעַר, בְּמַחֲלוֹת וּמַכּוֹת, כְּמוֹ שֶׁנֶּאֱמַר וּבָשָׂר כִּי יִהְיֶה בְעוֹרוֹ. אֶת הַנֶּגַע בְּעוֹר הַבָּשָׂר. הַבָּשָׂר הַחַי. וּמִשּׁוּם כָּךְ לֹא כָתוּב כָּל רוּחַ יָבאוּ, אֶלָּא כָּל בָּשָׂר יָבֹאוּ. מַה זֶּה עָדֶיךְ? אֶלָּא כְּמוֹ שֶׁנֶּאֱמַר וְהוּבָא אֶל הַכֹּהֵן, זֶה הוּא הַקָּדוֹשׁ בָּרוּךְ הוּא. זֶהוּ שֶׁכָּתוּב וְאִם יִרְאֶנָּה הַכֹּהֵן. בֹּא רְאֵה, בְּמָקוֹם אֶחָד אַהֲרֹן הַכֹּהֵן, וּבְמָקוֹם אַחֵר הַכֹּהֵן סְתָם, וְזֶה הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>"],[9522012063,"<p>אָמַר רַבִּי יִצְחָק, וַהֲרֵי כָּתוּב נֶגַע צָרַעַת כִּי תִהְיֶה בְּאָדָם וְהוּבָא אֶל הַכֹּהֵן, אִם כָּךְ, זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא? אָמַר לוֹ, כֵּן, מִשּׁוּם שֶׁבּוֹ תְלוּיָה כָּל טָהֳרָה וְכָל קְדֻשָּׁה. אָמַר לוֹ, אִם כָּךְ, לָמָּה וְהוּבָא? וְהָעֳלָה הָיָה צָרִיךְ לִהְיוֹת! אָמַר לוֹ, כְּמוֹ שֶׁנֶּאֱמַר (שם כז) וְהוּבָא אֶת בַּדָּיו בַּטַּבָּעֹת, שֶׁמַּכְנִיס זֶה לְתוֹךְ זֶה. אַף כָּאן וְהוּבָא, שֶׁיִּכָּנְסוּ לַכֹּהֵן לְטַהֵר אוֹתוֹ (כשחוזר בו) וְיַכְנִיסוּ דָבָר לְפָנָיו.</p>\n<p>אָמַר רַבִּי יִצְחָק, כָּךְ שָׁנִינוּ, נֶגַע צָרַעַת: נֶגַע - הוּא הַדִּין הַקָּשֶׁה הַשָּׁרוּי בָּעוֹלָם. צָרַעַת - הַסְגָּרָה, כְּמוֹ שֶׁנֶּאֱמַר הֶסְגֵּר הָאוֹר הָעֶלְיוֹן. הֶסְגֵּר שֶׁל הַטּוֹב הָעֶלְיוֹן שֶׁלֹּא יוֹרֵד לָעוֹלָם. כִּי תִהְיֶה בְּאָדָם - בְּאָדָם סְתָם. וְהוּבָא אֶל הַכֹּהֵן - זֶה הַכֹּהֵן שֶׁלְּמַטָּה, וְהוּא מְתֻקָּן לִפְתֹּחַ אוֹתוֹ הַסֶּגֶר וּלְהַדְלִיק מְאוֹרוֹת, שֶׁיִּמָּצְאוּ עַל יָדוֹ בְּרָכוֹת לְמַעְלָה וּלְמַטָּה, וְיַעֲבֹר וְיִסְתַּלֵּק אוֹתוֹ הַנֶּגַע, וְיִשְׁרֶה אוֹר שֶׁל רַחֲמִים עַל הַכֹּל, וּמִשּׁוּם כָּךְ וְהוּבָא אֶל הַכֹּהֵן.</p>"],[9522012064,"<p>אָמַר רַבִּי אַבָּא, רָאִיתִי אוֹתָם בְּנֵי הָעוֹלָם שֶׁלֹּא מַשְׁגִּיחִים וְלֹא יוֹדְעִים בִּכְבוֹד רִבּוֹנָם. כָּתוּב בְּיִשְׂרָאֵל, (ויקרא כ) אֲשֶׁר הִבְדַּלְתִּי אֶתְכֶם מִן הָעַמִּים לִהְיוֹת לִי. וְכָתוּב (שם) וְהִתְקַדִּשְׁתֶּם וִהְיִיתֶם קְדשִׁים כִּי קָדוֹשׁ אֲנִי ה'. אִם הֵם מִתְרַחֲקִים, אֵיפֹה הַקְּדֻשָּׁה שֶׁלָּהֶם? הֲרֵי רְצוֹנָם הִתְרַחֵק מִמֶּנּוּ, וְהַכָּתוּב מַכְרִיז וְאוֹמֵר, (תהלים לב) אַל תִּהְיוּ כְּסוּס כְּפֶרֶד אֵין הָבִין. בַּמֶּה נִפְרָדִים בְּנֵי אָדָם מִסּוּס וּפֶרֶד? בִּקְדֻשַּׁת עַצְמָם, שֶׁיִּמָּצְאוּ שְׁלֵמִים וּרְשׁוּמִים מֵהַכֹּל.</p>\n<p>וְעַל כֵּן זִוּוּגָם שֶׁל בְּנֵי אָדָם הוּא בִּזְמַנִּים יְדוּעִים, לְכַוֵּן הָרָצוֹן לְהִדָּבֵק בַּקָּדוֹשׁ בָּרוּךְ הוּא. וַהֲרֵי הֵעִירוּ, בַּחֲצוֹת הַלַּיְלָה הַקָּדוֹשׁ בָּרוּךְ הוּא נִכְנָס לְגַן עֵדֶן לְהִשְׁתַּעֲשֵׁעַ עִם הַצַּדִּיקִים, וּכְנֶסֶת יִשְׂרָאֵל מְשַׁבַּחַת אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, וְהִיא עֵת רָצוֹן לִדְבֹּק בָּהֶם.</p>\n<p>וְהַחֲבֵרִים שֶׁמִּשְׁתַּדְּלִים בַּתּוֹרָה, מִשְׁתַּתְּפִים עִם כְּנֶסֶת יִשְׂרָאֵל לְשַׁבֵּחַ אֶת הַמֶּלֶךְ הַקָּדוֹשׁ, וּמִתְעַסְּקִים בַּתּוֹרָה לִשְׁאָר בְּנֵי הָאָדָם, אָז עֵת רָצוֹן לְהִתְקַדֵּשׁ בִּקְדֻשַּׁת הַקָּדוֹשׁ בָּרוּךְ הוּא וּלְכַוֵּן רָצוֹן לִדְבֹּק בּוֹ. וְאוֹתָם הַחֲבֵרִים שֶׁמִּשְׁתַּדְּלִים בַּתּוֹרָה, הַזִּוּוּג שֶׁלָּהֶם בְּשָׁעָה שֶׁנִּמְצָא זִוּוּג אַחֵר, וְזֶה מִשַּׁבָּת לְשַׁבָּת, לְכַוֵּן הָרָצוֹן לִדְבֹּק בַּקָּדוֹשׁ בָּרוּךְ הוּא וּבִכְנֶסֶת יִשְׂרָאֵל, שֶׁהִיא עֵת רָצוֹן שֶׁהַכֹּל מִתְבָּרְכִים, הָעֶלְיוֹנִים וְהַתַּחְתּוֹנִים.</p>\n<p>אִם בְּנֵי אָדָם הִתְרַחֲקוּ מִמֶּנּוּ וְעוֹשִׂים כַּבְּהֵמוֹת, אֵיפֹה הַקְּדֻשָּׁה שֶׁלָּהֶם שֶׁיִּמָּצְאוּ קְדוֹשִׁים? אֵיפֹה הַנְּפָשׁוֹת הַקְּדוֹשׁוֹת שֶׁמּוֹשְׁכִים מִלְּמַעְלָה? וּשְׁלֹמֹה הַמֶּלֶךְ צוֹוֵחַ וְאוֹמֵר, (משלי יט) גַּם בְּלֹא דַעַת נֶפֶשׁ לֹא טוֹב. גַּם בְּלֹא דַעַת, מִי הוּא הַדַּעַת? זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא. נֶפֶשׁ לֹא טוֹב - זוֹהִי הַנֶּפֶשׁ שֶׁהֵם מוֹשְׁכִים בְּמַעֲשֵׂיהֶם. לֹא טוֹב, שֶׁהֲרֵי מֵהַצַּד הָאַחֵר נִמְשָׁכוֹת עֲלֵיהֶם נֶפֶשׁ שֶׁאֵינָהּ טוֹב, מִשּׁוּם שֶׁלֹּא מְכַוְּנִים לִבָּם לַקָּדוֹשׁ בָּרוּךְ הוּא.</p>\n<p>מִי שֶׁמִּתְלַהֵט בַּיֵּצֶר הָרָע בְּלִי רָצוֹן וְכַוָּנַת הַלֵּב לַקָּדוֹשׁ בָּרוּךְ הוּא, מֵהַצַּד שֶׁל יֵצֶר הָרָע נִמְשֶׁכֶת עָלָיו נֶפֶשׁ שֶׁאֵינָהּ טוֹב. זֶהוּ שֶׁכָּתוּב גַּם בְּלֹא דַעַת נֶפֶשׁ לֹא טוֹב וְאָץ בְּרַגְלַיִם חוֹטֵא. מִי שֶׁהוּא אָץ בָּרַגְלַיִם וְדוֹחֶה אֶת הַשָּׁעָה בְּלִי רָצוֹן קָדוֹשׁ - חוֹטֵא, חוֹטֵא וַדַּאי בַּכֹּל.</p>\n<p>וְעַל זֶה שׁוֹרוֹת מַכּוֹת רָעוֹת בִּבְנֵי אָדָם, וּמְעִידִים בִּפְנֵיהֶם עַל חֻצְפָּתָם, לְהַרְאוֹת שֶׁהִנֵּה הַקָּדוֹשׁ בָּרוּךְ הוּא מוֹאֵס בָּהֶם וְאֵין דַּעְתּוֹ בָּהֶם, עַד שֶׁהֵם זוֹכִים וּמַכְשִׁירִים אֶת מַעֲשֵׂיהֶם כְּמִקֹּדֶם וּמִתְבָּרְכִים (ומטהרים). וְעַל זֶה נוֹדָעוֹת הַמַּכּוֹת לַכֹּהֵן, אוֹתָן שֶׁבָּאוֹת מִצַּד הַטֻּמְאָה וְאוֹתָן שֶׁבָּאוֹת מֵהַצַּד הָאַחֵר.</p>"],[9522012065,"<p>כְּמוֹ זֶה כָּתוּב, כִּי תָבֹאוּ אֶל אֶרֶץ כְּנַעַן וְגוֹ', וְנָתַתִּי נֶגַע צָרַעַת בְּבֵית אֶרֶץ אֲחֻזַּתְכֶם. וְכִי שָׂכָר טוֹב הוּא שֶׁיִּמָּצֵא בְאוֹתָם שֶׁזּוֹכִים לְהִכָּנֵס לָאָרֶץ? אֶלָּא הִנֵּה פֵּרְשׁוּהָ, לִמְצֹא מַטְמוֹנִים שֶׁהִטְמִינוּ בְּבֵיתָם, וְלֵהָנוֹת בָּהֶם אֶת יִשְׂרָאֵל.</p>\n<p>אֲבָל בּא רְאֵה, אַשְׁרֵיהֶם יִשְׂרָאֵל שֶׁהֵם מִתְדַּבְּקִים לַקָּדוֹשׁ בָּרוּךְ הוּא, וְהַקָּדוֹשׁ בָּרוּךְ הוּא אוֹהֵב אוֹתָם, שֶׁכָּתוּב (מלאכי א) אָהַבְתִּי אֶתְכֶם אָמַר ה'. וּמִתּוֹךְ אַהֲבָתוֹ הִכְנִיס אוֹתָם לָאָרֶץ הַקְּדוֹשָׁה, לְהַשְׁרוֹת שְׁכִינָתוֹ בֵּינֵיהֶם, וְשֶׁיִּהְיֶה דִיּוּרוֹ עִמָּהֶם, וְיִשְׂרָאֵל שֶׁיִּמָּצְאוּ קְדוֹשִׁים עַל כָּל בְּנֵי הָעוֹלָם.</p>\n<p>בֹּא רְאֵה, כָּתוּב (שמות לה) וְכָל הַנָּשִׁים אֲשֶׁר נָשָׂא לִבָּן וְגוֹ'. בְּשָׁעָה שֶׁהָיוּ עוֹשִׂים מַעֲשֶׂה, הָיוּ אוֹמְרִים: זֶה לַמִּקְדָּשׁ, זֶה לַמִּשְׁכָּן, וְזֶה לַפָּרֹכֶת. וְכֵן כָּל אוֹתָם הָאָמָּנִים, כְּדֵי שֶׁתִּשְׁרֶה קְדֻשָּׁה עַל יְדֵיהֶם, וּמִתְקַדֶּשֶׁת אוֹתָהּ עֲבוֹדָה. וּכְשֶׁעוֹלֶה לִמְקוֹמוֹ, עוֹלֶה בִקְדֻשָּׁה.</p>\n<p>כְּמוֹ כֵן מִי שֶׁעוֹשֶׂה עֲבוֹדָה לַעֲבוֹדָה זָרָה אוֹ לַצַּד הָאַחֵר שֶׁאֵינוֹ קָדוֹשׁ, כֵּיוָן שֶׁמַּזְכִּיר אוֹתוֹ עַל אוֹתוֹ הַמַּעֲשֶׂה, הֲרֵי רוּחַ טֻמְאָה שׁוֹרָה עָלָיו. וּכְשֶׁעוֹלֶה הַמַּעֲשֶׂה, עוֹלֶה בְטֻמְאָה. הַכְּנַעֲנִיִּים הֵם עוֹבְדֵי עֲבוֹדָה זָרָה, וּמְדֻבָּקִים כֻּלָּם יַחַד בְּרוּחַ טֻמְאָה בַּעֲבוֹדָה זָרָה, וְהָיוּ בּוֹנִים בִּנְיָן לְפַרְצוּפֵיהֶם (לטנופיהם) וּלְגִעוּלֵיהֶם לַצַּד הַטָּמֵא לַעֲבוֹדָה זָרָה. וּכְשֶׁמַּתְחִילִים לִבְנוֹת, הָיוּ אוֹמְרִים דִּבּוּר. וְכֵיוָן שֶׁנִּזְכָּר בְּפִיהֶם, עוֹלָה עָלָיו רוּחַ שֶׁל טֻמְאָה. כְּשֶׁעוֹלֶה הַמַּעֲשֶׂה, הוּא עוֹלֶה בְּרוּחַ טֻמְאָה.</p>\n<p>כֵּיוָן שֶׁנִּכְנְסוּ יִשְׂרָאֵל לָאָרֶץ, רָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לְטַּהֵר אוֹתָם וּלְקַדֵּשׁ לָהֶם אֶת הָאָרֶץ, וּלְפַנּוֹת מָקוֹם לַשְּׁכִינָה, שֶׁלֹּא תִשְׁרֶה הַשְּׁכִינָה בְּתוֹךְ הַטֻּמְאָה. וְעַל כֵּן בְּאוֹתוֹ נֶגַע צָרַעַת הָיוּ סוֹתְרִים בִּנְיָנִים שֶׁל עֵצִים וַאֲבָנִים שֶׁנַּעֲשׂוּ בְטֻּמְאָה.</p>"],[9522012066,"<p>בֹּא רְאֵה, אִם הַמַּעֲשֶׂה הַזֶּה הָיָה לִמְצֹא מַטְמוֹנִים בִּלְבַד, יַחֲזִירוּ הָאֲבָנִים אַחַר כָּךְ כְּמוֹת שֶׁהֵם לִמְקוֹמָם, וְהֶעָפָר לִמְקוֹמוֹ. אֲבָל הַפָּסוּק כּוֹתֵב, וְחִלְּצוּ אֶת הָאֲבָנִים. וְכָתוּב וְעָפָר אַחֵר יִקַּח. כְּדֵי שֶׁתַּעֲבֹר רוּחַ הַטֻּמְאָה, וְיִתְפַּנֶּה וְיִתְקַדֵּשׁ כָּעֵת כְּמִקֹּדֶם, וְיִמָּצְאוּ יִשְׂרָאֵל בִּקְדֻשָּׁה וּבְדִיּוּר קָדוֹשׁ, לְהַשְׁרוֹת בֵּינֵיהֶם שְׁכִינָה.</p>\n<p>וְעַל כֵּן, מִי שֶׁבּוֹנֶה בִּנְיָן, כְּשֶׁמַּתְחִיל לִבְנוֹת צָרִיךְ לְהַזְכִּיר בְּפִיו, שֶׁהֲרֵי לַעֲבוֹדַת הַקָּדוֹשׁ בָּרוּךְ הוּא הוּא בּוֹנֶה, מִשּׁוּם שֶׁכָּתוּב (ירמיה כב) הוֹי בּנֶה בֵיתוֹ בְּלֹא צֶדֶק וְגוֹ'. וְאָז סִיּוּעַ שְׁמֵימִי שׁוֹרֶה עָלָיו, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מַזְמִין עָלָיו קְדֻשָּׁה וְקוֹרֵא עָלָיו שָׁלוֹם. זֶהוּ שֶׁכָּתוּב (איוב ה) וְיָדַעְתָּ כִּי שָׁלוֹם אָהֳלֶךְ וְגוֹ'. מַה זֶּה וּפָקַדְתָּ נָוְךְ? הֲרֵי פֵּרְשׁוּהָ. אֲבָל וּפָקַדְתָּ, לְהַפְקִיד דִּבּוּר בַּפֶּה כְּשֶׁהוּא בּוֹנֶה. וְאָז כָּתוּב וְלֹא תֶחֱטָא. וְאִם לֹא, הֲרֵי מַזְמִין לְבֵיתוֹ אֶת הַצַּד הָאַחֵר.</p>\n<p>כָּל שֶׁכֵּן מִי שֶׁבּוֹנֶה, וּרְצוֹנוֹ בְּצוּרָה אַחֶרֶת, מִשּׁוּם שֶׁמְּיַחֵד הַבַּיִת לַצַּד הָאַחֵר לְהִטָּמֵא בּוֹ, הֲרֵי וַדַּאי שׁוֹרָה בּוֹ רוּחַ שֶׁל טֻמְאָה, וְלֹא יוֹצֵא אוֹתוֹ אָדָם מִן הָעוֹלָם עַד שֶׁנֶּעֱנָשׁ בַּבַּיִת הַהוּא. וּמִי שֶׁדָּר בּוֹ יָכוֹל לְהִנָּזֵק, שֶׁהֲרֵי בַּדִּירָה הַהִיא שׁוֹרָה בָּהּ רוּחַ טֻמְאָה, וּמַזִּיקָה מִי שֶׁנִּמְצָא בָּהּ.</p>"],[9522012067,"<p>וְאִם תֹּאמַר, בַּמֶּה יָדוּעַ? כְּגוֹן שֶׁנִּזּוֹק בַּבַּיִת הַהוּא אוֹתוֹ שֶׁבָּנָה אוֹתוֹ, אוֹ אַנְשֵׁי בֵיתוֹ, אוֹ בְּנִזְקֵי גוּף, אוֹ בְּנִזְקֵי מָמוֹן, הוּא וּשְׁנֵי אֲחֵרִים אַחֲרָיו. הֲרֵי וַדַּאי יִבְרַח אָדָם לְהַר, וְלֹא יָדוּר בּוֹ. יָדוּר בִּמְחִלַּת עָפָר, וְלֹא יָדוּר בּוֹ.</p>\n<p>וּמִשּׁוּם כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא חָס עַל יִשְׂרָאֵל, שֶׁהֵם לֹא יוֹדְעִים דָּבָר בְּכָל אוֹתָם הַבָּתִּים, וְהוּא אוֹמֵר: אַתֶּם לֹא יוֹדְעִים - אֲנִי יוֹדֵעַ, וְרָשַׁמְתִּי אוֹתָם בְּנֶגַע. נֶגַע דָּר בְּבַיִת, הִנֵּה נֶגַע אַחֵר תַּקִּיף שֶׁיּוֹצִיא אוֹתוֹ וְיַעֲבִיר אוֹתוֹ מִן הָעוֹלָם. וְאָז - וְנָתַץ אֶת הַבַּיִת אֶת אֲבָנָיו וְאֶת עֵצָיו. כֵּיוָן שֶׁהוֹלֵךְ לוֹ, מָה הַטַּעַם וְנָתַץ אֶת הַבַּיִת? אֶלָּא בְּכָל זְמַן שֶׁאוֹתוֹ בִּנְיָן יִהְיֶה קַיָּם - שֶׁלּוֹ הוּא, וְיָכוֹל לַחֲזֹּר.</p>\n<p>זְהִ בָּאָרֶץ הַקְּדוֹשָׁה, כָּל שֶׁכֵּן בְּאֶרֶץ אַחֶרֶת, שֶׁרוּחַ הַטֻּמְאָה מְצוּיָה יוֹתֵר, וְיָכוֹל אָדָם לְהִנָּזֵק. אָמַר רַבִּי אֶלְעָזָר, וְכָל שֶׁכֵּן שֶׁנִּקְרָא בַקְּלִפּוֹת שֶׁל חֲבֵרָיו הָאֲחֵרִים לְהִמָּצֵא שָׁם, וַאֲפִלּוּ דְּפִיקוֹת בַּכֵּלִים לֹא מַעֲבִירִים אוֹתוֹ מִן הַבַּיִת. וּמִשּׁוּם כָּךְ הַפָּסוּק הַזֶּה מַכְרִיז וְאוֹמֵר, הוֹי בּנֶה בֵיתוֹ בְּלֹא צֶדֶק. הוֹי וַדַּאי שֶׁאוֹמְרִים כָּל יוֹם בַּבַּיִת הַהוּא.</p>\n<p>רַבִּי יוֹסֵי נִכְנַס יוֹם אֶחָד לְבַיִת אֶחָד, הִגִּיעַ לַסַּף (טרח בטפוס) וְנִכְנַס פְּנִימָה. שָׁמַע קוֹל אֶחָד שֶׁאוֹמֵר: הִתְכַּנְּסוּ וְהִכָּנְסוּ, הִנֵּה אֶחָד מֵהַיְרִיבִים שֶׁלָּנוּ. הִתְחַבְּרוּ וְנַזִּיק אוֹתוֹ לִפְנֵי שֶׁיֵּצֵא. אָמְרוּ, לֹא נוּכַל אֶלָּא אִם דִּיּוּרוֹ כָּאן. יָצָא רַבִּי יוֹסֵי וּפָחַד. אָמַר, וַדַּאי מִי שֶׁעוֹבֵר עַל דִּבְרֵי הַחֲבֵרִים, מִתְחַיֵּב בְּנַפְשׁוֹ.</p>\n<p>אָמַר לוֹ רַבִּי חִיָּיא, וַהֲרֵי הַגּוֹיִם וּשְׁאָר בְּנֵי אָדָם דָּרִים בְּתוֹכוֹ, וְנִשְׁלְמוּ. אָמַר לוֹ, הֵם מִצִּדָּם הֵם בָּאִים, אֲבָל מִי שֶׁיְּרֵא חֵטְא יָכוֹל לְהִנָּזֵק. וַאֲפִלּוּ הֵם, אִם יְעַכְּבוּ אֶת דִּיּוּרָם בּוֹ, לֹא יֵצְאוּ בְשָׁלוֹם. אָמַר לוֹ, וַהֲרֵי כָּתוּב (איוב כא) בָּתֵּיהֶם שָׁלוֹם מִפָּחַד. אָמַר לוֹ, כְּגוֹן שֶׁהָיָה מֵאַחֵר, וְנִבְנָה מִצֶּדֶק. וְהַפָּסוּק כָּךְ הוּא, בָּתֵּיהֶם שָׁלוֹם מִפָּחַד - כְּשֶׁבָּתֵּיהֶם שָׁלוֹם מִפַּחַד, שֵׁבֶט אֱלוֹהַּ לֹא שׁוֹרֶה עֲלֵיהֶם.</p>"],[9522012068,"<p>וּבָא אֲשֶׁר לוֹ הַבַּיִת וְהִגִּיד וְגוֹ' (ויקרא יד). וְהִגִּיד?! וַיֹּאמֶר הָיָה צָרִיךְ לִהְיוֹת, אוֹ וַיְדַבֵּר. מַה זֶּה וְהִגִּיד? אֶלָּא בְּכָל מָקוֹם דָּבָר שֶׁל חָכְמָה הוּא, וְהִנֵּה פֵּרְשׁוּהָ. כְּנֶגַע נִרְאָה לִי בַּבָּיִת. כְּנֶגַע?! נֶגַע הָיָה צָרִיךְ לִהְיוֹת! נִרְאָה לִי?! יֵשׁ לִי הָיָה צָרִיךְ לִהְיוֹת, שֶׁהֲרֵי כָּתוּב וְנָתַתִּי נֶגַע צָרַעַת בְּבֵית אֶרֶץ אֲחֻזַּתְכֶם, שֶׁיֵּרָאֶה לַכֹּל! לָמָּה כְּנֶגַע נִרְאָה לִי.</p>\n<p>אֶלָּא בְּשָׁעָה שֶׁזֶּה נִכְנָס, אַחֵר מִתְגַּלֶּה, וּמִתְגָּרִים זֶה בָּזֶה. וְעַל זֶה נִרְאָה לִי. אוֹתוֹ שֶׁהִתְכַּסָּה הִתְגַּלָּה, וְשֶׁהִתְגַּלָּה הִתְכַּסָּה, וְאַחַר כָּךְ נִרְאָה לוֹ בִּדְמוּת אוֹתוֹ הַנֶּגַע שֶׁל הַבַּיִת, וְאַחֵר מִתְכַּסֶּה. וְעַל זֶה וְהִגִּיד לַכֹּהֵן, שֶׁדְּבַר חָכְמָה הוּא.</p>\n<p>וְאָז בָּא הַכֹּהֵן, וְיַפִּילוּ הַבַּיִת, וִינַתְּצוּ לוֹ הָאֲבָנִים וְהָעֵצִים וְהַכֹּל. כֵּיוָן שֶׁנִּתְּצוּ וְטִהֲרוּ הַכֹּל, מִתְבָּרְכִים. אָז כָּתוּב (דברים ה) וּבָתִּים טוֹבִים תִּבְנֶה וְיָשָׁבְתָּ. אֵלּוּ נִקְרָאִים טוֹבִים, שֶׁהֲרֵי הָרִאשׁוֹנִים אֵינָם טוֹבִים, וְאֵינָם בִּכְלָל שֶׁל קְדֻשָּׁה וְטָהֳרָה.</p>\n<p>אָמַר רַבִּי יְהוּדָה, אִם כָּךְ, בַּמֶּה מְפָרְשִׁים אֶת הַפָּסוּק שֶׁכָּתוּב, (שם ו) וּבָתִּים מְלֵאִים כָּל טוּב אֲשֶׁר לֹא מִלֵּאתָ? אִם רוּחַ טֻמְאָה שׁוֹרָה בְתוֹכָם, אֵיךְ מְלֵאִים כָּל טוּב? אָמַר רַבִּי אֶלְעָזָר, מְלֵאִים כָּל טוֹב - בְּמָמוֹן, בְּכֶסֶף וּבְזָהָב, וּבַכֹּל, כְּמוֹ שֶׁנֶּאֱמַר (בראשית מה) כִּי טוּב כָּל אֶרֶץ מִצְרַיִם. וְאָמַר רַבִּי יְהוּדָה, וְהִנֵּה כָּל בָּתֵּי הַמִּצְרִים הָיוּ מְלֵאִים כְּשָׁפִים וְתוֹעֵבוֹת? אֶלָּא עֲבוּר הָעֹשֶׁר שֶׁל הָאָרֶץ זֶה נֶאֱמַר. אַף כָּאן עֲבוּר הָעֹשֶׁר וְהַמָּמוֹן הוּא.</p>\n<p>שְׁתֵּי עֲשִׁירֻיּוֹת נָטְלוּ יִשְׂרָאֵל, אַחַת כְּשֶׁיָּצְאוּ מִגָּלוּת מִצְרַיִם, וְאַחַת כְּשֶׁנִּכְנְסוּ לָאָרֶץ. רַבִּי שִׁמְעוֹן אָמַר, כָּל זֶה וַדַּאי הָיָה לְקַדֵּשׁ אֶת הָאָרֶץ, וּלְהַעֲבִיר רוּחַ הַטֻּמְאָה מִן הָאָרֶץ וּמִתּוֹךְ יִשְׂרָאֵל. וּכְשֶׁהַבַּיִת הָיָה מְנֻתָּץ, הָיָה נִמְצָא בּוֹ מָמוֹן לִבְנוֹת אוֹתוֹ וּלְמַלֵּא אֶת בֵּיתוֹ, כְּדֵי שֶׁלֹּא יִצְטַעֵר עַל הַבַּיִת וְיִשְׁהוּ בְדִיּוּר שֶׁל קְדֻשָּׁה.</p>\n<p>וְאִישׁ אוֹ אִשָּׁה כִּי יִהְיֶה בְעוֹר וְגוֹ'. רַבִּי יוֹסֵי אָמַר, כְּמוֹ מָקוֹם גָּבוֹהַּ שֶׁמַּקִּיף בְּבַהֶרֶת עַזָּה, מַרְאֶה שָׁנִינוּ, וּבְמַרְאֶה נִדּוֹן, בְּאוֹתָם הַגְּוָנִים. אָמַר רַבִּי יִצְחָק, שְׁלֹשׁ מֵאוֹת טְעָמִים יֵשׁ מִי שֶׁגּוֹרֵס בְּבַהֶרֶת עַזָּה, וְכֻלָּם לָמַדְתִּי מֵאָבִי, פְּרָט לְשַׂעֲרָה (לבנה) אַחַת טְמֵאָה, עֵד אֶחָד. שְׁנַיִם, שְׁנֵי עֵדִים, וְטָהוֹר. מִכָּאן וָהָלְאָה, אֲפִלּוּ מֵאָה כִּשְׁנַיִם, וּשְׁנַיִם כְּמֵאָה. וְזֶה לָמַדְנוּ לְאַחַר שֶׁכָּתוּב, (דברים יט) לֹא יָקוּם עֵד אֶחָד בְּאִישׁ וְגוֹ', עַל פִּי שְׁנַיִם עֵדִים וְגוֹ'.</p>"],[9522012069,"<p>רַבִּי חִזְקִיָּה הָיָה יוֹשֵׁב לִפְנֵי רַבִּי שִׁמְעוֹן. אָמַר, כָּתוּב נֶגַע לָבָן אֲדַמְדָּם, אָז הוּא נֶגַע, שֶׁהֲרֵי הַלָּבָן לֹא עוֹמֵד בְּעֵינוֹ. פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, כָּתוּב אִם יִהְיוּ חֲטָאֵיכֶם כַּשָּׁנִים וְגוֹ'. אַשְׁרֵיהֶם יִשְׂרָאֵל, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא רוֹצֶה לְטַהֵר אוֹתָם בַּכֹּל כְּדֵי שֶׁלֹּא יִמָּצְאוּ בְדִין לְפָנָיו, וּבַעֲלֵי הַדִּין לֹא יִשְׁלְטוּ בָהֶם, שֶׁהֲרֵי הַכֹּל הוֹלֵךְ אַחַר מִינוֹ. אָדם לְאָדם, וְלָבָן לְלָבָן, יָמִין לְיָמִין, וּשְׂמֹאל לִשְׂמֹאל.</p>\n<p>בְּעֵשָׂו כָּתוּב וַיֵּצֵא הָרִאשׁוֹן אַדְמוֹנִי, וְעַל כֵּן שׁוֹרֶה בּוֹ מִינוֹ. וְאִם תֹּאמַר אַדְמוֹנִי כָּתוּב בְּעֵשָׂו, וְכָתוּב בּוֹ בְּדָוִד, (שמואל א טז) וַיְבִיאֵהוּ וְהוּא אַדְמוֹנִי. אֶלָּא זֶה מִזֻּהֲמַת הַזָּהָב נַעֲשָׂה, וְזֶה נִדְבַּק בְּזֹּהַר הַזָּהָב. כָּתוּב בְּעֵשָׂו, אַדְמוֹנִי כֻּלּוֹ כְּאַדֶּרֶת שֵׂעָר, יָצָא בְזֻהֲמַת הַהִתּוּךְ. בְּדָוִד כָּתוּב, עִם יְפֵה עֵינַיִם וְטוֹב רֹאִי.</p>\n<p>בֹּא וּרְאֵה מָה הַטַּעַם. הַגָּוֶן הַלָּבָן נוֹדָע, וְהַגָּוֶן הָאָדם נוֹדָע. אָדם בָּרִאשׁוֹנָה, וְהִנֵּה נִרְאֶה בּוֹ לָבָן, הֲרֵי טָהֳרָה נוֹלְדָה בּוֹ וּמַתְחִיל לְהִטָּהֵר. לָבָן בָּרִאשׁוֹנָה וְנִרְאֶה בּוֹ אָדם, הִנֵּה מַתְחִיל לְהִטָּמֵא. וְכָתוּב וְטִמְּאוֹ הַכֹּהֵן, שֶׁהִנֵּה נוֹלָד בּוֹ אָדם לְהִטָּמֵא. וְהַכֹּהֵן הָיָה יוֹדֵעַ בְּכָל אוֹתָם הַגְּוָנִים. וְלִפְעָמִים שֶׁנִּרְאֶה בּוֹ גָּוֶן שֶׁל טָהֳרָה, וְיַסְגִּירוֹ לִרְאוֹת אִם יִוָּלֵד בּוֹ גָּוֶן אַחֵר. וְאִם לֹא, מְטַהֵר אוֹתוֹ. זֶהוּ שֶׁכָּתוּב וְטִהֲרוֹ הַכֹּהֵן וְגוֹ'.</p>\n<p>רַבִּי יִצְחָק וְרַבִּי יְהוּדָה הָיוּ הוֹלְכִים בַּדֶּרֶךְ. אָמַר רַבִּי יְהוּדָה, כָּתוּב (מלכים ב ה) וְצָרַעַת נַעֲמָן תִּדְבַּק בְּךְ וּבְזַרְעֲךְ לְעוֹלָם וְגוֹ'. אִם הוּא חָטָא, לָמָּה יִלְקוּ בָנָיו? אָמַר לוֹ, אֱלִישָׁע רָאָה יוֹתֵר מִשְּׁאָר הַנְּבִיאִים. רָאָה שֶׁלֹּא יֵצֵא מִגֵּיחֲזִי בֵּן מְעֻלֶּה, וְעַל כֵּן קִלֵּל אֶת כֻּלָּם.</p>\n<p>וְלֹא עוֹד, אֶלָּא אָמַר לוֹ: אֲנִי עָבַדְתִּי בְּשִׁמּוּשׁ עֶלְיוֹן אֵצֶל אֵלִיָּהוּ, וְזָכִיתִי בִּשְׁנֵי חֲלָקִים, שֶׁהֲרֵי עָבַדְתִּי אוֹתוֹ בֶּאֱמֶת. וְאַתָּה רָשָׁע פָּגַמְתָּ אוֹתִי, נִשְׁבַּעְתָּ לַשֶּׁקֶר וְחָמַדְתָּ, הֲרֵי עָבַרְתָּ עַל כָּל הַתּוֹרָה כֻּלָּהּ, וּמִי שֶׁעוֹבֵר עַל זֶה, מֵת הוּא לָעוֹלָם הַבָּא. אֲבָל מִשּׁוּם שֶׁעָבַדְתָּ אוֹתִי, הַשִּׁמּוּשׁ שֶׁלְּךְ לֹא יִהְיֶה לְחִנָּם; תִּהְיֶה מִיתָתְךְ בָּעוֹלָם הַזֶּה, וְלֹא בָּעוֹלָם הַבָּא. וּמִשּׁוּם כָּךְ, וְצָרַעַת נַעֲמָן תִּדְבַּק בְּךְ וּבְזַרְעֲךְ. (גון הלבן נודע, וגון האדם נודע).</p>"],[9522012070,"<p>אָמַר רַבִּי יוֹסֵי, בֶּגֶד הַצֶּמֶר אוֹ הַפִּשְׁתִּים לָמָּה? אָמַר רַבִּי יִצְחָק, בַּכֹּל שׁוֹרֶה וּבַכֹּל שׁוֹלֵט. וְיֵשׁ כְּמוֹ זֶה, שֶׁכָּתוּב (משלי לא) דָּרְשָׁה צֶמֶר וּפִשְׁתִּים. וּמִשּׁוּם כָּךְ שִׁלְטוֹנוֹ שֶׁל אוֹתוֹ נֶגַע שֶׁיּוֹצֵא מִמָּקוֹם עֶלְיוֹן, זֶה שׁוֹלֵט בַּכֹּל, בִּשְׁנֵי גְוָנִים, בְּצֶמֶר וּבְפִשְׁתִּים. וּמִשּׁוּם כָּךְ, זֹּאת תּוֹרַת נֶגַע הַצָּרַעַת בֶּגֶד הַצֶּמֶר אוֹ הַפִּשְׁתִּים.</p>"],[9522012071,"<p>רַבִּי יִצְחָק הָיָה הוֹלֵךְ לַבָּצִיר שֶׁל אָבִיו. רָאָה אִישׁ אֶחָד שֶׁסָּטָה עִם קֶשֶׁר שֶׁל מַשָּׂא עַל כְּתֵפוֹ. אָמַר לוֹ, קָנִים שֶׁל עֵצִים שֶׁעַל כְּתֶפְךְ לְשֵׁם מָה? לֹא אָמַר לוֹ דָּבָר. הָלַךְ אַחֲרָיו. רָאָה שֶׁנִּכְנַס לִמְעָרָה אַחַת, נִכְנַס אַחֲרָיו. רָאָה קִיטוֹר שֶׁל עָשָׁן שֶׁהָיָה עוֹלֶה מִתַּחַת לָאָרֶץ, וְנִכְנַס הָאִישׁ הַהוּא לְנֶקֶב אֶחָד וְהִתְכַּסָּה מִמֶּנּוּ. פָּחַד רַבִּי יִצְחָק, וְיָצָא לְפִי הַמְּעָרָה.</p>\n<p>בְּעוֹדוֹ יוֹשֵׁב, עָבְרוּ רַבִּי יְהוּדָה וְרַבִּי חִזְקִיָּה. רָאָה אוֹתָם וְקָרַב אֲלֵיהֶם. סִפֵּר לָהֶם אֶת הַמַּעֲשֶׂה. אָמַר רַבִּי יְהוּדָה, בָּרוּךְ הָרַחֲמָן שֶׁהִצִּילְךְ. זוֹהִי מְעָרַת הַמְּצֹרָעִים שֶׁל סְרוֹנְיָא, וְכָל יוֹשְׁבֵי הַקִּרְיָה הַהִיא הֵם מְכַשְּׁפִים, וּבָאִים לַמִּדְבָּר לַנְּחָשִׁים הַשְּׁחֹרִים, שֶׁהֵם בְּנֵי עֶשֶׂר שָׁנִים אוֹ יוֹתֵר, לַעֲשׂוֹת כְּשָׁפִים, וְלֹא נִשְׁמָרִים מֵהֶם וְנַעֲשִׂים מְצֹרָעִים, וְכָל מִינֵי כְשָׁפִים שֶׁלָּהֶם הֵם בַּמְּעָרָה הַזּוֹ.</p>\n<p>הָלְכוּ, בְּעוֹדָם הוֹלְכִים פָּגְשׁוּ בְאִישׁ אֶחָד שֶׁהָיָה בָּא, וּבְנוֹ שֶׁהָיָה חוֹלֶה קָשׁוּר עַל הַחֲמוֹר. אָמְרוּ לוֹ, מִי אַתָּה? אָמַר לָהֶם, יְהוּדִי, וְזֶה הוּא בְּנִי שֶׁקָּשׁוּר עַל הַחֲמוֹר. אָמְרוּ לוֹ, לָמָּה הוּא קָשׁוּר? אָמַר לָהֶם, מְגוּרַי הֵם בִּכְפָר אֶחָד, שֶׁהוּא מִבְּנֵי הָרוֹמָאִים, וּבְנִי הַזֶּה הָיָה לוֹמֵד תּוֹרָה בְּכָל יוֹם, וְהָיָה חוֹזֵר הַבַּיְתָה וְלוֹמֵד אֶת אוֹתָם הַדְּבָרִים, וְשָׁלֹשׁ שָׁנִים הָיוּ מְגוּרַי בַּבַּיִת הַהוּא וְלֹא רָאִיתִי דָבָר. וְכָעֵת יוֹם אֶחָד נִכְנַס בְּנִי לַבַּיִת לַחֲזֹּר עַל הַדְּבָרִים, עָבְרָה רוּחַ אַחַת לְפָנָיו וְהִזִּיקָה לוֹ, הִתְעַקְּמוּ פִיו וְעֵינָיו, וְיָדָיו הִתְעַקְּמוּ וְלֹא יָכֹל לְדַבֵּר. וּבָאתִי לִמְעָרַת הַמְּצֹרָעִים שֶׁל סְרוֹנְיָא אוּלַי יְלַמְּדוּ אוֹתִי דָּבָר שֶׁל רְפוּאָה.</p>\n<p>אָמַר לוֹ רַבִּי יְהוּדָה, וּבְאוֹתוֹ הַבַּיִת הַאִם יָדַעְתָּ מִקֹּדֶם לָכֵן אִם נִזּוֹק בּוֹ אִישׁ אַחֵר? אָמַר לוֹ, יָדַעְתִּי, שֶׁהֲרֵי מִכַּמָּה יָמִים נִזּוֹק בּוֹ אִישׁ אֶחָד, וְהָיוּ אוֹמְרִים שֶׁהָיָה חוֹלֶה, וּמֵהֶם אוֹמְרִים שֶׁרוּחַ שֶׁל הַבַּיִת, וְאַחַר כָּךְ נִכְנְסוּ בוֹ כַּמָּה אֲנָשִׁים וְלֹא נִזּוֹקוּ. אָמְרוּ, זֶהוּ שֶׁאוֹמְרִים הַחֲבֵרִים, אוֹי לְאוֹתָם שֶׁעוֹבְרִים עַל דִּבְרֵיהֶם.</p>\n<p>פָּתַח רַבִּי יְהוּדָה וְאָמַר, (ירמיה כב) הוֹי בֹּנֶה בֵיתוֹ בְּלֹא צֶדֶק, שֶׁהֲרֵי בְּכָל מָקוֹם שֶׁנִּמְצָא בּוֹ צֶדֶק, כָּל הָרוּחוֹת וְכָל מַזִּיקֵי הָעוֹלָם בּוֹרְחִים מִמֶּנּוּ, וְלֹא נִמְצָאִים לְפָנָיו. וְעִם כָּל זֶה, מִי שֶׁמַּקְדִּים וְנוֹטֵל הַמָּקוֹם, אוֹחֵז בּוֹ. אָמַר לוֹ רַבִּי חִזְקִיָּה, אִם כָּךְ, שָׁקוּל הַשֵּׁם הַקָּדוֹשׁ כְּרוּחַ הַטֻּמְאָה?</p>\n<p>אָמַר לוֹ, לֹא כָּךְ, אֶלָּא הַשֵּׁם הַקָּדוֹשׁ לֹא שׁוֹרֶה בְמָקוֹם טָמֵא, וּמִשּׁוּם כָּךְ, אִם הַשֵּׁם הַקָּדוֹשׁ נוֹטֵל הַמָּקוֹם מִקֹּדֶם לָכֵן, כָּל הָרוּחוֹת וְכָל מַזִּיקֵי הָעוֹלָם לֹא יְכוֹלִים לְהֵרָאוֹת בּוֹ, כָּל שֶׁכֵּן לִקְרַב עִמּוֹ. אִם רוּחַ טֻמְאָה קוֹדֵם וְנוֹטֵל אֶת הַמָּקוֹם - הַשֵּׁם הַקָּדוֹשׁ לֹא שׁוֹרֶה בּוֹ, שֶׁהֲרֵי אֵינוֹ מְקוֹמוֹ.</p>\n<p>וּכְשֶׁהָיָה יוֹרֵד נֶגַע צָרַעַת, הָיָה מְטַהֵר אֶת הַמָּקוֹם, וּמוֹצִיא אֶת רוּחַ הַטֻּמְאָה מִמְּקוֹמוֹ, וְאַחַר כָּךְ מְנַתְּצִים אֶת הַבַּיִת, הָאֲבָנִים וְהָעֵצִים וְהַכֹּל, וּבוֹנֶה אוֹתוֹ כְּמִקֹּדֶם, בַּצַּד הַקָּדוֹשׁ בְּצֶדֶק, שֶׁמַּזְכִּיר אֶת הַשֵּׁם הַקָּדוֹשׁ וּמַשְׁרֶה עָלָיו קְדֻשָּׁה, וְעִם כָּל זֶה בְּעָפָר אַחֵר, וְיַרְחִיק אֶת הַבַּיִת מִמְּקוֹמוֹ, מֵהַיְסוֹד הָרִאשׁוֹן שְׁנֵי טְפָחִים.</p>\n<p>עֵכְשָׁו שֶׁלֹּא נִרְאֶה וְלֹא יוֹרֵד מִי שֶׁמִּתְגָּרֶה בְּאוֹתָהּ רוּחַ טֻמְאָה לְהוֹצִיאָהּ מִמְּקוֹמוֹ, מַה תַּקָּנָתוֹ? אִם יָכוֹל לָצֵאת מִן הַבַּיִת הַזֶּה - יָפֶה, וְאִם לֹא - יִבְנֶה אוֹתוֹ כְּמִקֹּדֶם בַּאֲבָנִים אֲחֵרוֹת, וְעֵצִים וְהַכֹּל. וְיוֹצִיא וְיַרְחִיק אוֹתוֹ מֵהַמָּקוֹם הָרִאשׁוֹן, וְיִבְנֶה אוֹתוֹ עַל הַשֵּׁם הַקָּדוֹשׁ.</p>\n<p>וְעִם כָּל זֶה לֹא יוֹצֵאת אוֹתָהּ הָרוּחַ מִן הַמָּקוֹם הָרִאשׁוֹן, מִשּׁוּם שֶׁקְּדֻשָּׁה לֹא שׁוֹרָה עַל מָקוֹם טָמֵא. אָמַר רַבִּי יִצְחָק, לָמָּה לוֹ לִטְרֹחַ עַל זֶה? בַּזְּמַן הַזֶּה כָּתוּב, (קהלתא) מְעֻוָּת לֹא יוּכַל לִתְקוֹן וְגוֹ'. מִיּוֹם שֶׁנֶּחֱרַב בֵּית הַמִּקְדָּשׁ לֹא נִמְצְאָה רְפוּאָה בָּעוֹלָם, מִשּׁוּם כָּךְ צָרִיךְ אָדָם לְהִזָּהֵר, כָּךְ שֶׁיִּהְיֶה שָׁמוּר.</p>\n<p>אָמְרוּ, נֵלֵךְ עִם הָאִישׁ הַזֶּה וְנִרְאֶה. אָמַר רַבִּי יִצְחָק, אָסוּר לָנוּ. אִם הָיָה הוֹלֵךְ לְאִישׁ גָּדוֹל יְרֵא חֵטְא, כְּמוֹ נַעֲמָן לֶאֱלִישָׁע, נֵלֵךְ אַחֲרָיו. עַכְשָׁו שֶׁהוּא הוֹלֵךְ לִרְחוֹקֵי הָעוֹלָם, רְחוֹקֵי הַתּוֹרָה, מְגֹעָלִים מִן הַכֹּל, אָסוּר לָנוּ לְהֵרָאוֹת לִפְנֵיהֶם. בָּרוּךְ הָרַחֲמָן שֶׁהִצִּיל אוֹתָנוּ מֵהֶם. וְהָאִישׁ הַזֶּה אָסוּר לוֹ. אָמַר רַבִּי יְהוּדָה, וַהֲרֵי שָׁנִינוּ, בַּכֹּל מִתְרַפְּאִים חוּץ מֵעֲצֵי אֲשֵׁרָה וְכוּ'. אָמַר לוֹ, וְזֶהוּ עֲבוֹדָה זָרָה, וְלֹא עוֹד, אֶלָּא שֶׁהֲרֵי כָּתוּב, (דברים יח) לֹא יִמָּצֵא בְךְ בְּנוֹ וּבִתּוֹ בָּאֵשׁ וְגוֹ'. הָלְכוּ לְדַרְכָּם.</p>\n<p>הָלַךָ אוֹתוֹ הָאִישׁ לַמְּעָרָה הַהִיא, הוּא וּבְנוֹ, שָׂם אוֹתוֹ בַּמְּעָרָה. עַד שֶׁיָּצָא אָבִיו לִקְשֹׁר אֶת חֲמוֹרוֹ, יָצָא קִיטוֹר שֶׁל אֵשׁ וְהִכָּה אוֹתוֹ בְּרֹאשׁוֹ וְהָרַג אוֹתוֹ. בֵּינְתַיִם נִכְנַס אָבִיו וּמָצָא אוֹתוֹ מֵת. לָקַח אוֹתוֹ וְאֶת חֲמוֹרוֹ וְהָלַךְ לוֹ. וּמָצָא אַחַר יוֹם אֶחָד אֶת רַבִּי יִצְחָק וְאֶת רַבִּי יְהוּדָה וְאֶת רַבִּי חִזְקִיָּה שֶׁהָיוּ הוֹלְכִים. בָּכָה לִפְנֵיהֶם, וְסִפֵּר לָהֶם אֶת הַמַּעֲשֶׂה. אָמַר רַבִּי יִצְחָק, וְהַאִם לֹא אָמַרְתִּי לְךְ פְּעָמִים רַבּוֹת שֶׁאָסוּר לָלֶכֶת לְשָׁם? בָּרוּךְ הָרַחֲמָן שֶׁכָּל מַעֲשָׂיו אֱמֶת, וּדְרָכָיו אֱמֶת. אַשְׁרֵיהֶם הַצַּדִּיקִים שֶׁהוֹלְכִים בְּדֶרֶךְ הָאֱמֶת בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא, וַעֲלֵיהֶם כָּתוּב (משלי ד) וְאֹרַח צַדִּיקִים כְּאוֹר נֹגַהּ וְגוֹ'.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, בְּכָל מַעֲשֵׂי הָאָדָם צָרִיךְ שֶׁכֻּלָּם יִהְיוּ לַשֵּׁם הַקָּדוֹשׁ. מַה זֶּה לַשֵּׁם הַקָּדוֹשׁ? לְהַזְכִּיר בְּפִיו אֶת הַשֵּׁם הַקָּדוֹשׁ עַל כָּל מַה שֶּׁהוּא עוֹשֶׂה שֶׁהַכֹּל הוּא לַעֲבוֹדָתוֹ, וְלֹא יִשְׁרֶה עָלָיו הַצַּד הָאַחֵר, מִשּׁוּם שֶׁהוּא תָּמִיד מְזֻמָּן לִבְנֵי הָאָדָם וְיָכוֹל לִשְׁרוֹת עַל אוֹתוֹ הַמַּעֲשֶׂה. וְעַל כֵּן, הַשְּׁתִי אוֹ הָעֵרֶב הָיָה נִטְמָא, וְשׁוֹרָה עָלָיו רוּחַ טֻמְאָה. וּמַה בָּזֶה כָּךְ - מִי שֶׁמַּפְקִיד דְּבָרָיו לַצַּד הָאַחֵר שֶׁלֹּא צָרִיךְ עַל אַחַת כַּמָּה וְכַמָּה. וּמִשּׁוּם כָּךְ כָּתוּב, (דברים כב) וְנִשְׁמַרְתָּ מִכָּל דָּבָר רָע.</p>"],[9522012072,"<p>רַבִּי אֶלְעָזָר הָיָה הוֹלֵךְ לִרְאוֹת אֶת אָבִיו (חמיו), וְהָיָה עִמּוֹ רַבִּי אַבָּא. אָמַר רַבִּי אַבָּא, נֹאמַר דִּבְרֵי תוֹרָה וְנֵלֵךְ. פָּתַח רַבִּי אֶלְעָזָר וְאָמַר, (בראשית יב) אִמְרִי נָא אֲחֹתִי אָתְּ. הַפָּסוּק הַזֶּה קָשֶׁה, וְכִי אַבְרָהָם שֶׁהוּא יְרֵא חֵטְא, אֲהוּבוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, הָיָה אוֹמֵר כָּךְ עַל אִשְׁתּוֹ כְּדֵי שֶׁיֵּיטִיבוּ לוֹ? אֶלָּא אַבְרָהָם, אַף עַל גַּב שֶׁהָיָה יְרֵא חֵטְא, לֹא סָמַךְ עַל זְכוּתוֹ, וְלֹא רָצָה מֵהַקָּדוֹשׁ בָּרוּךְ הוּא לְהוֹצִיא מִזְּכוּתוֹ, אֶלָּא עַל זְכוּת אִשְׁתּוֹ, שֶׁיַּרְוִיחַ בִּשְׁבִילָהּ מָמוֹן שֶׁל שְׁאָר הָעַמִּים, שֶׁהֲרֵי הַמָּמוֹן זוֹכֶה לוֹ הָאָדָם בְּאִשְׁתּוֹ. זֶהוּ שֶׁכָּתוּב (משלי יט) בַּיִת וָהוֹן נַחֲלַת אָבוֹת וּמֵה' אִשָּׁה מַשְׂכָּלֶת. מִי שֶׁזּוֹכֶה בְּאִשָּׁה מַשְׂכֶּלֶת, זוֹכֶה בַּכֹּל. וְכָתוּב, (שם לא) בָּטַח בָּהּ לֵב בַּעְלָהּ וְשָׁלָל לֹא יֶחְסָר.</p>\n<p>וְאַבְרָהָם הָיָה הוֹלֵךְ בִּשְׁבִילָהּ לֶאֱכֹל הַשָּׁלָל מִשְּׁאָר הָעַמִּים, וְסָמַךְ עַל זְכוּתָהּ שֶׁלֹּא יוּכְלוּ לְהַעֲנִישׁוֹ וְלִצְחֹק בָּהּ. וּמִשּׁוּם כָּךְ לֹא נָתַן דָּבָר לוֹמַר אֲחֹתִי הִיא, וְלֹא עוֹד, אֶלָּא שֶׁרָאָה מַלְאָךְ אֶחָד הוֹלֵךְ לְפָנֶיהָ, וְאָמַר לְאַבְרָהָם: אַל תִּפְחַד עָלֶיהָ, הַקָּדוֹשׁ בָּרוּךְ הוּא שָׁלַח אוֹתִי לְהוֹצִיא לוֹ אֶת מָמוֹן שְׁאָר הָעַמִּים וְלִשְׁמֹר אוֹתָהּ מֵהַכֹּל. וְאָז לֹא פָחַד עַל אִשְׁתּוֹ, אֶלָּא עָלָיו, שֶׁלֹּא רָאָה עִמּוֹ מַלְאָךְ, אֶלָּא עִמָּהּ. אָמַר, הֲרֵי הִיא שְׁמוּרָה, וַאֲנִי לֹא שָׁמוּר. וּמִשּׁוּם כָּךְ אָמַר, אִמְרִי נָא אֲחֹתִי אָתְּ וְגוֹ'.</p>\n<p>יִיטַב לִי?! יֵיטִיבוּ לִי הָיָה צָרִיךְ לִהְיוֹת, שֶׁכָּתוּב וְהָיָה כִּי יִרְאוּ אוֹתָךְ הַמִּצְרִים וְאָמְרוּ אִשְׁתּוֹ זֹּאת, וְעַל כֵּן יֵיטִיבוּ לִי צָרִיךְ לִהְיוֹת! אֶלָּא יִיטַב לִי - זֶה שֶׁהוֹלֵךְ לְפָנֶיךְ. יִיטַב לִי הַקָּדוֹשׁ בָּרוּךְ הוּא בָּעוֹלָם הַזֶּה בְּמָמוֹן. וְחָיְתָה נַפְשִׁי בְּאוֹתוֹ הָעוֹלָם בִּגְלָלֵךְ, שֶׁלֹּא תִסְטִי מִדֶּרֶךְ הָאֱמֶת. שֶׁאִם אֶזְכֶּה בִּגְלָלֵךְ בְּמָמוֹן בָּעוֹלָם הַזֶּה וְאַתְּ תִּסְטִי בַדֶּרֶךְ, הֲרֵי מִיתָה זְמִינָה בָּעוֹלָם הַהוּא, אֶלָּא תִּשָּׁמְרִי, שֶׁתְּחִי נַפְשִׁי בָּעוֹלָם הַהוּא בִּגְלָלֵךְ.</p>\n<p>וּמִשּׁוּם שֶׁהַמַּלְאָךְ הַהוּא הָלַךְ לְפָנֶיהָ לִשְׁמֹר אוֹתָהּ, מַה כָּתוּב? וַיְנַגַּע ה' אֶת פַּרְעֹה וְגוֹ', עַל דְּבַר שָׂרַי, וַדַּאי. שֶׁהָיְתָה אוֹמֶרֶת לַמַּלְאָךְ הַכֵּה - וְהוּא מַכֶּה. וְעַל כֵּן לֹא פָחַד אַבְרָהָם עָלֶיהָ כְּלוּם, שֶׁהֲרֵי הִיא שְׁמוּרָה. וּמַה שֶּׁפָּחַד - עַל עַצְמוֹ פָּחַד, וְלֹא רָאָה עִמּוֹ שְׁמִירָה כָּזוֹ.</p>\n<p>בֹּא רְאֵה, עֶשֶׂר פְּעָמִים צִוְּתָה שָׂרָה לַמַּלְאָךְ לְהַכּוֹת אֶת פַּרְעֹה, וּבְעֶשֶׂר מַכּוֹת לָקָה. סִימָן עָשְׂתָה שָׂרָה לְבָנֶיהָ אַחֲרֶיהָ בְּמִצְרַיִם.</p>\n<p>רַבִּי אַבָּא פָּתַח, (מיכהז) כִּימֵי צֵאתְךְ מֵאֶרֶץ מִצְרָיִם אַרְאֶנּוּ נִפְלָאוֹת. עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַרְאוֹת גְּאֻלָּה לְבָנָיו כְּאוֹתָם הַיָּמִים שֶׁשָּׁלַח הַקָּדוֹשׁ בָּרוּךְ הוּא לְהוֹצִיא אֶת יִשְׂרָאֵל, וְהֶרְאָה אֶת אוֹתָן הַמַּכּוֹת לְמִצְרַיִם, וְהִלְקָה אוֹתָם בִּגְלַל יִשְׂרָאֵל. בֹּא וּרְאֵה מַה בֵּין הַגְּאֻלָּה הַזּוֹ לִגְאֻלַּת מִצְרַיִם. גְּאֻלַּת מִצְרַיִם הָיְתָה בְּמֶלֶךְ אֶחָד, וּבְמַלְכוּת אַחַת - כָּאן בְּכָל הַמְּלָכִים שֶׁל הָעוֹלָם. וְאָז יִתְכַּבֵּד הַקָּדוֹשׁ בָּרוּךְ הוּא בְּכָל הָעוֹלָם, וְיֵדְעוּ הַכֹּל שִׁלְטוֹנוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, וְכֻלָּם יִלְקוּ בְמַכּוֹת עֶלְיוֹנוֹת, עַל אַחַת שְׁתַּיִם, מִפְּנֵי שֶׁיְּסָרְבוּ כֻלָּם אֶת יִשְׂרָאֵל.</p>\n<p>וְאָז יִתְגַּלֶּה שִׁלְטוֹנוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁכָּתוּב (זכריה יד) וְהָיָה ה' לְמֶלֶךְ עַל כָּל הָאָרֶץ. וְאָז כֻּלָּם יִתְנַדְּבוּ אֶת יִשְׂרָאֵל לַקָּדוֹשׁ בָּרוּךְ הוּא. זֶהוּ שֶׁכָּתוּב (ישעיה סו) וְהֵבִיאוּ אֶת כָּל אֲחֵיכֶם וְגוֹ'. אָז יַעַמְדוּ הָאָבוֹת בְּשִׂמְחָה לִרְאוֹת אֶת גְּאֻלַּת בְּנֵיהֶם כְּמִקֹּדֶם. זֶהוּ שֶׁכָּתוּב כִּימֵי צֵאתְךְ מֵאֶרֶץ מִצְרָיִם אַרְאֶנּוּ נִפְלָאוֹת, אָמֵן כֵּן יְהִי רָצוֹן. בָּרוּךְ ה' לְעוֹלָם אָמֵן וְאָמֵן יִמְלֹךְ ה' לְעוֹלָם אָמֵן וְאָמֵן פרשׁת מְצֹרָע</p>"],[9522012073,"<p>וַיְדַבֵּר ה' אֶל מֹשֶׁה לֵאמֹר. זֹּאת תִּהְיה תּוֹרַת הַמְּצֹרָע בְּיוֹם טָהֳרָתוֹ וְגוֹ'. רַבִּי אַבָּא פָּתַח, (איוב יט) גּוּרוּ לָכֶם מִפְּנֵי חֶרֶב כִּי חֵמָה עֲונוֹת חָרֶב לְמַעַן תֵּדְעוּן שַׁדּוּן. שַׁדּוּן, שַׁדִּין כָּתוּב. כַּמָּה יֵשׁ לִבְנֵי אָדָם לִשְׁמֹר אֶת דַּרְכֵיהֶם וְלִפְחֹד מִלִּפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁלֹּא יִסְטוּ מִדֶּרֶךְ כְּשֵׁרָה, וְלֹא לַעֲבֹר עַל דִּבְרֵי תוֹרָה וְלֹא תִשָּׁכַח מִמֶּנּוּ.</p>\n<p>שֶׁכָּל מִי שֶׁלֹּא לוֹמֵד תּוֹרָה וְלֹא מִשְׁתַּדֵּל בָּהּ, נָזוּף הוּא מֵהַקָּדוֹשׁ בָּרוּךְ הוּא, רָחוֹק הוּא מִמֶּנּוּ, וְלֹא שׁוֹרָה עִמּוֹ שְׁכִינָה. וְאוֹתָם הַשּׁוֹמְרִים שֶׁהוֹלְכִים עִמּוֹ, מִסְתַּלְּקִים מִמֶּנּוּ, וְלֹא עוֹד, אֶלָּא שֶׁמַּכְרִיזִים לְפָנָיו וְאוֹמְרִים: הִסְתַּלְּקוּ מִסָּבִיב לִפְלוֹנִי, שֶׁלֹּא חוֹשֵׁשׁ עַל כְּבוֹד רִבּוֹנוֹ. אוֹי לוֹ! שֶׁהֲרֵי עָזְבוּ אוֹתוֹ עֶלְיוֹנִים וְתַחְתּוֹנִים, אֵין לוֹ חֵלֶק בְּדֶרֶךְ הַחַיִּים.</p>\n<p>וּכְשֶׁהוּא מִשְׁתַּדֵּל בַּעֲבוֹדַת רִבּוֹנוֹ וְלוֹמֵד תּוֹרָה, כַּמָּה שׁוֹמְרִים מְזֻמָּנִים כְּנֶגְדּוֹ לִשְׁמֹר אוֹתוֹ, וּשְׁכִינָה שׁוֹרָה עָלָיו, וְכֻלָּם מַכְרִיזִים לְפָנָיו וְאוֹמְרִים: תְּנוּ כָבוֹד לִדְיוֹקַן הַמֶּלֶךְ. תְּנוּ כָבוֹד לְבֶן הַמֶּלֶךְ. שָׁמוּר הוּא בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא. אַשְׁרֵי חֶלְקוֹ!</p>\n<p>בֹּא רְאֵה, בַּלָּשׁוֹן הָרָע שֶׁאָמַר הַנָּחָשׁ לָאִשָּׁה, גָּרַם לָאִשָּׁה וּלְאָדָם לִגְזֹּר עֲלֵיהֶם מִיתָה וְעַל כָּל הָעוֹלָם. בְּלָשׁוֹן הָרָע כָּתוּב, (תהלים נז) וּלְשׁוֹנָם חֶרֶב חַדָּה. מִשּׁוּם כָּךְ, גּוּרוּ לָכֶם מִפְּנֵי חֶרֶב, מִפְּנֵי לָשׁוֹן הָרָע. כִּי חֵמָה עֲונוֹת חָרֶב. מַהוּ כִּי חֵמָה עֲונוֹת חָרֶב? זוֹ חֶרֶב לַה'. שֶׁשָּׁנִינוּ, יֵשׁ לַקָּדוֹשׁ בָּרוּךְ הוּא חֶרֶב שֶׁבָּהּ הוּא דָּן אֶת הָרְשָׁעִים. זֶהוּ שֶׁכָּתוּב, (ישעיה לד) חֶרֶב לַה' מָלְאָה דָם. (דברים לב) וְחַרְבִּי תֹּאכַל בָּשָׂר. וּמִשּׁוּם כָּךְ גּוּרוּ לָכֶם מִפְּנֵי חֶרֶב כִּי חֵמָה עֲונוֹת חָרֶב לְמַעַן תֵּדְעוּן שַׁדּוּן, שַׁדִּין כָּתוּב, כְּדֵי שֶׁתֵּדְעוּ שֶׁכָּךְ נִדּוֹן. מִי שֶׁיֵּשׁ לוֹ חֶרֶב בִּלְשׁוֹנוֹ, מִזְדַּמֶּנֶת לוֹ חֶרֶב (נדון באותה חרב) שֶׁמַּשְׁמִידָה הַכֹּל. זֶהוּ שֶׁכָּתוּב זֹּאת תִּהְיֶה תּוֹרַת הַמְּצֹרָע.</p>"],[9522012074,"<p>רַבִּי אֶלְעָזָר פָּתַח, (קהלת ט) וְכַצִּפֳּרִים הָאֲחֻזוֹת בַּפָּח כָּהֵם יוּקָשִׁים בְּנֵי הָאָדָם. הַפָּסוּק הַזֶּה הֲרֵי נִתְבָּאֵר. אֲבָל בֹּא רְאֵה, בְּנֵי אָדָם לֹא יוֹדְעִים וְלֹא שׁוֹמְעִים וְלֹא מִסְתַּכְּלִים בִּרְצוֹן אֲדוֹנָם, וְהַכָּרוֹז כָּל יוֹם קוֹרֵא לִפְנֵיהֶם, וְאֵין מִי שֶׁמַּקְשִׁיב לוֹ, וְאֵין מִי שֶׁמֵּעִיר אֶת רוּחוֹ לַעֲבוֹדַת אֲדוֹנוֹ.</p>\n<p>בְּשָׁעָה שֶׁיּוֹרֵד הַלַּיְלָה וְהַשְּׁעָרִים נִסְתָּמִים, מִתְעוֹרֵר נֶקֶב תְּהוֹם רַבָּה, וְכַמָּה קְבוּצוֹת שֶׁל מְחַבְּלִים נִמְצָאִים בָּעוֹלָם. אָז מַפִּיל הַקָּדוֹשׁ בָּרוּךְ הוּא שֵׁנָה עַל כָּל בְּנֵי הָעוֹלָם, וַאֲפִלּוּ עַל כָּל שֶׁבָּהֶם הִתְעוֹרְרוּת שֶׁל חַיִּים, וְהֵם מְשׁוֹטְטִים בָּעוֹלָם וּמוֹדִיעִים לִבְנֵי אָדָם דְּבָרִים, מֵהֶם כּוֹזְבִים וּמֵהֶם אֱמֶת, וּבְנֵי אָדָם קְשׁוּרִים בְּשֵׁנָה.</p>\n<p>כְּשֶׁמִּתְעוֹרֶרֶת רוּחַ צָפוֹן וְנֶחֱלָק הַלַּיְלָה, הַשַּׁלְהֶבֶת יוֹצֵאת וּמַכָּה תַּחַת כַּנְפֵי הַתַּרְנְגוֹל, וְהוּא קוֹרֵא, וְהַקָּדוֹשׁ בָּרוּךְ הוּא נִכְנָס לְגַן עֵדֶן לְהִשְׁתַּעֲשֵׁעַ עִם הַצַּדִּיקִים. וְאָז הַכָּרוֹז יוֹצֵא וְקוֹרֵא, וְכָל בְּנֵי הָעוֹלָם מִתְעוֹרְרִים בְּמִטּוֹתֵיהֶם. אוֹתָם שֶׁיֵּשׁ בָּהֶם הִתְעוֹרְרוּת שֶׁל חַיִּים, עוֹמְדִים לַעֲבוֹדַת רִבּוֹנָם וְעוֹסְקִים בַּתּוֹרָה וּבְשִׁבְחוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא עַד שֶׁבָּא הַבֹּקֶר.</p>"],[9522012075,"<p>כְּשֶׁבָּא הַבֹּקֶר, (כרוז קורא וכל) כָּל הַחֲיָלוֹת וְהַמַּחֲנוֹת שֶׁלְּמַעְלָה מְשַׁבְּחִים אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא. זֶהוּ שֶׁכָּתוּב (איוב לח) בְּרָן יַחַד כּוֹכְבֵי בֹקֶר וְגוֹ'. אָז כַּמָּה שְׁעָרִים נִפְתָּחִים לְכָל הַצְּדָדִים, וְהַשַּׁעַר שֶׁל אַבְרָהָם נִפְתָּח לִכְנֶסֶת יִשְׂרָאֵל לְזַמֵּן אֶת כָּל בְּנֵי הָעוֹלָם. זֶהוּ שֶׁכָּתוּב וַיִּטַּע אֵשֶׁל בִּבְאֵר שָׁבַע.</p>\n<p>וּמִי שֶׁלֹּא מֵעִיר אֶת רוּחוֹ לַעֲבוֹדַת רִבּוֹנוֹ, בְּאֵיזֶה פָנִים יַעֲמֹד לִפְנֵי הַמֶּלֶךְ כְּשֶׁיִּתְעוֹרְרוּ עָלָיו בְּדִין, וְיִתְפְּסוּ אוֹתוֹ בְּקוֹלָר, וְלֹא תִמָּצֵא עָלָיו זְכוּת לְהִנָּצֵל? וְאָז כָּתוּב, וְכַצִּפֳּרִים הָאֲחֻזוֹת בַּפָּח כָּהֵם יוּקָשִׁים בְּנֵי הָאָדָם. וְטֶרֶם שֶׁיֵּצֵא אָדָם מִן הָעוֹלָם הַזֶּה, בְּכַמָּה דִינִים הוּא נִדּוֹן הַנֶּפֶשׁ עִם הַגּוּף טֶרֶם שֶׁיִּפָּרְדוּ זֶה מִזֶּה, וְאֵין מִי שֶׁיַּשְׁגִּיחַ.</p>\n<p>(אפלו) בְּאוֹתוֹ זְמַן שֶׁמַּגִּיעָה שְׁעַת הַהַפְרָדָה, לֹא יוֹצֵאת הַנֶּפֶשׁ מִן הַגּוּף עַד שֶׁמִּתְגַּלָּה עָלָיו שְׁכִינָה, וְהַנֶּפֶשׁ מִתּוֹךְ שִׂמְחָה וַחֲבִיבוּת שֶׁל הַשְּׁכִינָה יוֹצֵאת מִן הַגּוּף כְּנֶגְדָּהּ. אִם הוּא צַדִּיק, הוּא נִקְשָׁר וְנִדְבָּק בָּהּ. וְאִם לֹא, הַשְּׁכִינָה הוֹלֶכֶת, וְהִיא נִשְׁאֶרֶת וְהוֹלֶכֶת וּמִתְאַבֶּלֶת עַל פְּרֵדַת הַגּוּף. מָשָׁל אוֹמְרִים, חָתוּל לֹא נִפְרָד מֵאֵשׁ, חַדֵּד אֶת הַסַּכִּין, וְהוּא יֵלֵךְ אַחֲרָיו.</p>\n<p>אַחַר כָּךְ נִדּוֹנִים שְׁנֵיהֶם עַל יְדֵי דוּמָה. הַגּוּף נִדּוֹן בַּקֶּבֶר עַד שֶׁשָּׁב לֶעָפָר, וְהַנֶּפֶשׁ בְּאֵשׁ הַגֵּיהִנֹּם בְּכַמָּה דִינִים, עַד אוֹתוֹ זְמַן שֶׁנִּגְזַר עָלֶיהָ לְקַבֵּל עֹנֶשׁ. אַחַר שֶׁקִּבְּלָה עָנְשָׁהּ וּמַגִּיעַ הַזְּמַן לְהִטָּהֵר, אָז עוֹלָה הִיא מֵהַגֵּיהִנֹּם, וּמִתְלַבֶּנֶת מֵחֲטָאֶיהָ כְּמוֹ בַּרְזֶל שֶׁמִּתְלַבֵּן בָּאֵשׁ, וְעוֹלִים עִמָּהּ עַד שֶׁנִּכְנֶסֶת לְגַן עֵדֶן שֶׁלְּמַטָּה, וְרוֹחֶצֶת שָׁם בְּאוֹתָם מַיִם, וְרוֹחֶצֶת בַּבְּשָׂמִים שֶׁשָּׁם, כְּמוֹ שֶׁנֶּאֱמַר (שיר ג) מְקֻטֶּרֶת מֹר וּלְבֹנָה. וְעוֹמֶדֶת שָׁם עַד הַזְּמַן שֶׁנִּגְזָר עָלֶיהָ לְהִתְרַחֵק מֵהַמָּקוֹם שֶׁיּוֹשְׁבִים בּוֹ הַצַּדִּיקִים.</p>\n<p>וּכְשֶׁמַּגִּיעַ הַזְּמַן לַעֲלוֹת, אָז עוֹלִים עִמָּהּ דַּרְגָּה אַחַר דַּרְגָּה, עַד שֶׁנִּקְרֶבֶת כְּקָרְבָּן עַל הַמִּזְבֵּחַ. זֶהוּ שֶׁכָּתוּב זֹּאת תִּהְיֶה תּוֹרַת הַמְּצֹרָע בְּיוֹם טָהֳרָתוֹ וְהוּבָא אֶל הַכֹּהֵן, הַכֹּהֵן הָעֶלְיוֹן שֶׁלְּמַעְלָה, הַנֶּפֶשׁ הַזּוֹ שֶׁלֹּא נִטְמְאָה כָּל כָּךְ בָּעוֹלָם הַזֶּה, לָזוֹ יֵשׁ תַּקָּנָה כְּמוֹ כֵן. וְאִם לֹא, אָז מְעֻוָּת לֹא יוּכַל לִתְקֹן וְגוֹ'.</p>"],[9522012076,"<p>זֹאת תִּהְיֶה תּוֹרַת הַמְּצֹרָע. רַבִּי יִצְחָק פָּתַח, וְזָרַח הַשֶּׁמֶשׁ וּבָא הַשָּׁמֶשׁ וְגוֹ'. פָּסוּק זֶה נִתְבָּאֵר, וּבֵאַרְנוּ אוֹתוֹ עַל נִשְׁמַת הָאָדָם, בְּשָׁעָה שֶׁהִיא עוֹמֶדֶת עִם הָאָדָם בָּעוֹלָם הַזֶּה, אָז וְזָרַח הַשֶּׁמֶשׁ. בָא הַשָּׁמֶשׁ, בִּזְמַן שֶׁיּוֹצֵא בֶּן אָדָם מִן הָעוֹלָם הַזֶּה וְנִמְצָא בִתְשׁוּבָה, אָז - אֶל מְקוֹמוֹ שׁוֹאֵף זוֹרֵחַ הוּא שָׁם, אם הוּא צַדִּיק, כְּמוֹ שֶׁנֶּאֱמַר וּבָא הַשֶּׁמֶשׁ וְטָהֵר, וְאַחַר יֹאכַל מִן הַקְּדָשִׁים.</p>\n<p>בֹּא רְאֵה, עַל כָּל חֲטָאֵי הָעוֹלָם הַקָּדוֹשׁ בָּרוּךְ הוּא מְכַפֵּר בִּתְשׁוּבָה, פּרָט מֵאוֹתוֹ לָשׁוֹן הָרָע שֶׁמּוֹצִיא שֵׁם רע עַל חֲבֵרוֹ. וַהֲרֵי פֵּרְשׁוּהָ, שֶׁכָּתוּב זֹּאת תִּהְיֶה תּוֹרַת הַמְּצֹרָע - זֹּאת הִיא תּוֹרָתוֹ שֶׁל מוֹצִיא שֵׁם רָע. רַבִּי חִיָּיא אָמַר, כָּל מִי שֶׁמּוֹצִיא שֵׁם רָע, מְטַמְּאִים לוֹ אֶת כָּל אֵיבָרָיו וְרָאוּי לסֶגֶר, מִשּׁוּם שֶׁאוֹתוֹ דִּבּוּר רָע עוֹלֶה מֵעִיר רוּחַ טֻמְאָה עָלָיו, וְהוּא נִטְמָא. בָּא לְהִטָּמֵא - מְטַמְּאִים אוֹתוֹ. בַּדִּבּוּר שֶׁלְּמַטָּה מִתְעוֹרֵר דִּבּוּר אַחֵר.</p>\n<p>פָּתַח וְאָמַר, (ישעיה א) אֵיכָה הָיְתָה לזוֹנָה קִרְיָה נֶאֱמָנָה וְגוֹ'. מִי שֶׁהָיְתָה אֱמָנָה לְבַעְלָהּ, הָפְכָה לְזוֹנָה. מְלֵאֲתִי מִשְׁפָּט. מִשְׁפָּט - זֶה וַדַּאי הַקָּדוֹשׁ בָּרוּךְ הוּא. צֶדֶק - זוֹ כְּנֶסֶת יִשְׂרָאֵל. מִשּׁוּם שֶׁהֵעִירָה דָּבָר אַחֵר, הִסְתַּלֵּק מִמֶּנָּה הַקָּדוֹשׁ בָּרוּךְ הוּא, וְשָׁרְתָה בָּהּ רוּחַ שֶׁל מְרַצְּחִים. זֶהוּ שֶׁכָּתוּב וְעַתָּה מְרַצְּחִים. וּמַה יְרוּשָׁלַיִם הַקְּדוֹשָׁה כָּךְ - שְׁאָר בְּנֵי אָדָם עַל אַחַת כַּמָּה וְכַמָּה. זְהוּ שֶׁכָּתוּב זֹּאת תִּהְיֶה תּוֹרַת הַמְּצֹרָע.</p>\n<p>רבִּי יְהוּדָה אָמַר, זֹּאת תִּהְיֶה וַדַּאי כּנֶגְדּוֹ לְהִפָּרַע מִמֶּנּוּ, שֶׁל אוֹתוֹ מוֹצִיא שֵׁם רַע. בְּיוֹם טָהֳרָתוֹ וְהוּבָא אֶל הַכֹּהֵן, מַה בָּא לְהַשְׁמִיעֵנוּ? מַשְׁמָע, מִי שֶׁיֵּשׁ לוֹ לָשׁוֹן הָרָע, תְּפִלָּתוֹ אֵינָהּ כְנֶסֶת לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁהֲרֵי עוֹרֵר עָלָיו רוּחַ טֻמְאָה. כֵּיוָן שֶׁחָזַר בּתְשׁוּבָה וְקִבֵּל עָלָיו תְּשׁוּבָה, מַה כָּתוּב? בְּיוֹם טָהֳרָתוֹ וְהוּבָא אֶל הַכֹּהֵן וְגוֹ', וְרָאָה הַכֹּהֵן וְגוֹ'.</p>\n<p>וְצִוָּה הַכֹּהֵן וְלָקַח לַמִּטַּהֵר שְׁתֵּי צִפֳּרִים חַיּוֹת. רַבִּי יִצְחָק וְרַבִּי יוֹסֵי הָיוּ מְצוּיִים לִפְנֵי רַבִּי שִׁמְעוֹן. יוֹם אֶחָד אָמַר לוֹ, עֵץ אֶרֶז הֲרֵי יָדוּעַ, כְּמוֹ שֶׁנֶּאֱמַר (מלכים א ה) מִן הָאֶרֶז אֲשֶׁר בַּלְּבָנוֹן, שֶׁהֲרֵי אוֹתוֹ עֵץ אֶרֶז לֹא נִשְׁרָשִׁים נְטִיעוֹתָיו אֶלָּא בַּלְּבָנוֹן, וַהֲרֵי נִתְבָּאֵר. אֵזוֹב לָמָּה? וּמַה הוּא?</p>\n<p>פָּתַח וְאָמַר, וְלָקַח לַמִּטַּהֵר שְׁתֵּי צִפֳּרִים חַיּוֹת טְהֹרוֹת וְעֵץ אֶרֶז וּשְׁנִי תוֹלַעַת וְאֵזוֹב. בּא רְאֵה, אָדָם שֶׁמִּשְׁתַּדֵּל בַּעֲבוֹדַת רִבּוֹנוֹ וּמִשְׁתַּדֵּל בַּתּוֹרָה, הַקָּדוֹשׁ בָּרוּךְ הוּא שׁוֹרֶה עָלָיו, וְהַשְּׁכִינָה מִשְׁתַּתֶּפֶת עִמּוֹ. כֵּיוָן שֶׁאָדָם בָּא לְהִטָּמֵא, הַשְּׁכִינָה מִסְתַּלֶּקֶת מִמֶּנּוּ, הַקָּדוֹשׁ בָּרוּךְ הוּא מִתְרַחֵק מִמֶּנּוּ, וְכָל צַד הַקְּדֻשָּׁה שֶׁל רִבּוֹנוֹ מְרֻחָקִים מִמֶּנּוּ, וְשׁוֹרָה עָלָיו רוּחַ טֻמְאָה וְכָל צַד הַטֻּמְאָה. אִם בָּא לְהִטָּהֵר, מְסַיְּעִים אוֹתוֹ. אַחַר שֶׁנִּטְהַר וְחָזַר בִּתְשׁוּבָה, אוֹתוֹ שֶׁהִסְתַּלֵּק מִמֶּנּוּ חוֹזֵר וְשׁוֹרֶה עָלָיו.</p>"],[9522012077,"<p>בֹּא רְאֵה, כָּתוּב וְלָקַח לַמִּטַּהֵר שְׁתֵּי צִפֳּרִים חַיּוֹת טְהֹרוֹת. כֵּיוָן שֶׁאָמַר שְׁתֵּי צִפֳּרִים, לֹא יָדַעְנוּ שֶׁהֵן חַיּוֹת? אֶלָּא הֲרֵי פֵּרְשׁוּהָ, אֲבָל חַיּוֹת, חַיּוֹת מַמָּשׁ, כְּמוֹ שֶׁנֶּאֱמַר (יחזקאל א) וָאֵרֶא הַחַיּוֹת, כְּנֶגֶד הַמָּקוֹם שֶׁיּוֹנְקִים מֵהֶם הַנְּבִיאִים הַנֶּאֱמָנִים. וְעֵץ אֶרֶז, הֲרֵי נִתְבָּאֵר. וּשְׁנִי תוֹלַעַת, הַצַּד הָאָדֹם שֶׁל גְּבוּרָה שֶׁהִשְׁתַּתֵּף עִמּוֹ בָּרִאשׁוֹנָה. וְאֵזֹּב, זוֹ ו' קְטַנָּה שֶׁמֵּינִיקָה אֶת כְּנֶסֶת יִשְׂרָאֵל. וּמִשּׁוּם כָּךְ עֵץ אֶרֶז וְאֵזוֹב הוֹלְכִים יַחַד, וְעַל כֵּן ו' ו' נִמְצְאוּ כְאֶחָד, אֶחָד עֶלְיוֹן וְאֶחָד קָטָן, וְקוֹרְאִים לָהֶם ו' עֶלְיוֹנָה, ו' תַּחְתּוֹנָה. וְכֻלָּם חוֹזְרִים לִשְׁרוֹת עָלָיו, מִשּׁוּם שֶׁהֲרֵי נִטְהַר. כְּנֶגֶד אֵלֶּה לְמַטָּה (מהם) - עֵץ אֶרֶז וְאֵזוֹב וּשְׁנִי תוֹלַעַת נִמְצְאוּ (בשם) בַגְּדֻלָּה הַזּוֹ, וּתְלוּיִים מֵהָעֶלְיוֹנוֹת הַלָּלוּ.</p>"],[9522012078,"<p>רַבִּי יְהוּדָה וְרַבִּי יִצְחָק הָיוּ הוֹלְכִים בַּדֶּרֶךְ. יָשְׁבוּ בְּאוֹתוֹ שָׂדֶה וְהִתְפַּלְלוּ. אַחַר שֶׁסִּיְּמוּ אֶת הַתְּפִלָּה, קָמוּ וְהָלְכוּ. פָּתַח רַבִּי יְהוּדָה בְּדִבְרֵי תוֹרָה וְאָמַר, (משלי ג) עֵץ חַיִּים הִיא לַמַּחֲזִיקִים בָּהּ וְתֹמְכֶיהָ מְאֻשָּׁר. עֵץ חַיִּים - זוֹ הַתּוֹרָה, שֶׁהִיא עֵץ עֶלְיוֹן גָּדוֹל וְחָזָק. תּוֹרָה, לָמָּה נִקְרֵאת תּוֹרָה? מִשּׁוּם שֶׁמּוֹרָה וּמְגַלָּה אֶת מַה שֶּׁהָיָה סָתוּם וְלֹא יָדוּעַ. חַיִּים, שֶׁכָּל הַחַיִּים שֶׁלְּמַעְלָה נִכְלְלוּ בָהּ, וּמִמֶּנָּה יוֹצְאִים. לַמַּחֲזִיקִים בָּהּ, אֶת אוֹתָם שֶׁאוֹחֲזִים בָּהּ, שֶׁמִּי שֶׁאוֹחֵז בַּתּוֹרָה אוֹחֵז בַּכֹּל. אָחוּז לְמַעְלָה וּלְמַטָּה. וְתֹמְכֶיהָ מְאֻשָּׁר, מִי זֶה תּוֹמְכֶיהָ? אֵלּוּ אוֹתָם שֶׁמְּטִילִים מְלַאי לְכִיסָם שֶׁל תַּלְמִידֵי חֲכָמִים, כְּמוֹ שֶׁבֵּאֲרוּהָ.</p>\n<p>וְתֹמְכֶיהָ, זוֹכֶה שֶׁיֵּצְאוּ מִמֶּנּוּ נְבִיאִים נֶאֱמָנִים. מְאֻשָּׁר, אַל תִּקְרֵי מְאֻשָּׁר אֶלָּא מֵרֹאשׁוֹ. אוֹתָם הַתּוֹמְכִים שֶׁל הַתּוֹרָה מֵרֹאשׁוֹ וְעַד סוֹפוֹ. מֵרֹאשׁוֹ, צַד הָרֹאשׁ שֶׁל הַכֹּל שֶׁנִּקְרָא רֹאשׁ, שֶׁכָּתוּב (שם ח) מֵעוֹלָם נִסַּכְתִּי מֵרֹאשׁ. וְרֹאשׁ זוֹ חָכְמָה, שֶׁהִיא הָרֹאשׁ לְכָל הַגּוּף, וְהַגּוּף מִתְפַּשֵּׁט בָּהּ עַד הַסִּיּוּם שֶׁל שֵׁשֶׁת הַצְּדָדִים וְתֹמְכֶיהָ, כְּמוֹ שֶׁנֶּאֱמַר (שיר ה) שׁוֹקָיו עַמּוּדֵי שֵׁשׁ. שֶׁאוֹתָם שֶׁמְּטִילִים מְלַאי לְכִיסָם שֶׁל תַּלְמִידֵי חֲכָמִים, הֵם תּוֹמְכִים אֶת הַתּוֹרָה מֵהָרֹאשׁ עַד סִיּוּם הַגּוּף, וְכָל הָאֱמוּנָה בּוֹ תְּלוּיָה, וְנִתְמָךְ. וְזוֹכֶה לְבָנִים שֶׁיֵּרָאוּ לִנְבִיאִים נֶאֱמָנִים.</p>"],[9522012079,"<p>רַבִּי יִצְחָק פָּתַח, וַיִּקְרָא אֶל מֹשֶׁה וַיְדַבֵּר ה' אֵלָיו מֵאֹהֶל מוֹעֵד לֵאמֹר. וַיִּקְרָא, אָלֶף קְטַנָּה, לָמָּה? אֶלָּא כְּדֵי לְהַרְאוֹת מִיהוּ אוֹתוֹ שֶׁקָּרָא - אוֹתוֹ שֶׁשָּׁרוּי בַּמִּקְדָּשׁ, וְאָז זִמֵּן אֶת מֹשֶׁה כְּמוֹ שֶׁמַּזְמִין אוֹרֵחַ. כָּאן א' קְטַנָּה, שָׁם א' גְּדוֹלָה. אָדָם שֵׁת אֱנוֹשׁ. (אדם) זוֹ שְׁלֵמוּת הַכֹּל.</p>\n<p>בֹּא וּרְאֵה מַה בֵּין מֹשֶׁה לְאַהֲרֹן, מִי מֵהֶם עֶלְיוֹן? אֶלָּא מֹשֶׁה הוּא הָעֶלְיוֹן, מֹשֶׁה הוּא שׁוֹשְׁבִין הַמֶּלֶךְ, וְאַהֲרֹן שׁוֹשְׁבִין הַגְּבִירָה. מָשָׁל לְמֶלֶךְ שֶׁהָיְתָה לוֹ גְּבִירָה עֶלְיוֹנָה. מֶה עָשָׂה? נָתַן לוֹ שׁוֹשְׁבִין לְתַקֵּן אוֹתָהּ וּלְהִסְתַּכֵּל בְּדִבְרֵי הבַּיִת. וְעַל כֵּן, כְּשֶׁנִּכְנָס הַשּׁוֹשְׁבִין הַזֶּה לַמֶּלֶךְ, לֹא נִכְנָס אֶלָּא רַק עִם הַגְּבִירָה. זֶהוּ שֶׁכָּתוּב בְּזֹּאת יָבא אַהֲרֹן וְגוֹ'.</p>\n<p>מֹשֶׁה הוּא שׁוֹשְׁבִין הַמֶּלֶךְ, מִשּׁוּם כָּךְ הִזְדַּמֵּן כְּאוֹרֵחַ, וְאַחַר כָּךְ - וַיְדַבֵּר ה' אֵלָיו. אַהֲרֹן הוּא שׁוֹשְׁבִין שֶׁל הַגְּבִירָה, וְכָל דְּבָרָיו הָיוּ לְפַיֵּס אֶת הַמֶּלֶךְ עִם הַמַּלְכָּה, וְיִתְפַּיֵּס הַמֶּלֶךְ עִמָּהּ. וְעַל כֵּן, מִשּׁוּם שֶׁהוּא שׁוֹשְׁבִין שֶׁלָּהּ, הוּא שָׂם מְדוֹרוֹ עִמָּהּ לְתַקֵּן אֶת הַבַּיִת וּלְעַיֵּן תָּמִיד בְּדִבְרֵי הַבַּיִת. וְעַל כֵּן הִתְתַּקֵּן כְּמוֹ שֶׁלְּמַעְלָה, וְנִקְרָא כֹּהֵן גָּדוֹל. מִנַּיִן לָנוּ? שֶׁכָּתוּב (תהלים קי) אַתָּה כֹהֵן לְעוֹלָם עַל דִּבְרָתִי מַלְכִּי צֶדֶק.</p>\n<p>וּמִשּׁוּם כָּךְ, כָּל מַה שֶּׁצָּרִיךְ מִבֵּית הַמֶּלֶךְ הוּא נוֹטֵל, וְאֵין מִי שֶׁיִּמְחֶה בְיָדוֹ. וְלָכֵן הוּא עוֹמֵד לְטַהֵר אֶת כָּל אוֹתָם שֶׁנִּכְנָסִים לְבֵית הַגְּבִירָה, כְּדֵי שֶׁלֹּא תִמָּצֵא טֻמְאָה בְּאוֹתָם בְּנֵי הַהֵיכָל, וּמִשּׁוּם כָּךְ כָּתוּב וְלָקַח לַמִּטַּהֵר שְׁתֵּי צִפֳּרִים וְגוֹ'.</p>\n<p>רַבִּי יְהוּדָה פָּתַח וְאָמַר, (תהלים ב) יוֹשֵׁב בַּשָּׁמַיִם יִשְׂחָק ה' יִלְעַג לָמוֹ. יוֹשֵׁב בַּשָּׁמַיִם יִשְׂחָק - זֶה יִצְחָק שֶׁבָּא מִצַּד הַיַּיִן, מֵאִיר בָּרִאשׁוֹנָה, וְצוֹחֵק, וְאַחַר כָּךְ זוֹעֵם וּמְגָרֵשׁ. זֶהוּ שֶׁכָּתוּב יוֹשֵׁב בַּשָּׁמַיִם יִשְׂחָק, וְלֹא כָתוּב יוֹשֵׁב שָׁמַיִם. יִשְׂחָק, מֵאִיר וְצוֹחֵק. וְעַל כֵּן הַדִּין מֵאִיר וְצוֹחֵק לָהֶם לָרְשָׁעִים.</p>\n<p>וְאַחַר כָּךְ מַה כָּתוּב? אָז יְדַבֵּר אֵלֵימוֹ בְאַפּוֹ וּבַחֲרוֹנוֹ יְבַהֲלֵמוֹ. וְכָךְ דַּרְכֵי הָרְשָׁעִים - הַקָּדוֹשׁ בָּרוּךְ הוּא מֵאִיר לָהֶם בָּעוֹלָם הַזֶּה, וּמֵאִיר לָהֶם כְּמוֹ יַיִן שֶׁמֵּאִיר בָּרִאשׁוֹנָה, וְאַחַר כָּךְ זוֹעֵם וְהוֹרֵג. וְהַקָּדוֹשׁ בָּרוּךְ הוּא מוֹשֵׁךְ אֶת הָרְשָׁעִים, אִם יַחְזְרוּ כְנֶגְדּוֹ - יָפֶה. אִם לֹא - הוּא מְכַלֶּה אוֹתָם מֵאוֹתוֹ הָעוֹלָם הַבָּא, וְאֵין לָהֶם בּוֹ חֵלֶק וְיֻשְׁמְדוּ מֵהַכֹּל. בָּא לְהִטָּהֵר - מְסַיְּעִים לָהֶם, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מְטַהֵר אוֹתָם וּמְקָרֵב אוֹתָם אֵלָיו וְקוֹרֵא עֲלֵיהֶם שָׁלוֹם. זֶהוּ שֶׁכָּתוּב שָׁלוֹם שָׁלוֹם לָרָחוֹק וְלַקָּרוֹב וְגוֹ'.</p>"],[9522012080,"<p>וְאִשָּׁה כִּי יָזוּב זוֹב דָּמָהּ יָמִים רַבִּים בְּלֹא עֶת נִדָּתָהּ וְגוֹ'. רַבִּי חִיָּיא פָּתַח וְאָמַר, (זכריה יד) הִנֵּה יוֹם בָּא לַה' וְחֻלַּק שְׁלָלֵךְ בְּקִרְבֵּךְ. הַפָּסוּק הַזֶּה כָּךְ הָיָה צָרִיךְ לִהְיוֹת: הִנֵּה יוֹם יָבֹא. מַה זֶּה הִנֵּה יוֹם בָּא? אֶלָּא שֶׁכְּבָר בָּא טֶרֶם שֶׁנִּבְרָא הָעוֹלָם, וְהוּא הַיּוֹם שֶׁבּוֹ יַעֲשֶׂה דִּין לָרְשָׁעִים, וְהוּא הַיּוֹם שֶׁבּוֹ יִפָּרַע הַקָּדוֹשׁ בָּרוּךְ הוּא מֵאוֹתָם שֶׁהֵצִיקוּ לָהֶם לְיִשְׂרָאֵל. הַיּוֹם הַזֶּה בָּא וְעוֹמֵד לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וּמְבַקֵּשׁ מִמֶּנּוּ לַעֲשׂוֹת דִּין וּלְכַלּוֹת עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת, וְנִתֶּנֶת לוֹ רְשׁוּת, כְּמוֹ שֶׁנֶּאֱמַר (שם) וְאָסַפְתִּי אֶת כָּל הַגּוֹיִם אֶל יְרוּשָׁלם לַמִּלְחָמָה וְגוֹ'.</p>\n<p>רַבִּי יִצְחָק אָמַר, שְׁנֵי יָמִים הֵם לַקָּדוֹשׁ בָּרוּךְ הוּא, אֶחָד שָׁרוּי עִמּוֹ, וְאֶחָד בָּא לְפָנָיו, וּבְאֵלּוּ עוֹשֶׂה הַקָּדוֹשׁ בָּרוּךְ הוּא קְרָבוֹת עִם הַכֹּל. וּכְשֶׁבָּא הַיּוֹם הַזֶּה לַעֲרֹךְ קְרָב, הוּא מִזְדַּוֵּג עִם אוֹתוֹ יוֹם אַחֵר, וְנוֹטֵל כְּלֵי זַיִן עַל כְּלֵי זֵינוֹ, וְעוֹרֵךְ קְרָב בְּכֻלָּם, בְּאוֹתָם רָמִים וּנְמוּכִים. זֶהוּ שֶׁכָּתוּב (ישעיה ב) כִּי יוֹם לַה' צְבָאוֹת עַל כָּל גֵּאֶה וָרָם וְעַל כָּל נִשָּׂא וְשָׁפֵל.</p>\n<p>רַבִּי שִׁמְעוֹן אָמַר, וְאִשָּׁה כִּי יָזוּב זוֹב דָּמָהּ וְגוֹ'. הַיְנוּ שֶׁכָּתוּב, (שם לד) חֶרֶב לַה' מָלְאָה דָם. מָלְאָה דָם וַדַּאי, שֶׁכָּתוּב כִּי יָזוּב זוֹב דָּמָהּ יָמִים רַבִּים. בְּלֹא עֶת נִדָּתָהּ, הַיְנוּ שֶׁכָּתוּב (דניאל ט) וַיִּשְׁקֹד ה' עַל הָרָעָה וַיְבִיאֶהָ עָלֵינוּ. שֶׁשָּׁנִינוּ, הַקָּדוֹשׁ בָּרוּךְ הוּא מַקְדִּים פֻּרְעָנוּת לָעוֹלָם, וְהָרְשָׁעִים מַקְדִּימִים אֶת הַפֻּרְעָנוּת בַּחֲטָאֵיהֶם לָבֹא לָעוֹלָם. אוֹ כִי תָזוּב עַל נִדָּתָהּ, הַיְנוּ (ויקרא כו) וְיָסַפְתִּי לְיַסְּרָה אֶתְכֶם. מַה זֶּה וְיָסַפְתִּי לְיַסְּרָה? אוֹסִיף דִּין עַל דִּין וְאֶתֵּן דָּם עַל דָּם יוֹתֵר עַל מַה שֶּׁיֵּשׁ בְּאוֹתָהּ הַחֶרֶב לַה' מָלְאָה דָם.</p>\n<p>כָּתוּב, לֹא אֹסִף לְקַלֵּל עוֹד אֶת הָאֲדָמָה בַּעֲבוּר הָאָדָם. מַה זֶּה לֹא אֹסִף? אֶלָּא, לֹא אֶתֵּן עוֹד תּוֹסֶפֶת לְאוֹתָהּ חֶרֶב, אֶלָּא כְּמוֹ שֶׁיָּכוֹל הָעוֹלָם לִסְבֹּל. וַהֲרֵי כָּתוּב וְיָסַפְתִּי? אֶלָא כָּתוּב לְיַסְּרָה, וְלֹא לְכַלּוֹת. זֶהוּ שֶׁכָּתוּב אוֹ כִּי תָזוּב עַל נִדָּתָהּ.</p>\n<p>כָּל יְמֵי זוֹב טֻמְאָתָהּ. מַה זֶּה כָּל יְמֵי זוֹב טֻמְאָתָהּ? אֶלָּא שֶׁהָרְשָׁעִים מְטַמְּאִים אֶת עַצְמָם בַּחֲטָאֵיהֶם וּמְטַמְּאִים מָקוֹם אַחֵר, כְּמוֹ שֶׁנֶּאֱמַר (במדבר יט) כִּי אֶת מִקְדַּשׁ ה' טִמֵּא. וּמְעוֹרְרִים רוּחַ טֻמְאָה עֲלֵיהֶם. וְלֶעָתִיד לָבֹא עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְטַהֵר אֶת יִשְׂרָאֵל וּלְהַעֲבִיר אֶת אוֹתָהּ רוּחַ טֻמְאָה מִן הָעוֹלָם, שֶׁכָּתוּב לֹא יוֹסִיף יָבֹא בָךְ עוֹד עָרֵל וְטָמֵא. וְכָתוּב וְאֶת רוּחַ הַטֻּמְאָה אַעֲבִיר מִן הָאָרֶץ. מִן הָאָרֶץ וַדַּאי. (מי שבא להטמא, מטמאים אותו ודאי).</p>"],[9522012081,"<p>רַבִּי חִזְקִיָּה הָיָה יוֹשֵׁב לִפְנֵי רַבִּי אֶלְעָזָר. לַיְלָה אֶחָד קָמוּ בַּחֲצוֹת הַלַּיְלָה לַעֲסֹק בַּתּוֹרָה. פָּתַח רַבִּי אֶלְעָזָר וְאָמַר, (קהלת ז) בְּיוֹם טוֹבָה הֱיֵה בְטוֹב וְגוֹ', גַּם אֶת זֶה עֻמַּת זֶה עָשָׂה הָאֱלֹהִים וְגוֹ'. בְּיוֹם טוֹבָה הֱיֵה בְטוֹב - בִּזְמַן שֶׁמַּרְבֶּה הַקָּדוֹשׁ בָּרוּךְ הוּא חֶסֶד בָּעוֹלָם צָרִיךְ אָדָם לָלֶכֶת בַּשְּׁוָקִים וּלְהֵרָאוֹת לִפְנֵי הַכֹּל, שֶׁהֲרֵי כְּשֶׁמַּתְחִיל טוּבוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא בָּעוֹלָם, הוּא שׁוֹרֶה בַכֹּל, וּבַכֹּל הוּא עוֹשֶׂה טוֹב וּמַרְבֶּה אוֹתוֹ בָּעוֹלָם. וּמִשּׁוּם כָּךְ יֵרָאֶה אָדָם בְּגָלוּי בַּשְּׁוָקִים, וְיַעֲשֶׂה טוֹב שֶׁיִּשְׁרֶה עָלָיו טוֹב אַחֵר. זֶהוּ שֶׁכָּתוּב (שם) בְּיוֹם טוֹבָה הֱיֵה בְטוֹב. הֱיֵה בְטוֹב וַדַּאי.</p>\n<p>וּבְיוֹם רָעָה רְאֵה. לֹא כָתוּב וּבְיוֹם רָעָה הֱיֵה בְרָע, אֶלָּא בְּיוֹם רָעָה רְאֵה. שֶׁהֲרֵי בְּשָׁעָה שֶׁהַדִּין תָּלוּי בָּעוֹלָם, אֵין צָרִיךְ לָאָדָם לְהֵרָאוֹת בַּשּׁוּק וְלָלֶכֶת יְחִידִי בָּעוֹלָם. שֶׁהֲרֵי כְּשֶׁדִּין שָׁרוּי בָּעוֹלָם, עַל הַכֹּל הוּא שׁוֹרֶה. וּמִי שֶׁפּוֹגֵעַ בּוֹ וְנִפְגָּשׁ לְפָנָיו, יִדּוֹן בְּאוֹתוֹ הַדִּין, וְאָז כָּתוּב (משלי יג) וְיֵשׁ נִסְפֶּה בְּלֹא מִשְׁפָּט. שֶׁהֲרֵי מִשְׁפָּט הִסְתַּלֵּק מִצֶּדֶק, וְלֹא שׁוֹרִים זֶה עִם זֶה עַל הָעוֹלָם. וְעַל כָּךְ רְאֵה. רְאֵה וֶהְיֵה שָׁמוּר, הַשְׁגַּח וְעַיֵּן לְכָל צַד וֶהְיֵה יוֹדֵעַ שֶׁבְּכֻלָּם שָׁרוּי הַדִּין, וְאַל תֵּצֵא הַחוּצָה וְאַל תֵּרָאֶה בַּשּׁוּק, כְּדֵי שֶׁלֹּא יִשְׁרֶה עָלֶיךְ. מָה הַטַּעַם? מִשּׁוּם שֶׁגַּם אֶת זֶה לְעֻמַּת זֶה עָשָׂה הָאֱלֹהִים. כְּמוֹ שֶׁכְּשֶׁשּׁוֹרֶה הַטּוֹב בָּעוֹלָם, הוּא שׁוֹרֶה עַל הַכֹּל - כָּךְ כְּשֶׁשּׁוֹרֶה הַדִּין בָּעוֹלָם, הוּא שׁוֹרֶה עַל הַכֹּל, וּמִי שֶׁפּוֹגֵשׁ בּוֹ נִתְפָּס.</p>\n<p>בֹּא רְאֵה, כְּשֶׁדִּין שָׁרוּי בָּעוֹלָם, כַּמָּה חֲרָבוֹת תְּלוּיוֹת שֶׁיּוֹצְאוֹת מֵאוֹתָהּ חֶרֶב עֶלְיוֹנָה, וְזוֹקְפִים רֹאשׁ וְרוֹאִים שֶׁהֲרֵי אוֹתָהּ חֶרֶב עֶלְיוֹנָה הִיא אֲדֻמָּה, מְלֵאָה דָם בְּכָל הַצְּדָדִים, וְאָז גּוֹזְרִים גְּזֵרוֹת. וְכַמָּה מִינֵי חֲרָבוֹת מִתְעוֹרְרִים, (אז מתחדדות חרבות, וכמה חקים מתעוררים) כְּמוֹ שֶׁנֶּאֱמַר (שיר ג) אִישׁ חַרְבּוֹ עַל יְרֵכוֹ, וְכָתוּב (יהושע ה) וְחַרְבּוֹ שְׁלוּפָה בְּיָדוֹ. וְכֻלָּם מְצוּיִים לַעֲשׂוֹת דִּין. וּמִי שֶׁפּוֹגֵשׁ בָּהֶם נִזּוֹק. כָּתוּב (בראשית יט) הִנֵּה נָא מָצָא עַבְדְּךְ חֵן בְּעֵינֶיךְ וַתַּגְדֵּל חַסְדְּךְ וְגוֹ'. מָה הַטַּעַם? מִשּׁוּם שֶׁבְּכָל מָקוֹם שֶׁהַדִּין שָׁרוּי, בַּכֹּל הוּא שׁוֹרֶה, בֵּין בָּעִיר בֵּין בַּמִּדְבָּר וּסְבִיב הָעִיר.</p>"],[9522012082,"<p>עוֹד פָּתַח וְאָמַר, (שיר ח) שִׂימֵנִי כַחוֹתָם עַל לִבֶּךְ וְגוֹ'. שִׂימֵנִי כַחוֹתָם, כְּנֶסֶת יִשְׂרָאֵל אָמְרָה אֶת זֶה לַקָּדוֹשׁ בָּרוּךְ הוּא. שִׂימֵנִי כַחוֹתָם, מִי הוּא הַחוֹתָם? זֶהוּ חוֹתַם הַטַּבַּעַת שֶׁל הָאֱמֶת. כַחוֹתָם עַל לִבֶּךְ - זֶהוּ חוֹתָם שֶׁל תְּפִלִּין שֶׁמֵּנִיחַ אָדָם עַל לִבּוֹ. כַּחוֹתָם עַל זְרוֹעֶךְ - זוֹ יָד כֵּהָה שֶׁמֵּנִיחַ בְּאוֹתָהּ זְרוֹעַ. וּמִיהוּ? יִצְחָק. וּכְנֶסֶת יִשְׂרָאל אוֹמֶרֶת, שִׂימֵנִי כַחוֹתָם. חוֹתָם הָיָה צָרִיךְ לִהְיוֹת! מַה זֶּה כַּחוֹתָם? כְּאוֹתָן תְּפִלִּין שֶׁל רֹאשׁ שֶׁמֵּבִיא שֶׁבַח לְכָל הַגּוּף. וְעַל כָּךְ תְּפִלִּין בַּזְּרוֹעַ, עַל הַלֵּב, וּבָזֶה נִמְצָא אָדָם שָׁלֵם כְּמוֹ שֶׁלְּמַעְלָה.</p>\n<p>כִּי עַזָּה כַמָּוֶת אַהֲבָה. מַה זֶּה כִּי עַזָּה כַמָּוֶת? אֶלָּא לֹא נִמְצֵאת קַשְׁיוּת בָּעוֹלָם כְּמוֹ פְּרֵדַת הַנֶּפֶשׁ מֵהַגּוּף כְּשֶׁרוֹצִים לְהִפָּרֵד. (ועל זה) כָּךְ אַהֲבַת כְּנֶסֶת יִשְׂרָאֵל לַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁלֹּא נִפְרָדִים לְעוֹלָמִים, וּמִשּׁוּם כָּךְ תְּפִלָּה שֶׁל יָד נִקְשֶׁרֶת בַּזְּרוֹעַ, לְקַיֵּם אֶת הַכְּתוּב, (שם ב) שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי.</p>\n<p>קָשָׁה כִשְׁאוֹל קִנְאָה. בְּכָל דַּרְגוֹת הַגֵּיהִנֹּם אֵין קָשֶׁה כְּמוֹ הַשְּׁאוֹל, שֶׁיּוֹרֵד לְמַטָּה מִכֻּלָּם, פְּרָט לְאוֹתָהּ מַדְרֵגָה שֶׁנִּקְרֵאת אֲבַדּוֹן, וְזֶה וָזֶה הִשְׁתַּתְּפוּ כְאֶחָד, וְזֶה קָשֶׁה לָרְשָׁעִים מֵהַכֹּל. כָּךְ קָשָׁה כִשְׁאוֹל קִנְאָה, שֶׁאֵין קִנְאָה אֶלָּא בְּאַהֲבָה, וּמִתּוֹךְ אַהֲבָה בָּאָה קִנְאָה. וּמִי שֶׁמְּקַנֵּא לְאוֹתוֹ שֶׁאוֹהֵב בְּיוֹתֵר, קָשֶׁה לוֹ לְהִפָּרֵד מִמֶּנּוּ מֵאוֹתָהּ דַּרְגָּה שֶׁנִּקְרֵאת שְׁאוֹל, שֶׁהִיא קָשָׁה מִכָּל דַּרְגּוֹת הַגֵּיהִנֹּם.</p>\n<p>רְשָׁפֶיהָ רִשְׁפֵּי אֵשׁ שַׁלְהֶבֶת יָהּ. וּמִי הִיא שַׁלְהֶבֶת יָהּ? זוֹ אֵשׁ שֶׁיּוֹצֵאת מִתּוֹךְ שׁוֹפָר, כְּלוּלָה מֵרוּחַ וּמַיִם. וּמִתּוֹךְ אוֹתָהּ הַשַּׁלְהֶבֶת כְּשֶׁמִּתְלַהֶטֶת בִּכְנֶסֶת יִשְׂרָאֵל, שׂוֹרֶפֶת הָעוֹלָם בְּשַׁלְהֶבֶת בְּקִנְאָה שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא. וּבְשָׁעָה שֶׁהִיא מְקַנְּאָה לוֹ, אוֹי לַפּוֹגֵשׁ בַּשַּׁלְהֶבֶת, שֶׁהוּא יִשָּׂרֵף בָּהֶם.</p>"],[9522012083,"<p>עוֹד פָּתַח וְאָמַר, (שיר ח) מַיִם רַבִּים לֹא יוּכְלוּ לְכַבּוֹת וְגוֹ'. מַיִם רַבִּים - זוֹ זְרוֹעַ יָמִין שֶׁצָּרִיךְ לִקְשֹׁר בָּהּ קֶשֶׁר שֶׁל תְּפִלָּה עַל זְרוֹעַ שְׂמֹאל, לְקַיֵּם וִימִינוֹ תְּחַבְּקֵנִי. דָּבָר אַחֵר מַיִם רַבִּים - זֶהוּ הַנָּהָר הָעֶלְיוֹן שֶׁמִּמֶּנּוּ יוֹצְאִים נְהָרוֹת לְכָל הָעֲבָרִים, וְכֻלָּם שׁוֹפְעִים וְנִמְשָׁכִים מִמֶּנּוּ, כְּמוֹ שֶׁנֶּאֱמַר (תהלים צג) מִקֹּלוֹת מַיִם רַבִּים. מֵאוֹתָם קוֹלוֹת שֶׁל מַיִם רַבִּים שֶׁיּוֹצְאִים וְנִמְשָׁכִים מִמֶּנּוּ, כְּמוֹ שֶׁנֶּאֱמַר נָשְׂאוּ נְהָרוֹת וְגוֹ'.</p>\n<p>אִם יִתֵּן אִישׁ אֶת כָּל הוֹן בֵּיתוֹ בָּאַהֲבָה - שֶׁאוֹהֶבֶת כְּנֶסֶת יִשְׂרָאֵל אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא - יָבוּזוּ לוֹ. בּוֹז יָבוּזוּ לוֹ?! יָבוּז הָיָה צָרִיךְ לִהְיוֹת! אֶלָּא אִם יִתֵּן אִישׁ - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא. אֶת כָּל הוֹן בֵּיתוֹ, כְּמוֹ שֶׁנֶּאֱמַר (משלי כד) כָּל הוֹן יָקָר וְנָעִים. בָּאַהֲבָה - שֶׁל כְּנֶסֶת יִשְׂרָאֵל אֵלָיו וְלֹא לְהִתְקַשֵּׁר עִמָּהּ, בּוֹז יָבוּזוּ לוֹ - כָּל אוֹתָם אוּכְלוּסִים וְכָל אוֹתָם מַחֲנוֹת שֶׁלְּמַעְלָה לְאוֹתוֹ הוֹן יָקָר, שֶׁהֲרֵי אֵין רָצוֹן לְכֻלָּם אֶלָּא בְּשָׁעָה שֶׁמִּתְקַשֶּׁרֶת כְּנֶסֶת יִשְׂרָאֵל עִם הַקָּדוֹשׁ בָּרוּךְ הוּא וּמִתְעַטֶּרֶת עִמּוֹ, וְאָז כָּל אוֹתָם הָאוּכְלוּסִים וְכָל אוֹתָם הַמַּחֲנוֹת וְכָל הָעוֹלָמוֹת, כֻּלָּם בְּשִׂמְחָה, בְּאוֹר וּבִבְרָכוֹת, (ועלזהאמר) כָּתוּב שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי וִימִינוֹ תְּחַבְּקֵנִי. מִי שֶׁמֵּנִיחַ תְּפִלִּין, כְּשֶׁמֵּנִיחַ תְּפִלָּה שֶׁל יָד, צָרִיךְ לְהוֹשִׁיט זְרוֹעַ שְׂמֹאל לְקַבֵּל אֶת כְּנֶסֶת יִשְׂרָאֵל וְלִקְשֹׁר קֶשֶׁר עִם הַיָּמִין כְּדֵי לְחַבֵּק אוֹתָהּ, לְקַיֵּם אֶת הַכָּתוּב, שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי וִימִינוֹ תְּחַבְּקֵנִי. שֶׁיֵּרָאֶה הָאָדָם כְּמוֹ שֶׁלְּמַעְלָה וּלְהִתְעַטֵּר בַּכֹּל, וְאָז הָאָדָם שָׁלֵם בַּכֹּל, בִּקְדֻשָּׁה עֶלְיוֹנָה. וְהַקָּדוֹשׁ בָּרוּךְ הוּא קוֹרֵא עָלָיו, (ישעיה מט) יִשְׂרָאֵל אֲשֶׁר בְּךְ אֶתְפָּאָר.</p>\n<p>בּוֹז יָבוּזוּ לוֹ. מַה זֶּה בּוֹז? יוֹם שֵׁנִי וְיוֹם שִׁשִּׁי וְיוֹם שְׁבִיעִי שֶׁל סֻכּוֹת, שֶׁבָּהֶם הָיוּ מְנַסְּכִים מַיִם וְיַיִן שֶׁל שִׁבְעַת יְמֵי הַסֻּכּוֹת, בָּהֶם הָיוּ מַקְרִיבִים יִשְׂרָאֵל שִׁבְעִים פָּרִים לְכַפֵּר עַל שִׁבְעִים מְמֻנִּים, כְּדֵי שֶׁלֹּא יִשָּׁאֵר הָעוֹלָם חָרֵב מֵהֶם, זֶהוּ שֶׁכָּתוּב וּבַחֲמִשָּׁה עָשָׂר יוֹם וְגוֹ' וְהִקְרַבְתֶּם עֹלָה אִשֵּׁה וְגוֹ'. (עד כאן תוספתא).</p>"],[9522012084,"<p>רַבִּי חִזְקִיָּה פָּתַח וְאָמַר, (תהלים יז) שִׁמְעָה ה' צֶדֶק וְגוֹ'. כַּמָּה חֲבִיבָה כְּנֶסֶת יִשְׂרָאֵל לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁבְּכָל זְמַן שֶׁכְּנֶסֶת יִשְׂרָאֵל בָּאָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, הַקָּדוֹשׁ בָּרוּךְ הוּא מִזְדַּמֵּן כְּנֶגְדָּהּ. זֶהוּ שֶׁכָּתוּב שִׁמְעָה ה' צֶדֶק הַקְשִׁיבָה רִנָּתִי הַאֲזִינָה תְפִלָּתִי. אָמַר דָּוִד, אֲנִי הִתְקַשַּׁרְתִּי עִם כְּנֶסֶת יִשְׂרָאֵל, כְּמוֹ שֶׁהִיא נִמְצֵאת לְפָנֶיךְ, גַּם אֲנִי כָּךְ נִמְצָא. וּמִשּׁוּם כָּךְ, שִׁמְעָה ה' צֶדֶק - בָּרִאשׁוֹנָה, וְאַחַר כָּךְ - הַקְשִׁיבָה רִנָּתִי הַאֲזִינָה תְפִלָּתִי.</p>\n<p>בְּלֹא שִׂפְתֵי מִרְמָה, מַה זֶּה בְּלֹא שִׂפְתֵי מִרְמָה? אֶלָּא כָּךְ שָׁנִינוּ, כָּל דִּבּוּר וְדִבּוּר שֶׁל תְּפִלָּה שֶׁמּוֹצִיא אָדָם מִפִּיו, עוֹלֶה לְמַעְלָה וּבוֹקֵעַ רְקִיעִים, וְנִכְנָס לְמָקוֹם שֶׁנִּכְנָס, וְשָׁם נִבְחָן אוֹתוֹ הַדִּבּוּר, אִם זֶה דִּבּוּר כָּשֵׁר וְאִם לֹא. אִם זֶה דִּבּוּר כָּשֵׁר - מַכְנִיסִים אוֹתוֹ לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ לַעֲשׂוֹת רְצוֹנוֹ. וְאִם לֹא - מַסְטִים אוֹתוֹ הַחוּצָה, וּמִתְעוֹרֶרֶת בְּאוֹתוֹ דִבּוּר רוּחַ אַחֶרֶת.</p>\n<p>וּבֹא רְאֵה, בְּיוֹסֵף כָּתוּב, (שם קה) עִנּוּ בַכֶּבֶל רַגְלוֹ וְגוֹ'. עַד מָתַי עִנּוּ בַכֶּבֶל רַגְלוֹ? עַד עֵת בּא דְבָרוֹ אִמְרַת ה' צְרָפָתְהוּ. עַד עֵת בֹּא דְבָרוֹ שֶׁל מִי? אֶלָּא עַד עֵת בֹּא דְבָרוֹ (של יוסף, ונבחן) אוֹתוֹ דִבּוּר. זֶהוּ שֶׁכָּתוּב אִמְרַת ה' צְרָפָתְהוּ. וְאָז - שָׁלַח מֶלֶךְ וַיַּתִּירֵהוּ מֹשֵׁל עַמִּים וַיְפַתְּחֵהוּ. בֵּינְתַיִם הָיָה בָּא הַבֹּקֶר.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, כָּתוּב (שמואל א כה) והיתה נפש אדני צרורה בִּצְרוֹר הַחַיִּים. נֶפֶשׁ אֲדנִי, סְתָם, כְּמוֹ שֶׁנֶּאֱמַר (תהלים כד) אֲשֶׁר לֹא נָשָׂא לַשָּׁוְא נַפְשִׁי. הֲרֵי הַזְּמַן בַּבֹּקֶר לְקַשֵּׁר אֶת כְּנֶסֶת יִשְׂרָאֵל וּלְחַבְּרָהּ לְבַעְלָהּ. אַשְׁרֵי הַצַּדִּיקִים שֶׁמִּשְׁתַּדְּלִים בַּתּוֹרָה בַּלַּיְלָה וּבָאִים לְהִתְקַשֵּׁר עִם הַקָּדוֹשׁ בָּרוּךְ הוּא וְעִם כְּנֶסֶת יִשְׂרָאֵל, עֲלֵיהֶם כָּתוּב (משלי כג) יִשְׂמַח אָבִיךְ וְאִמֶּךְ וְתָגֵל יוֹלַדְתֶּךְ.</p>"],[9522012085,"<p>אָמַר רַבִּי אֶלְעָזָר, כָּתוּב (ויקרא טו) וְהִזַּרְתֶּם אֶת בְּנֵי יִשְׂרָאֵל מִטֻּמְאָתָם וְגוֹ' בְּטַמְּאָם אֶת מִשְׁכָּנִי אֲשֶׁר בְּתוֹכָם. וְהִזַּרְתֶּם, כְּמוֹ הַזָּר הַזֶּה, שֶׁהוּא זָר מִכֻּלָּם וְלֹא מִתְחַבֵּר בְּמַה שֶּׁאֵינוֹ שֶׁלּוֹ.</p>\n<p>וּבֹא רְאֵה, בְּשָׁעָה שֶׁאֲנָשִׁים מִטַּמְּאִים לְמַטָּה, מְטַמְּאִים אוֹתָם בַּכֹּל, וַהֲרֵי זֶה נֶאֱמַר. אֲבָל בְּשָׁעָה שֶׁרוּחַ טֻמְאָה מִתְעוֹרֶרֶת (למטה, מתעוררת רוח וכו') נֶחְשַׁבְתֶּם כְּזָר, אֶלָּא רוּחַ טֻמְאָה שֶׁלְּמַטָּה מְעוֹרֶרֶת רוּחַ טֻמְאָה אַחֶרֶת, וְנִתֶּנֶת לָהּ רְשׁוּת לָרֶדֶת לָעוֹלָם. אֵיזוֹ רְשׁוּת? רְשׁוּת שֶׁל קְדֻשָּׁה, שֶׁהָיָה יוֹרֵד וּמַכֶּה בּוֹ, לֹא נִמְצָא וּמִסְתַּלֵּק, וְאָז מִתְגַּלֶּה הַדִּין כְּנֶגֶד הָרְשָׁעִים, וּמוֹסִיף דִּין עַל דִּינוֹ. וְאָז שְׁתֵּי רוּחוֹת נִמְצָאוֹת בָּעוֹלָם, אַחַת רוּחַ הַדִּין, וְאַחַת רוּחַ הַטֻּמְאָה.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, הִצְטָרַכְתִּי כָּאן לוֹמַר דָּבָר שֶׁלָּמַדְתִּי מֵאָבִי. בֹּא רְאֵה, כָּאן לָמַדְנוּ מִנֶּגַע הַבַּיִת, שֶׁכְּשֶׁרוּחַ טֻמְאָה שׁוֹרָה בַּבַּיִת וְהַקָּדוֹשׁ בָּרוּךְ הוּא רוֹצֶה לְטַהֵר אוֹתוֹ, שׁוֹלֵחַ נֶגַע צָרַעַת בַּבַּיִת לְהִלָּחֵם זֶה עִם זֶה, וְאוֹתוֹ הַנֶגַע לֹא סָר מֵהַבַּיִת. וְאַף עַל גַּב שֶׁרוּחַ טֻמְאָה הִסְתַּלְּקָה מֵאוֹתוֹ בַּיִת, עַד שֶׁיְּנַתְּצוּ אֶת הַבַּיִת, הָאֲבָנִים וְהָעֵצִים וְהַכֹּל, אָז נִטְהָר הַמָּקוֹם.</p>\n<p>כְּמוֹ כֵן מִי שֶׁנִּמְצָא וּמֵעִיר רוּחַ טֻמְאָה וְשׁוֹרָה עָלָיו, כְּשֶׁרוֹצֶה הַקָּדוֹשׁ בָּרוּךְ הוּא לְטַהֵר אֶת הָעוֹלָם, מִתְעוֹרֶרֶת רוּחַ דִּין קָשֶׁה, וְנִמְצֵאת בָּעוֹלָם, וְשׁוֹרָה עַל אוֹתָהּ רוּחַ טֻמְאָה, וְנִלְחָמוֹת זוֹ עִם זוֹ עַד שֶׁתַּעֲבֹר מִן הָעוֹלָם. וְאוֹתָהּ רוּחַ הַדִּין הַקָּשֶׁה לֹא מִסְתַּלֶּקֶת מִמְּקוֹמָהּ עַד שֶׁיְּנַתֵּץ אֶת הַמָּקוֹם, אֵיבָרִים וַעֲצָמוֹת וְהַכֹּל, וְאָז נִטְהָר הָעוֹלָם, וְעוֹבְרוֹת מִמֶּנּוּ רוּחוֹת שֶׁל טֻמְאָה, וְהָעוֹלָם נִמְצָא בְטֹהַר.</p>\n<p>וְעַל זֶה שָׁנִינוּ, הַבָּא לִטָּמֵא מְטַמְּאִים אוֹתוֹ וַדַּאי. אוֹי לְאָדָם כְּשֶׁשּׁוֹרָה עָלָיו רוּחַ טֻמְאָה וְנִמְצָא עִמָּהּ בָּעוֹלָם, שֶׁוַּדַּאי יֵדַע שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא רוֹצֶה לְבַעֲרוֹ מִן הָעוֹלָם. אַשְׁרֵי הַצַּדִּיקִים שֶׁכֻּלָּם קְדוֹשִׁים וְנִמְצָאִים בִּקְדֻשָּׁה לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ, וְשׁוֹרָה עֲלֵיהֶם רוּחַ קְדֻשָּׁה בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא. כֵּיוָן שֶׁבָּא הַבֹּקֶר, קָמוּ וְהָלְכוּ.</p>"],[9522012086,"<p>עֵד שֶׁהָיוּ הוֹלְכִים, פָּתַח רַבִּי אֶלְעָזָר וְאָמַר, (בראשית לב) וְיַעֲקֹב הָלַךְ לְדַרְכּוֹ וַיִּפְגְּעוּ בוֹ מַלְאֲכֵי אֱלֹהִים. וְיַעֲקֹב הָלַךְ לְדַרְכּוֹ, שֶׁהָיָה הוֹלֵךְ כְּנֶגֶד אָבִיו. בֹּא רְאֵה, כָּל זְמַן שֶׁיַּעֲקֹב נִמְצָא אֵצֶל לָבָן, לֹא דִבֵּר עִמּוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא (ולא נמצא אצלו). וְאִם תֹּאמַר, הֲרֵי כָּתוּב (בראשית לא) וַיֹּאמֶר ה' אֶל יַעֲקֹב שׁוּב אֶל אֶרֶץ אֲבוֹתֶיךְ וּלְמוֹלַדְתֶּךְ וְגוֹ'. זֶה הָיָה בַּסּוֹף, בִּזְמַן שֶׁרָצָה לְהִפָּרֵד מִלָּבָן. וּכְשֶׁנִּפְרַד מִמֶּנּוּ, בָּאוּ לִקְרָאתוֹ אוֹתָם מַלְאָכִים וְלִוּוּהוּ בְדַרְכּוֹ.</p>\n<p>בֹּא רְאֵה, כָּתוּב וַיִּפְגְּעוּ בוֹ. וַיִּפְגַּע בְּמַלְאֲכֵי אֱלֹהִים הָיָה צָרִיךְ לִהְיות! מַה זֶּה בּו? אֶלָּא הֵם בָּאוּ לְהִכָּלֵל בּוֹ (ולוהו בדרך). מַה זֶּה לְהִכָּלֵל בּוֹ? אֶלָּא הֵם בָּאוּ מִצַּד הַגְּבוּרָה, שֶׁכָּתוּב מַלְאֲכֵי אֱלֹהִים, וְרָאָה מִצַּד אַחֵר מַלְאֲכֵי רַחֲמִים, וְנִכְלְלוּ בוֹ רַחֲמִים וְדִין.</p>\n<p>בֹּא רְאֵה, בָּרִאשׁוֹנָה מַלְאֲכֵי אֱלֹהִים, זֶה אֶחָד. אַחַר כָּךְ - וַיִּקְרָא שֵׁם הַמָּקוֹם הַהוּא מַחֲנָיִם, שְׁנַיִם. אֶחָד מִצַּד הַדִּין, וְאֶחָד מִצַּד הָרַחֲמִים. מַלְאָכִים מִן הַצַּד הַזֶּה, וּמַלְאָכִים מִן הַצַּד הַזֶּה. וְעַל זֶה כָּתוּב וַיִּפְגְּעוּ בוֹ. בּוֹ דַּוְקָא. וַיֹּאמֶר יַעֲקֹב כַּאֲשֶׁר רָאָם, רָאָה אוֹתָם הָיָה צָרִיךְ לִהְיוֹת! מַה זֶּה רָאָם? אֶלָּא רָאָה אוֹתָם כְּלוּלִים כְּאֶחָד מְדֻבָּקִים זֶה בָּזֶה, מְחוּבָּרִים זֶה בָּזֶה, וְלָכֵן כָּתוּב רָאָם, וְכֻלָּם בָּאוּ לְלַוּוֹת אוֹתוֹ וּלְהַצִּילוֹ מִיַּד עֵשָׂו.</p>"],[9522012087,"<p>כָּתוּב בְּעֵשָׂו, (שם כה) וַיֵּצֵא הָרִאשׁוֹן אַדְמוֹנִי. וַיֵּצֵא הָרִאשׁוֹן, אִם תֹּאמַר שֶׁיַּעֲקֹב הָיָה מִטִּפָּה רִאשׁוֹנָה - לֹא כָּךְ, שֶׁהֲרֵי כָּתוּב וַיֵּצֵא הָרִאשׁוֹן, וְלֹא כָתוּב וַיֵּצֵא רִאשׁוֹן. וּמִשּׁוּם שֶׁיִּצְחָק בָּא מִצַּד הַדִּין הַקָּשֶׁה, יָצָא עֵשָׂו אַדְמוֹנִי, אָדם. שֶׁאִם יַעֲקֹב הָיָה בְּכוֹר, אוֹתָהּ טִפָּה רִאשׁוֹנָה אֵיךְ יָצְאָה כָּךְ אֲדֻמָּה. אֲבָל טִפָּה שְׁנִיָּה הָיָה, וּמִשּׁוּם כָּךְ לֹא יָצָא כָּךְ, שֶׁהֲרֵי אוֹתָהּ טִפָּה הָיְתָה מִצַּד הָרַחֲמִים מִצַּד זֶה וּמִצַּד זֶה.</p>\n<p>וְהַטִפָּה שֶׁל עֵשָׂו לֹא הָיְתָה כְּמוֹ הַטִּפָּה שֶׁל יַעֲקֹב, שֶׁזֶּה שָׁלֵם וְזֶה לֹא שָׁלֵם. וּבְאוֹתָהּ שָׁעָה הָיָה יִצְחָק מְכַוֵּן בְּסִיּוּם הַדִּין הַקָּשֶׁה, שֶׁהוֹצִיא בְצִדּוֹ בְּאוֹרוֹת חֲקוּקִים בְּאֵיבָרָיו, וּמִשּׁוּם כָּךְ עֵשָׂו זֻהֲמָא שֶׁהֻתְּכָה מֵהַזָּהָב.</p>\n<p>וְעַל כָּךְ שָׁנִינוּ, שֶׁצָּרִיךְ אָדָם לְכַוֵּן בְּאוֹתָהּ שָׁעָה בָּרָצוֹן שֶׁל רִבּוֹנוֹ, כְּדֵי שֶׁיּוֹצִיא בָנִים קְדוֹשִׁים לָעוֹלָם. וְאִם תֹּאמַר שֶׁיִּצְחָק לֹא הִתְכַּוֵּן - לֹא כָּךְ, אֶלָּא הִתְכַּוֵּן בִּקְדֻשָּׁה, וְהִתְכַּוֵּן בַּסִּיּוּם שֶׁל אוֹתוֹ מָקוֹם, וְנִמְצָא כְּשֶׁיָּצְאָה אוֹתָהּ טִפָּה רִאשׁוֹנָה בְּאוֹתוֹ מָקוֹם מַמָּשׁ, וְלָכֵן כָּתוּב, כֻּלּוֹ כְּאַדֶּרֶת שֵׂעָר.</p>\n<p>בֹּא רְאֵה, דָּוִד יָצָא בְּיֹפִי שֶׁל אֹדֶם, וְנֶאֱחַז בִּקְדֻשַּׁת רִבּוֹנוֹ, וְעַל זֶה כָּתוּב (שמואל א טז) וְהוּא אַדְמוֹנִי עִם יְפֵה עֵינַיִם וְטוֹב רֹאִי. אֲבָל יַעֲקֹב הָיָה בְּכוֹר מֵעֵשָׂו, לֹא מִטִּפָּה, אֶלָּא שֶׁכִּוֵּן אֶת הָרָצוֹן לָעֵץ הָעֶלְיוֹן הַגָּדוֹל וְהַתַּקִּיף, וְעֵשָׂו בְּאוֹתוֹ מָקוֹם שֶׁל סִיּוּם הַכֹּל, וּמִשּׁוּם כָּךְ כָּתוּב, (עובדיה א) הִנֵּה קָטֹן נְתַתִּיךְ בַּגּוֹיִם בָּזוּי אַתָּה מְאֹד.</p>\n<p>רַבִּי יְהוּדָה הָיָה שׁוֹנֶה כָּךְ. עֵשָׂו נִקְרָא רִאשׁוֹן, שֶׁכָּתוּב וַיֵּצֵא הָרִאשׁוֹן אַדְמוֹנִי כֻּלּוֹ. וְהַקָּדוֹשׁ בָּרוּךְ הוּא נִקְרָא רִאשׁוֹן, שֶׁכָּתוּב (ישעיה מד) אֲנִי רִאשׁוֹן וַאֲנִי אַחֲרוֹן, (שם מא) וְאֶת אַחֲרֹנִים אֲנִי הוּא. וְעָתִיד לְהִפָּרַע רִאשׁוֹן מֵרִאשׁוֹן, וְלִבְנוֹת רִאשׁוֹן, שֶׁכָּתוּב (ירמיה יז) כִּסֵּא כָבוֹד מָרוֹם מֵרִאשׁוֹן. וְלֶעָתִיד לָבא כָּתוּב, (ישעיה מא) רִאשׁוֹן לְצִיּוֹן הִנֵּה הִנָּם וְלִירוּשָׁלם מְבַשֵּׂר אֶתֵּן.</p>\n<p>שָׁנִינוּ, עֲתִידָה יְרוּשָׁלַיִם לִהְיוֹת חוֹמָתָהּ לְמַעְלָה וּלְהִתְקָרֵב עַד כִּסֵּא כְּבוֹד הַמֶּלֶךְ. זֶהוּ שֶׁכָּתוּב (ירמיה כ) בָּעֵת הַהִיא יִקְרְאוּ לִירוּשָׁלם כִּסֵּא ה'. אָז כָּתוּב, (ישעיה ל) וְהָיָה אוֹר הַלְּבָנָה כְּאוֹר הַחַמָּה וְאוֹר הַחַמָּה יִהְיֶה שִׁבְעָתַיִם. אָז, (זכריה יד) בַּיּוֹם הַהוּא יִהְיֶה ה' אֶחָד וּשְׁמוֹ אֶחָד. בָּרוּךְ ה' לְעוֹלָם אָמֵן וְאָמֵן. יִמִלֹךְ ה' לִעוֹלָם אָמֵן וִאָמֵן.</p>"],[9522012088,"<p>תּוֹסֶפְתָּא רַבִּי אֶלְעָזָר וְרַבִּי יוֹסֵי חָמִיו הָיוּ הוֹלְכִים מֵאוּשָׁא לְלוֹד. אָמַר רַבִּי יוֹסֵי לְרַבִּי אֶלְעָזָר, אֶפְשָׁר שֶׁשָּׁמַעְתָּ מֵאָבִיךְ מַה שֶּׁכָּתוּב וְיַעֲקֹב הָלַךְ לְדַרְכּוֹ וְגוֹ'? אָמַר לוֹ, לֹא יָדַעְתִּי. עַד שֶׁהָיוּ הוֹלְכִים, הִגִּיעוּ לַמְּעָרָה שֶׁל לוֹד. שָׁמְעוּ אוֹתוֹ קוֹל שֶׁאוֹמֵר: שְׁנֵי עֳפָרִים שֶׁל הָאַיֶּלֶת עָשׂוּ לְפָנַי רָצוֹן שֶׁל נַחַת לִי, וְהֵם הָיוּ הַמַּחֲנֶה הַקָּדוֹשׁ שֶׁפָּגַשׁ יַעֲקֹב לְפָנָיו. הִתְרַגֵּשׁ רַבִּי אֶלְעָזָר וְהִסְתַּעֵר בְּנַפְשׁוֹ, וְאָמַר: רִבּוֹן הָעוֹלָם כָּךְ דַּרְכּוֹ, טוֹב לָנוּ שֶׁלֹּא נִשְׁמַע, שָׁמַעְתִּי וְלֹא יָדַעְתִּי.</p>\n<p>הִתְרַחֵשׁ לוֹ נֵס, וְשָׁמַע אוֹתוֹ קוֹל שֶׁאוֹמֵר: אַבְרָהָם וְיִצְחָק הָיוּ. נָפַל עַל פָּנָיו וְרָאָה אֶת דְּיוֹקַן אָבִיו. אָמַר לוֹ, אַבָּא, שָׁאַלְתִּי וֶהֱשִׁיבוּנִי, שֶׁאַבְרָהָם וְיִצְחָק הֵם שֶׁפָּגְשׁוּ אֶת יַעֲקֹב כְּשֶׁנִּצַּל מִלָּבָן. אָמַר לוֹ, בְּנִי, הוֹצֵא אֶת (פסקך) פִּתְקְךְ, וְקַח אֶת דִּבְרֵי אָבִיךְ הַזָּקֵן, פֶּה מְדַבֵּר גְּדוֹלוֹת הָיָה. וְלֹא רַק זֶה בִּלְבַד, אֶלָּא אֶת כָּל הַצַּדִּיקִים פּוֹגְשׁוֹת נְשָׁמוֹת שֶׁל צַדִּיקִים לִפְנֵיהֶם לְהַצָּלָתָם, וְהֵם מַלְאָכִים קְדוֹשִׁים עֶלְיוֹנִים.</p>\n<p>וּבֹא רְאֵה, יִצְחָק הָיָה קַיָּם בְּאוֹתָהּ שָׁעָה, אֲבָל נִשְׁמָתוֹ הַקְּדוֹשָׁה נִלְקְחָה לְכִסֵּא הַכָּבוֹד שֶׁל אֲדוֹנוֹ, כְּשֶׁנֶּעֱקַד עַל גַּבֵּי הַמִּזְבֵּחַ, וְאָז נִסְתְּמוּ עֵינָיו מֵרְאוֹת. הַיְנוּ שֶׁכָּתוּב לוּלֵא וְגוֹ' וּפַחַד יִצְחָק הָיָה לִי. (עד כאן התוספתא).</p>"],[9522012089,"<p>וַיְדַבֵּר ה' אֶל מֹשֶׁה אַחֲרֵי מוֹת שְׁנֵי בְּנֵי אַהֲרֹן וְגוֹ'. וַיֹּאמֶר ה' אֶל מֹשֶׁה. רַבִּי יְהוּדָה אָמַר, כֵּיוָן שֶׁכָּתוּב וַיְדַבֵּר ה' אֶל מֹשֶׁה, לָמָּה פַּעַם אַחֶרֶת וַיֹּאמֶר ה' אֶל מֹשֶׁה דַּבֵּר אֶל אַהֲרֹן אָחִיךְ, שֶׁהֲרֵי בַּדִּבּוּר הָרִאשׁוֹן מַסְפִּיק? אֶלָּא כָּךְ שָׁנִינוּ, כָּתוּב וַיִּקְרָא אֶל מֹשֶׁה וַיְדַבֵּר ה' אֵלָיו. וְכָתוּב (שמות כד) וְאֶל מֹשֶׁה אָמַר עֲלֵה אֶל ה'. וַהֲרֵי בֵּאֲרוּ אֶת הַדָּבָר, כָּאן דַּרְגָּה אַחַת, וְאַחַר כָּךְ דַּרְגָּה אַחֶרֶת. אַף כָּאן, וַיְדַבֵּר ה' אֶל מֹשֶׁה - דַּרְגָּה אַחַת. וְאַחַר כָּךְ, וַיֹּאמֶר ה' אֶל מֹשֶׁה דַּבֵּר אֶל אַהֲרֹן אָחִיךְ - דַּרְגָּה אַחֶרֶת. וְהַכֹּל עוֹלֶה בְּמִשְׁקָל אֶחָד, וּמִשֹּׁרֶשׁ אֶחָד הַכֹּל הִתְחַבֵּר.</p>\n<p>אַחֲרֵי מוֹת שְׁנֵי בְּנֵי אַהֲרֹן. רַבִּי יִצְחָק פָּתַח, (תהלים ב) עִבְדוּ אֶת ה' בְּיִרְאָה וְגִילוּ בִּרְעָדָה. וְכָתוּב (שם ק) עִבְדוּ אֶת ה' בְּשִׂמְחָה בֹּאוּ לְפָנָיו בִּרְנָנָה. הַפְּסוּקִים הַלָּלוּ קָשִׁים זֶה עַל זֶה. אֶלָּא כָּךְ שָׁנִינוּ, עִבְדוּ אֶת ה' בְּיִרְאָה - שֶׁכָּל עֲבוֹדָה שֶׁרוֹצֶה בֶּן אָדָם לַעֲבֹד לִפְנֵי רִבּוֹנוֹ, בָּרִאשׁוֹנָה צָרִיךְ יִרְאָה, לִפְחֹד מִמֶּנּוּ. וּמִשּׁוּם הַפַּחַד שֶׁל אֲדוֹנוֹ יִמָּצֵא אַחַר כָּךְ שֶׁיַּעֲשֶׂה בְשִׂמְחָה אֶת מִצְווֹת הַתּוֹרָה, וְעַל כֵּן כָּתוּב, (דברים י) מָה ה' אֱלֹהֶיךְ שּאֵל מֵעִמָּךְ כִּי אִם לְיִרְאָה.</p>\n<p>וְגִילוּ בִּרְעָדָה - שֶׁאָסוּר לָאָדָם לִשְׂמֹחַ יוֹתֵר בָּעוֹלָם הַזֶּה. וְזֶה בְּדִבְרֵי הָעוֹלָם. אֲבָל בְּדִבְרֵי תוֹרָה וּבְמִצְווֹת הַתּוֹרָה צָרִיךְ לִשְׂמֹחַ. אַחַר כָּךְ יִמָּצֵא אָדָם שֶׁיַּעֲשֶׂה בְשִׂמְחָה אֶת מִצְווֹת הַתּוֹרָה, שֶׁכָּתוּב עִבְדוּ אֶת ה' בְּשִׂמְחָה.</p>\n<p>רַבִּי אַבָּא אָמַר, עִבְדוּ אֶת ה' בְּיִרְאָה - סוֹד הַדָּבָר הוּא. עִבְדוּ אֶת ה' בְּיִרְאָה, אֵיזוֹ יִרְאָה כָּאן? אֶלָּא כְּמוֹ שֶׁבֵּאַרְנוּ, שֶׁכָּתוּב (משלי א) יִרְאַת ה' רֵאשִׁית דָּעַת, וְכָתוּב (תהלים קיא) רֵאשִׁית חָכְמָה יִרְאַת ה'. יִרְאַת ה' - כָּךְ נִקְרָא הַקָּדוֹשׁ בָּרוּךְ הוּא. רַבִּי אֶלְעָזָר אָמַר, עִבְדוּ אֶת ה' בְּיִרְאָה - מִי שֶׁרוֹצֶה לַעֲשׂוֹת עֲבוֹדַת אֲדוֹנוֹ, מֵאֵיזֶה מָקוֹם מַתְחִיל, וּבְאֵיזֶה מָקוֹם יְכַוֵּן אֶת הָעֲבוֹדָה לְיַחֵד אֶת שֵׁם רִבּוֹנוֹ? חָזַר וְאָמַר, בְּיִרְאָה. בְּיִרְאָה הִיא הָרֵאשִׁית, מִמַּטָּה לְמַעְלָה. (בא ראה, בני אהרן הרי בארנו, והרי נתבאר הדבר).</p>\n<p>בֹּא רְאֵה, מַה כָּתוּב כָּאן אַחֲרֵי מוֹת, וְאַחַר כָּךְ - דַּבֵּר אֶל אַהֲרֹן אָחִיךְ וְגוֹ' בְּזֹּאת יָבא אַהֲרֹן? אֶלָּא מִכָּאן הָרֵאשִׁית לְהַזְהִיר אֶת הַכֹּהֲנִים, כָּל מִי שֶׁצְּרִיכִים לְהִזָּהֵר בְּזֹּאת הַזּוֹ, וְזוֹהִי יִרְאַת ה'.</p>\n<p>דָּבָר אַחֵר אַחֲרֵי מוֹת שְׁנֵי בְּנֵי אַהֲרֹן - רַבִּי יוֹסֵי אָמַר, אַחֲרֵי מוֹת נָדָב וַאֲבִיהוּא הָיָה צָרִיךְ לִהְיוֹת! מָה הַטַּעַם שְׁנֵי בְּנֵי אַהֲרֹן, וַהֲרֵי יָדוּעַ שֶׁהָיוּ בָנָיו? אֶלָּא כָּךְ שָׁנָה, שֶׁעַד כָּאן לֹא עָמְדוּ בִרְשׁוּתָם, אֶלָּא בִּרְשׁוּת אֲבִיהֶם, וּמִשּׁוּם כָּךְ - בְּקָרְבָתָם לִפְנֵי ה' וַיָּמֻתוּ, שֶׁהֵם דָּחֲקוּ אֶת הַשָּׁעָה בְּחַיֵּי אֲבִיהֶם, וְהַכֹּל הָיָה בִּשְׁבִיל אוֹתוֹ חֵטְא שֶׁעָשׂוּ, שֶׁכָּתוּב (במדבר ג) בְּהַקְרִיבָם אֵשׁ זָרָה. שֶׁשָּׁנִינוּ, בְּמָקוֹם אֶחָד כָּתוּב בְּהַקְרִיבָם אֵשׁ זָרָה, וּבְמָקוֹם אֶחָד כָּתוּב בְּקָרְבָתָם לִפְנֵי ה'. וְזֶה וְגַם זֶה הָיָה, וּמִשּׁוּם כָּךְ כָּתוּב בְּנֵי אַהֲרֹן, וְכָתוּב בְּקָרְבָתָם.</p>\n<p>אָמַר רַבִּי חִיָּיא, יוֹם אֶחָד הָיִיתִי הוֹלֵךְ בַּדֶּרֶךְ לָלֶכֶת אֶל רַבִּי שִׁמְעוֹן לִלְמֹד מִמֶּנּוּ פָּרָשַׁת הַפֶּסַח. פָּגַשְׁתִּי בְּהַר אֶחָד, וְרָאִיתִי בְקִיעִים וְחוֹרִים בְּסֶלַע אֶחָד וּשְׁנֵי אֲנָשִׁים בּוֹ. עַד שֶׁהָיִיתִי הוֹלֵךְ, שָׁמַעְתִּי קוֹל הָאֲנָשִׁים הַלָּלוּ שֶׁהָיוּ אוֹמְרִים, (תהלים מח) שִׁיר מִזְמוֹר לִבְנֵי קֹרַח גָּדוֹל ה' וּמְהֻלָּל מְאֹד וְגוֹ'. מַהוּ שִׁיר מִזְמוֹר? אֶלָּא כָּךְ שָׁנוּ מִשְּׁמוֹ שֶׁל רַבִּי שִׁמְעוֹן, שִׁיר שֶׁהוּא כָּפוּל, שִׁיר שֶׁהוּא מְשֻׁבָּח מִשְּׁאָר הַשִּׁירִים, וְעַל שֶׁהוּא מְשֻׁבָּח מִשְּׁאָר הַשִּׁירִים, פְּעָמִים נֶאֱמָר בּוֹ שִׁירָה, וְכֵן (שם צב) מִזְמוֹר שִׁיר לְיוֹם הַשַּׁבָּת. כְּמוֹ כֵן שִׁיר הַשִּׁירִים אֲשֶׁר לִשְׁלֹמֹה, שִׁירָה לְמַעְלָה מִשִּׁירָה.</p>\n<p>שִׁיר מִזְמוֹר, שִׁירָה שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁמְּזַמְּרִים בְּנֵי קֹרַח (על) אוֹתָם שֶׁיּוֹשְׁבִים עַל פֶּתַח הַגֵּיהִנֹּם. וּמִי הֵם? אֲחֵיהֶם שֶׁהֵם שֶׁיּוֹשְׁבִים בְּשַׁעֲרֵי הַגֵּיהִנֹּם. וְעַל כֵּן הַשִּׁירָה הַזֹּאת נֶאֱמֶרֶת בְּיוֹם שֵׁנִי. קָרַבְתִּי אֲלֵיהֶם וְאָמַרְתִּי לָהֶם: מָה עִסְקֵיכֶם בַּמָּקוֹם הַזֶּה? אָמְרוּ: סוֹחֲרִים אֲנַחְנוּ, וּשְׁנֵי יָמִים בַּשָּׁבוּעַ אָנוּ בְּדֵלִים מֵהַיִּשּׁוּב וְעוֹסְקִים בַּתּוֹרָה, כִּי לֹא עוֹזְבִים אוֹתָנוּ בְּנֵי אָדָם כָּל יוֹם וָיוֹם. אָמַרְתִּי: אַשְׁרֵי חֶלְקְכֶם.</p>\n<p>עוֹד פָּתְחוּ וְאָמְרוּ, בְּכָל זְמַן שֶׁצַּדִּיקִים מִסְתַּלְּקִים מִן הָעוֹלָם, הַדִּין מִסְתַּלֵּק מִן הָעוֹלָם, וּמִיתַת הַצַּדִּיקִים מְכַפֶּרֶת עַל חֲטָאֵי הַדּוֹר. וְלָכֵן פָּרָשַׁת בְּנֵי אַהֲרֹן קוֹרְאִים אוֹתָהּ בְּיוֹם הַכִּפּוּרִים שֶׁתִּהְיֶה כַּפָּרָה עַל חֲטָאֵי יִשְׂרָאֵל. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא: הִתְעַסְּקוּ בְמִיתַת הַצַּדִּיקִים הַלָּלוּ, וְיֵחָשֵׁב לָכֶם כְּאִלּוּ אַתֶּם מַקְרִיבִים קָרְבָּנוֹת בַּיּוֹם הַזֶּה לְכַפֵּר עֲלֵיכֶם. שֶׁשָּׁנִינוּ, כָּל זְמַן שֶׁיִּשְׂרָאֵל יִהְיוּ בַגָּלוּת וְלֹא יַקְרִיבוּ קָרְבָּנוֹת בַּיּוֹם הַזֶּה, וְאֶת אוֹתָם שְׁנֵי שְׂעִירִים לֹא יְכוֹלִים לְהַקְרִיב, יִהְיֶה לָהֶם זִכָּרוֹן שֶׁל שְׁנֵי בְּנֵי אַהֲרֹן, וְיִתְכַּפֵּר עֲלֵיהֶם.</p>\n<p>שֶׁכָּךָ לָמַדְתִּי, שֶׁכָּתוּב (במדבר ג) וְאֵלֶּה שְׁמוֹת בְּנֵי אַהֲרֹן הַכֹּהֲנִים וְגוֹ'. וְכָתוּב, הַבְּכֹר נָדָב וַאֲבִיהוּא אֶלְעָזָר וְאִיתָמָר. וְאֶלְעָזָר וְאִיתָמָר הָיָה צָרִיךְ לִהְיוֹת! מַה זֶּה אֶלְעָזָר וְאִיתָמָר? אֶלָּא שָׁקוּל הָיָה אֲבִיהוּא כִּשְׁנֵי אֶחָיו, וְנָדָב כְּמוֹ כֻלָּם.</p>\n<p>וְיִשִׁ שֶׁשּׁוֹנִים (אתזההפוך), הַבְּכֹר נָדָב - זֶה לְבַדּוֹ, וַאֲבִיהוּא - לְבַדּוֹ, וְכָל אֶחָד נֶחְשָׁב בְּעֵינָיו כִּשְׁנֵיהֶם, כְּמוֹ אֶלְעָזָר וְאִיתָמָר. אֲבָל נָדָב וַאֲבִיהוּא לְבַדָּם שְׁקוּלִים הָיוּ כְּנֶגֶד שִׁבְעִים סַנְהֶדְרִין, שֶׁהָיוּ מְשַׁמְּשִׁים לִפְנֵי מֹשֶׁה. וּמִשּׁוּם כָּךְ מִיתָתָם מְכַפֶּרֶת עַל יִשְׂרָאֵל. וְעַל זֶה כָּתוּב, (ויקרא י) וַאֲחֵיכֶם כָּל בֵּית יִשְׂרָאֵל יִבְכּוּ אֶת הַשְּׂרֵפָה. וְאָמַר רַבִּי שִׁמְעוֹן, הַבְּכֹר נָדָב - כְּלוֹמַר, אוֹתוֹ שֶׁכָּל הַשֶּׁבַח וְהַכָּבוֹד שֶׁלּוֹ (מה שמו). נָדָב וַאֲבִיהוּא, עַל אַחַת כַּמָּה וְכַמָּה, שֶׁשְּׁנֵי אֵלֶּה לֹא נִמְצְאוּ כְמוֹתָם בְּיִשְׂרָאֵל.</p>"],[9522012090,"<p>וַיְדַבֵּר ה' אֶל מֹשֶׁה אַחֲרֵי מוֹת שְׁנֵי בְּנֵי אַהֲרֹן. רַבִּי חִזְקִיָּה פָּתַח וְאָמַר, (ישעיה כט) לָכֵן כֹּה אָמַר ה' אֶל בֵּית יַעֲקֹב אֲשֶׁר פָּדָה אֶת אַבְרָהָם וְגוֹ'. פָּסוּק זֶה הוּא קָשֶׁה. לָכֵן כֹּה אָמַר ה' אֲשֶׁר פָּדָה אֶת אַבְרָהָם הָיָה צָרִיךְ לִהְיוֹת! מַה זֶּה כֹּה אָמַר ה' אֶל בֵּית יַעֲקֹב אֲשֶׁר פָּדָה אֶת אַבְרָהָם?</p>\n<p>אֶלָּא הֲרֵי פֵּרְשׁוּהָ וַהֲרֵי נִתְבָּאֵר, שֶׁיַּעֲקֹב פָּדָה אֶת אַבְרָהָם וַדַּאי. שֶׁבְּאוֹתָהּ הַשָּׁעָה שֶׁנָּפַל בְּתוֹךְ אֵשׁ הַכַּשְׂדִּים, דָּנוּ דִינוֹ (ס\"י ואמרו לפני הקדוש ברוך הוא', בשביל מה זה ינצל, ' זכות אבות אין לו, אמר להם, שינצל בשביל בניו, שכך שנינו, הבן מזכה את האב). אָמְרוּ: הֲרֵי יִשְׁמָעֵאל שֶׁיֵּצֵא מִמֶּנּוּ. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא: הֲרֵי יִצְחָק שֶׁיּוֹשִׁיט צַוָּארוֹ עַל גַּבֵּי הַמִּזְבֵּחַ. אָמְרוּ: הֲרֵי עֵשָׂו שֶׁיֵּצֵא מִמֶּנּוּ. אָמַר: הֲרֵי יַעֲקֹב שֶׁהוּא כִּסֵּא שָׁלֵם וְכָל בָּנָיו שְׁלֵמִים לְפָנַי. אָמְרוּ: הֲרֵי וַדַּאי בִּזְכוּתוֹ שֶׁל זֶה יִנָּצֵל אַבְרָהָם. זֶהוּ שֶׁכָּתוּב, אֲשֶׁר פָּדָה אֶת אַבְרָהָם.</p>\n<p>לֹא עַתָּה יֵבוֹשׁ יַעֲקֹב וְלֹא עַתָּה פָּנָיו יֶחֱוָרוּ כִּי בִרְאוֹתוֹ יְלָדָיו מַעֲשֵׂה יָדַי בְּקִרְבּוֹ יַקְדִּישׁוּ שְׁמִי. מִי הֵם יְלָדָיו מַעֲשֵׂה וְגוֹ'? אֶלָּא הֵם חֲנַנְיָה מִישָׁאֵל וַעֲזַרְיָה שֶׁהִפִּילוּ עַצְמָם לְתוֹךְ כִּבְשַׁן הָאֵשׁ לְקַדֵּשׁ אֶת שְׁמוֹ. לֹא עַתָּה יֵבוֹשׁ יַעֲקֹב, מָה עוֹשֶׂה כָּאן יַעֲקֹב? וַהֲרֵי כָּתוּב (דניאל א) וַיְהִי בָהֶם מִבְּנֵי יְהוּדָה דָּנִיֵּאל חֲנַנְיָה מִישָׁאֵל וַעֲזַרְיָה. בְּנֵי יְהוּדָה נִקְרְאוּ, וּמִשּׁוּם כָּךְ לֹא עַתָּה יֵבוֹשׁ יְהוּדָה הָיָה צָרִיךְ לִהְיוֹת, מַה זֶּה לֹא עַתָּה יֵבוֹשׁ יַעֲקֹב?</p>\n<p>אֶלָּא כָּךְ שָׁנִינוּ, בְּשָׁעָה הַזּוֹ שֶׁנִּכְפְּתוּ לִפֹּל בָּאֵשׁ, כָּל אֶחָד הֵרִים קוֹלוֹ וְאָמַר אֶל כָּל אוֹתָם עַמִּים וּמְלָכִים וְשָׂרִים. חֲנַנְיָה אָמַר, (תהלים קיח) ה' לִי לֹא אִירָא מַה יַּעֲשֶׂה לִי אָדָם ה' לִי בְּעֹזְרָי וַאֲנִי אֶרְאֶה בְשׂנְאָי טוֹב לַחֲסוֹת בַּה' וְגוֹ'. מִישָׁאֵל פָּתַח וְאָמַר, (ירמיה ל) וְאַתָּה אַל תִּירָא עַבְדִּי יַעֲקֹב נְאֻם ה' וְגוֹ' כִּי אִתְּךְ אֲנִי נְאֻם ה' לְהוֹשִׁיעֶךְ כִּי אֶעֱשֶׂה וְגוֹ'. בְּאוֹתָהּ שָׁעָה שֶׁשָּׁמְעוּ כֻלָּם אֶת שֵׁם יַעֲקֹב, תָּמְהוּ וְצָחֲקוּ בְּלֵיצָנוּת. עֲזַרְיָה פָּתַח וְאָמַר, (דברים ו) שְׁמַע יִשְׂרָאֵל ה' אֱלֹהֵינוּ ה' אֶחָד.</p>\n<p>זְהִוּ שֶׁכָּתוּב, (ישעיה מד) זֶה יֹאמַר לַה' אָנִי וְגוֹ'. זֶה יֹאמַר לַה' אָנִי - זֶה חֲנַנְיָה. וְזֶה יִקְרָא בְשֵׁם יַעֲקֹב - זֶה מִישָׁאֵל. וְזֶה יִכְתֹּב יָדוֹ לַה' וּבְשֵׁם יִשְׂרָאֵל יְכַנֶּה - זֶה עֲזַרְיָה. בְּאוֹתָהּ שָׁעָה כִּנֵּס הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הַפָּמַלְיָא שֶׁלּוֹ, וְאָמַר לָהֶם: בְּאֵיזֶה דִבּוּר מֵאוֹתָם הַדִּבּוּרִים שֶׁאָמְרוּ אֵלֶּה הַשְּׁלֹשָׁה אַצִּיל אוֹתָם? פָּתְחוּ וְאָמְרוּ, (תהלים סג) וְיֵדְעוּ כִּי אַתָּה שִׁמְךְ ה' לְבַדֶּךְ עֶלְיוֹן עַל כָּל הָאָרֶץ.</p>\n<p>בְּאוֹתָהּ שָׁעָה אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לַכִּסֵּא: כִּסֵּא שֶׁלִּי, בְּאֵיזֶה דִבּוּר מֵאוֹתָם הַדִּבּוּרִים אַצִּיל אֶת אוֹתָם הַצַּדִּיקִים? אָמַר לוֹ: בְּאוֹתוֹ הַדִּבּוּר שֶׁכֻּלָּם צָחֲקוּ עָלָיו אַצִּיל אוֹתָם, לֹא עַתָּה יֵבוֹשׁ יַעֲקֹב וְלֹא עַתָּה פָּנָיו יֶחֱוָרוּ. כְּמוֹ שֶׁעָמַד יַעֲקֹב אֵצֶל אַבְרָהָם בָּאֵשׁ, יָקוּם עַכְשָׁו אֵצֶל אֵלֶּה. זֶהוּ שֶׁכָּתוּב, כֹּה אָמַר ה' אֶל בֵּית יַעֲקֹב אֲשֶׁר פָּדָה אֶת אַבְרָהָם לֹא עַתָּה יֵבוֹשׁ יַעֲקֹב וְגוֹ'. מֵהַבּוּשָׁה שֶׁל הַלֵּיצָנוּת.</p>\n<p>שָׁנִינוּ, כָּל אוֹתָם שֶׁצָּחֲקוּ מֵהַדִּבּוּר הַזֶּה, נִשְׂרְפוּ בְּאוֹתָהּ אֵשׁ, וְהָרַג אוֹתָם שְׁבִיב שֶׁל אֵשׁ. מַה הִצִּיל אֶת אֵלֶּה? עַל שֶׁהָיוּ מִתְפַּלְלִים לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וּמְיַחֲדִים שְׁמוֹ כָּרָאוּי, וְעַל שֶׁמְּיַחֲדִים שְׁמוֹ כָּרָאוּי, נִצְּלוּ מֵאוֹתָהּ אֵשׁ יוֹקֶדֶת.</p>"],[9522012091,"<p>שְׁנֵי בְּנֵי אַהֲרֹן הִקְרִיבוּ אֵשׁ זָרָה, שֶׁלֹּא יִחֲדוּ אֶל שְׁמוֹ כָּרָאוּי וְנִשְׂרְפוּ בָאֵשׁ. רַבִּי יִצְחָק אָמַר, כָּתוּב אַחֲרֵי מוֹת, וְכָתוּב וַיָּמֻתוּ. כֵּיוָן שֶׁאָמַר אַחֲרֵי מוֹת שְׁנֵי בְּנֵי אַהֲרֹן, לֹא יָדַעְנוּ שֶׁהֲרֵי וַיָּמֻתוּ? אֶלָּא כָּךְ שָׁנִינוּ, שְׁתֵּי מִיתוֹת הָיוּ, אַחַת לִפְנֵי ה', וְאַחַת שֶׁלֹּא הָיוּ לָהֶם בָּנִים. שֶׁכָּל מִי שֶׁלֹּא זוֹכֶה לְבָנִים, הוּא מֵת. מִשּׁוּם כָּךְ, אַחֲרֵי מוֹת, וַיָּמֻתוּ.</p>\n<p>רַבִּי אַבָּא אָמַר, מַה שֶּׁכָּתוּב (במדבר ג) וַיָּמָת נָדָב וַאֲבִיהוּא לִפְנֵי ה' בְּהַקְרִבָם אֵשׁ זָרָה לִפְנֵי ה' בְּמִדְבַּר סִינַי וּבָנִים לֹא הָיוּ לָהֶם וַיְכַהֵן אֶלְעָזָר וְאִיתָמָר. מַה זֶּה לְגַבֵּי זֶה, שֶׁכָּתוּב וּבָנִים לֹא הָיוּ לָהֶם וַיְכַהֵן אֶלְעָזָר וְאִיתָמָר? אֶלָּא סוֹד הַדָּבָר - זֶה שֶׁאָמַרְתִּי, וַיָּמֻתוּ, שֶׁלֹּא הָיוּ לָהֶם בָּנִים. וְכָךְ זֶה וַדַּאי. אֲבָל לֹא כִּשְׁאָר בְּנֵי הָעוֹלָם, אַף עַל גַּב שֶׁלֹּא נִשְּׂאוּ, שֶׁהֲרֵי אֵלּוּ לֹא מֵתוּ אֶלָּא מִיתַת עַצְמָם, אֲבָל מִיתַת נַפְשָׁם לֹא מֵתוּ.</p>\n<p>מִנַּיִן לָנוּ? שֶׁכָּתוּב (שמות ו) וְאֶלְעָזָר בֶּן אַהֲרֹן לָקַח לוֹ מִבְּנוֹת פּוּטִיאֵל לוֹ לְאִשָּׁה וַתֵּלֶד לוֹ אֶת פִּינְחָס אֵלֶּה רָאשֵׁי אֲבוֹת הַלְוִיִּם לְמִשְׁפְּחֹתָם. אֵלֶּה, וַהֲרֵי פִּנְחָס לְבַדּוֹ הָיָה, וְכָתוּב רָאשֵׁי אֲבוֹת הַלְוִיִּם. מִשּׁוּם כָּךְ מֵתוּ מִיתַת עַצְמָם, וּמִיתַת נַפְשָׁם לֹא מֵתוּ. אָמַר רַבִּי אֶלְעָזָר, וַדַּאי מַשְׁמָע אֵלֶּה, וּמַשְׁמָע רָאשֵׁי.</p>\n<p>וּמִשּׁוּם כָּךְ כָּתוּב, (במדבר כה) פִּינְחָס בֶּן אֶלְעָזָר בֶּן אַהֲרֹן הַכֹּהֵן, וְכָתוּב וּפִינְחָס בֶּן אֶלְעָזָר בֶּן אַהֲרֹן הַכֹּהֵן הָיָה כֹּהֵן בַּיָּמִים הָהֵם. פִּנְחָס בֶּן אֶלְעָזָר הַכֹּהֵן הָיָה צָרִיךְ לִהְיוֹת! אֶלָּא בְּכָל מָקוֹם שֶׁבָּא פִּנְחָס, בֶּן אַהֲרֹן הַכֹּהֵן כָּתוּב. וְאֶלְעָזָר לֹא כָתוּב, אֶלָּא אֶלְעָזָר הַכֹּהֵן, שֶׁכָּתוּב (שם כז) וְלִפְנֵי אֶלְעָזָר הַכֹּהֵן. (שם לא) וַיֹּאמֶר אֶלְעָזָר הַכֹּהֵן וְגוֹ'. וְעַל כֵּן מִיתַת עַצְמָם מֵתוּ, וּמִיתַת נַפְשָׁם לֹא מֵתוּ.</p>\n<p>וְשָׁנִינוּ בְּסוֹד הַמִּשְׁנָה, שְׁנַיִם זוּג - פֶּן חָס. וַהֲרֵי נִתְבָּאֵר, יוֹ\"ד קְטַנָּה בֵּין אוֹתִיּוֹת פִּנְחָס, שֶׁהֲרֵי יוֹ\"ד כּוֹלֶלֶת שְׁנַיִם כְּאֶחָד, וְזֶהוּ סוֹד הַדָּבָר, וְזֶה נִתְבָּאֵר.</p>\n<p>רַבִּי אֶלְעָזָר שָׁאַל אֶת אָבִיו וְאָמַר לוֹ, וַהֲרֵי שְׁנַיִם הֵם וּשְׁנַיִם הָיוּ, לָמָּה לֹא נִמְצְאוּ שְׁנַיִם? אָמַר לוֹ, שְׁנֵי חֲצָאֵי גוּף הָיוּ, שֶׁהֲרֵי לֹא נִשְּׂאוּ, וּמִשּׁוּם כָּךְ הֵם נִכְלְלוּ בְאֶחָד, שֶׁכָּתוּב וַתֵּלֶד לוֹ אֶת פִּינְחָס אֵלֶּה רָאשֵׁי וְגוֹ'.</p>\n<p>וְיוֹ\"ד שֶׁל פִּנְחָס לֹא נִתַּן בָּהּ לְחַבֵּר הָאוֹתִיּוֹת, אֶלָּא בְּשָׁעָה שֶׁקִּנֵּא לַקָּדוֹשׁ בָּרוּךְ הוּא וּבָא לְיַשֵּׁר אֶת הֶעָקֹם, שֶׁרָאָה אֶת אוֹת הַבְּרִית הַקְּדוֹשָׁה הַזּוֹ שֶׁהִכְנִיס זִמְרִי לְרָשׁוּת אַחֶרֶת, וּבְמַה שֶּׁהִתְעַקֵּם בָּרִאשׁוֹנָה הִתְתַּקֵּן כָּאן. בְּנָכְרִיָּה הִתְעַקְּמוּ בַהַתְחָלָה, שֶׁכָּתוּב בְּהַקְרִיבָם אֵשׁ זָרָה, וְכָאן בְּנָכְרִיָּה הִתְתַּקְּנוּ, כְּמוֹ שֶׁכָּתוּב וּבָעַל בַּת אֵל נֵכָר. מַה לְּהָלְאָה אֵשׁ זָרָה, אַף כָּאן גַּם אִשָּׁה זָרָה.</p>\n<p>מַה נִּרְאֶה כָּאן? אֶלָּא בַּהַתְחָלָה הִקְרִיבוּ אֶת הָרְחוֹקָה, שֶׁכָּתוּב בְּהַקְרִבָם אֵשׁ זָרָה. אַף כָּאן זִמְרִי הָיָה מַקְרִיב אֶת הָרְחוֹקָה, אֶת שֵׁם הַמֶּלֶךְ הָיָה מְקָרֵב לָרְחוֹקָה, מִיָּד - (שם כה) וַיַּרְא פִּינְחָס בֶּן אֶלְעָזָר בֶּן אַהֲרֹן הַכֹּהֵן וַיָּקָם מִתּוֹךְ הָעֵדָה. כָּאן תִּקֵּן אֶת הֶעָקֹם שֶׁבָּרִאשׁוֹנָה, וְאָז נִתְּנָה יוֹ\"ד לִשְׁמוֹ לְחַבֵּר אֶת הָאוֹתִיּוֹת כְּאֶחָד וְהִתְבַּשֵּׂר בְּשָׁלוֹם, שֶׁכָּתוּב לָכֵן אֱמֹר הִנְנִי נֹתֵן לוֹ אֶת בְּרִיתִי שָׁלוֹם. (בריתי ממש).</p>\n<p>מָה הַשָּׁלוֹם כָּאן? אֶלָּא בְּאוֹתוֹ הַכֶּתֶר חָטְאוּ בַתְּחִלָּה, בְּאוֹתוֹ הַכֶּתֶר הֵעִירוּ קְטָטָה בַּתְּחִלָּה, וְעַכְשָׁו שֶׁתֻּקַּן, כָּתוּב הִנְנִי נֹתֵן לוֹ אֶת בְּרִיתִי שָׁלוֹם, בְּרִיתִי מַמָּשׁ תִּהְיֶה עִמּוֹ בְשָׁלוֹם, וּמִשּׁוּם כָּךְ נִתְּנָה יוֹ\"ד קְטַנָּה בִּשְׁמוֹ, שֶׁהֲרֵי הִיא מֵהָאוֹתִיּוֹת הַקְּטַנּוֹת, לְהַרְאוֹת שֶׁהֲרֵי תֻּקַּן מַה שֶּׁהִתְעַקֵּם בַּתְּחִלָּה, וַהֲרֵי הִשְׁלִימָה עִמּוֹ. בָּא רַבִּי אֶלעָזָר וְנָשַׁק יָדוֹ וְאָמַר, בָּרוּךְ הָרַחֲמָן שֶׁשָּׁאַלְתִּי דָבָר זֶה וְלֹא אָבַד מִמֶּנִּי.</p>\n<p>שָׁנִינוּ, אָמַר רַבִּי יוֹסֵי, בְּיוֹם הַכִּפּוּרִים הַזֶּה תִּקְּנוּ לִקְרֹא פָּרָשָׁה זוֹ, לְכַפֵּר עַל יִשְׂרָאֵל בַּגָּלוּת, בִּשְׁבִיל זֶה סֵדֶר הַיּוֹם הַזֶּה כָּאן הִסְתַּדֵּר, וּמִשּׁוּם שֶׁמִּיתַת בְּנֵי אַהֲרֹן מְכַפֶּרֶת עַל יִשְׂרָאֵל.</p>\n<p>מִכָּאן לָמַדְנוּ, כָּל אוֹתוֹ בֶּן אָדָם שֶׁיִּסּוּרֵי רִבּוֹנוֹ בָּאִים עָלָיו - כַּפָּרַת חֲטָאָיו הֵם. וְכָל מִי שֶׁמִּצְטַעֵר עַל יִסּוּרֵי הַצַּדִּיקִים, מַעֲבִירִים חֲטָאֵיהֶם מִן הָעוֹלָם. וְעַל כֵּן בַּיּוֹם הַזֶּה קוֹרְאִים אַחֲרֵי מוֹת שְׁנֵי בְּנֵי אַהֲרֹן, שֶׁיִּשְׁמְעוּ הָעָם וְיִצְטַעֲרוּ עַל אָבְדַן הַצַּדִּיקִים, וְיִתְכַּפְּרוּ לָהֶם חֲטָאֵיהֶם. וְכָל מִי שֶׁמִּצְטַעֵר עַל אָבְדָנָם שֶׁל הַצַּדִּיקִים אוֹ מוֹרִיד עֲלֵיהֶם דְּמָעוֹת, הַקָּדוֹשׁ בָּרוּךְ הוּא מַכְרִיז עָלָיו וְאוֹמֵר: (ישעיה ו) וְסָר עֲוֹנֶךְ וְחַטָּאתְךְ תְּכֻפָּר. וְלֹא עוֹד, אֶלָּא שֶׁלֹּא יָמוּתוּ בָנָיו בְּיָמָיו. וְעָלָיו כָּתוּב, (שם נג) יִרְאֶה זֶרַע יַאֲרִיךְ יָמִים וְגוֹ'.</p>"],[9522012092,"<p>וַיֹּאמֶר ה' אֶל מֹשֶׁה דַּבֵּר אֶל אַהֲרֹן אָחִיךְ וְאַל יָבֹא בְעֵת עֵת אֶל הַקֹּדֶשׁ וְגוֹ'. רַבִּי שִׁמְעוֹן פָּתַח וְאָמַר, (קהלת א) כָּל הַנְּחָלִים הֹלְכִים אֶל הַיָּם וְהַיָּם אֵינֶנּוּ מָלֵא וְגוֹ'. אָמַר רַבִּי שִׁמְעוֹן, תְּמֵהַנִי עַל בְּנֵי הָעוֹלָם, שֶׁהֲרֵי אֵין לָהֶם עֵינַיִם לִרְאוֹת וְלֵב לְהַשְׁגִּיחַ, וְלֹא יוֹדְעִים וְלֹא שָׂמִים לִבָּם לְהִסְתַּכֵּל עַל רְצוֹן רִבּוֹנָם, אֵיךְ יְשֵׁנִים וְלֹא מִתְעוֹרְרִים מִשְּׁנָתָם טֶרֶם יָבֹא אוֹתוֹ הַיּוֹם שֶׁחֹשֶׁךְ וַאֲפֵלָה יְכַסּוּ עֲלֵיהֶם, וְיִתְבַּע אוֹתוֹ בַּעַל הַפִּקָּדוֹן מֵהֶם חֶשְׁבּוֹן.</p>\n<p>וְהַכָּרוֹז בְּכָל יוֹם קוֹרֵא עֲלֵיהֶם, וְנִשְׁמָתָם מְעִידָה בָהֶם בְּכָל יוֹם וָלַיְלָה, הַתּוֹרָה מְרִימָה קוֹלוֹת לְכָל עֵבֶר, מַכְרִיזָה וְאוֹמֶרֶת: (משליא) עַד מָתַי פְּתָיִם תְּאֵהֲבוּ פֶתִי. (שם ט) מִי פֶתִי יָסֻר הֵנָּה חֲסַר לֵב אָמְרָה לּוֹ לְכוּ לַחֲמוּ בְלַחְמִי וּשְׁתוּ בְּיַיִן מָסָכְתִּי. וְאֵין מִי שֶׁיַּרְכִּין אָזְנוֹ וְאֵין מִי שֶׁיָּעִיר אֶת לִבּוֹ.</p>\n<p>בֹּא רְאֵה, עֲתִידִים הַדּוֹרוֹת הָאַחֲרוֹנִים שֶׁיָּבאוּ שֶׁתִּשָּׁכַח תּוֹרָה מִבֵּינֵיהֶם, וְחַכְמֵי הַלֵּב יִתְכַּנְּסוּ לִמְקוֹמָם (לחדרקדוש), וְלֹא יִמָּצֵא מִי שֶׁסּוֹגֵר וּפוֹתֵחַ. אוֹי לְאוֹתוֹ הַדּוֹר! וּמִכָּאן וָהָלְאָה לֹא יִהְיֶה דוֹר כְּמוֹ הַדּוֹר הַזֶּה, עַד הַדּוֹר שֶׁיָּבֹא מֶלֶךְ הַמָּשִׁיחַ, וְהַדֵּעָה תִתְעוֹרֵר בָּעוֹלָם, שֶׁכָּתוּב (ירמיה לא) כִּי כֻלָּם יֵדְעוּ אוֹתִי לְמִקְּטַנָּם וְעַד גְּדוֹלָם.</p>\n<p>בֹּא רְאֵה, כָּתוּב (בראשית ב) וְנָהָר יֹצֵא מֵעֵדֶן. וְשָׁנִינוּ, מַה שְּׁמוֹ שֶׁל אוֹתוֹ נָהָר? בֵּאַרְנוּ שֶׁשְּׁמוֹ יוּבַל, שֶׁכָּתוּב (ירמיה טז) וְעַל יוּבַל יְשַׁלַּח שָׁרָשָׁיו. וּבְסִפְרוֹ שֶׁל רַב הַמְנוּנָא סָבָא: חַיִּים שְׁמוֹ, שֶׁמִּשָּׁם יוֹצְאִים חַיִּים לָעוֹלָם, וְהֵם נִקְרָאִים חַיֵּי הַמֶּלֶךְ. וַהֲרֵי בֵּאַרְנוּ, אוֹתוֹ עֵץ גָּדוֹל וְחָזָק שֶׁבּוֹ יֵשׁ מָזוֹן לַכֹּל נִקְרָא עֵץ הַחַיִים. הָאִילָן שֶׁנָּטַע שָׁרָשָׁיו בְּאוֹתָם הַחַיִּים, וְהַכֹּל הוּא נָאֶה.</p>\n<p>וְשָׁנִינוּ, אוֹתוֹ הַנָּהָר הוֹצִיא נְחָלִים עֲמֻקִּים בְּשֶׁמֶן הַמִּשְׁחָה, לְהַשְׁקוֹת אֶת הַגָּן וּלְהַרְווֹת עֵצִים וּנְטִיעוֹת, שֶׁכָּתוּב (תהלים קד) יִשְׂבְּעוּ עֲצֵי ה' אַרְזֵי לְבָנוֹן אֲשֶׁר נָטָע. וְאוֹתָם הַנְּחָלִים שׁוֹפְעִים וְנִמְשָׁכִים וּמִתְכַּנְּסִים לִשְׁנֵי עַמּוּדִים, וְאוֹתָן בָּרַיְתוֹת (שתים) קוֹרְאִים לָהֶן יָכִי\"ן וּבוֹעַ\"ז, וְיָפֶה. וּמִשּׁוּם יוֹצְאִים כָּל אוֹתָם נְחָלִים, וּמַשְׁרִים אוֹתָם בְּדַרְגָּה אַחַת שֶׁנִּקְרֵאת צַדִּיק, שֶׁכָּתוּב (משלי י) וְצַדִּיק יְסוֹד עוֹלָם. וְכֻלָּם הוֹלְכִים וּמִתְכַּנְּסִים לְאוֹתוֹ מָקוֹם שֶׁנִּקְרָא יָם, וְהוּא יָם הַחָכְמָה. זֶהוּ שֶׁכָּתוּב (קהלת א) כָּל הַנְּחָלִים הֹלְכִים אֶל הַיָּם וְגוֹ'.</p>\n<p>וְאִם תֹּאמַר שֶׁהֲרֵי מַגִּיעִים לַמָּקוֹם הַזֶּה וְלֹא שָׁבִים - כָּתוּב אַחַר כָּךְ, אֶל מְקוֹם שֶׁהַנְּחָלִים הֹלְכִים שָׁם הֵם שָׁבִים לָלָכֶת, מִשּׁוּם שֶׁאוֹתוֹ נָהָר לֹא פוֹסֵק לְעוֹלָמִים. הֵם שָׁבִים, לְאֵיזֶה מָקוֹם הֵם שָׁבִים? לְאוֹתָם שְׁנֵי עַמּוּדִים, נֵצַח וְהוֹד. לָלָכֶת, בַּצַּדִּיק הַזֶּה, לִמְצֹא בְּרָכוֹת וְשִׂמְחָה. וְזֶהוּ הַסּוֹד שֶׁשָּׁנִינוּ, (תהלים קד) לִוְיָתָן זֶה יָצַרְתָּ לְשַׂחֶק בּוֹ, זֶה צַדִּיק.</p>\n<p>כֻּלָּם אֵלֶיךְ יְשַׂבֵּרוּן לָתֵת אָכְלָם בְּעִתּוֹ. מִי זוֹ עִתּוֹ? (זו עתו של צדיק) זוֹ הַגְּבִירָה, שֶׁנִּקְרֵאת עִתּוֹ שֶׁל צַדִּיק, וּמִשּׁוּם כָּךְ כֻּלָּם מְחַכִּים לָעִתּוֹ הַזּוֹ. כָּל אֵלּוּ שֶׁנִּזּוֹנִים לְמַטָּה, מִמָּקוֹם זֶה נִזּוֹנִים, וְסוֹד זֶה בֵּאַרְנוּ, (שם קמה) עֵינֵי כֹל אֵלֶיךְ יְשַׂבֵּרוּ וְגוֹ', כְּמוֹ שֶׁבֵּאַרְנוּ.</p>\n<p>בֹּא רְאֵה, בְּשָׁעָה שֶׁהַכֹּל הַזֶּה מְבַשֵּׂם אֶת עִתּוֹ וּמִתְחַבֵּר עִמּוֹ, אָז כָּל הָעוֹלָמוֹת בְּשִׂמְחָה וְכָל הָעוֹלָמוֹת בִּבְרָכוֹת, אָז נִמְצָא שָׁלוֹם בָּעֶלְיוֹנִים וּבַתַּחְתּוֹנִים, וּכְשֶׁגּוֹרְמִים רִשְׁעֵי הָעוֹלָם שֶׁשָּׁם לֹא נִמְצָאוֹת בְּרָכוֹת שֶׁל אוֹתָם הַנְּחָלִים, וְהָעֵת הַזּוֹ יוֹנֶקֶת מִצַּד הָאַחֵר, אֲזַי מִתְעוֹרְרִים דִּינִים בָּעוֹלָם וְלֹא נִמְצָא שָׁלוֹם. וּכְשֶׁרוֹצִים בְּנֵי הָעוֹלָם לְהִתְבָּרֵךְ, לֹא יְכוֹלִים, אֶלָּא רַק עַל יְדֵי הַכֹּהֵן, כְּדֵי שֶׁיְּעוֹרֵר אֶת הַכֶּתֶר שֶׁלּוֹ וְתִתְבָּרֵךְ הַגְּבִירָה, וְיִמָּצְאוּ בְרָכוֹת בְּכָל הָעוֹלָמוֹת.</p>\n<p>שָׁנִינוּ, בְּאוֹתָהּ שָׁעָה בִּקֵּשׁ מֹשֶׁה מִלִּפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא דָּבָר זֶה. אָמַר לוֹ, אִם בְּנֵי הָעוֹלָם יָשׁוּבוּ לְפָנֶיךְ, עַל יְדֵי מִי מִתְבָּרְכִים? אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, וְלִי אַתָּה אוֹמֵר?! דַּבֵּר אֶל אַהֲרֹן אָחִיךְ, שֶׁהֲרֵי בְּיָדוֹ מְסוּרוֹת הַבְּרָכוֹת לְמַעְלָה וּלְמַטָּה.</p>"],[9522012093,"<p>וַיֹּאמֶר ה' אֶל מֹשֶׁה דַּבֵּר אֶל אַהֲרֹן אָחִיךְ וְאַל יָבֹא בְכָל עֵת אֶל הַקֹּדֶשׁ וְגוֹ'. אָמַר רַבִּי אַבָּא, יֵשׁ זְמַנִּים לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁנִּמְצָאִים רְצוֹנוֹת וְנִמְצָאוֹת בְּרָכוֹת וּלְבַקֵּשׁ בַּקָּשׁוֹת, וְלִפְעָמִים שֶׁאֵין נִמְצָאִים רְצוֹנוֹת, וְאֵין מִזְדַּמְּנוֹת בְּרָכוֹת, וְדִינִים הַקָּשִׁים מִתְעוֹרְרִים בָּעוֹלָם. וְלִפְעָמִים שֶׁהַדִּין תָּלוּי. בֹּא רְאֵה, יֵשׁ בַּשָּׁנָה זְמַנִּים שֶׁנִּמְצָא רָצוֹן, וְיֵשׁ זְמַנִּים בַּשָּׁנָה שֶׁהַדִּין נִמְצָא וְתָלוּי. יֵשׁ זְמַנִּים בֶּחֳדָשִׁים שֶׁהָרָצוֹן נִמְצָא בָהֶם, וְיֵשׁ זְמַנִּים בֶּחֳדָשִׁים שֶׁנִּמְצָאִים דִּינִים, וּתְלוּיִים עַל הַכֹּל.</p>\n<p>יִשִׁ זְמַנִּים בַּשָּׁבוּעוֹת שֶׁרְצוֹנוֹת נִמְצָאִים, וְיֵשׁ זְמַנִּים בַּשָּׁבוּעוֹת שֶׁדִּינִים נִמְצָאִים בָּעוֹלָם. וְיֵשׁ זְמַנִּים בַּיָּמִים שֶׁנִּמְצָא רָצוֹן בָּעוֹלָם וְהָעוֹלָם מִתְבַּשֵּׂם. וְיֵשׁ זְמַנִּים בַּיָּמִים שֶׁהַדִּינִים תְּלוּיִים וְנִמְצָאִים, וַאֲפִלּוּ בְּשָׁעוֹת, וְעַל זֶה כָּתוּב (קהלת ג) וְעֵת לְכָל חֵפֶץ וְגוֹ'. וְכָתוּב (תהלים סט) וַאֲנִי תְפִלָּתִי לְךְ וְגוֹ'. וְכָתוּב (ישעיה נח) דִּרְשׁוּ ה' בְּהִמָּצְאוֹ. וְכָתוּב (תהלים י) לָמָה ה' תַּעֲמֹד בְּרָחוֹק תַּעְלִים לְעִתּוֹת בַּצָּרָה. וְכָתוּב (ירמיה לא) מֵרָחוֹק ה' נִרְאָה לִי. וְלִפְעָמִים שֶׁהוּא קָרוֹב, שֶׁכָּתוּב (תהלים קמה) קָרוֹב ה' לְכָל קֹרְאָיו. מִשּׁוּם כָּךְ, וְאַל יָבֹא בְכָל עֵת אֶל הַקֹּדֶשׁ וְגוֹ'.</p>\n<p>רַבִּי שִׁמְעוֹן אָמַר, הֲרֵי בֵּאַרְנוּ הַדָּבָר בְּעִתּוֹ, וְכָךְ הוּא וַדַּאי, וְכָאן הַקָּדוֹשׁ בָּרוּךְ הוּא בָּא לְהַזְהִיר אֶת אַהֲרֹן שֶׁלֹּא יִטְעֶה בְּאוֹתוֹ חֵטְא שֶׁטָּעוּ בָנָיו, שֶׁהֲרֵי הָעֵת הַזּוֹ יְדוּעָה, כְּדֵי שֶׁלֹּא יִטְעֶה לְחַבֵּר עֵת אַחֶרֶת לַמֶּלֶךְ. זֶהוּ שֶׁכָּתוּב וְאַל יָבֹא בְכָל עֵת אֶל הַקֹּדֶשׁ. כְּלוֹמַר, אַף עַל גַּב שֶׁיֵּרָאֶה זְמַן שֶׁנִּמְסָר לְיַד אַחֵר לְהַנְהִיג אֶת הָעוֹלָם וְיִמָּסֵר בְּיָדוֹ לְיַחֵד בּוֹ לְקָרְבוֹ לַקֹּדֶשׁ, שֶׁהֲרֵי אֲנִי וּשְׁמִי אֶחָד הוּא. וּמִשּׁוּם כָּךְ, (לקרב אותו להקדוש ברוך הוא, שהרי העת הזו ידועה. משום כך) וְאַל יָבא בְכָל עֵת אֶל הַקֹּדֶשׁ. וְאִם רוֹצֶה לָדַעַת בַּמֶּה יִכָּנֵס - בְּזֹּאת. בְּזֹּאת יָבֹא אַהֲרֹן אֶל הַקֹּדֶשׁ. שֶׁהַזֹּאת הַזּוֹ הִיא עֵת שֶׁאֲחוּזָה בִשְׁמִי, בַּי' הַזּוֹ שֶׁרְשׁוּמָה בִשְׁמִי יִכָּנֵס אֶל הַקֹּדֶשׁ, (אבל) וְאַל יָבֹא בְכָל עֵת.</p>\n<p>שָׁנִינוּ, אָמַר רַבִּי יוֹסֵי, כָּתוּב (קהלת ג) אֶת הַכֹּל עָשָׂה יָפֶה בְעִתּוֹ. דָּבָר זֶה בֵּאֲרוֹ הַמְּנוֹרָה (בשם) הַקְּדוֹשָׁה, וְכָךְ הוּא שֶׁשָּׁנִינוּ, אֶת הַכֹּל עָשָׂה יָפֶה בְעִתּוֹ, וְכָךְ הוּא וַדַּאי. אֶת הַכֹּל וַדַּאי. עָשָׂה יָפֶה בְעִתּוֹ, זֶה עִם זֶה, שֶׁלֹּא יִתְעָרְבוּ אֲחֵרִים בֵּינֵיהֶם. בְעִתּוֹ מַמָּשׁ, וְלֹא בְאַחֵר. מִשּׁוּם כָּךְ אַזְהָרָה לְאַהֲרֹן, וְאַל יָבא בְכָל עֵת אֶל הַקֹּדֶשׁ. אֲבָל בַּמֶּה יִכָּנֵס? בְּזֹּאת, כְּמוֹ שֶׁבֵּאַרְנוּ, שֶׁכָּתוּב בְּזֹּאת יָבֹא אַהֲרֹן אֶל הַקֹּדֶשׁ.</p>\n<p>רַבִּי אֶלְעָזָר הָיָה יוֹשֵׁב לִפְנֵי אָבִיו. אָמַר לוֹ, כָּתוּב בַּעֲדַת קֹרַח, וַיֹּאבְדוּ מִתּוֹךְ הַקָּהָל. מַה זֶּה וַיֹּאבְדוּ? אֶלָּא כְּמוֹ שֶׁכָּתוּב, (במדבר טז) וְהַאֲבַדְתִּי אֶת הַנֶּפֶשׁ הַהִיא מִקֶּרֶב עַמָּהּ. (כתוב בבני אהרן, (שם י) ותצא אש מלפני ה' ותאכל אותם וימתו. וכתוב בעדת קרח, ואש יצאה מאת ה' ותאכל את החמשים ומאתים איש. היעלה בדעתך ששקולים אלה כאלה ?!) אָמַר רַבִּי שִׁמְעוֹן, שׁוֹנִים בְּנֵי אַהֲרֹן, שֶׁלֹּא כָתוּב בָּהֶם אֲבֵדָה כְּאוֹתָם שֶׁל עֲדַת קֹרַח שֶׁכָּתוּב בָּהֶם, וַיֹּאבְדוּ מִתּוֹךְ הַקָּהָל, וְכָתוּב (במדבר יז) הֵן גָּוַעְנוּ אָבַדְנוּ כֻּלָּנוּ אָבָדְנוּ. לְהַכְלִיל אֶת אוֹתָם שֶׁהִקְרִיבוּ קְטֹרֶת בְּשָׂמִים, מָאתַיִם וַחֲמִשִׁים שֶׁאָבְדוּ וַדַּאי, וְאֵלֶּה (נדב ואביהוא) לֹא אָבְדוּ.</p>\n<p>אָמַר לוֹ, כָּתוּב וְאַל יָבֹא בְכָל עֵת אֶל הַקֹּדֶשׁ. וְכָתוּב בְּזֹּאת יָבֹא אַהֲרֹן אֶל הַקֹּדֶשׁ. כֵּיוָן שֶׁאָמַר וְאַל יָבא בְכָל עֵת, לָמָּה לֹא כָתוּב בְּאֵיזֶה זְמַן יִכָּנֵס? אָמַר לוֹ (רבי) אֶלְעָזָר, הֲרֵי נֶאֱמַר, וְדָבָר אֶחָד הוּא, וּזְמַן אֶחָד הוּא שֶׁיָּדְעוּ הַכֹּהֲנִים. אֲבָל עַל מַה שֶּׁחָטְאוּ בָנָיו רָצָה לְהַזְהִיר כָּאן, וַהֲרֵי זֶה נִתְבָּאֵר. אָמַר לוֹ, וַאֲנִי כָּךְ סָבַרְתִּי, וּכְדֵי לְיַשֵּׁב אֶת הַדָּבָר רָצִיתִי.</p>\n<p>אָמַר לוֹ, אֶלְעָזָר בְּנִי, בֹּא רְאֵה, כָּל הַקָּרְבָּנוֹת וְכָל הָעוֹלוֹת נַחַת הֵם לַקָּדוֹשׁ בָּרוּךְ הוּא, אֲבָל לֹא הָיְתָה נַחַת כְּמוֹ הַקְּטֹרֶת הַזּוֹ, שֶׁהַקְּטֹרֶת הִיא מְעֻלָּה מֵהַכֹּל, וּמִשּׁוּם כָּךְ הָיוּ מַכְנִיסִים אוֹתָהּ לִפְנַי וְלִפְנִים בְּלַחַשׁ, וַהֲרֵי זֶה נִתְבָּאֵר. וּמִשּׁוּם כָּךְ לֹא נֶעֶנְשׁוּ כָּל בְּנֵי הָאָדָם בִּשְׁאָר הַקָּרְבָּנוֹת וְהָעוֹלוֹת כְּמוֹ בַּקְּטֹרֶת, שֶׁכָל הָעֲבוֹדָה שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא כָּאן נִקְשְׁרֶת וְנִקְטֶרֶת יוֹתֵר מֵהַכֹּל, וְלָכֵן נִקְרֵאת קְטֹרֶת. וַהֲרֵי נֶאֱמַר, (משלי כז) שֶׁמֶן וּקְטֹרֶת יְשַׂמַּח לֵב.</p>"],[9522012094,"<p>פָּתַח רַבִּי שִׁמְעוֹן וְדָרַשׁ, (שיר א) לְרֵיחַ שְׁמָנֶיךְ טוֹבִים וְגוֹ'. בַּפָּסוּק הַזֶּה הִסְתַּכַּלְתִּי, וְכָךְ הוּא: לְרֵיחַ, מַה זֶּה לְרֵיחַ? רֵיחַ הַקְּטֹרֶת שֶׁהוּא דַּק וּמְעֻלֶּה וּפְנִימִי מֵהַכֹּל, וּכְשֶׁעוֹלֶה אוֹתוֹ הָרֵיחַ לְהִתקַשֵּׁר בְּאוֹתוֹ שֶׁמֶן מִשְׁחָה שֶׁל הַנְּחָלִים הַנּוֹבְעִים, מִתְעוֹרְרִים זֶה עִם זֶה וְנִקְשָׁרִים כְּאֶחָד. וְאָז הֵם שְׁמָנִים טוֹבִים לְהָאִיר, כְּמוֹ שֶׁנֶּאֱמַר לְרֵיחַ שְׁמָנֶיךְ טוֹבִים.</p>\n<p>וְאָז מוּרָק שֶׁמֶן מִדַּרְגָּה לְדַרְגָּה בְּאוֹתָן הַדְּרָגוֹת שֶׁנִּקְרָאוֹת הַשֵּׁם הַקָּדוֹשׁ. זֶהוּ שֶׁכָּתוּב שֶׁמֶן תּוּרַק שְׁמֶךְ עַל כֵּן עֲלָמוֹת אֲהֵבוּךְ. מַה זֶּה עֲלָמוֹת? כְּמוֹ שֶׁבֵּאַרְנוּ עוֹלָמוֹת, עוֹלָמוֹת מַמָּשׁ. דָּבָר אַחֵר עַל כֵּן עֲלָמוֹת אֲהֵבוּךְ - כְּמוֹ שֶׁנֶּאֱמַר (תהלים מו) עַל עֲלָמוֹת שִׁיר, וְהַכֹּל אֶחָד.</p>\n<p>וּבְסִפְרוֹ שֶׁל רַב הַמְנוּנָא סָבָא כָּתוּב, מַה זֶּה עֲלָמוֹת? כְּמוֹ שֶׁנֶּאֱמַר (משלילא) וַתִּתֵּן טֶרֶף לְבֵיתָהּ וְחֹק לְנַעֲרֹתֶיהָ. נַעֲרֹתֶיהָ אֵלּוּ הָעֲלָמוֹת. אֲהֵבוּךְ, לְבָרֵךְ אֶת שִׁמְךְ וּלְזַמֵּר לְפָנֶיךְ, וּמִשָּׁם יוֹצְאוֹת בְּרָכוֹת בְּכָל הַתַּחְתּוֹנִים, וּמִתְבָּרְכִים עֶלְיוֹנִים וְתַחְתּוֹנִים.</p>\n<p>דָּבָר אַחֵר עַל כֵּן עֲלָמוֹת אֲהֵבוּךְ - יָפֶה הוּא מִי שֶׁאָמַר, עַל מָוֶת אֲהֵבוּךְ. שֶׁהֲרֵי בַּדָּבָר הַזֶּה בַּעֲלֵי הַדִּינִים מִתְבַּשְּׂמִים, וּבִשְׁבִיל שֶׁהַקְּטֹרֶת הַזּוֹ נִקְשֶׁרֶת בַּשֶּׁמֶן שֶׁלְּמַעְלָה יוֹתֵר, נֶחְשֶׁבֶת לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא מִכָּל הַקָּרְבָּנוֹת וְהָעוֹלוֹת. אָמְרָה כְּנֶסֶת יִשְׂרָאֵל: אֲנִי כִּקְטֹרֶת וְאַתָּה כְּשֶׁמֶן, מָשְׁכֵנִי אַחֲרֶיךְ נָרוּצָה וְגוֹ'. נָרוּצָה, כְּמוֹ שֶׁנֶּאֱמַר עַל כֵּן עֲלָמוֹת אֲהֵבוּךְ, אֲנִי וְכָל הָאוּכְלוּסִים, שֶׁהֲרֵי כֻּלָּם אֲחוּזִים בִּי, וְלָכֵן מָשְׁכֵנִי, שֶׁהֲרֵי בִּי הֵם תְּלוּיִים.</p>\n<p>הֱבִיאַנִי הַמֶּלֶךְ חֲדָרָיו. אִם יַכְנִיס אוֹתִי לַחֲדָרָיו, נָגִילָה וְנִשְׂמְחָה בָּךְ, אֲנִי וְכָל הָאוּכְלוּסִים. שָׁנִינוּ, כָּל הָאוּכְלוּסִים בְּשָׁעָה שֶׁכְּנֶסֶת יִשְׂרָאֵל שְׂמֵחָה וּמִתְבָּרֶכֶת, כֻּלָּם שְׂמֵחִים, וְאָז הַדִּין לֹא שָׁרוּי בָּעוֹלָם. וְעַל זֶה כָּתוּב (תהלים צו) יִשְׂמְחוּ הַשָּׁמַיִם וְתָגֵל הָאָרֶץ.</p>\n<p>כִּי בֶּעָנָן אֵרָאֶה עַל הַכַּפֹּרֶת. אָמַר רַבִּי יְהוּדָה, אַשְׁרֵיהֶם הַצַּדִּיקִים שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא רוֹצֶה בִּכְבוֹדָם. וְשָׁנִינוּ, מֶלֶךְ בָּשָׂר וָדָם, אִם אָדָם רוֹכֵב עַל סוּסוֹ, הוּא בֶּן מָוֶת, וְהַקָּדוֹשׁ בָּרוּךְ הוּא הִרְכִּיב אֶת אֵלִיָּהוּ עַל שֶׁלּוֹ, שֶׁכָּתוּב (מלכים ב ב) וַיַּעַל אֵלִיָּהוּ בַּסֳעָרָה הַשָּׁמָיִם וְגוֹ'. כָּאן מַה כָּתוּב? וְלֹא יָמוּת כִּי בֶּעָנָן אֵרָאֶה עַל הַכַּפֹּרֶת. וְהַקָּדוֹשׁ בָּרוּךְ הוּא הִכְנִיסוֹ לְמֹשֶׁה בּוֹ, זֶהוּ שֶׁכָּתוּב (שמות כד) וַיָּבֹא מֹשֶׁה בְּתוֹךְ הֶעָנָן, בְּתוֹךְ הֶעָנָן מַמָּשׁ, כִּי בֶּעָנָן אֵרָאֶה עַל הַכַּפֹּרֶת. זֶהוּ שֶׁכָּתוּב, (ישעיה ד) וּבָרָא ה' עַל כָּל מְכוֹן הַר צִיּוֹן וְעַל מִקְרָאֶהָ עָנָן יוֹמָם וְעָשָׁן. וְכָתוּב, (שמות מ) כִּי עֲנַן ה' עַל הַמִּשְׁכָּן יוֹמָם.</p>\n<p>וְלָמַדְנוּ, מַה שֶּׁכָּתוּב (שם לד) וַיֵּרֶד ה' בֶּעָנָן. בֶּעָנָן אֵרָאֶה עַל הַכַּפֹּרֶת. לָמַדְנוּ, מָקוֹם שֶׁהָיוּ שׁוֹרִים הַכְּרוּבִים הַלָּלוּ, כְּמוֹ שֶׁבֵּאַרְנוּ, שֶׁהַכְּרוּבִים עַל אוֹת הָיוּ יוֹשְׁבִים. וְלָמַדְנוּ, שָׁלֹשׁ פְּעָמִים בַּיּוֹם הִתְרַחֵשׁ נֵס בְּכַנְפֵיהֶם. בְּשָׁעָה שֶׁהִתְגַּלְּתָה עֲלֵיהֶם קְדֻשַּׁת הַמֶּלֶךְ, הֵם מֵעַצְמָם הָיוּ מַעֲלִים כַּנְפֵיהֶם וּפוֹרְשִׂים אוֹתָם וּמְכַסִּים עַל הַכַּפֹּרֶת. אַחר כָּךְ סוֹגְרִים כַּנְפֵיהֶם וְנֶאֱחָזִים בְּכַנְפֵיהֶם (ונאחזים בגופם), כְּמוֹ שֶׁנֶּאֱמַר (שם כה) וְהָיוּ הַכְּרֻבִים פֹּרְשֵׂי כְנָפַיִם לְמַעְלָה. פֹּרְשֵׂי וְלֹא פְּרוּשֵׂי. סֹכֲכִים וְלֹא סְכוּכִים. זֶה בְּאוֹת (בזאת) הָיוּ עוֹמְדִים וּשְׂמֵחִים עִם הַשְּׁכִינָה.</p>"],[9522012095,"<p>אָמַר רַבִּי אַבָּא, מָה רָצָה כָּאן, כִּי בֶּעָנָן אֵרָאֶה עַל הַכַּפֹּרֶת, וְכָתוּב בְּזֹּאת יָבֹא אַהֲרֹן, וַהֲרֵי הַכֹּהֵן אֵינוֹ רוֹאֶה אֶת הַשְּׁכִינָה בְּשָׁעָה שֶׁנִּכְנָס? אֶלָּא עָנָן הָיָה יוֹרֵד, וּכְשֶׁהָיָה יוֹרֵד, מַגִּיעַ עַל הַכַּפֹּרֶת הַזּוֹ וּמִתְעוֹרְרִים כַּנְפֵי הַכְּרוּבִים, וּמַקִּישִׁים בָּהֶם וְאוֹמְרִים שִׁירָה.</p>\n<p>וְאֵיזוֹ שִׁירָה אוֹמְרִים? (תהלים צו) כִּי גָדוֹל ה' וּמְהֻלָּל מְאֹד נוֹרָא הוּא עַל כָּל אֱלֹהִים. זֶה כְּשֶׁמַּעֲלִים אֶת כַּנְפֵיהֶם. וּבְשָׁעָה שֶׁפּוֹרְשִׂים אוֹתָן, אוֹמְרִים, כִּי כָּל אֱלֹהֵי הָעַמִּים אֱלִילִים וַה' שָׁמַיִם עָשָׂה. כְּשֶׁמְּכַסִּים עַל הַכַּפֹּרֶת, אוֹמְרִים, לִפְנֵי ה' כִּי בָא לִשְׁפֹּט הָאָרֶץ יִשִׁפֹּט תֵּבֵל בְּצֶדֶק, וְעַמִּים בְּמֵישָׁרִים.</p>\n<p>וְקֹוֹלוֹתֵיהֶם הָיָה שׁוֹמֵעַ הַכֹּהֵן בַּמִּקְדָּשׁ, אָז שָׂם קְטֹרֶת בִּמְקוֹמָהּ, וּמִתְכַּוֵּן בַּמֶּה שֶׁמִּתְכַּוֵּן, כְּדֵי שֶׁיִּתְבָּרֵךְ הַכֹּל (וקולותיהם). וְכַנְפֵי הַכְּרוּבִים עוֹלִים וְיוֹרְדִים, וְשָׁרִים שִׁירִים, מְכַסִּים לַכַּפֹּרֶת וּמַעֲלִים לָהֶם. זֶהוּ שֶׁכָּתוּב סֹכְכִים. סֹכְכִים דַּוְקָא. וּמִנַּיִן לָנוּ שֶׁקּוֹלוֹתֵיהֶם נִשְׁמָעִים? כְּמוֹ שֶׁנֶּאֱמַר (יחזקאל א) וָאֶשְׁמַע אֶת קוֹל וְגוֹ'.</p>\n<p>אָמַר רַבִּי יוֹסֵי, וְעַמִּים בְּמֵישָׁרִים. מַהוּ בְּמֵישָׁרִים? כְּמוֹ שֶׁנֶּאֱמַר מֵישָׁרִים אֲהֵבוּךְ - לְהַכְלִיל שְׁנֵי כְרוּבִים, זָכָר וּנְקֵבָה, מֵישָׁרִים וַדַּאי. וְעַל זֶה, וְעַמִּים בְּמֵישָׁרִים.</p>"],[9522012096,"<p>וְכָתוּב, (במדבר ז) וַיִּשְׁמַע אֶת הַקּוֹל מִדַּבֵּר אֵלָיו (וגו') מִבֵּין שְׁנֵי הַכְּרֻבִים וַיְדַבֵּר אֵלָיו. רַבִּי יִצְחָק אָמַר, מִכָּאן לָמַדְנוּ, שֶׁבְּכָל מָקוֹם שֶׁלֹּא נִמְצָא זָכָר וּנְקֵבָה, אֵינוֹ כְּדַאי לִרְאוֹת פְּנֵי שְׁכִינָה. זֶהוּ שֶׁכָּתוּב (תהלים קמ) יֵשְׁבוּ יְשָׁרִים אֶת פָּנֶיךְ, וְשָׁנִינוּ, כָּתוּב (דברים לב) צַדִּיק וְיָשָׁר הוּא, זָכָר וּנְקֵבָה, אַף כָּאן כְּרוּבִים זָכָר וּנְקֵבָה. וַעֲלֵיהֶם כָּתוּב, (תהלים צט) אַתָּה כּוֹנַנְתָּ מֵישָׁרִים. וְעַמִּים בְּמֵישָׁרִים. וּמִשּׁוּם כָּךְ, (שמות כה) וּפְנֵיהֶם אִישׁ אֶל אָחִיו, וַהֲרֵי בֵּאַרְנוּ.</p>"],[9522012097,"<p>שָׁנִינוּ שֶׁאָמַר רַבִּי יוֹסֵי, פַּעַם אַחַת הָיָה צָרִיךְ הָעוֹלָם לְמָטָר, בָּאוּ לִפְנֵי (הלכו אצל) רַבִּי שִׁמְעוֹן רַבִּי יֵיסָא וְרַבִּי חִזְקִיָּה וּשְׁאָר הַחֲבֵרִים. מְצָאוּהוּ שֶׁהָיָה הוֹלֵךְ לִרְאוֹת אֶת רַבִּי פִּנְחָס בֶּן יָאִיר, הוּא וְרַבִּי אֶלְעָזָר בְּנוֹ. כֵּיוָן שֶׁרָאָה אוֹתָם, פָּתַח וְאָמַר, (תהלים קלג) שִׁיר הַמַּעֲלוֹת הִנֵּה מַה טּוֹב וּמַה נָּעִים שֶׁבֶת אַחִים גַּם יָחַד. מַה זֶּה שֶׁבֶת אַחִים גַּם יָחַד?</p>\n<p>כְּמוֹ שֶׁנֶּאֱמַר וּפְנֵיהֶם אִישׁ אֶל אָחִיו. בְּשָׁעָה שֶׁהָיוּ אֶחָד עִם אֶחָד, מַשְׁגִּיחִים פָּנִים בְּפָנִים, כָּתוּב מַה טּוֹב וּמַה נָּעִים. וּכְשֶׁהַזָּכָר מַחֲזִיר פָּנָיו מִן הַנְּקֵבָה - אוֹי לָעוֹלָם, שֶׁאָז כָּתוּב, (משלייג) וְיֵשׁ נִסְפֶּה בְּלֹא מִשְׁפָּט. בְּלֹא מִשְׁפָּט וַדַּאי. וְכָתוּב (תהלים פט) צֶדֶק וּמִשְׁפָּט מְכוֹן כִּסְאֶךְ, שֶׁלֹּא הוֹלְכִים זֶה בְּלִי זֶה. וּכְשֶׁמִּשְׁפָּט מִתְרַחֵק מִצֶּדֶק - אוֹי לָעוֹלָם. (אז כתוב (משלי יג) ויש נספה בלא משפט).</p>\n<p>וְעַכְשָׁו רָאִיתִי שֶׁאַתֶּם בָּאתֶם עַל שֶׁהַזָּכָר לֹא שׁוֹרֶה עִם הַנְּקֵבָה. אָמַר, אִם לְשֵׁם זֶה בָּאתֶם אֵלַי - שְׁבוּ, שֶׁהֲרֵי הַיּוֹם הִסְתַּכַּלְתִּי, שֶׁיַּחֲזֹר הַכֹּל פָּנִים בְּפָנִים לִשְׁרוֹת. וְאִם לַתּוֹרָה בָּאתֶם - שְׁבוּ לְפָנַי. אָמְרוּ לוֹ, לַכֹּל בָּאנוּ לִפְנֵי מוֹרֵנוּ, יִשְׁתַּמֵּט אֶחָד מֵאִתָּנוּ לְבַשֵּׂר לְאַחֵינוּ שְׁאָר הַחֲבֵרִים, וְאָנוּ נֵשֵׁב לִפְנֵי מוֹרֵנוּ.</p>\n<p>עַד שֶׁהָיוּ הוֹלְכִים, פָּתַח וְאָמַר, (שיר א) שְׁחוֹרָה אֲנִי וְנָאוָה בְּנוֹת יְרוּשָׁלָיִם וְגוֹ'. אָמְרָה כְּנֶסֶת יִשְׂרָאֵל לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא: שְׁחוֹרָה אֲנִי בַּגָּלוּת, וְנָאוָה אֲנִי בְּמִצְווֹת הַתּוֹרָה. שֶׁאַף עַל פִּי שֶׁיִּשְׂרָאֵל בַּגָּלוּת, אֵין עוֹזְבִים אוֹתָם. כְּאָהֳלֵי קֵדָר, שֶׁאוֹתָם בְּנֵי קְטוּרָה (הרים) שֶׁמְּקַדְּמִים פְּנֵיהֶם תָּמִיד, וְעִם כָּל זֶה - כִּירִיעוֹת שְׁלֹמֹה, כְּאוֹתוֹ מַרְאֵה הַשָּׁמַיִם לָטֹהַר, שֶׁכָּתוּב (תהלים קד) נוֹטֶה שָׁמַיִם כַּיְרִיעָה.</p>\n<p>אַל תִּרְאֻנִי שֶׁאֲנִי שְׁחַרְחֹרֶת. מָה הַטַּעַם (אני שחרחרת משום שזזפתני) אַל תִּרְאֻנִי? מִשּׁוּם שֶׁאֲנִי שְׁחַרְחֹרֶת. שֶׁשְּׁזָפַתְנִי הַשֶּׁמֶשׁ, שֶׁלֹּא הִסְתַּכֵּל עָלַי הַשֶּׁמֶשׁ לְהָאִיר לִי כָּרָאוּי. וּמַה יִּשְׂרָאֵל אוֹמְרִים? בְּנֵי אִמִּי נִחֲרוּ בִי. מִי הֵם אוֹתָם בְּנֵי אִמִּי? אֵלּוּ הַמְמֻנִּים הַגְּדוֹלִים הַמְגִנִּים עַל שְׁאָר הָעַמִּים.</p>\n<p>דָּבָר אַחֵר, בְּנֵי אִמִּי מַמָּשׁ, כְּמוֹ שֶׁנֶּאֱמַר (איכה ב) הִשְׁלִיךְ מִשָּׁמַיִם אֶרֶץ וְגוֹ'. וּכְשֶׁהִשְׁלִיךְ מִשָּׁמַיִם אֶרֶץ, שָׂמֻנִי נֹטֵרָה אֶת הַכְּרָמִים. מָה הַטַּעַם? שֶׁכַּרְמִי שֶׁלִּי לֹא נָטָרְתִּי. וְשָׁנִינוּ, בְּנֵי אִמִּי וַדַּאי הִסְכִּימוּ עָלַי, כְּלוֹמַר, כְּשֶׁסָּרָה אֶרֶץ מִשָּׁמַיִם, כְּמוֹ שֶׁבֵּאַרְנוּ, שֶׁכָּתוּב (שמות ב) וַתֵּתַּצַּב אֲחֹתוֹ מֵרָחֹק.</p>\n<p>וְכָאן נֶאֱמַר וַדַּאי, הִנֵּה מַה טּוֹב וּמַה נָּעִים שֶׁבֶת אַחִים גַּם יָחַד. וּבָהֶם בֵּאַרְנוּ (וכאן בארנו), גַּם יָחַד, כְּמוֹ שֶׁנֶּאֱמַר (ויקרא כו) וְאַף גַּם זֹּאת בִּהְיוֹתָם, שֶׁבֶת אַחִים בִּכְלָל, כֵּיוָן שֶׁכָּתוּב גַּם, לְהַכְלִיל כָּל אוֹתָם שֶׁלְּמַעְלָה, שֶׁכָל הַשִּׁלְטוֹן נִמְצָא בְּאוֹתוֹ מָקוֹם.</p>\n<p>דָּבָר אַחֵר הִנֵּה מַה טּוֹב וּמַה נָּעִים וְגוֹ' - אֵלּוּ אוֹתָם הַחֲבֵרִים בְּשָׁעָה שֶׁהֵם יוֹשְׁבִים כְּאֶחָד וְלֹא נִפְרָדִים זֶה מִזֶּה, בַּהַתְחָלָה הֵם נִרְאִים אֲנָשִׁים עוֹרְכֵי קְרָב שֶׁרוֹצִים לַהֲרֹג זֶה אֶת זֶה. אַחַר כָּךְ חוֹזְרִים לְאַהֲבָה וְאַחֲוָה. מָה אוֹמֵר הַקָּדוֹשׁ בָּרוּךְ הוּא? הִנֵּה מַה טּוֹב וּמַה נָּעִים שֶׁבֶת אַחִים גַּם יָחַד. גַּם - לְהַכְלִיל עִמָּהֶם שְׁכִינָה. וְלֹא עוֹד, אֶלָּא שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מַקְשִׁיב לְדִבְרֵיהֶם, וְיֵשׁ לוֹ נַחַת וְשָׂמֵחַ בָּהֶם. זֶהוּ שֶׁכָּתוּב (מלאכי ג) אָז נִדְבְּרוּ יִרְאֵי ה' אִישׁ אֶל רֵעֵהוּ וַיַּקְשֵׁב ה' וַיִּשְׁמָע וַיִּכָּתֵב סֵפֶר זִכָּרוֹן לְפָנָיו וְגוֹ'.</p>\n<p>וְאַתֶּם הַחֲבֵרִים שֶׁל כָּאן, כְּמוֹ שֶׁהֱיִיתֶם בַּחֲבִיבוּת וְאַהֲבָה מִקֹּדֶם לָכֵן, כָּךְ גַּם מִכָּאן וָהָלְאָה לֹא תִפָּרְדוּ זֶה מִזֶּה, עַד שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא יִשְׂמַח עִמָּכֶם, יִקְרָא עֲלֵיכֶם שָׁלוֹם, וְיִמָּצֵא בִגְלַלְכֶם שָׁלוֹם בָּעוֹלָם. זֶהוּ שֶׁכָּתוּב, (תהלים קכב) לְמַעַן אַחַי וְרֵעָי אֲדַבְּרָה נָא שָׁלוֹם בָּךְ.</p>\n<p>הָלְכוּ, עַד שֶׁהָיוּ הוֹלְכִים, הִגִּיעוּ לְבֵית רַבִּי פִּנְחָס בֶּן יָאִיר. יָצָא רַבִּי פִּנְחָס וּנְשָׁקוֹ. אָמַר, זָכִיתִי לְנַשֵּׁק אֶת הַשְּׁכִינָה. אַשְׁרֵי חֶלְקִי. תִּקֵּן לָהֶם מַצְּעֵי מִטּוֹת בְּקִשְׁרֵי קְלִיעָה. אָמַר רַבִּי שִׁמְעוֹן, הַתּוֹרָה לֹא צְרִיכָה כָּךְ. הֶעֱבִיר אוֹתָם, וְיָשְׁבוּ. אָמַר רַבִּי פִּנְחָס, טֶרֶם שֶׁנֹּאכַל נִשְׁמַע מִבַּעַל הַתּוֹרָה דָּבָר, שֶׁהֲרֵי רַבִּי שִׁמְעוֹן, כָּל דְּבָרָיו הֵם בְּנִגְלֶה, הוּא אִישׁ שֶׁלֹּא פוֹחֵד מִמַּעְלָה וּמִמַּטָּה לוֹמַר אוֹתָם. לֹא פוֹחֵד מִמַּעְלָה, שֶׁהֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא הִסְכִּים עַל יָדוֹ. וְלֹא פוֹחֵד מִמַּטָּה, כְּמוֹ אַרְיֵה שֶׁלֹּא פוֹחֵד מִבְּנֵי הַצֹּאן. אָמַר רַבִּי שִׁמְעוֹן לְרַבִּי אֶלְעָזָר בְּנוֹ, עֲמֹד בִּמְקוֹמְךְ וֶאֱמֹר דָּבָר חָדָשׁ אֶל רַבִּי פִּנְחָס וּשְׁאָר הַחֲבֵרִים.</p>"],[9522012098,"<p>קָם רַבִּי אֶלְעָזָר, פָּתַח וְאָמַר, וַיְדַבֵּר ה' אֶל מֹשֶׁה אַחֲרֵי מוֹת שְׁנֵי בְּנֵי אַהֲרֹן וְגוֹ'. בַּפָּסוּק הַזֶּה יֵשׁ לְהִסְתַּכֵּל, שֶׁנִּרְאֶה שֶׁהוּא מְיֻתָּר, שֶׁהֲרֵי כָּתוּב אַחֲרָיו, וַיֹּאמֶר ה' אֶל מֹשֶׁה דַּבֵּר אֶל אַהֲרֹן אָחִיךְ. מִכָּאן רֵאשִׁית הַפָּרָשָׁה, הַפָּסוּק הַזֶּה שֶׁלְּמַעְלָה מַה הוּא, שֶׁכָּתוּב וַיְדַבֵּר ה' אֶל מֹשֶׁה? מַה הוּא שֶׁאָמַר לוֹ, וְאַחַר כָּךְ וַיֹּאמֶר ה' אֶל מֹשֶׁה?</p>\n<p>אֶלָּא בְּשָׁעָה שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא נָתַן קְטֹרֶת בְּשָׂמִים לְאַהֲרֹן, רָצָה שֶׁלֹּא יִשְׁתַּמֵּשׁ בּוֹ בְּחַיָּיו אָדָם אַחֵר. מָה הַטַּעַם? מִשּׁוּם שֶׁאַהֲרֹן מַרְבֶּה שָׁלוֹם בָּעוֹלָם. אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא: אַתָּה רוֹצֶה לְהַרְבּוֹת שָׁלוֹם בָּעוֹלָם - עַל יָדְךְ יִרְבֶּה שָׁלוֹם לְמַעְלָה, הֲרֵי קְטֹרֶת הַבְּשָׂמִים תִּהְיֶה מְסוּרָה בְיָדְךְ מִכָּאן וָהָלְאָה, וּבְחַיֶּיךְ לֹא יִשְׁתַּמֵּשׁ בָּהּ אָדָם אַחֵר. נָדָב וַאֲבִיהוּא הִקְדִּימוּ בְּחַיֵּי אֲבִיהֶם לְהַקְרִיב מַה שֶּׁלֹּא נִמְסַר לָהֶם, וְדָבָר זֶה גָּרַם לָהֶם שֶׁטָּעוּ בוֹ.</p>\n<p>וְשָׁנִינוּ, מֹשֶׁה הָיָה מְהַרְהֵר מַה גָּרַם לָהֶם אֶת הַטָּעוּת הַזּוֹ, וְהָיָה עָצוּב. מַה כָּתוּב? וַיְדַבֵּר ה' אֶל מֹשֶׁה אַחֲרֵי מוֹת שְׁנֵי בְּנֵי אַהֲרֹן. וּמָה אָמַר לוֹ? בְּקָרְבָתָם לִפְנֵי ה' וַיָּמֻתוּ. בְּהַקְרִיבָם לֹא כָתוּב, אֶלָּא בְּקָרְבָתָם. אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא לְמֹשֶׁה: זֶה גָּרַם לָהֶם - שֶׁדָּחֲקוּ אֶת הַשָּׁעָה בְּחַיֵּי אֲבִיהֶם וְטָעוּ בָהּ, וְהַיְנוּ מַה שֶּׁכָּתוּב אֲשֶׁר לֹא צִוָּה אוֹתָם. אוֹתָם לֹא צִוָּה, אֲבָל לְאַהֲרֹן צִוָּה. וּמַה שְּׁנֵי בְּנֵי אַהֲרֹן, עַל שֶׁדָּחֲקוּ אֶת הַשָּׁעָה בְּחַיֵּי אֲבִיהֶם גָּרְמוּ לְעַצְמָם כָּל כָּךְ - אֲנִי כְּלַפֵּי אַבָּא וְרַבִּי פִּנְחָס וּשְׁאָר הַחֲבֵרִים עַל אַחַת כַּמָּה וְכַמָּה. בָּא רַבִּי פִּנְחָס, נְשָׁקוֹ וּבֵרְכוֹ.</p>"],[9522012099,"<p>רַבִּי שִׁמְעוֹן פָּתַח וְאָמַר, (שיר ג) הִנֵּה מִטָּתוֹ שֶׁלִּשְׁלֹמֹה שִׁשִּׁים גִּבֹּרִים סָבִיב לָהּ וְגוֹ'. הִנֵּה מִטָּתוֹ שֶׁלִּשְׁלֹמֹה, מִי זוֹ מִטָּתוֹ? זֶהוּ כִּסֵּא (מטת) הַכָּבוֹד שֶׁל הַמֶּלֶךְ, שֶׁכָּתוּב בּוֹ (משלי לא) בָּטַח בָּהּ לֵב בַּעְלָהּ. שֶׁלִּשְׁלֹמֹה, הַמֶּלֶךְ שֶׁכָּל הַשָּׁלוֹם שֶׁלּוֹ הוּא. שִׁשִּׁים גִּבֹּרִים סָבִיב לָהּ, שֶׁנֶּאֱחָזִים בְּצִדֶּיהָ מִן הַדִּין הַקָּשֶׁה, וְנִקְרָאִים שִׁשִּׁים מַכּוֹת שֶׁל אֵשׁ (ששים מזינים בכלי זין קשים) שֶׁאוֹתוֹ נַעַר מִתְלַבֵּשׁ בָּהֶם.</p>\n<p>מִימִינוֹ שְׁנִינוּת הַחֶרֶב הַקָּשָׁה, מִשְּׂמֹאלוֹ גַּחֲלֵי אֵשׁ חֲזָקָה שֶׁאֲחוּזָה בַּחֲקִיקוֹתָיו (במקלותיו) בְּשִׁבְעִים אֶלֶף לַהֲטֵי אֵשׁ אוֹכֶלֶת, וְהֵם שִׁשִּׁים מְזֻיָּנִים בִּכְלֵי זַיִן קָשִׁים מֵאוֹתָן גְּבוּרוֹת תַּקִּיפוֹת שֶׁל אוֹתָהּ גְּבוּרָה עֶלְיוֹנָה שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא. זֶהוּ שֶׁכָּתוּב מִגִּבֹּרֵי יִשְׂרָאֵל.</p>\n<p>וְלָמַדְנוּ, בַּמִּטָּה הַזּוֹ מַה כָּתוּב בָּהּ? וַתָּקָם בְּעוֹד לַיְלָה, כַּאֲשֶׁר יוֹנֶקֶת מִצַּד הַיָּמִין (מצד הדין). וַתִּתֵּן טֶרֶף לְבֵיתָהּ. מָה הַטֶּרֶף? כְּמוֹ שֶׁנֶּאֱמַר (מיכה ה) וְטָרַף וְאֵין מַצִּיל. זֶהוּ שֶׁכָּתוּב כֻּלָּם אֲחֻזֵי חֶרֶב מְלֻמְּדֵי מִלְחָמָה, זְמִינִים בְּכָל מָקוֹם לַעֲשׂוֹת דִּין, וְנִקְרָאִים בַּעֲלֵי יְבָבָה וִילָלָה.</p>\n<p>אִישׁ חַרְבּוֹ עַל יְרֵכוֹ, כְּמוֹ שֶׁנֶּאֱמַר (תהלים מה) חֲגוֹר חַרְבְּךְ עַל יָרֵךְ גִּבּוֹר. מִפַּחַד בַּלֵּילוֹת, הֲרֵי פֵּרְשׁוּהָ מִפַּחְדָּהּ שֶׁל גֵּיהִנֹּם וְכוּ'. אֲבָל מִפַּחַד בַּלֵּילוֹת, כְּלוֹמַר, אֶת כָּל זֶה מֵאֵיזֶה מָקוֹם לוֹקְחִים? מִפַּחַד, מֵאוֹתוֹ מָקוֹם שֶׁנִּקְרָא פַּחַד, כְּמוֹ שֶׁנֶּאֱמַר (בראשית לא) וּפַחַד יִצְחָק הָיָה לִי. וַיִּשָּׁבַע יַעֲקֹב בְּפַחַד אָבִיו יִצְחָק. בַּלֵּילוֹת, בִּזְמַנִּים שֶׁהֵם מֻנּוּ לַעֲשׂוֹת דִּין.</p>\n<p>וְלָמַדְנוּ, כָּתוּב (משלי לא) זָמְמָה שָׂדֶה וַתִּקָּחֵהוּ. זֶהוּ שֶׁכָּתוּב (איוב מ) וְכָל חַיַּת הַשָּׂדֶה יְשַׂחֲקוּ שָׁם. וְעַל זֶה כָּתוּב, (תהלים קד) זֶה הַיָּם גָּדוֹל וּרְחַב יָדַיִם וְגוֹ' שָׁם אֳנִיּוֹת יְהַלֵּכוּן וְגוֹ', כְּמוֹ שֶׁנֶּאֱמַר (משלי לא) הָיְתָה כָּאֳנִיּוֹת סוֹחֵר מִמֶּרְחָק תָּבִיא לַחְמָהּ. מִמֶּרְחָק וַדַּאי. מֵרֹאשׁ הַמֹּחַ, וּמִמַּעְלָה שֶׁל הָרֹאשׁ, תָּבִיא לַחְמָהּ, עַל יְדֵי הַצַּדִּיק כְּשֶׁמִּזְדַּוְּגִים כְּאֶחָד, אֲזַי שִׂמְחָה בַּכֹּל. זֶהוּ שֶׁכָּתוּב לִוְיָתָן זֶה יָצַרְתָּ לְשַׂחֶק בּוֹ.</p>\n<p>לָמַדְנוּ, אֶלֶף וַחֲמֵשׁ מֵאוֹת בַּעֲלֵי מָגִנִּים בַּעֲלֵי הַשִּׁלְטוֹן נֶאֱחָזִים מֵהַצַּד הַזֶּה, שֶׁהֵם גִּבּוֹרִים. בִּידֵי אוֹתוֹ שֶׁנִּקְרָא נַעַר אַרְבָּעָה מַפְתְּחוֹת גְדוֹלִים. תַּנִּינִים שֶׁהוֹלְכִים תַּחַת הַסְּפִינָה שֶׁל הַיָּם הַגָּדוֹל הַזֶּה לְאַרְבַּע זָוִיּוֹת. זֶה הוֹלֵךְ לְצַד זֶה, וְזֶה הוֹלֵךְ לְצַד זֶה, וְכָךְ כֻּלָּם. אַרְבָּעָה מַרְאוֹת שֶׁל פָּנִים נִרְאִים בָּהֶם, וּכְשֶׁנִּכְלָלִים בְּאֶחָד, כָּתוּב (יחזקאל א) וּדְמוּת פְּנֵיהֶם פְּנֵי אָדָם, פְּנֵיהֶם שֶׁל כֻּלָּם.</p>\n<p>פָּנִים גְּדוֹלִים וּפָנִים קְטַנִּים כְּלוּלִים כְּאֶחָד לְמַעְלָה, שְׁנַיִם עוֹלִים וּמְשׁוֹטְטִים, וּשְׁתֵּי מַגְרֵפוֹת בִּידֵיהֶם. אֶלֶף הָרִים עוֹלִים וְנִכְנָסִים (אלו מכסים נכנסים ועולים) בְּכָל יוֹם מֵהַשְׁקָאַת אוֹתוֹ הַיָּם, אַחַר כָּךְ נֶעֱקָרִים מִמֶּנָּה וְעוֹלִים לְיָם אַחֵר.</p>\n<p>אֵין חֶשְׁבּוֹן לְאוֹתָם הַנֶּאֱחָזִים בְּשַׂעֲרוֹתֶיהָ, שְׁנֵי בָנִים יוֹנְקִים כָּל יוֹם, שֶׁנִּקְרָאִים מְרַגְּלֵי הָאָרֶץ, וְזֶהוּ סוֹד שֶׁל סִפְרָא דִצְנִיעוּתָא, שֶׁכָּתוּב (יהושע ב) וַיִּשְׁלַח יְהוֹשֻׁעַ בִּן נוּן מִן הַשִּׁטִּים שְׁנַיִם אֲנָשִׁים מְרַגְּלִים חֶרֶשׁ לֵאמֹר. וְאֵלּוּ יוֹנְקִים מִתַּחַת צִדְדֵי אֵיבָרֶיהָ. שְׁתֵּי בָנוֹת תַּחַת רַגְלֶיהָ, (ואלו יונקים מצד אברהם, שתי בנות בתחתיה) וְעַל זֶה כָּתוּב (בראשית ו) וַיִּרְאוּ בְנֵי הָאֱלֹהִים אֶת בְּנוֹת הָאָדָם. וְאֵלּוּ נֶאֱחָזִים בַּעֲלֵי (בצפרני) אוֹתָהּ מִטָּה, וְזֶהוּ שֶׁשָּׁנִינוּ, שֶׁכָּתוּב (מלכים א ג) אָז תָּבאנָה שְׁתַּיִם נָשִׁים זֹּנוֹת אֶל הַמֶּלֶךְ. אָז תָּבאנָה, וְלֹא מִקֹּדֶם לָכֵן. וּבִזְמַן שֶׁיִּשְׂרָאֵל לְמַטָּה, מַחֲזִירִים עֹרֶף מֵאַחַר הַקָּדוֹשׁ בָּרוּךְ הוּא, מַה כָּתוּב? (ישעיה ג) עַמִּי נֹגְשָׂיו מְעוֹלֵל וְנָשִׁים מָשְׁלוּ בוֹ. וַדַּאי.</p>\n<p>בְּיַד שְׂמֹאל שִׁבְעִים עֲנָפִים שֶׁמְּגֻדָּלִים בֵּין דְּגֵי הַיָּם, כֻּלָּם אֲדֻמִּים כַּשּׁוֹשַׁנָּה, וּמֵעֲלֵיהֶם עָנָף אֶחָד יוֹתֵר אָדם, זֶה עוֹלֶה וְיוֹרֵד, וְכֻלָּם מִתְכַּסִּים בְּשַׂעֲרוֹתֶיהָ.</p>\n<p>בַּעַל הַלָּשׁוֹן הָרָע, כְּשֶׁיּוֹרֵד הַנָּחָשׁ, נַעֲשֶׂה מְקַפֵּץ עַל הֶהָרִים מְדַלֵּג עַל הַסְּלָעִים, עַד שֶׁיִּמְצָא טֶרֶף שֶׁאָחוּז בְּצִפָּרְנַיִם, וְיֹאכַל. אָז שׁוֹכֵךְ, וְחוֹזֶרֶת לְשׁוֹנוֹ לְטוֹב. אַשְׁרֵיהֶם יִשְׂרָאֵל שֶׁמְּזַמְּנִים לוֹ טַרְפּוֹ. חוֹזֵר לִמְקוֹמוֹ (לאחריו), וְנִכְנָס לְנֶקֶב תְּהוֹם רַבָּה.</p>\n<p>כְּשֶׁעוֹלִים (עולה עולים) בַּעֲלֵי הָרְמָחִים וְהַחֲרָבוֹת, שֶׁאֵין לָהֶם חֶשְׁבּוֹן, סְבִיב אוֹתָם שִׁשִּׁים עֶלְיוֹנִים שֶׁסְּבִיב הַמִּטָּה הַזּוֹ, אֶלֶף אֲלָפִים וְרִבּוֹא רְבָבוֹת עוֹמְדִים בְּכָל צַד שֶׁל הַמִּטָּה הַזּוֹ לְמַעְלָה, וּמִמֶּנָּה נִזּוֹנִים, כֻּלָּם מִלְּפָנֶיהָ (וממנה נזונים, כלם עובדים לה לפניה) יַעַמְדוּ.</p>\n<p>מִתַּחַת לְכֻלָּם יוֹצְאִים כַּמָּה אֶלֶף וּרְבָבוֹת שֶׁאֵין לָהֶם חֶשְׁבּוֹן, וְיוֹרְדִים וּמְשׁוֹטְטִים בָּעוֹלָם, עַד שֶׁתּוֹקְעִים בַּעֲלֵי הַשּׁוֹפָר וּמִתְכַּנְּסִים, וְאֵלֶּה אֲחוּזִים בְּזֻהֲמַת הַצִּפָּרְנַיִם.</p>\n<p>הַמִּטָה הַזּוֹ כּוֹלֶלֶת אוֹתָם. רַגְלֵי הַמִּטָּה הַזּוֹ אֲחוּזִים בְּאַרְבַּעַת צִדְדֵי הָעוֹלָם, כֻּלָּם נִכְלָלִים בַּכְּלָל שֶׁנִּמְצָא לְמַעְלָה וְנִמְצָא לְמַטָּה, בַּשָּׁמַיִם מִמַּעַל וְעַל הָאָרֶץ מִתָּחַת, וְעַל זֶה כָּתוּב הִנֵּה. מַה זֶּה הִנֵּה? מִשּׁוּם שֶׁמְּזֻמֶּנֶת לְכֻלָּם, לְמַעְלָה וּלְמַטָּה. וּרְשׁוּמָה הַמִּטָּה הַזּוֹ מֵהַכֹּל, וְנִקְרֵאת אֲדנָ\"י, הָרִבּוֹן שֶׁל הַכֹּל, רְשׁוּמָה בֵּין חֵילוֹתֶיהָ.</p>\n<p>מִשּׁוּם כָּךְ הַכֹּהֵן צָרִיךְ לְכַוֵּן דְּבָרִים שֶׁלְּמַעְלָה, לְיַחֵד אֶת הַשֵּׁם הַקָּדוֹשׁ מֵהַמָּקוֹם שֶׁצָּרִיךְ לְיַחֲדוֹ, וְעַל זֶה שָׁנִינוּ, כָּתוּב בְּזֹּאת יָבֹא אַהֲרֹן אֶל הַקֹּדֶשׁ, בָּזֶה צָרִיךְ לְקָרֵב קְדֻשָּׁה לִמְקוֹמָהּ, מֵהַמָּקוֹם הַזֶּה צָרִיךְ אָדָם לִפְחֹד מִלִּפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. וְעַל זֶה כָּתוּב, (דברים לד) לוּ חָכְמוּ יַשְׂכִּילוּ זֹּאת מִיָּד יָבִינוּ לְאַחֲרִיתָם. כְּלוֹמַר, אִם יִסְתַּכְּלוּ בְּנֵי אָדָם בְּעֹנֶשׁ, אֵיךְ זֹּאת אֲחוּזָה בֵּין חֵילוֹתֶיהָ, וְאֵיךְ הִתְמַנּוּ לְפָנֶיהָ כָּל אוֹתָם בְּנֵי הַחֲיָלוֹת, וְאוֹחֲזִים בַּעֲבוֹדָה לְהִפָּרַע מִן הָרְשָׁעִים, מִיָּד יָבִינוּ לְאַחֲרִיתָם, וְיִשְׁמְרוּ אֶת מַעֲשֵׂיהֶם, וְלֹא יֶחֶטְאוּ לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ.</p>\n<p>עוֹד אָמַר רַבִּי שִׁמְעוֹן, כָּל אָדָם שֶׁזּוֹכֶה לִלְמֹד תּוֹרָה וְשׁוֹמֵר אֶת הַזֹּאת הַזּוֹ, הַזֹּאת הַזּוֹ שׁוֹמֶרֶת אוֹתוֹ וְכוֹרֶתֶת עִמּוֹ בְּרִית עַל בְּרִיתוֹ, שֶׁלֹּא תָסוּר מִמֶּנּוּ וּמִבָּנָיו וּמִבְּנֵי בָנָיו לְעוֹלָמִים. זֶהוּ שֶׁכָּתוּב (ישעיה נט) וַאֲנִי זֹּאת בְּרִיתִי אוֹתָם וְגוֹ'. יָשְׁבוּ לֶאֱכֹל. עַד שֶׁאָכְלוּ, אָמַר רַבִּי שִׁמְעוֹן לַחֲבֵרִים, כָּל אֶחָד וְאֶחָד יֹאמַר דָּבָר חָדָשׁ בַּתּוֹרָה עַל הַשֻּׁלְחָן לִפְנֵי רַבִּי פִּנְחָס.</p>"],[9522012100,"<p>פָּתַח רַבִּי חִזְקִיָּה וְאָמַר, ה' אֱלֹהִים נָתַן לִי לְשׁוֹן לִמּוּדִים לָדַעַת לָעוּת אֶת יָעֵף דָּבָר וְגוֹ'. אַשְׁרֵיהֶם יִשְׂרָאֵל שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הִתְרַצָּה בָהֶם מִכָּל שְׁאָר הָעַמִּים וּקְרָאָם קֹדֶשׁ, שֶׁכָּתוּב קֹדֶשׁ יִשְׂרָאֵל לַה', וְנָתַן לָהֶם חֵלֶק לְהֵאָחֵז בַּשֵּׁם הַקָּדוֹשׁ. וּבַמָּה אָחֲזוּ יִשְׂרָאֵל בַּשֵּׁם הַקָּדוֹשׁ? מִשּׁוּם שֶׁזָּכוּ בַתּוֹרָה. שֶׁכָּל מִי שֶׁאוֹחֵז בַּתּוֹרָה, זוֹכֶה בַּקָּדוֹשׁ בָּרוּךְ הוּא.</p>\n<p>(בקדש). וְשָׁנִינוּ לִפְנֵי מוֹרֵנוּ, מַה זֶּה קֹדֶשׁ? שְׁלֵמוּת הַכֹּל שֶׁנִּקְרֵאת הַחָכְמָה הָעֶלְיוֹנָה. וּמֵהַמָּקוֹם הַזֶּה (שופע שמן משחת קדש בשבילים ידועים למקום שנקרא בינה עליונה), וּמִשָּׁם יוֹצְאִים מַעְיָנוֹת וּנְחָלִים לְכָל עֵבֶר, עַד שֶׁמַּגִּיעִים לְזֹּאת הַזּוֹ. (וממקום זה מתעוררת רוח קדושה) וכשמתברכת הזאת הזו, נקראת קדש, ונקראת חכמה, וקוראים לה (והזאת הזו כשמתברכת ממקום עליון, זה שנקרא קדש ונקרא חכמה, קוראים לו) רוח הקדש. כלומר, רוח מאותו קדש שלמעלה. וכשיוצאים ומתעוררים ממנה סודות התורה, אז נקראת לשון הקדש.</p>\n<p>וּבְשָׁעָה שֶׁשּׁוֹפֵעַ אוֹתוֹ מִשְׁחַת קֹדֶשׁ לְאוֹתָם שְׁנֵי עַמּוּדִים, שֶׁנִּקְרָאִים לִמּוּדֵי ה', וְנִקְרָאִים צְבָאוֹת, מִתְכַּנֵּס לְשָׁם, וּכְשֶׁיּוֹצֵא מִשָּׁם בְּאוֹתָהּ דַּרְגָּה שֶׁנִּקְרֵאת יְסוֹד, לְאוֹתָהּ חָכְמָה קְטַנָּה, אָז נִקְרֵאת לְשׁוֹן לִמּוּדִים, וְיוֹצֵאת לְהָעִיר אוֹתָם קְדוֹשִׁים עֶלְיוֹנִים. אָז כָּתוּב, ה' אֱלֹהִים נָתַן לִי לְשׁוֹן לִמּוּדִים. וְלָמָּה? לָדַעַת לָעוּת אֶת יָעֵף דָּבָר. וְהַקָּדוֹשׁ בָּרוּךְ הוּא נָתַן אֶת זֶה לַמְּנוֹרָה הַקְּדוֹשָׁה, רַבִּי שִׁמְעוֹן. וְעוֹד, שֶׁהֶעֱלָה אוֹתוֹ לְמַעְלָה לְמַעְלָה, וּמִשׁוּם כָּךְ כָּל דְּבָרָיו בַּנִּגְלֶה נֶאֱמָרִים, וְלֹא מְכֻסִּים. עָלָיו כָּתוּב, (במדבר יב) פֶּה אֶל פֶּה אֲדַבֶּר בּוֹ וּמַרְאֶה וְלֹא בְחִידת.</p>"],[9522012101,"<p>פָּתַח רַבִּי יֵיסָא וְאָמַר, (מלכים א ה) וַה' נָתַן חָכְמָה לִשְׁלֹמֹה כַּאֲשֶׁר דִּבֶּר לוֹ וַיְהִי שָׁלוֹם בֵּין חִירָם וּבֵין שְׁלֹמֹה וְגוֹ'. וַה' נָתַן חָכְמָה לִשְׁלֹמֹה, זֶהוּ שֶׁשָּׁנִינוּ, בִּימֵי שְׁלֹמֹה הַמֶּלֶךְ עָמְדָה הַלְּבָנָה בִּשְׁלֵמוּתָהּ, כַּאֲשֶׁר דִּבֶּר לוֹ, כְּמוֹ שֶׁנֶּאֱמַר לוֹ, הַחָכְמָה וְהַמַּדָּע נָתוּן לָךְ.</p>\n<p>וַיְהִי שָׁלוֹם בֵּין חִירָם וּבֵין שְׁלֹמֹה. וְכִי מַה (בין) זֶה לָזֶה? אֶלָּא כָּךְ שָׁנִינוּ, וַה' נָתַן חָכְמָה לִשְׁלֹמֹה. וְאֶת הַחָכְמָה הַזּוֹ בַּמָּה הֶעֱמִיד אוֹתָהּ? אָמַר רַבִּי יוֹסֵי, הֶעֱמִיד אוֹתָהּ בָּזֶה בָּרִאשׁוֹנָה, שֶׁשְּׁלֹמֹה עָשָׂה שֶׁהוֹרִיד אֶת חִירָם מֵאוֹתָהּ דַּרְגָּה, שֶׁהָיָה אוֹמֵר (יחזקאל כח) מוֹשַׁב אֱלֹהִים יָשַׁבְתִּי וְגוֹ'. שֶׁלָּמַדְנוּ שֶׁחִירָם מֶלֶךְ צוֹר עָשָׂה עַצְמוֹ אֱלוֹהַּ. אַחַר שֶׁשְּׁלֹמֹה בָּא, עָשָׂה לוֹ בְּחָכְמָתוֹ שֶׁיֵּרֵד מֵאוֹתָהּ עֵצָה וְהוֹדָה לִשְׁלֹמֹה. וּמִשּׁוּם כָּךְ כָּתוּב, (מלכים א ה) וַיְהִי שָׁלוֹם בֵּין חִירָם וּבֵין שְׁלֹמֹה.</p>\n<p>וְשָׁנִינוּ, אָמַר רַבִּי יִצְחָק אָמַר רַבִּי יְהוּדָה, שֶׁשָּׁלַח לוֹ שֵׁד אֶחָד, וְהוֹרִיד אוֹתוֹ לְשִׁבְעָה מְדוֹרֵי גֵיהִנֹּם, וְהֶעֱלֶה אוֹתוֹ וְשָׁלַח לוֹ פְּתָקִים בְּכָל יוֹם וָיוֹם בְּיָדוֹ, עַד שֶׁחָזַר וְהוֹדָה לִשְׁלֹמֹה. וְשָׁנִינוּ, שְׁלֹמֹה יָרַשׁ אֶת הַלְּבָנָה בְּכָל הַצְּדָדִים, וּמִשּׁוּם כָּךְ שָׁלַט בַּכֹּל בְּחָכְמָתוֹ. וְרַבִּי שִׁמְעוֹן בַּר יוֹחַאי שׁוֹלֵט בְּחָכְמָתוֹ עַל כָּל בְּנֵי הָעוֹלָם, וְכָל אוֹתָם שֶׁעוֹלִים בְּדַרְגוֹתָיו לֹא עוֹלִים אֶלָּא לְהַשְׁלִים עִמּוֹ (אם לא שלמים עמו).</p>\n<p>פָּתַח רַבִּי יוֹסֵי וְאָמַר, (שיר ב) יוֹנָתִי בְּחַגְוֵי הַסֶּלַע בְּסֵתֶר הַמַּדְרֵגָה וְגוֹ'. יוֹנָתִי - זוֹ כְּנֶסֶת יִשְׂרָאֵל. מַה יּוֹנָה לֹא עוֹזֶבֶת אֶת בֶּן זוּגָהּ לְעוֹלָמִים, כָּךְ כְּנֶסֶת יִשְׂרָאֵל לֹא עוֹזֶבֶת אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא לְעוֹלָמִים. בְּחַגְוֵי הַסֶּלַע - אֵלּוּ תַּלְמִידֵי חֲכָמִים, שֶׁלֹּא נִמְצָאִים בִּמְנוּחָה בָּעוֹלָם הַזֶּה. בְּסֵתֶר הַמַּדְרֵגָה - אֵלּוּ תַּלְמִידֵי חֲכָמִים שֶׁצְּנוּעִים, שֶׁבָּהֶם חֲסִידִים יִרְאֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁשְּׁכִינָה לֹא זָזָה מֵהֶם לְעוֹלָמִים. אָז הַקָּדוֹשׁ בָּרוּךְ הוּא תּוֹבֵעַ אֶת כְּנֶסֶת יִשְׂרָאֵל בִּשְׁבִילָם וְאוֹמֵר, הַרְאִינִי אֶת מַרְאַיִךְ הַשְׁמִיעִנִי אֶת קוֹלֵךְ כִּי קוֹלֵךְ עָרֵב, שֶׁאֵין קוֹל שֶׁנִּשְׁמָע לְמַעְלָה, אֶלָּא קוֹלָם שֶׁל אֵלּוּ הָעוֹסְקִים בַּתּוֹרָה.</p>\n<p>וְלָמַדְנוּ, כָּל אוֹתָם הָעוֹסְקִים בַּתּוֹרָה בַּלָּיְלָה, הַדְּיוֹקָן שֶׁלָּהֶם נֶחְקָק לְמַעְלָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מִשְׁתַּעֲשֵׁעַ בָּהֶם כָּל הַיּוֹם וּמִסְתַּכֵּל בָּהֶם, וְאוֹתוֹ קוֹל (של כאן) עוֹלֶה וּבוֹקֵעַ אֶת כָּל אוֹתָם רְקִיעִים עַד שֶׁעוֹלֶה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וְאָז כָּתוּב, כִּי קוֹלֵךְ עָרֵב וּמַרְאֵיךְ נָאוֶה. וְעַכְשָׁו הַקָּדוֹשׁ בָּרוּךְ הוּא חוֹקֵק אֶת דְּיוֹקְנוֹ שֶׁל רַבִּי שִׁמְעוֹן לְמַעְלָה, וְקוֹלוֹ לְמַעְלָה לְמַעְלָה עוֹלֶה, וּמִתְעַטֵּר בַּכֶּתֶר הַקָּדוֹשׁ, עַד שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מִתְעַטֵּר בּוֹ בְּכָל הָעוֹלָמוֹת וּמִשְׁתַּבֵּחַ בּוֹ. עָלָיו כָּתוּב (ישעיה מט) וַיֹּאמֶר לִי עַבְדִּי אָתָּה יִשְׂרָאֵל אֲשֶׁר בְּךְ אֶתְפָּאָר.</p>"],[9522012102,"<p>פָּתַח רַבִּי חִיָּיא וְאָמַר, (קהלת ג) מַה שֶּׁהָיָה כְּבָר הוּא וַאֲשֶׁר לִהְיוֹת וְגוֹ'. מַה שֶּׁהָיָה כְּבָר, הַיְנוּ מַה שֶּׁשָּׁנִינוּ, שֶׁטֶּרֶם בָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם הַזֶּה, הָיָה בּוֹרֵא עוֹלָמוֹת וּמַחֲרִיבָם, עַד שֶׁעָלָה בִרְצוֹנוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא לִבְרֹא אֶת הָעוֹלָם הַזֶּה וְנִמְלַךְ בַּתּוֹרָה. אָז הוּא הִתְתַּקֵּן בְּתִקּוּנָיו וְהִתְעַטֵּר בְּעַטְרוֹתָיו, וּבָרָא אֶת הָעוֹלָם הַזֶּה, וְכָל מַה שֶּׁנִּמְצָא בָּעוֹלָם הַזֶּה הֲרֵי הָיָה לְפָנָיו (שהרי עלהמלפניו) וְהִתְתַּקֵּן לְפָנָיו.</p>\n<p>וְשָׁנִינוּ, כָּל אוֹתָם מַנְהִיגֵי הָעוֹלָם שֶׁנִּמְצָאִים בְּכָל דּוֹר וָדוֹר, טֶרֶם שֶׁיָּבאוּ לָעוֹלָם, הֲרֵי הָיוּ עוֹמְדִים לְפָנָיו בַּדְּיוֹקָן שֶׁלָּהֶם. (וכך שנינו) אֲפִלּוּ כָּל אוֹתָן נִשְׁמוֹת בְּנֵי הָאָדָם טֶרֶם שֶׁיָּרְדוּ לָעוֹלָם, כֻּלָּן חֲקוּקוֹת לְפָנָיו בָּרָקִיעַ בְּאוֹתוֹ דְיוֹקָן מַמָּשׁ שֶׁהֵם בָּעוֹלָם הַזֶּה. וְכָל מַה שֶּׁלּוֹמְדִים בָּעוֹלָם הַזֶּה, הַכֹּל יָדְעוּ טֶרֶם בּוֹאָם לָעוֹלָם. וְשָׁנִינוּ, זֶה בְּאוֹתָם צַדִּיקֵי אֱמֶת.</p>\n<p>וְכָל אוֹתָם שֶׁאֵין נִמְצָאִים צַדִּיקִים בָּעוֹלָם הַזֶּה, אֲפִלּוּ שָׁם מְרֻחָקִים מִלִּפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וְנִכְנָסִים לְנֶקֶב תְּהוֹם רַבָּה, וְדוֹחֲקִים אֶת הַשָּׁעָה וְיוֹרְדִים לָעוֹלָם. וְאוֹתָהּ הַנְּשָׁמָה שֶׁלָּהֶם, הֲרֵי לָמַדְנוּ, כְּמוֹ שֶׁהֵם קְשֵׁי עֹרֶף בָּעוֹלָם הַזֶּה, כָּךְ הָיוּ טֶרֶם בּוֹאָם לָעוֹלָם. וְאֶת אוֹתוֹ חֵלֶק קָדוֹשׁ שֶׁנָּתַן לָהֶם זָרְקוּ אוֹתוֹ, וְהוֹלְכִים וּמְשׁוֹטְטִים וְנִטְמָאִים בְּאוֹתוֹ נֶקֶב תְּהוֹם רַבָּה, וְנוֹטְלִים חֶלְקָם מִשָּׁם, וְדוֹחֲקִים אֶת הַשָּׁעָה וְיוֹרְדִים לָעוֹלָם. אִם זוֹכֶה אַחַר כָּךְ וְשָׁב בִּתְשׁוּבָה לִפְנֵי רִבּוֹנוֹ - הוּא נוֹטֵל אֶת אוֹתוֹ חֵלֶק שֶׁלּוֹ מַמָּשׁ. זֶהוּ שֶׁכָּתוּב, (קהלת ו) מַה שֶּׁהָיָה כְּבָר (נקרא שמו) הוּא, (שם ג) וַאֲשֶׁר לִהְיוֹת וְגוֹ' כְּבָר הָיָה.</p>\n<p>בֹּא רְאֵה, לֹא נִמְצְאוּ כְמוֹ בְּנֵי אַהֲרֹן בְּיִשְׂרָאֵל, פְּרָט לְמֹשֶׁה וְאַהֲרֹן, וְהֵם נִקְרְאוּ אֲצִילֵי בְּנֵי יִשְׂרָאֵל. וְעַל שֶׁטָּעוּ לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ מֵתוּ. וְכִי הַקָּדוֹשׁ בָּרוּךְ הוּא רָצָה לְאַבְּדָם? וַהֲרֵי שָׁנִינוּ בְּסוֹד הַמִּשְׁנָה, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה חֶסֶד עִם הַכֹּל, וַאֲפִלּוּ אֶת רִשְׁעֵי הָעוֹלָם אֵינוֹ רוֹצֶה לְאַבְּדָם, וְצַדִּיקֵי הָאֱמֶת הַלָּלוּ, הֲיַעֲלֶה עַל דַּעְתְּךְ שֶׁנֶּאֶבְדוּ מִן הָעוֹלָם?! אֵיפֹה הַזְּכוּת שֶׁלָּהֶם? אֵיפֹה הַזְּכוּת שֶׁל אֲבִיהֶם, וּזְכוּתוֹ שֶׁל מֹשֶׁה גַּם כֵּן? וְאֵיךְ הֵם נֶאֶבְדוּ?</p>\n<p>אֶלָּא כָּךְ לָמַדְנוּ מֵהַמָּאוֹר הַקָּדוֹשׁ, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא חָס עַל כְּבוֹדָם, וְנִשְׂרַף גּוּפָם בִּפְנִים, וְנִשְׁמָתָם לֹא נֶאֶבְדָה, וַהֲרֵי בֵּאַרְנוּ. וּבא רְאֵה, טֶרֶם שֶׁמֵּתוּ בְּנֵי אַהֲרֹן, כָּתוּב (שמות ו) וְאֶלְעָזָר בֶּן אַהֲרֹן לָקַח לוֹ וְגוֹ', נִקְרָא שְׁמוֹ פִּנְחָס, שֶׁהָיָה עָתִיד לְתַקֵּן אֶת הֶעָקֹם. זֶהוּ שֶׁכָּתוּב וַאֲשֶׁר לִהְיוֹת כְּבָר הָיָה. וְלָמַדְנוּ, כָּל צַדִּיקֵי הָאֱמֶת טֶרֶם</p>\n<p>שֶׁיָּבאוּ לָעוֹלָם, כֻּלָּם מְתֻקָּנִים לְמַעְלָה וְנִקְרָאִים בְּשֵׁמוֹת. וְרַשְׁבִּ\"י, מִיּוֹם שֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם, הָיָה מְזֻמָּן לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וְנִמְצָא עִמּוֹ, וְהַקָּדוֹשׁ בָּרוּךְ הוּא קָרָא אוֹתוֹ בִּשְׁמוֹ, אַשְׁרֵי חֶלְקוֹ לְמַעְלָה וּלְמַטָּה, עָלָיו כָּתוּב (משליכג) יִשְׂמַח אָבִיךְ וְאִמֶּךְ. אָבִיךְ - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא. וְאִמֶּךְ - זוֹ כְּנֶסֶת יִשְׂרָאֵל.</p>"],[9522012103,"<p>פָּתַח רַבִּי אַבָּא וְאָמַר, (שיר א) עַד שֶׁהַמֶּלֶךְ בִּמְסִבּוֹ נִרְדִּי נָתַן רֵיחוֹ. אֶת הַפָּסוּק הַזֶּה פֵּרְשׁוּהוּ הַחֲבֵרִים בְּשָׁעָה שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הָיָה נִמְצָא וּמְזֻמָּן בְּהַר סִינַי לָתֵת תּוֹרָה לְיִשְׂרָאֵל. נִרְדִּי נָתַן רֵיחוֹ, יִשְׂרָאֵל נָתְנוּ וְהָעֱלוּ רֵיחַ טוֹב שֶׁעָמַד וְהֵגֵן עֲלֵיהֶם לְדוֹרוֹ דוֹרוֹת, וְאָמְרוּ (בראשית א) כָּל אֲשֶׁר דִּבֶּר ה' נַעֲשֶׂה וְנִשְׁמָע. דָּבָר אַחֵר עַד שֶׁהַמֶּלֶךְ בִּמְסִבּוֹ - בְּעוֹד שֶׁעָלָה מֹשֶׁה לְקַבֵּל תּוֹרָה מֵהַקָּדוֹשׁ בָּרוּךְ הוּא וְנֶחְקְקָה בִּשְׁנֵי לוּחוֹת אֲבָנִים, עָזְבוּ יִשְׂרָאֵל אֶת אוֹתוֹ רֵיחַ טוֹב שֶׁהָיָה מִתְעַטֵּר עֲלֵיהֶם, וְאָמְרוּ לָעֵגֶל, אֵלֶּה אֱלֹהֶיךְ יִשְׂרָאֵל.</p>\n<p>עֵכְשָׁו פָּסוּק זֶה הוּא בְּסוֹד הַחָכְמָה. בּא רְאֵה, כָּתוּב (בראשית ב) וְנָהָר יֹצֵא מֵעֵדֶן לְהַשְׁקוֹת אֶת הַגָּן. הַנָּהָר הַזֶּה הִתְפַּשֵּׁט לִצְדָדָיו, בְּשָׁעָה שֶׁמִּזְדַּוֵּג עִמּוֹ בְּזִוּוּג שָׁלֵם, כַּאֲשֶׁר הָעֵדֶן הַזֶּה (זווגו) בְּאוֹתוֹ נָתִיב שֶׁלֹּא נוֹדָע לְמַעְלָה וּלְמַטָּה, כְּמוֹ שֶׁנֶּאֱמַר (שמות טז) נָתִיב לֹא יְדָעוֹ עָיִט. וְנִמְצְאוּ בְרָצוֹן שֶׁלֹּא נִפְרָדִים תָּמִיד אֶחָד מֵאֶחָד. אָז יוֹצְאִים מַעְיָנוֹת וּנְחָלִים וּמְעַטְּרִים אֶת הַבֵּן הַקָּדוֹשׁ בְּכָל אוֹתָם הַכְּתָרִים, וְאָז כָּתוּב (שיר ג) בָּעֲטָרָה שֶׁעִטְּרָה לּוֹ אִמּוֹ. וּבְאוֹתָהּ שָׁעָה יָרַשׁ אוֹתוֹ בֵּן יְרֻשַּׁת אָבִיו וְאִמּוֹ, וְאָז הוּא הִשְׁתַּעֲשַׁע בְּאוֹתוֹ עֹנֶג וְתַפְנוּק.</p>\n<p>וְלָמַדְנוּ, בְּשָׁעָה שֶׁהַמֶּלֶךְ הָעֶלְיוֹן בְּתַפְנוּקֵי מְלָכִים יוֹשֵׁב בְּעַטְרוֹתָיו, אֲזַי כָּתוּב, עַד שֶׁהַמֶּלֶךְ בִּמְסִבּוֹ נִרְדִּי נָתַן רֵיחוֹ. זֶה הַיְסוֹד שֶׁמּוֹצִיא בְרָכוֹת לְזַוֵּג אֶת הַמֶּלֶךְ הַקָּדוֹשׁ עִם הַגְּבִירָה (בדרגה הזו). וְאָז נִתָּנוֹת בְּרָכוֹת בְּכָל הָעוֹלָמוֹת, (ויוצאים) וּמִתְבָּרְכִים עֶלְיוֹנִים וְתַחְתּוֹנִים. וְעַכְשָׁו הֲרֵי הַמָּאוֹר הַקָּדוֹשׁ מִתְעַטֵּר בְּעַטְרוֹת הַדַּרְגָּה הַזּוֹ, הוּא וְהַחֲבֵרִים מַעֲלִים תִּשְׁבָּחוֹת מִמַּטָּה לְמַעְלָה, וְהִיא מִתְעַטֶּרֶת בְּאוֹתָן הַתִּשְׁבָּחוֹת. עַכְשָׁו יֵשׁ לְהוֹצִיא בְרָכוֹת לְכָל הַחֲבֵרִים מִמַּעְלָה לְמַטָּה בַּדַּרְגָּה הַקְּדוֹשָׁה הַזּוֹ, וְרַבִּי אֶלְעָזָר (שרבי אלעזר) בְּנוֹ יֹאמַר מֵאוֹתָם הַדְּבָרִים הַמְעֻלִּים שֶׁלָּמַד מֵאָבִיו.</p>"],[9522012104,"<p>פָּתַח רַבִּי אֶלְעָזָר וְאָמַר, (בראשית כט) וַיַּרְא וְהִנֵּה בְאֵר בַּשָּׂדֶה וְגוֹ', וְנֶאֶסְפוּ שָׁמָּה כָל הָעֲדָרִים וְגוֹ'. יֵשׁ לְהִסְתַּכֵּל בַּפְּסוּקִים הַלָּלוּ, וְהֵם בְּסוֹד הַחָכְמָה שֶׁלָּמַדְתִּי מֵאַבָּא, וְכָךְ לָמַדְתִּי: וַיַּרְא וְהִנֵּה בְאֵר בַּשָּׂדֶה, אֵיזוֹ בְּאֵר? זֶהוּ שֶׁכָּתוּב (במדבר כא) בְּאֵר חֲפָרוּהָ שָׂרִים כָּרוּהָ נְדִיבֵי הָעָם. וְהִנֵּה שָׁם שְׁלֹשָׁה עֶדְרֵי צֹאן רֹבְצִים עָלֶיהָ, אֵלּוּ הֵם נֵצַח סוֹד יְסוֹד, שֶׁאֵלּוּ הֵם הָרוֹבְצִים עָלֶיהָ וְעוֹמְדִים עָלֶיהָ. וּמֵאֵלֶּה מִתְמַלֵּאת הַבְּאֵר הַזּוֹ בִּבְרָכוֹת.</p>\n<p>כִּי מִן הַבְּאֵר הַהִיא יַשְׁקוּ הָעֲדָרִים, שֶׁהֲרֵי מֵהַבְּאֵר הַזּוֹ נִזּוֹנִים עֶלְיוֹנִים וְתַחְתּוֹנִים (עולמות תחתונים), וְכֻלָּם מִתְבָּרְכִים כְּאֶחָד. וְהָאֶבֶן גְּדֹלָה עַל פִּי הַבְּאֵר, זֶהוּ הַדִּין הַקָּשֶׁה שֶׁעוֹמֵד עָלֶיהָ מֵהַצַּד הָאַחֵר לְהָנִיק לָהּ (ממנה). וְנֶאֶסְפוּ שָׁמָּה כָל הָעֲדָרִים, אֵלּוּ הֵם שֵׁשֶׁת כִּתְרֵי הַמֶּלֶךְ שֶׁכֻּלָּם מִתְכַּנְּסִים וּמַשְׁפִּיעִים בְּרָכוֹת מֵרֹאשׁ הַמֶּלֶךְ וּמְרִיקִים לְתוֹכָהּ. וּכְשֶׁכֻּלָּם מִתְחַבְּרִים כְּאֶחָד לְהָרִיק בָּהּ, אָז כָּתוּב וְגָלֲלוּ אֶת הָאֶבֶן מֵעַל פִּי הַבְּאֵר, מְנַדְּדִין (גוללים) אֶת אוֹתוֹ הַדִּין הַקָּשֶׁה וּמַעֲבִירִים אוֹתוֹ מִמֶּנָּה.</p>\n<p>וְהִשְׁקוּ אֶת הַצּאן, מְרִיקִים בְּרָכוֹת מֵאוֹתָהּ בְּאֵר לָעֶלְיוֹנִים וְלַתַּחְתּוֹנִים. אַחַר כָּךְ - וְהֵשִׁיבוּ אֶת הָאֶבֶן עַל פִּי הַבְּאֵר לִמְקֹמָהּ. וְשָׁב אוֹתוֹ הַדִּין לִמְקוֹמוֹ, מִשּׁוּם שֶׁצָּרִיךְ לוֹ לְבַשֵּׂם אֶת הָעוֹלָם וּלְתַקֵּן הָעוֹלָם. וְעַכְשָׁו הֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא מֵרִיק עֲלֵיכֶם בְּרָכוֹת מִמַּעְיַן הַנַּחַל, וּמִכֶּם מִתְבָּרְכִים כָּל בְּנֵי הַדּוֹר. אַשְׁרֵי חֶלְקְכֶם בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא, עֲלֵיכֶם כָּתוּב (ישעיה נד) וְכָל בָּנַיִךְ לִמּוּדֵי ה' וְרַב שְׁלוֹם בָּנָיִךְ.</p>\n<p>פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, (תהלים קמט) יַעְלְזוּ חֲסִידִים בְּכָבוֹד יְרַנְּנוּ עַל מִשְׁכְּבוֹתָם וְגוֹ'. לָמַדְנוּ, בְּי\"ג מִדּוֹת נִקְשָׁר קֶשֶׁר הָאֱמוּנָה, שֶׁיִּמָּצְאוּ בְרָכוֹת לַכֹּל. וְכָל אֱמוּנָתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא נִסְתְּרוּ בְּשָׁלֹשׁ. וְעַל זֶה בִּשְׁלֹשׁ עֶשְׂרֵה מִדּוֹת מִתְעַטֶּרֶת הַתּוֹרָה, כְּמוֹ שֶׁבֵּאַרְנוּ מִקַּל וָחֹמֶר וּמִגְּזֵרָה שָׁוָה וְכוּ', וְכַמָּה פְעָמִים בֵּאַרְנוּ אֶת זֶה, וְהַשֵּׁם הַקָּדוֹשׁ מִתְעַטֵּר בָּזֶה.</p>"],[9522012105,"<p>בֹּא רְאֵה, בְּאוֹתָהּ שָׁעָה שֶׁרָצָה יַעֲקֹב שֶׁיִּתְבָּרְכוּ בָנָיו בְּשֵׁם (בקשר) הָאֱמוּנָה, מַה כָּתוּב? (בראשית מט) כָּל אֵלֶּה שִׁבְטֵי יִשְׂרָאֵל שְׁנֵים עָשָׂר וְזֹּאת - הֲרֵי שְׁלֹשָׁה עָשָׂר, שֶׁהִשְׁתַּתְּפָה עִמָּהֶם שְׁכִינָה וְהִתְקַיְּמוּ הַבְּרָכוֹת. וְהַיְנוּ שֶׁכָּתוּב אִישׁ אֲשֶׁר כְּבִרְכָתוֹ בֵּרַךְ אֹתָם. מַה זֶּה כְּבִרְכָתוֹ? בְּאוֹתָהּ דֻּגְמָא שֶׁל מַעְלָה, כְּבִרְכָתָהּ שֶׁל כָּל מִדָּה וּמִדָּה.</p>\n<p>וְלָמַדְנוּ, כָּל אוֹתָן מִדּוֹת עוֹלוֹת וּמִתְעַטְּרוֹת וְנָחוֹת בְּרֹאשׁ אֶחָד, וְשָׁם מִתְעַטֵּר רֹאשׁ הַמֶּלֶךְ, אוֹתוֹ שֶׁנִּקְרָא בְּדַרְגָּה עֶלְיוֹנָה שֶׁל חֲסִידוּת, וְהַחֲסִידִים יוֹרְשִׁים כָּל אוֹתוֹ הַכָּבוֹד שֶׁלְּמַעְלָה, שֶׁכָּתוּב יַעְלְזוּ חֲסִידִים בְּכָבוֹד - בָּעוֹלָם הַזֶּה, יְרַנְּנוּ עַל מִשְׁכְּבוֹתָם - בָּעוֹלָם הַבָּא. רוֹמְמוֹת אֵל בִּגְרוֹנָם - שֶׁיּוֹדְעִים לִקְשֹׁר אֶת קֶשֶׁר הָאֱמוּנָה כָּרָאוּי, וְאָז חֶרֶב פִּיפִיּוֹת בְּיָדָם. אֵיזוֹ חֶרֶב פִּיפִיּוֹת? זוֹהִי חֶרֶב לַה', חַרְבּוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא. פִּיפִיּוֹת - לוֹהֶטֶת בִּשְׁנֵי דִינִים. וְלָמָּה? לַעֲשׂוֹת נְקָמָה בַּגּוֹיִם וְגוֹ'.</p>\n<p>וַהֲרֵי רַבִּי פִּנְחָס בֶּן יָאִיר, כֶּתֶר הַחֶסֶד, הָרֹאשׁ הָעֶלְיוֹן, מִשּׁוּם כָּךְ יָרַשׁ אֶת הַכָּבוֹד שֶׁלְּמַעְלָה, וְהוּא קָשַׁר קֶשֶׁר עֶלְיוֹן, קֶשֶׁר קָדוֹשׁ, קֶשֶׁר הָאֱמוּנָה. אַשְׁרֵי חֶלְקוֹ בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא. עַל הַשֻּׁלְחָן הַזֶּה נֶאֱמַר, (יחזקאל מא) זֶה הַשֻּׁלְחָן אֲשֶׁר לִפְנֵי ה'. קָם רַבִּי פִּנְחָס וְנָשַׁק לוֹ וּבֵרַךְ אוֹתוֹ, וְנָשַׁק לְרַבִּי אֶלְעָזָר וּלְכָל הַחֲבֵרִים וּבֵרַךְ אוֹתָם. נָטַל כּוֹס וּבֵרַךְ.</p>"],[9522012106,"<p>פָּתַח וְאָמַר, (תהלים כג) תַּעֲרֹךְ לְפָנַי שֻׁלְחָן נֶגֶד צֹרְרָי וְגוֹ'. יָשְׁבוּ (שמחו) שָׁם כָּל אוֹתוֹ הַיּוֹם, וְהָיוּ כָּל הַחֲבֵרִים שְׂמֵחִים בְּדִבְרֵי תוֹרָה, וְשִׂמְחָתוֹ שֶׁל רַבִּי שִׁמְעוֹן הָיְתָה רַבָּה. לָקַח רַבִּי פִּנְחָס אֶת רַבִּי אֶלְעָזָר, וְלֹא עָזַב אוֹתוֹ כָּל אוֹתוֹ הַיּוֹם וְכָל הַלַּיְלָה, וְהָיָה שָׂמֵחַ עִמּוֹ. קָרָא עָלָיו, (ישעיה נח) אָז תִּתְעַנַּג עַל ה'. כָּל הַשִּׂמְחָה וְהָעֹנֶג הַיָּתֵר הַזֶּה - שֶׁל חֶלְקִי הוּא, (על זה שעמי הוא, על זה כתוב (תהלים קמד) אשרי העם שככה לו וגו') עֲתִידִים בְּאוֹתוֹ עוֹלָם לְהַכְרִיז עָלַי: אַשְׁרֵי חֶלְקְךְ רַבִּי פִּנְחָס, שֶׁאַתָּה זָכִיתָ לְכָל זֶה, שָׁלוֹם לְךְ וְשָׁלוֹם לְעוֹזְרֶךְ כִּי עֲזָרְךְ אֱלֹהֶיךְ. הִשְׁכִּימוּ לָלֶכֶת. קָם רַבִי פִּנְחָס וְאָחַז בְּרַבִּי אֶלְעָזָר, וְלֹא הִשְׁאִיר אוֹתוֹ לָלֶכֶת. לִוָּה רַבִּי פִּנְחָס אֶת רַבִּי שִׁמְעוֹן וּבֵרְכוֹ, וְאֶת כָּל הַחֲבֵרִים. עַד שֶׁהָיוּ הוֹלְכִים, אָמַר לָהֶם רַבִּי שִׁמְעוֹן לַחֲבֵרִים, (תהלים קיט) עֵת לַעֲשׂוֹת לַה'.</p>"],[9522012107,"<p>בָּא רַבִּי אַבָּא וְשָׁאַל, כָּתוּב וְנָתַן אַהֲרֹן עַל שְׁנֵי הַשְּׂעִירִים גֹּרָלוֹת וְגוֹ'. הַגּוֹרָלוֹת הַלָּלוּ לָמָּה? וְאַהֲרֹן לָמָּה לוֹ לָתֵת גּוֹרָלוֹת? וְהַפָּרָשָׁה הַזּוֹ לָמָּה? וַהֲרֵי לָמַדְנוּ לִפְנֵי מוֹרֵנוּ אֶת סֵדֶר הַיּוֹם, וַהֲרֵי רוֹצִים לָדַעַת.</p>\n<p>פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, (בראשית מב) וַיִּקַּח מֵאִתָּם אֶת שִׁמְעוֹן וַיֶּאֱסֹר אֹתוֹ לְעֵינֵיהֶם. וְכִי מָה רָאָה יוֹסֵף לָקַחַת אֶת שִׁמְעוֹן עִמּוֹ יוֹתֵר מֵאֶחָיו? אֶלָּא אָמַר יוֹסֵף בְּכָל מָקוֹם שִׁמְעוֹן (ולוי) הוּא (הם) פְּתִיחַת הַדִּין, וְאוֹתָהּ הַשָּׁעָה שֶׁהָלַכְתִּי מֵאָבִי אֶל אָחִי, שִׁמְעוֹן פָּתַח בָּרִאשׁוֹנָה בְּדִין, זֶהוּ שֶׁכָּתוּב (שם לז) וַיֹּאמְרוּ אִישׁ אֶל אָחִיו הִנֵּה בַּעַל הַחֲלֹמוֹת הַלָּזֶה בָּא וְעַתָּה לְכוּ וְגוֹ'. אַחַר כָּךְ בִּשְׁכֶם, (שם לד) וַיִּקְחוּ שְׁנֵי בְּנֵי יַעֲקֹב שִׁמְעוֹן וְלֵוִי, כֻּלָּם בְּדִין הָיוּ. טוֹב לָקַחַת אֶת זֶה, וְלֹא יָעִיר קְטָטָה עִם כָּל הַשְּׁבָטִים.</p>\n<p>וְשָׁנִינוּ, מָה רָאָה שִׁמְעוֹן לְהִזְדַּוֵּג עִם לֵוִי יוֹתֵר מֵהַכֹּל, וַהֲרֵי רְאוּבֵן הָיָה אָחִיו וְסָמוּךְ לוֹ? אֶלָּא שִׁמְעוֹן רָאָה וְיָדַע שֶׁלֵּוִי בָּא מִצַּד הַדִּין, וְשִׁמְעוֹן נֶאֱחָז יוֹתֵר בְּצַד הַדִּין הַקָּשֶׁה. אָמַר, נִתְעָרֵב אֵחָד עִם אֶחָד, וְאָנוּ נַחֲרִיב אֶת הָעוֹלָם. מֶה עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא? נָטַל לְחֶלְקוֹ אֶת לֵוִי וְאָמַר: מִכָּאן וָהָלְאָה שֶׁיֵּשֵׁב שִׁמְעוֹן עִם שַׁלְשֶׁלֶת הַגְּבוּרָה עִמּוֹ לְבַדּוֹ.</p>\n<p>לָמַדְנוּ, בְּצַד הָאֵם שְׁנֵי שׁוֹמְרִים חוֹקְרֵי דִין (מגנים) אֲחוּזִים בְּיָד שְׂמֹאל, וַהֲרֵי בֵּאַרְנוּ שֶׁהֵם מְרַגְּלִים אֶת הָאָרֶץ בְּכָל יוֹם וָיוֹם, וְהַיְנוּ סוֹד הַכָּתוּב, (יהושע ב) שְׁנַיִם אֲנָשִׁים מְ רַגְּלִים.</p>\n<p>וְשָׁנִינוּ, אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל יוֹתֵר מִכָּל הָעַמִּים עוֹבְדֵי עֲבוֹדָה זָרָה, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא רוֹצֶה לְטַהֵר אוֹתָם וּלְרַחֵם עֲלֵיהֶם, שֶׁהֵם חֶלְקוֹ וְגוֹרָלוֹ. זֶהוּ שֶׁכָּתוּב (דברים לב) כִּי חֵלֶק ה' עַמּוֹ וְגוֹ'. וְכָתוּב (שם) יַרְכִּבֵהוּ עַל בָּמֳתֵי אָרֶץ. עַל בָּמֳתֵי אָרֶץ דַּוְקָא, שֶׁהֲרֵי הֵם אֲחוּזִים לְמַעְלָה לְמַעְלָה, וְעַל כֵּן אַהֲבָתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא נִדְבֶּקֶת בָּהֶם. זֶהוּ שֶׁכָּתוּב (מלאכי א) אָהַבְתִּי אֶתְכֶם אָמַר ה', וְכָתוּב (דברים ז) כִּי מֵאַהֲבַת ה' אֶתְכֶם וְגוֹ'. וּמִתּוֹךְ הָאַהֲבָה הַיְתֵרָה שֶׁאוֹהֵב אוֹתָם, נָתַן לָהֶם יוֹם אֶחָד בַּשָּׁנָה לְטַהֵר אוֹתָם וּלְזַכּוֹת אוֹתָם מִכָּל חֲטָאֵיהֶם, שֶׁכָּתוּב כִּי בַיּוֹם הַזֶּה וְגוֹ', כְּדֵי שֶׁיִּהְיוּ צַדִּיקִים בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא, וְלֹא יִמָּצֵא בָהֶם חֵטְא. וְעַל כֵּן בַּיּוֹם הַזֶּה מִתְעַטְּרִים יִשְׂרָאֵל וְשׁוֹלְטִים עַל כָּל חוֹקְרֵי הַדִּין וְעַל כָּל הָרוּחוֹת.</p>\n<p>לָמַדְנוּ, וְנָתַן אַהֲרֹן עַל שְׁנֵי הַשְּׂעִירִים גֹּרָלוֹת. וְנָתַן אַהֲרֹן, מִשּׁוּם שֶׁבָּא מִצַּד הַחֶסֶד. עַל שְׁנֵי הַשְּׂעִירִים, בְּדִיּוּק עַל, כְּדֵי שֶׁתִּתְבַּשֵּׂם הַגְּבִירָה. גּוֹרָל אֶחָד לַה' וְגוֹרָל אֶחָד לַעֲזָאזֵל, וַהֲרֵי שְׁנֵי שְׂעִירִים הֵם. אָז לָמָּה אֶחָד לַה'? אֶלָּא אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא: יֵשֵׁב זֶה אֶצְלִי, וְאֶחָד יֵלֵךְ וִישׁוֹטֵט בָּעוֹלָם, שֶׁאִלְמָלֵא שְׁנֵיהֶם מִזְדַּוְּגִים, לֹא יָכוֹל הָעוֹלָם לִסְבֹּל.</p>\n<p>יָצָא זֶה, הוֹלֵךְ וּמְשׁוֹטֵט בָּעוֹלָם, וּמוֹצֵא אֶת יִשְׂרָאֵל בְּכַמָּה עֲבוֹדוֹת, בְּכַמָּה דְרָגוֹת, בְּכַמָּה הַנְהָגוֹת טוֹבוֹת, וְלֹא יָכוֹל לָהֶם, בֵּין כֻּלָּם שָׁלוֹם, וְלֹא יָכוֹל לְהִכָּנֵס עִמָּהֶם בְּמַלְשִׁינוּת. (הולך ומשוטט בעולם ומוצא את ישראל בצורה הזו) (אף ישראל למטה כך בצורה הזו) אֶת הַשָּׂעִיר הָאַחֵר שׁוֹלְחִים אוֹתוֹ עִם מַשָּׂא שֶׁל כָּל חֲטָאֵי יִשְׂרָאֵל.</p>\n<p>לָמַדְנוּ, כַּמָּה קְבוּצוֹת מְחַבְּלִים מִזְדַּוְּגִים (מזדמנים), שֶׁהֵם תַּחַת יָדוֹ, וּמְמֻנִּים לְרַגֵּל אֶת הָאָרֶץ עַל כָּל אוֹתָם שֶׁעוֹבְרִים עַל דִּבְרֵי הַתּוֹרָה, וְאוֹתוֹ יוֹם לֹא מָצוּי הַמַּלְשִׁין (פתחון) לְדַבֵּר עַל יִשְׂרָאֵל. כְּשֶׁמַּגִּיעַ הַשָּׂעִיר הַזֶּה אֶל הָהָר, כַּמָּה שִׂמְחָה עַל שִׂמְחָה מִתְבַּשְּׂמִים כֻּלָּם בּוֹ. וְאוֹתוֹ שׁוֹמֵר שֶׁיּוֹצֵא, חוֹזֵר וְאוֹמֵר אֶת תִּשְׁבַּחְתָּם שֶׁל יִשְׂרָאֵל, הַקָּטֵגוֹר נַעֲשֶׂה סָנֵגוֹר.</p>\n<p>וּבֹא רְאֵה, לֹא זֶה לְבַדּוֹ הוּא, אֶלָּא בְּכָל מָקוֹם שֶׁרוֹצִים יִשְׂרָאֵל לְהִטָּהֵר מֵחֲטָאֵיהֶם, הַקָּדוֹשׁ בָּרוּךְ הוּא נוֹתֵן לָהֶם עֵצָה לִקְשֹׁר אֶת בַּעֲלֵי הַדִּין וּלְבַשֵּׂם אוֹתָם בְּאוֹתָם קָרְבָּנוֹת וְעוֹלוֹת שֶׁקְּרֵבִים לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וְאָז לֹא יְכוֹלִים לְהָרַע. וְאוֹתוֹ יוֹם יוֹתֵר עַל הַכֹּל, כְּמוֹ שֶׁיִּשְׂרָאֵל מְבַשְּׂמִים לְמַטָּה אֶת הַכֹּל, כָּךְ מְבַשְּׂמִים אֶת כָּל אֵלּוּ שֶׁלָּהֶם יֵשׁ הַלְשָׁנָה (פתחון), וְהַכֹּל הוּא קָרְבָּן וַעֲבוֹדָה שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>\n<p>לָמַדְנוּ, בְּאוֹתָה שָׁעָה שֶׁכָּתוּב וְלָקַח אַהֲרֹן אֶת שְׁנֵי הַשְּׂעִירִים וְגוֹ', הֵם מִתְעוֹרְרִים בְּאוֹת יוֹם לְמַעְלָה וְרוֹצִים לִשְׁלֹט (לשטות) וְלָצֵאת לָעוֹלָם. כֵּיוָן שֶׁהַכֹּהֵן מַקְרִיב אֶת אֵלּוּ לְמַטָּה, אָז נִקְרָבִים אוֹתָם שֶׁלְּמַעְלָה, וְאָז עוֹלִים הַגּוֹרָלוֹת בְּכָל הַצְּדָדִים. הַכֹּהֵן נוֹתֵן גּוֹרָלוֹת לְמַטָּה, הַכֹּהֵן נוֹתֵן גּוֹרָלוֹת לְמַעְלָה. כְּמוֹ שֶׁאֶחָד נִשְׁאָר עִם הַקָּדוֹשׁ בָּרוּךְ הוּא לְמַטָּה, וְאֶת הָאֶחָד מוֹצִיאִים לְאוֹתוֹ הַמִּדְבָּר, כָּךְ גַּם לְמַעְלָה אֶחָד נִשְׁאָר עִם הַקָּדוֹשׁ בָּרוּךְ הוּא, וְאֶחָד יוֹצֵא לְשׁוֹטֵט בָּעוֹלָם לְאוֹתוֹ הַמִּדְבָּר הָעֶלְיוֹן, וְאֶחָד נִקְשָׁר בְּאֶחָד.</p>\n<p>כָּתוּב וְסָמַךְ אַהֲרֹן אֶת שְׁתֵּי יָדָו עַל רֹאשׁ הַשָּׂעִיר הַחַי וְהִתְוַדָּה עָלָיו וְגוֹ'. מִשּׁוּם כָּךְ וְסָמַךְ אַהֲרֹן אֶת שְׁתֵּי יָדָו, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הִסְכִּים עַל יָדוֹ. עַל רֹאשׁ הַשָּׂעִיר הַחַי, הַחַי דַּוְקָא, לְהַכְלִיל אוֹתוֹ שֶׁלְּמַעְלָה.</p>\n<p>וְהִתְוַדָּה עָלָיו אֶת כָּל עֲונֹת, כְּמוֹ שֶׁכָּתוּב (ויקרא ה) וְהִתְוַדָּה אֲשֶׁר חָטָא עָלֶיהָ. וּבֵאַרְנוּ עָלֶיהָ, שֶׁנִּטְהָר הָאָדָם וְנִשְׁאָר עָלֶיהָ כָּל אוֹתוֹ הַחֵטְא. אַף כָּאן וְהִתְוַדָּה עָלָיו, אַחַר שֶׁהִתְוַדָּה הַכֹּהֵן בַּעֲבוּרָם שֶׁל יִשְׂרָאֵל - עָלָיו, כְּלוֹמַר, כֻּלָּם יִשָּׁאֲרוּ עָלָיו.</p>\n<p>אָמַר לוֹ רַבִּי אַבָּא, אִם כָּךְ, כָּתוּב וְלֹא יִזְבְּחוּ עוֹד אֶת זִבְחֵיהֶם לַשְּׂעִירִים. אָמַר לוֹ, כָּאן שׁוֹנֶה, שֶׁשָּׁם לַשְּׂעִירִים הָיוּ מַקְרִיבִים קָרְבָּן, וּמִשּׁוּם כָּךְ לֹא כָתוּב וְלֹא יִזְבְּחוּ עוֹד אֶת זִבְחֵיהֶם שְׂעִירִים, אֶלָּא לַשְּׂעִירִים, שֶׁשָּׁם לַשְּׂעִירִים הָיוּ עוֹשִׂים פֻּלְחָן וְשִׁלְטוֹן, וְכָאן - וְנָשָׂא הַשָּׂעִיר עָלָיו אֶת כָּל עֲונֹתָם, וְהַקָּרְבָּן אֵינוֹ נַעֲשֶׂה אֶלָּא לַקָּדוֹשׁ בָּרוּךְ הוּא. בֹּא וּרְאֵה שֶׁבִּגְלַל הַקָּרְבָּן מִתְבַּשְּׂמִים עֶלְיוֹנִים וְתַחְתּוֹנִים וְהַדִּין לֹא שׁוֹלֵט וְשׁוֹרֶה עַל יִשְׂרָאֵל.</p>"],[9522012108,"<p>לָמַדְנוּ, וְשִׁלַּח בְּיַד אִישׁ עִתִּי הַמִּדְבָּרָה. מַהוּ אִישׁ עִתִּי? אֶלָּא סוֹד הַדָּבָר כָּךְ הוּא - בְּכָל מַה שֶּׁנַּעֲשֶׂה, צָרִיךְ אָדָם מְזֻמָּן לְאוֹתוֹ דָבָר. יֵשׁ אָדָם שֶׁהַבְּרָכָה מִתְקַיֶּמֶת עַל יָדוֹ יוֹתֵר מֵאַחֵר. בּא וּרְאֵה מַה כָּתוּב בְּכֹהֵן, טוֹב עַיִן הוּא יְבֹרָךְ, אַל תִּקְרֵי יְבֹרָךְ אֶלָּא יְבָרֵךְ, כִּי הוּא מְזֻמָּן שֶׁתִּתְקַיֵּם בְּרָכָה עַל יָדוֹ בָּזֶה. (ושורה הברכה בהשגחתו).</p>\n<p>וְיִשִׁ אָדָם שֶׁמְּזֻמָּן שֶׁיִּתְקַיְּמוּ עַל יָדוֹ קְלָלוֹת, וּבְכָל מַה שֶּׁיִּתְבּוֹנֵן יָבֹאוּ קְלָלוֹת וּמְאֵרָה וּבְעָתָה, כְּמוֹ בִּלְעָם שֶׁנִּקְרָא רַע עַיִן, שֶׁהָיָה מְזֻמָּן לְכָל רַע וְלֹא הָיָה מְזֻמָּן לְטוֹב, וְאַף עַל גַּב שֶׁבֵּרַךְ, בִּרְכָתוֹ אֵינָהּ בְּרָכָה וְלֹא הִתְקַיְּמָה. וּכְשֶׁהָיָה מְקַלֵּל, כָּל מַה שֶּׁקִּלֵּל הִתְקַיֵּם, וַאֲפִלּוּ בְּרֶגַע אֶחָד, וְעַל זֶה כָּתוּב (במדבר כד) שְׁתֻם הָעָיִן. בְּכָל מָקוֹם שֶׁעֵינוֹ שָׁלְטָה - הִתְקַלֵּל.</p>\n<p>בֹּא וּרְאֵה מַה כָּתוּב, (שם) וַיָּשֶׁת אֶל הַמִּדְבָּר פָּנָיו, כְּדֵי שֶׁיִּתְעוֹרֵר מֵאוֹתוֹ צַד שֶׁהוּא שׁוֹלֵט שָׁם, וְיָבֹא בְהַלְשָׁנָה עַל יִשְׂרָאֵל. מַה כָּתוּב בַּכֹּהֲנִים? (משלי כב) טוֹב עַיִן הוּא יְבֹרָךְ, שֶׁהוּא הָיָה מְזֻמָּן לָזֶה וְשׁוֹרָה בְרָכָה בַּהַשְׁגָּחָה שֶׁלּוֹ. וְעַל זֶה שָׁנִינוּ, יִסְטֶה אָדָם אֲפִלּוּ מִמֵּאָה דְרָכִים וְלֹא יִפְגֹּשׁ אָדָם שֶׁיֵּשׁ לוֹ עַיִן רָעָה.</p>\n<p>אַף כָּאן, וְשִׁלַּח בְּיַד אִישׁ עִתִּי - שֶׁהוּא מְזֻמָּן לָזֶה וְרָשׁוּם לָזֶה, וְהַכֹּהֵן הָיָה מַכִּיר בּוֹ עַיִן אַחַת יוֹתֵר מֵאַחֶרֶת מְעַט. הָעוֹר שֶׁעַל הָעַיִן מְכֻסֶּה בִּשְׂעָרוֹת רַבּוֹת, הָעַיִן מְכֻחֶלֶת וְלֹא מִסְתַּכֵּל יָשָׁר, זֶהוּ הָאָדָם הַמְזֻמָּן לְכָךְ וְהָרָאוּי לוֹ. וְעַל זֶה כָּתוּב בְּיַד אִישׁ עִתִּי.</p>\n<p>בְּגוּשׁ חָלָב הָיָה אָדָם, שֶׁבְּכָל מָקוֹם שֶׁמַּכֶּה בְּיָדוֹ, הָיָה מֵת, וְלֹא הָיוּ אֲנָשִׁים מִתְקָרְבִים אֵלָיו. בְּסוּרְיָה הָיָה אָדָם, שֶׁבְּכָל מָקוֹם שֶׁבּוֹ הִסְתַּכֵּל, אֲפִלּוּ לְטוֹב, הַכֹּל הִתְהַפֵּךְ לְרַע. יוֹם אֶחָד הָיָה אִישׁ אֶחָד הוֹלֵךְ בַּשּׁוּק, וְהָיוּ פָנָיו מְאִירוֹת. בָּא אוֹתוֹ אִישׁ וְהִסְתַּכֵּל בּוֹ, וְנִבְקְעָה עֵינוֹ. מִשּׁוּם כָּךְ לַכֹּל הָיָה אָדָם מוּכָן, לָזֶה וְלָזֶה. וְעַל זֶה כָּתוּב טוֹב עַיִן הוּא יְבֹרָךְ, אַל תִּקְרֵי יְבֹרָךְ אֶלָּא יְבָרֵךְ.</p>\n<p>וְלָמַדְנוּ, הָאִישׁ הַזֶּה שֶׁהָיָה הוֹלֵךְ לַמִּדְבָּר, כְּשֶׁהִגִּיעַ שָׁם אוֹתוֹ שָׂעִיר, הָיָה עוֹלֶה לָהָר, וְדוֹחֶה אוֹתוֹ בִּשְׁתֵּי יָדָיו, וְלֹא הָיָה מַגִּיעַ לַחֲצִי הָהָר עַד שֶׁנַּעֲשָׂה אֵיבָרִים אֵיבָרִים, וְאוֹתוֹ אִישׁ הָיָה אוֹמֵר: כָּךְ יִמָּחוּ עֲווֹנוֹת עַמְּךְ וְגוֹ'. וּמִשּׁוּם שֶׁעוֹלֶה אוֹתוֹ קָטֵגוֹר וְנַעֲשֶׂה סָנֵגוֹר שֶׁל יִשְׂרָאֵל, אָז הַקָּדוֹשׁ בָּרוּךְ הוּא, אֶת כָּל חֲטָאֵי יִשְׂרָאֵל וְכָל מַה שֶּׁכָּתוּב בְּאוֹתָם פְּתָקִים שֶׁלְּמַעְלָה לְהַזְכִּיר אֶת חֲטָאֵי בְּנֵי הָאָדָם, הוּא נוֹטֵל אוֹתָם וְזוֹרֵק אוֹתָם כְּמוֹ זֶה לְמָקוֹם שֶׁנִּקְרָא מְצוּלוֹת יָם. זֶהוּ שֶׁכָּתוּב (מיכה ז) וְתַשְׁלִיךְ בִּמְצֻלוֹת יָם כָּל חַטֹּאתָם.</p>"],[9522012109,"<p>לָמַדְנוּ, וּמֵאֵת עֲדַת בְּנֵי יִשְׂרָאֵל יִקַּח שְׁנֵי שְׂעִירֵי עִזִּים לְחַטָּאת. וּמֵאֵת עֲדַת, כְּדֵי שֶׁיִּהְיֶה מִכֻּלָּם וְיִתְכַּפֵּר לְכֻלָּם, שֶׁהֲרֵי כָּל חֲטָאֵי בְּנֵי יִשְׂרָאֵל כָּאן תְּלוּיִים, וְכֻלָּם מִתְכַּפְּרִים בָּזֶה, וְלֹא מַסְפִּיק מֵאִישׁ אֶחָד. וּמֵאֵיזֶה מָקוֹם נִלְקָחִים? מֵאוֹתָן קֻפּוֹת שֶׁבָּעֲזָרָה נוֹטְלִים שָׂכָר, וּמְבִיאִים אוֹתָם מֵאוֹתָם דָּמִים שֶׁהָיוּ מִכֻּלָּם.</p>\n<p>וְאוֹתוֹ הַשָּׂעִיר הָאַחֵר, שֶׁהָיָה נִשְׁאָר לַקָּדוֹשׁ בָּרוּךְ הוּא, עוֹשִׂים אוֹתוֹ חַטָּאת בָּרִאשׁוֹנָה. וַהֲרֵי בֵּאַרְנוּ בְּאֵיזֶה מָקוֹם הָיָה נִקְשָׁר. וְאַחַר כָּךְ מַקְרִיבִים אֶת אֵלֶּה, וְהַכֹּל מִתְבַּשְּׂמִים, וְיִשְׂרָאֵל נִשְׁאָרִים צַדִּיקִים לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא מִכָּל הַחֲטָאִים שֶׁעָשׂוּ וְחָטְאוּ לְפָנָיו. זֶהוּ שֶׁכָּתוּב כִּי בַיּוֹם הַזֶּה יְכַפֵּר עֲלֵיכֶם וְגוֹ'.</p>\n<p>עוֹד אָמַר רַבִּי שִׁמְעוֹן, (בראשית כז) וַיֹּאמֶר יַעֲקֹב אֶל רִבְקָה אִמּוֹ הֵן עֵשָׂו אָחִי אִישׁ שָׂעִיר וְאָנֹכִי אִישׁ חָלָק. מַה הוּא רוֹמֵז? אֶלָּא וַדַּאי שֶׁעֵשָׂו אִישׁ שָׂעִיר, וְהוּא מֵאוֹתוֹ שֶׁנִּקְרָא שֵׂעִיר, שֶׁהֲרֵי מֵאוֹתוֹ צַד הוּא בָּא. וְאָנֹכִי אִישׁ חָלָק - אִישׁ מֵאוֹתוֹ שֶׁחִלֵּק לְכָל שְׁאָר הָעַמִּים מְמֻנִּים גְּדוֹלִים, שֶׁכָּתוּב (דברים ד) אֲשֶׁר חָלַק ה' אֱלֹהֶיךְ אֹתָם, וְכָתוּב (שם לב) כִּי חֵלֶק ה' עַמּוֹ וְגוֹ'. עוֹד אִישׁ חָלָק, מִשְּׁנֵי שְׂעִירִים, וְנִשְׁאָר אֶחָד. שֶׁהַכֹּהֵן חִלֵּק אוֹתָם - אֶחָד לְחֶלְקוֹ, וְאֶחָד לַקָּדוֹשׁ בָּרוּךְ הוּא. לָמָּה? כְּדֵי שֶׁיִּטְעַן עַל כְּתֵפוֹ אֶת כָּל חֲטָאֵי יַעֲקֹב, שֶׁכָּתוּב וְנָשָׂא הַשָּׂעִיר עָלָיו אֶת כָּל עֲונֹתָם, עֲונֹת תָּם.</p>\n<p>לָמַדְנוּ, בְּאוֹתוֹ יוֹם כַּמָּה פְתָחִים פְּתוּחִים כְּנֶגֶד יִשְׂרָאֵל לְקַבֵּל תְּפִלּוֹתֵיהֶם. אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל, שֶׁהֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא רוֹצֶה לְטַהֵר אוֹתָם וּלְזַכּוֹת אוֹתָם, זֶהוּ שֶׁכָּתוּב כִּי בַיּוֹם הַזֶּה וְגוֹ'. בַּיּוֹם הַזֶּה מִתְעַטֵּר הַכֹּהֵן בְּכַמָּה עֲטָרוֹת. בַּיּוֹם הַזֶּה עֲבוֹדַת הַכֹּהֵן נִכְבָּדָה וּגְדוֹלָה מִכָּל הָעֲבוֹדוֹת. לְכֻלָּם נוֹתֵן חֵלֶק בְּאוֹתָם הַקָּרְבָּנוֹת שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא. בַּיּוֹם הַזֶּה מִתְעַטֵּר (מתעורר) הַחֶסֶד בָּעוֹלָם עַל יְדֵי הַכֹּהֵן, מַקְרִיב אֶת הַקָּרְבָּנוֹת עַל חֲטָאֵי הָעָם, עַל חֶטְאוֹ בָּרִאשׁוֹנָה, וְאַחַר כָּךְ עַל חֲטָאֵי הָעָם. הוּא מַקְרִיב עוֹלוֹת עָלָיו וְעַל הָעָם, וַהֲרֵי בֵּאַרְנוּ אֶת הַדְּבָרִים.</p>"],[9522012110,"<p>מִצְוָה זוֹ, שֶׁיַּעֲבֹד הַכֹּהֵן הַגָּדוֹל אֶת עֲבוֹדַת אוֹתוֹ הַיּוֹם כְּמוֹ שֶׁצָּרִיךְ, וְלִשְׁלֹחַ שָׂעִיר לַעֲזָאזֵל. הַסּוֹד הַזֶּה כְּמוֹ שֶׁנֶּאֱמַר, כְּדֵי שֶׁיִּפָּרֵד מֵהָעָם הַקָּדוֹשׁ וְלֹא יִתְבַּע אֶת חֲטָאֵיהֶם לִפְנֵי הַמֶּלֶךְ וְלֹא יְקַטְרֵג עֲלֵיהֶם, שֶׁהֲרֵי אֵין לוֹ תֹּקֶף וְשִׁלְטוֹן (בה) אֶלָּא רַק כְּשֶׁמִּתְחַזֵּק הָרֹגֶז מִלְמַעְלָה, וּבְאוֹתוֹ דוֹרוֹן מִתְהַפֵּךְ אַחַר כָּךְ לְאַפּוֹטְרוֹפּוֹס עֲלֵיהֶם, וְעַל כֵּן נִדְחֶה מִלִּפְנֵי הַמֶּלֶךְ. וַהֲרֵי בֵּאַרִנוּ, מִשּׁוּם שֶׁהוּא קֵץ כָּל בָּשָׂר.</p>\n<p>וְהָעָֹם הַקָּדוֹשׁ נוֹתְנִים לוֹ כְּמוֹ שֶׁהוּא צָרִיךְ שָׂעִיר, וְסוֹד זֶה - (בראשיתכז) הֵן עֵשָׂו אָחִי אִישׁ שָׂעִיר. כְּמוֹ שֶׁהוּא בְּצַד הַקְּדֻשָּׁה זָכָר וּנְקֵבָה, אַף כָּךְ בְּצַד הַטֻּמְאָה זָכָר וּנְקֵבָה. מָשָׁל אוֹמְרִים, זְרֹק עֶצֶם לְכֶלֶב, וְהוּא יְלַחֵךְ אֶת עֲפַר רַגְלְךְ.</p>\n<p>שָׁאֲלוּ אֶת בֶּן זוֹמָא, הַאִם לְסָרֵס כֶּלֶב? אָמַר לָהֶם, (ויקרא כב) וּבְאַרְצְכֶם לֹא תַעֲשׂוּ, כֹּל שֶׁבְּאַרְצְכֶם לֹא תַעֲשׂוּ. כְּמוֹ שֶׁהָעוֹלָם צָרִיךְ אֶת זֶה, כָּךְ צָרִיךְ הָעוֹלָם אֶת זֶה. וְעַל זֶה נֶאֱמַר, (בראשית א) וְהִנֵּה טוֹב מְאֹד - זֶה מַלְאַךְ הַמָּוֶת, אֵין לְבַטְּלוֹ מִן הָעוֹלָם, שֶׁהָעוֹלָם צָרִיךְ אוֹתוֹ. אַף עַל גַּב שֶׁכָּתוּב בּוֹ (ישעיה נב) וְהַכְּלָבִים עַזֵּי נֶפֶשׁ לֹא יָדְעוּ שָׂבְעָה וְגוֹ', לֹא יִתְבַּטְּלוּ מִן הָעוֹלָם. הַכֹּל צָרִיךְ, טוֹב וָרָע.</p>\n<p>וּמִשּׁוּם כָּךְ יֵשׁ לָנוּ בַּיּוֹם הַזֶּה לִזְרֹק עֶצֶם לַכֶּלֶב, עַד שֶׁהוּא גּוֹרֵר, יִכָּנֵס מִי שֶׁיִּכָּנֵס לְהֵיכַל הַמֶּלֶךְ, וְאֵין מִי שֶׁיִּמְחֶה בְיָדוֹ. אַחַר כָּךְ יְכַשְׁכֵּשׁ בִּזְנָבוֹ.</p>\n<p>מַה כָּתוּב? וְהִתְוַדָּה עָלָיו אֶת כָּל עֲונֹת בְּנֵי יִשְׂרָאֵל, וְכָתוּב וְנָשָׂא הַשָּׂעִיר עָלָיו אֶת כָּל עֲונֹתָם. כֵּיוָן שֶׁהוּא רוֹאֶה אֶת הַשָּׂעִיר הַזֶּה, תְּשׁוּקָתוֹ אֵלָיו וּלְהִתְתַּקֵּן עִמּוֹ, וְלֹא יוֹדֵעַ מֵאוֹתָם הַחֲטָאִים שֶׁנּוֹטֵל הַשָּׂעִיר. הוּא שָׁב אֶל יִשְׂרָאֵל, רוֹאֶה אוֹתָם בְּלִי חֲטָאִים, בְּלִי פְשָׁעִים, שֶׁהֲרֵי כֻּלָּם שׁוֹרִים עַל רֹאשׁ הַשָּׂעִיר, עוֹלֶה לְמַעְלָה וּמְשַׁבֵּחַ אוֹתָם לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. וְהַקָּדוֹשׁ בָּרוּךְ הוּא רוֹאֶה אֶת עֵדוּת אוֹתוֹ הַמְקַטְרֵג, וְהוֹאִיל וּתְשׁוּקָתוֹ לְרַחֵם עַל עַמּוֹ, אַף עַל גַּב שֶׁהוּא יוֹדֵעַ אֶת כָּל הַמַּעֲשֶׂה, הוּא חָס עַל יִשְׂרָאֵל.</p>\n<p>וְהַכֹּל שׁוֹרֶה עַל זֶה, כְּדֵי שֶׁלֹּא יְעוֹרֵר אֶת סוֹד הַדִּין מִלְמַעְלָה, וְזֶה יִתְחַזֵּק וְיֻשְׁמְדוּ בְּנֵי הָעוֹלָם, שֶׁהֲרֵי זֶה בָּא מִצַּד הַדִּין הַקָּשֶׁה, וְאִם זֶה יִתְעוֹרֵר, הוּא מִתְעוֹרֵר בַּחֲטָאֵי בְּנֵי הָאָדָם, שֶׁהֲרֵי אֵין לוֹ הִתְעוֹרְרוּת לַעֲלוֹת לְמַעְלָה לְעוֹרֵר דִּין קָשֶׁה רַק מִשּׁוּם חֲטָאֵי בְּנֵי אָדָם. שֶׁהֲרֵי בְּשָׁעָה שֶׁאָדָם עוֹשֶׂה חֵטְא, זֶה מִתְאַסֵּף, וְכַמָּה אֲלָפִים מְסַיְּעִים שֶׁלּוֹ, וּמִתְכַּנְּסִים שָׁם וְנוֹטְלִים אוֹתוֹ וְעוֹלִים לְמַעְלָה. הָרַחֲמָן יַצִּילֵנוּ. וְעַל הַכֹּל נוֹתֵן הַקָּדוֹשׁ בָּרוּךְ הוּא עֵצָה לְיִשְׂרָאֵל לְהִנָּצֵל מִכָּל הַצְּדָדִים, וְעַל זֶה כָּתוּב, (תהלים קמה) אַשְׁרֵי הָעָם שֶׁכָּכָה לּוֹ אַשְׁרֵי הָעָם שֶׁה' אֱלֹהָיו. (עד כאן הרעיא מהימנא).</p>"]]});
